use MathPHP\Solver\RootSearchLimitException;
use MathPHP\Solver\SolverOptions;
use PHPUnit\Framework\Attributes\DataProvider;
use PHPUnit\Framework\TestCase;

final class EquationSolverTest extends TestCase
{
    public function testSingletonIntervalReturnsOnlyDefinedRootsAtThatPoint(): void
    {
        $root = Math::solve('x^2 = 4', 'x', 2.0, 2.0);
        $noRoot = Math::solve('x^2 = 4', 'x', 0.0, 0.0);
        $identityPoint = Math::solve('sin(x) = sin(x)', 'x', 1.0, 1.0);
        $approximatePoint = Math::solve('x = 0.1 + 0.2', 'x', 0.3, 0.3);
        $undefinedPoint = Math::solve('ln(x) = 0', 'x', -1.0, -1.0);

        self::assertCount(1, $root);
        self::assertSame(2.0, $root[0]->value);
        self::assertSame([], $noRoot);
        self::assertCount(1, $identityPoint);
        self::assertSame(1.0, $identityPoint[0]->value);
        self::assertCount(1, $approximatePoint);
        self::assertSame(0.3, $approximatePoint[0]->value);
        self::assertSame([], $undefinedPoint);
    }

    public function testZeroExponentPolynomialTermsAgreeAcrossRealRootApis(): void
    {
        $equation = '2*x^0 + x^2 - 4 = 0';
        $solutions = Math::solve($equation, 'x', -3.0, 3.0);
        $rootCount = Math::countPolynomialRootsInInterval($equation, 'x', -3.0, 3.0);
        $isolatedRoots = Math::isolatePolynomialRootsInRationalInterval(
            $equation,
            'x',
            '-3',
            '3',
        );

        self::assertCount(2, $solutions);
        self::assertEqualsWithDelta(-\sqrt(2.0), $solutions[0]->value, 1.0E-12);
        self::assertEqualsWithDelta(\sqrt(2.0), $solutions[1]->value, 1.0E-12);
        self::assertSame(2, $rootCount);
        self::assertNotNull($isolatedRoots);
        self::assertCount(2, $isolatedRoots);
        self::assertFalse($isolatedRoots[0]->isExactRoot);
        self::assertFalse($isolatedRoots[1]->isExactRoot);
        self::assertLessThan(
            -\sqrt(2.0),
            (float) $isolatedRoots[0]->lowerNumerator / (float) $isolatedRoots[0]->lowerDenominator,
        );
        self::assertGreaterThan(
            -\sqrt(2.0),
            (float) $isolatedRoots[0]->upperNumerator / (float) $isolatedRoots[0]->upperDenominator,
        );
        self::assertLessThan(
            \sqrt(2.0),
            (float) $isolatedRoots[1]->lowerNumerator / (float) $isolatedRoots[1]->lowerDenominator,
        );
        self::assertGreaterThan(
            \sqrt(2.0),
            (float) $isolatedRoots[1]->upperNumerator / (float) $isolatedRoots[1]->upperDenominator,
        );
    }

    public function testFiniteLogarithmicEquationUsesTheCorrectSourceOffset(): void
    {
        foreach (['ln(x) = x - 2', 'x - 2 = ln(x)'] as $equation) {
            $solutions = Math::solve($equation, 'x', 0.01, 10.0);

            self::assertCount(2, $solutions, $equation);
            self::assertEqualsWithDelta(0.15859433955882, $solutions[0]->value, 1.0E-9, $equation);
            self::assertEqualsWithDelta(3.14619322062058, $solutions[1]->value, 1.0E-9, $equation);
            foreach ($solutions as $solution) {
                self::assertLessThan(1.0E-8, \abs(\log($solution->value) - $solution->value + 2.0), $equation);
            }
        }
    }

    public function testChainedEqualityIntersectsVariableAndConstantRelations(): void
    {
        self::assertSame([], Math::solve('x = 0 = 1', 'x', -2.0, 2.0));
        self::assertSame(
            [-1.0, 1.0],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve('x^2 = 1 = 1', 'x', -2.0, 2.0),
            ),
        );
        self::assertSame([], Math::solve('x^2 = 1 = 2', 'x', -2.0, 2.0));
        self::assertEqualsWithDelta(
            0.3,
            Math::solve('x = 0.1 + 0.2 = 0.3', 'x', 0.0, 1.0)[0]->value,
            1.0E-12,
        );
        self::assertSame(
            [-2.0, 2.0],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve('x^2 = scale = 4', 'x', -3.0, 3.0, ['scale' => 4]),
            ),
        );

        $this->expectException(\InvalidArgumentException::class);
        Math::solve('1 = 1 = 1', 'x', -2.0, 2.0);
    }

    public function testEquationSolverStillRejectsDescendingBounds(): void
    {
        $this->expectException(\InvalidArgumentException::class);
        Math::solve('x = 1', 'x', 2.0, 1.0);
    }

    public function testUnboundedPolynomialEquationsUseACauchySearchBound(): void
    {
        $allReal = Math::solve('x^2 = 2', 'x', -\INF, \INF);
        self::assertCount(2, $allReal);
        self::assertEqualsWithDelta(-\sqrt(2.0), $allReal[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(\sqrt(2.0), $allReal[1]->value, 1.0E-10);

        $equalCoefficientMagnitudes = Math::solve('x^3 + x^2 + 1 = 0', 'x', -\INF, \INF);
        self::assertCount(1, $equalCoefficientMagnitudes);
        self::assertEqualsWithDelta(-1.465571231876768, $equalCoefficientMagnitudes[0]->value, 1.0E-12);

        $largeRoots = Math::solve('x^2 = 1e308', 'x', -\INF, \INF);
        self::assertCount(2, $largeRoots);
        self::assertLessThanOrEqual(
            1.0E-12,
            \abs(($largeRoots[0]->value + \sqrt(1.0E308)) / \sqrt(1.0E308)),
        );
        self::assertLessThanOrEqual(
            1.0E-12,
            \abs(($largeRoots[1]->value - \sqrt(1.0E308)) / \sqrt(1.0E308)),
        );

        $maximumDegreeRoots = Math::solve('x^256 = 2', 'x', -\INF, \INF);
        self::assertCount(2, $maximumDegreeRoots);
        self::assertEqualsWithDelta(-\pow(2.0, 1.0 / 256.0), $maximumDegreeRoots[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(\pow(2.0, 1.0 / 256.0), $maximumDegreeRoots[1]->value, 1.0E-10);

        $positiveHalfLine = Math::solve('x^3 = x', 'x', 0.0, \INF);
        self::assertCount(2, $positiveHalfLine);
        self::assertEqualsWithDelta(0.0, $positiveHalfLine[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(1.0, $positiveHalfLine[1]->value, 1.0E-10);

        $negativeHalfLine = Math::solve('x^3 = x', 'x', -\INF, 0.0);
        self::assertCount(2, $negativeHalfLine);
        self::assertEqualsWithDelta(-1.0, $negativeHalfLine[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(0.0, $negativeHalfLine[1]->value, 1.0E-10);
    }

    public function testPositiveEvenPowerSumDoesNotReturnNumericalNearZeroCandidates(): void
    {
        self::assertSame(
            [],
            Math::solve('sin(x^3)^2 + exp(-x^2) = 0', 'x', -10.0, 10.0),
        );

        $solutions = Math::solve('sin(x)^2 - exp(-x^2) = 0', 'x', -2.0, 2.0);
        self::assertCount(2, $solutions);
        self::assertEqualsWithDelta(-0.8068908147688489, $solutions[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(0.8068908147688489, $solutions[1]->value, 1.0E-10);

        $zeroSet = Math::solve('sin(x)^2 = 0', 'x', -\M_PI, \M_PI);
        self::assertCount(3, $zeroSet);
        self::assertEqualsWithDelta(-\M_PI, $zeroSet[0]->value, 1.0E-12);
        self::assertSame(0.0, $zeroSet[1]->value);
        self::assertEqualsWithDelta(\M_PI, $zeroSet[2]->value, 1.0E-12);

        self::assertSame([], Math::solve('abs(sin(x)) + exp(-x) = 0', 'x', 0.0, 100.0));
        self::assertNotEmpty(Math::solve('abs(sin(x)) - exp(-x) = 0', 'x', 0.0, 10.0));
    }

    public function testSignPruningPreservesMissingVariableValidation(): void
    {
        $this->expectException(\InvalidArgumentException::class);
        Math::solve('4^2 = 0', 'x', -1.0, 1.0);
    }

    public function testKnownRealFunctionRangesPruneStrictlyPositiveSums(): void
    {
        foreach (
            [
                'sqrt(sin(x)) + exp(-x) = 0',
                'hypot(sin(x), cos(x)) + exp(-x) = 0',
                'cosh(x) + exp(-x) = 0',
                'sech(x) + exp(-x) = 0',
            ] as $equation
        ) {
            self::assertSame([], Math::solve($equation, 'x', 0.0, 100.0), $equation);
        }
    }

    public function testSignLatticeKeepsZeroProductsNonStrict(): void
    {
        $solutions = Math::solve('exp(x)*0 + x^2 = 0', 'x', -2.0, 2.0);
        self::assertCount(1, $solutions);
        self::assertSame(0.0, $solutions[0]->value);
        self::assertSame([], Math::solve('exp(x)*0 + x^2 = -1', 'x', -2.0, 2.0));

        $nonnegativeProductRoots = Math::solve('x^2*exp(x) = 0', 'x', -2.0, 2.0);
        self::assertCount(1, $nonnegativeProductRoots);
        self::assertSame(0.0, $nonnegativeProductRoots[0]->value);
        self::assertSame([], Math::solve('x^2/x = 0', 'x', -2.0, 2.0));
        self::assertSame([], Math::solve('x^2/(x^2) = 0', 'x', -2.0, 2.0));
        self::assertCount(1, Math::solve('x^2/(x^2 + 1) = 0', 'x', -2.0, 2.0));
    }

    public function testLargeIntegerExponentParityIsPreservedForNegativeFloatBases(): void
    {
        $options = new EvaluationOptions(
            new ResourceLimits(maxExponentMagnitude: 1.0E16),
        );
        self::assertSame(
            -1.0,
            Math::evaluate('(-x)^9007199254740993', ['x' => 1.0], $options),
        );
        self::assertSame(
            1.0,
            Math::evaluate('(-x)^9007199254740992', ['x' => 1.0], $options),
        );

        $oddExponentRoots = Math::solve(
            '(-1)^9007199254740993*x^2 + exp(-x^2) = 0',
            'x',
            -2.0,
            2.0,
            evaluationOptions: $options,
        );
        self::assertCount(2, $oddExponentRoots);
        self::assertEqualsWithDelta(-0.7530891649948899, $oddExponentRoots[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(0.7530891649948899, $oddExponentRoots[1]->value, 1.0E-10);
        self::assertSame(
            [],
            Math::solve(
                '(-1)^9007199254740992*x^2 + exp(-x^2) = 0',
                'x',
                -2.0,
                2.0,
                evaluationOptions: $options,
            ),
        );
    }

    public function testUnboundedAbsoluteEqualitiesReduceToSignedRationalBranches(): void
    {
        foreach (
            [
                'abs(x) = x^2 - 1' => [-1.618033988749895, 1.618033988749895],
                'x^2 - 1 = abs(x)' => [-1.618033988749895, 1.618033988749895],
                'abs(x) = x^2' => [-1.0, 0.0, 1.0],
            ] as $equation => $expectedRoots
        ) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF);
            self::assertEqualsWithDelta(
                $expectedRoots,
                \array_map(static fn (EquationSolution $solution): float => $solution->value, $solutions),
                1.0E-10,
                $equation,
            );
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-10, $solution->residual, $equation);
            }
        }

        self::assertSame([], Math::solve('abs(x) = -x^2 - 1', 'x', -\INF, \INF));
        self::assertSame([0.0], \array_map(
            static fn (EquationSolution $solution): float => $solution->value,
            Math::solve('abs(x^2) = -x^2', 'x', -\INF, \INF),
        ));
        self::assertSame([], Math::solve('abs(-x^2 - 1) = -x^2 - 1', 'x', -\INF, \INF));

        foreach (
            [
                'abs(1/(x - 1)) = x' => [(1.0 + \sqrt(5.0)) / 2.0],
                'abs(1/(x - 1)) = 1' => [0.0, 2.0],
                'abs((x^2 - 1)/(x - 1)) = 1' => [-2.0, 0.0],
                'abs((x - 1)/(x - 1)) = -1' => [],
            ] as $equation => $expectedRoots
        ) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF);
            self::assertEqualsWithDelta(
                $expectedRoots,
                \array_map(static fn (EquationSolution $solution): float => $solution->value, $solutions),
                1.0E-10,
                $equation,
            );
        }

        foreach (
            [
                'abs(x) = x',
                'abs(x) = -x',
                'abs((x - 1)/(x - 1)) = 1',
                'sin(x)/sin(x) = 1',
                '1 = sin(x)/sin(x)',
                'sin(x)/sin(x) = cos(x)/cos(x)',
                'exp(ln(x))/x = 1',
                'x/exp(ln(x)) = 1',
                '-sin(x)/sin(x) = -1',
                'sin(x)/(-sin(x)) = -1',
                '(x - 1)/(1 - x) = -1',
            ] as $identityEquation
        ) {
            try {
                Math::solve($identityEquation, 'x', -\INF, \INF);
                self::fail('Expected an infinite solution set for ' . $identityEquation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        self::assertSame([], Math::solve('sin(x)/sin(x) = 2', 'x', -3.0, 3.0));
        self::assertSame([], Math::solve('2 = sin(x)/sin(x)', 'x', -3.0, 3.0));
        self::assertSame([], Math::solve('sin(x)/sin(x) = -cos(x)/cos(x)', 'x', -3.0, 3.0));
        self::assertSame([], Math::solve('exp(ln(x))/x = -1', 'x', -3.0, 3.0));
        self::assertSame([], Math::solve('x/exp(ln(x)) = -1', 'x', -3.0, 3.0));
        self::assertSame(
            [],
            Math::solve(
                'exp(ln(x^2-1))/(x^2-1) = 1',
                'x',
                -1.0,
                1.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
        self::assertSame(
            [],
            Math::solve(
                'exp(ln(-x^2-1))/(-x^2-1) = 1',
                'x',
                -\INF,
                \INF,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
        self::assertSame(
            [],
            Math::solve(
                'expm1(log1p(-x^2-2))/(-x^2-2) = 1',
                'x',
                -\INF,
                \INF,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
        try {
            Math::solve(
                'expm1(log1p(0*x-0.5))/(0*x-0.5) = 1',
                'x',
                -\INF,
                \INF,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::fail('Expected the defined constant quotient to have infinitely many solutions.');
        } catch (InfiniteSolutionSetException) {
            self::assertTrue(true);
        }
        self::assertSame(
            [],
            Math::solve(
                'expm1(log1p(0*x-2))/(0*x-2) = 1',
                'x',
                -\INF,
                \INF,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
        try {
            Math::solve(
                'expm1(log1p(x^2-2))/(x^2-2) = 1',
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::fail('Expected an infinite solution set on the nonempty log1p domain.');
        } catch (InfiniteSolutionSetException) {
            self::assertTrue(true);
        }
        self::assertSame(
            [],
            Math::solve(
                'erf(erfinv(x^2))/x^2 = 1',
                'x',
                -2.0,
                -1.1,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
        self::assertSame(
            [],
            Math::solve(
                'sin(asin(x^2))/x^2 = 1',
                'x',
                1.1,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
        self::assertSame(
            [],
            Math::solve(
                'sin(asin(x^2))/x^2 = 1',
                'x',
                2.0,
                \INF,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
        self::assertSame(
            [[1.0, 0.0]],
            \array_map(
                static fn (EquationSolution $solution): array => [$solution->value, $solution->residual],
                Math::solve(
                    'sin(asin(x^2))/x^2 = 1',
                    'x',
                    1.0,
                    \INF,
                    solverOptions: new SolverOptions(scanSteps: 1),
                ),
            ),
        );
        self::assertSame(
            [],
            Math::solve(
                'erf(erfinv(x^2))/x^2 = 1',
                'x',
                1.0,
                \INF,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
        foreach (
            [
                'erf(erfinv(x))/x = 1',
                'tanh(atanh(x))/x = 1',
            ] as $narrowDomainIdentity
        ) {
            try {
                Math::solve(
                    $narrowDomainIdentity,
                    'x',
                    -2.0,
                    -0.9,
                    solverOptions: new SolverOptions(scanSteps: 1),
                );
                self::fail('Expected infinitely many roots on the restricted-domain overlap.');
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }
        $includedDomainEndpoint = Math::solve(
            'sin(asin(x))/x = 1',
            'x',
            -2.0,
            -1.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertSame([-1.0], \array_map(
            static fn (EquationSolution $solution): float => $solution->value,
            $includedDomainEndpoint,
        ));
        self::assertSame([], Math::solve('-sin(x)/sin(x) = 1', 'x', -3.0, 3.0));
        self::assertSame([], Math::solve('sin(x)/(-sin(x)) = 1', 'x', -3.0, 3.0));
    }

    public function testUnboundedRationalPowerEquationsUseExactPolynomialReduction(): void
    {
        foreach (
            [
                ['x^(2/3) = 4', [-8.0, 8.0]],
                ['x^(2/3) = 0', [0.0]],
                ['x^(-2/3) = 4', [-0.125, 0.125]],
                ['x^(3/2) = 8', [4.0]],
                ['x^(3/2) = -8', []],
                ['(x - 1)^(2/3) = 4', [-7.0, 9.0]],
            ] as [$equation, $expectedRoots]
        ) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF);
            self::assertEqualsWithDelta(
                $expectedRoots,
                \array_map(
                    static fn (EquationSolution $solution): float => $solution->value,
                    $solutions,
                ),
                1.0E-10,
                $equation,
            );
        }
    }

    public function testUnboundedRootFunctionsUseRationalPowerReduction(): void
    {
        foreach (
            [
                ['sqrt(x) = x - 2', [4.0]],
                ['sqrt(x) = x', [0.0, 1.0]],
                ['sqrt(x) = -1', []],
                ['cbrt(x) = x', [-1.0, 0.0, 1.0]],
                ['root(x, 3) = x', [-1.0, 0.0, 1.0]],
                ['root(x, 2) = 2', [4.0]],
            ] as [$equation, $expectedRoots]
        ) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF);
            self::assertEqualsWithDelta(
                $expectedRoots,
                \array_map(
                    static fn (EquationSolution $solution): float => $solution->value,
                    $solutions,
                ),
                1.0E-10,
                $equation,
            );
        }
    }

    public function testUnboundedSumsOfRationalPowersUsePolynomialElimination(): void
    {
        foreach (
            [
                ['x^(2/3) + x^(1/3) = 2', [-8.0, 1.0]],
                ['sqrt(x) + cbrt(x) = 2', [1.0]],
                ['sqrt(x) + x^(1/3) = 2', [1.0]],
                ['sqrt(x) + sqrt(x + 1) = 3', [16.0 / 9.0]],
                ['cbrt(x) + cbrt(x + 1) + cbrt(x + 2) = 3', [0.23688307980127202]],
            ] as [$equation, $expectedRoots]
        ) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF);
            self::assertEqualsWithDelta(
                $expectedRoots,
                \array_map(
                    static fn (EquationSolution $solution): float => $solution->value,
                    $solutions,
                ),
                1.0E-9,
                $equation,
            );
        }
    }

    public function testUnboundedLambertWProductEquationsReturnEveryRealBranch(): void
    {
        foreach (
            [
                ['x*exp(x) = 1', [0.567143290409784]],
                ['x*exp(x) = -0.1', [-3.577152063957297, -0.11183255915896298]],
                ['(2*x + 1)*exp(3*x) = 2', [0.14577041238466582]],
            ] as [$equation, $expectedRoots]
        ) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF);
            self::assertEqualsWithDelta(
                $expectedRoots,
                \array_map(
                    static fn (EquationSolution $solution): float => $solution->value,
                    $solutions,
                ),
                1.0E-10,
                $equation,
            );
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-8, $solution->residual, $equation);
            }
        }
    }

    public function testUnboundedRationalEquationsPreserveDenominatorHoles(): void
    {
        $solutions = Math::solve(
            '(x^2 - 1)/(x - 1) = 2',
            'x',
            -\INF,
            \INF,
        );

        self::assertSame([], $solutions);
    }

    public function testUnboundedNonRationalEquationIsRejectedExplicitly(): void
    {
        try {
            Math::solve('sin(exp(x) + x*sin(x)) = 0', 'x', -\INF, \INF);
            self::fail('An unbounded periodic equation cannot return a finite root list.');
        } catch (\InvalidArgumentException $exception) {
            self::assertStringContainsString('exact rational-function', $exception->getMessage());
        }
    }

    public function testUnboundedRationalPeriodicPhasesReportPoleAccumulation(): void
    {
        foreach (
            [
                ['sin(1/x) = 0', -\INF, \INF],
                ['cos(1/(x - 2)) = 0.5', 0.0, 4.0],
                ['tan(1/(x + 1)) = 1', -\INF, 0.0],
            ] as [$equation, $lowerBound, $upperBound]
        ) {
            try {
                Math::solve($equation, 'x', $lowerBound, $upperBound);
                self::fail('Expected infinitely many roots accumulating at a rational pole: ' . $equation);
            } catch (InfiniteRootAccumulationException) {
                self::assertTrue(true);
            }
        }
    }

    public function testUnboundedBoundedRationalPeriodicPhasesReturnFiniteRoots(): void
    {
        $expected = [2.0 - \sqrt(3.0), 2.0 + \sqrt(3.0)];
        $sineRoots = Math::solve('sin(x/(1 + x^2)) = sin(0.25)', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            $expected,
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $sineRoots),
            1.0E-10,
        );

        $tangentRoots = Math::solve('tan(x/(1 + x^2)) = 0.25', 'x', -\INF, \INF);
        $tangentPhase = \atan(0.25);
        $tangentDiscriminant = \sqrt(1.0 - (4.0 * $tangentPhase * $tangentPhase));
        $tangentExpected = [
            (1.0 - $tangentDiscriminant) / (2.0 * $tangentPhase),
            (1.0 + $tangentDiscriminant) / (2.0 * $tangentPhase),
        ];
        self::assertEqualsWithDelta(
            $tangentExpected,
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $tangentRoots),
            1.0E-10,
        );

        $zeroRoots = Math::solve('sin(x/(1 + x^2)) = 0', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [0.0],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $zeroRoots),
            1.0E-12,
        );

        $positiveHalfLineRoots = Math::solve(
            'sin(x/(1 + x^2)) = sin(0.25)',
            'x',
            0.0,
            \INF,
        );
        self::assertEqualsWithDelta(
            $expected,
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                $positiveHalfLineRoots,
            ),
            1.0E-10,
        );

        $equalDegreeLimitRoots = Math::solve(
            'sin(x^2/(1 + x^2)) = sin(0.75)',
            'x',
            -\INF,
            \INF,
        );
        self::assertEqualsWithDelta(
            [-\sqrt(3.0), \sqrt(3.0)],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                $equalDegreeLimitRoots,
            ),
            1.0E-10,
        );

        foreach (
            [
                ['sec(x/(1 + x^2)) = 1/cos(0.4)', [-2.0, -0.5, 0.5, 2.0]],
                ['csc(x/(1 + x^2)) = 1/sin(0.4)', [0.5, 2.0]],
                ['cot(x/(1 + x^2)) = 1/tan(0.4)', [0.5, 2.0]],
            ] as [$equation, $expectedRoots]
        ) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF);
            self::assertEqualsWithDelta(
                $expectedRoots,
                \array_map(
                    static fn (EquationSolution $solution): float => $solution->value,
                    $solutions,
                ),
                1.0E-10,
                $equation,
            );
        }

        foreach (
            [
                'sin((x^2 - 1)/(x - 1)) = 0',
                'cos((x^2 + 1)/(x + 1)) = 0',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', -\INF, \INF);
                self::fail('The rational phase grows without bound: ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        self::assertSame(
            [],
            Math::solve('sin((x^2 - 1)/(x - 1)) = 2', 'x', -\INF, \INF),
        );
    }

    public function testUnboundedExponentialPolynomialTrigonometricPhasesReportInfiniteRoots(): void
    {
        foreach (
            [
                'sin(exp(x) + x) = 0',
                'sin(3*exp(x) - exp(x) + x^2) = 0',
                'sin(exp(x^2) + exp(x) + x) = 0',
                'sin(exp(x^2) + exp(x^2 + 1) + x) = 0',
                'sin(exp(x^2 + 1) + exp(x^2) - exp(x^2) + x) = 0',
                'cos(exp(x^2) - exp(2*x^2) + x^4) = 0',
                'sin(exp(x^2) - exp(x^2) + x) = 0',
                'sin(exp(x^2) - exp(x^2) + exp(x) + x) = 0',
                'sin(exp(-x) + x) = 0',
                'cos(2*exp(x^2) - x^4) = 0.5',
                'tan(-exp(-x) + x^3) = 1',
            ] as $equation
        ) {
            try {
