    }

    public function testUnboundedLogarithmicExponentialTrigonometricPhasesRespectLogDomain(): void
    {
        foreach (
            [
                'sin(ln(exp(x) + 1)) = 0',
                'cos(ln(exp(x) - 1)) = 0.5',
                'tan(ln(exp(-x) + 2)) = 1',
                'sin(log2(exp(x) + 1)) = 0',
                'cos(log(exp(x) + 1, 0.5)) = 0',
                'tan(log1p(exp(x))) = 1',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', -\INF, \INF);
                self::fail('Expected infinitely many roots as the logarithmic phase diverges: ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        try {
            Math::solve('sin(ln(-exp(x) + x)) = 0', 'x', -\INF, \INF);
            self::fail('The logarithm argument is negative on both unbounded tails.');
        } catch (\InvalidArgumentException $exception) {
            self::assertStringContainsString('exact rational-function', $exception->getMessage());
        }

        foreach (
            [
                'sin(ln(exp(-x))) = 0',
                'cos(ln(exp(-x) + exp(-2*x))) = 0.5',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', 0.0, \INF);
                self::fail('The positive logarithm argument approaches zero: ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        foreach (
            [
                ['sin(1/ln(exp(x) + 1)) = 0', -\INF, \INF],
                ['cos(1/ln(exp(-x) + 1)) = 0', -\INF, \INF],
                ['sin(1/ln(1 + 1/x^2)) = 0', -\INF, \INF],
                ['cos(1/ln(1 - 1/x^2)) = 0', -\INF, \INF],
                ['tan(1/log1p(1/x^2)) = 1', -\INF, \INF],
                ['sin(1/ln(1 + exp(-x^2))) = 0', -\INF, \INF],
                ['cos(1/ln(1 - exp(-x^2))) = 0', -\INF, \INF],
                ['tan(2/log1p(exp(-x))) = 1', 0.0, \INF],
            ] as [$equation, $lowerBound, $upperBound]
        ) {
            try {
                Math::solve($equation, 'x', $lowerBound, $upperBound);
                self::fail('The reciprocal logarithmic phase diverges: ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        try {
            Math::solve('sin(1/ln(exp(x) + 2)) = 0', 'x', -\INF, \INF);
            self::fail('The logarithm denominator does not approach zero on either tail.');
        } catch (\InvalidArgumentException $exception) {
            self::assertStringContainsString('exact rational-function', $exception->getMessage());
        }

        try {
            Math::solve('sin(1/ln(2 + 1/x^2)) = 0', 'x', -\INF, \INF);
            self::fail('The rational logarithm denominator tends to a nonzero finite value.');
        } catch (\InvalidArgumentException $exception) {
            self::assertStringContainsString('exact rational-function', $exception->getMessage());
        }
    }

    public function testUnboundedLogarithmsCanMatchReciprocalArguments(): void
    {
        $positiveLevel = Math::solve('ln(x) = 1/x', 'x', -\INF, \INF);
        self::assertCount(1, $positiveLevel);
        self::assertEqualsWithDelta(1.7632228343518967, $positiveLevel[0]->value, 1.0E-10);
        self::assertLessThanOrEqual(1.0E-10, $positiveLevel[0]->residual);
        $reversed = Math::solve('1/x = ln(x)', 'x', -\INF, \INF);
        self::assertCount(1, $reversed);
        self::assertEqualsWithDelta($positiveLevel[0]->value, $reversed[0]->value, 1.0E-10);

        $affineArgument = Math::solve(
            'ln(2*x + 3) = 1/(2*x + 3)',
            'x',
            -\INF,
            \INF,
        );
        self::assertCount(1, $affineArgument);
        self::assertEqualsWithDelta(-0.6183885828240517, $affineArgument[0]->value, 1.0E-10);

        $differentAffineDenominator = Math::solve('ln(x) = 1/(x + 1)', 'x', -\INF, \INF);
        self::assertCount(1, $differentAffineDenominator);
        self::assertEqualsWithDelta(1.493404088774696, $differentAffineDenominator[0]->value, 1.0E-9);
        self::assertLessThanOrEqual(1.0E-10, $differentAffineDenominator[0]->residual);

        $scaledAffineArgument = Math::solve(
            'ln(2*x + 1) = 1/(x + 1)',
            'x',
            -\INF,
            \INF,
        );
        self::assertCount(1, $scaledAffineArgument);
        self::assertEqualsWithDelta(0.48185114440275356, $scaledAffineArgument[0]->value, 1.0E-9);

        $criticalPointPartitions = Math::solve('ln(x) = -100/(x + 1)', 'x', -\INF, \INF);
        self::assertCount(1, $criticalPointPartitions);
        self::assertEqualsWithDelta(-100.0, \log($criticalPointPartitions[0]->value), 1.0E-8);
        self::assertLessThanOrEqual(1.0E-8, $criticalPointPartitions[0]->residual);

        $largeAffineRationalLevel = Math::solve('ln(x) = 100*x/(x + 1)', 'x', -\INF, \INF);
        self::assertCount(1, $largeAffineRationalLevel);
        self::assertEqualsWithDelta(100.0, \log($largeAffineRationalLevel[0]->value), 1.0E-8);

        $poleSeparatedBranches = Math::solve('ln(x) = 1/(x - 1)', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [0.259246356668882, 2.2399778875987977],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $poleSeparatedBranches),
            1.0E-9,
        );
        foreach ($poleSeparatedBranches as $solution) {
            self::assertLessThanOrEqual(2.0E-10, $solution->residual);
        }
        self::assertSame([], Math::solve('ln(x) = 1/(1 - x)', 'x', -\INF, \INF));

        $shiftedTarget = Math::solve('ln(x) = 1/x + 1', 'x', -\INF, \INF);
        self::assertCount(1, $shiftedTarget);
        self::assertEqualsWithDelta(3.5911214766686226, $shiftedTarget[0]->value, 1.0E-10);
        self::assertLessThanOrEqual(1.0E-10, $shiftedTarget[0]->residual);

        $shiftedTwoBranchTarget = Math::solve('ln(x) = -1/x + 2', 'x', -\INF, \INF);
        self::assertCount(2, $shiftedTwoBranchTarget);
        foreach ($shiftedTwoBranchTarget as $solution) {
            self::assertGreaterThan(0.0, $solution->value);
            self::assertLessThanOrEqual(1.0E-10, $solution->residual);
        }

        $negativeLevel = Math::solve('ln(x) = -0.1/x', 'x', -\INF, \INF);
        self::assertCount(2, $negativeLevel);
        self::assertGreaterThan(0.0, $negativeLevel[0]->value);
        self::assertGreaterThan(0.0, $negativeLevel[1]->value);
        foreach ($negativeLevel as $solution) {
            self::assertLessThanOrEqual(1.0E-10, $solution->residual);
        }

        self::assertSame([], Math::solve('ln(x) = -1/x', 'x', -\INF, \INF));
    }

    public function testUnboundedLogarithmsCanMatchQuadraticRationalTargets(): void
    {
        $noPoleTarget = Math::solve('ln(x) = 1/(x^2 + 1)', 'x', -\INF, \INF);
        self::assertCount(1, $noPoleTarget);
        self::assertEqualsWithDelta(1.4013216221876097, $noPoleTarget[0]->value, 1.0E-8);
        self::assertLessThanOrEqual(1.0E-9, $noPoleTarget[0]->residual);

        $poleSeparatedTarget = Math::solve('ln(x) = 1/(x^2 - 1)', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [0.3265007878425261, 1.6990090340405786],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $poleSeparatedTarget),
            1.0E-8,
        );
        foreach ($poleSeparatedTarget as $solution) {
            self::assertLessThanOrEqual(1.0E-9, $solution->residual);
        }

        $quadraticNumerator = Math::solve('ln(x) = x/(x^2 + 1)', 'x', -\INF, \INF);
        self::assertCount(1, $quadraticNumerator);
        self::assertEqualsWithDelta(1.5726895059065638, $quadraticNumerator[0]->value, 1.0E-8);
        self::assertLessThanOrEqual(1.0E-9, $quadraticNumerator[0]->residual);

        $quarticDenominator = Math::solve('ln(x) = 1/(x^4 + 1)', 'x', -\INF, \INF);
        self::assertCount(1, $quarticDenominator);
        self::assertEqualsWithDelta(1.2977723640215117, $quarticDenominator[0]->value, 1.0E-8);
        self::assertLessThanOrEqual(1.0E-9, $quarticDenominator[0]->residual);

        $octicDenominator = Math::solve('ln(x) = 1/(x^8 + 1)', 'x', -\INF, \INF);
        self::assertCount(1, $octicDenominator);
        self::assertEqualsWithDelta(1.2034514036786277, $octicDenominator[0]->value, 1.0E-8);
        self::assertLessThanOrEqual(1.0E-9, $octicDenominator[0]->residual);

        $stationaryRoot = Math::solve('ln(x) = 2*(x - 1)/(x^4 + 1)', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [0.2041360378543511, 1.0],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $stationaryRoot),
            1.0E-8,
        );
        foreach ($stationaryRoot as $solution) {
            self::assertLessThanOrEqual(1.0E-9, $solution->residual);
        }

        $growingTarget = Math::solve('ln(x) = -x^4', 'x', -\INF, \INF);
        self::assertCount(1, $growingTarget);
        self::assertEqualsWithDelta(0.7404168294710746, $growingTarget[0]->value, 1.0E-8);
        self::assertLessThanOrEqual(1.0E-9, $growingTarget[0]->residual);
        self::assertSame([], Math::solve('ln(x) = x^4', 'x', -\INF, \INF));
        self::assertSame([], Math::solve('ln(x) = x^4/(1 - x)', 'x', -\INF, \INF));
    }

    public function testUnboundedLogarithmsWithDecreasingAffineArgumentsAreReflected(): void
    {
        foreach (
            [
                'ln(3 - 2*x) = 1/((3 - 2*x)^2 + 1)',
