        );
        foreach ($poleSeparated as $solution) {
            self::assertLessThanOrEqual(1.0E-9, $solution->residual);
        }
    }

    public function testUnboundedPiecewisePeriodicLevelsAreReducedWithoutFiniteWindowSampling(): void
    {
        foreach (
            [
                'min(sin(x), 0) = -0.5',
                'max(cos(2*x), 0) = 0.5',
                'min(sin(x^2), 0) = -0.5',
                'max(tan(x), 0) = 1',
                'min(abs(sin(x)), 0.5) = 0.25',
                'max(abs(sec(x)), 2) = 2',
                'min(sin(x), 0) = 0',
                'max(sin(x), 0) = 0',
                'min(sec(x), 2) = 2',
                'max(csc(x), -2) = -2',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', -\INF, \INF, solverOptions: new SolverOptions(scanSteps: 1));
                self::fail('Expected infinitely many roots for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        foreach (
            [
                'min(sin(x), 0) = 2',
                'max(cos(x), 0) = -1',
                'min(sin(x), 2) = 2',
                'max(sin(x), -2) = -2',
                'min(abs(sin(x)), 2) = 2',
                'max(abs(sec(x)), 0) = 0',
            ] as $equation
        ) {
            self::assertSame(
                [],
                Math::solve($equation, 'x', -\INF, \INF, solverOptions: new SolverOptions(scanSteps: 1)),
                $equation,
            );
        }
    }

    public function testUnboundedExponentialTrigonometricPhasesReportInfiniteRoots(): void
    {
        foreach (
            [
                'sin(exp(x)) = 1',
                'sin(exp(-x)) = 0.5',
                'cos(exp(2*x + 1)) = 0',
                'tan(exp(-3*x)) = 2',
                'sin(2*exp(x) + 1) = 0.25',
                'cos(3 - exp(-x)) = 0',
                'tan(2*exp(2*x) - 10) = 2',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', -\INF, \INF);
                self::fail('An unbounded exponential phase has infinitely many periodic roots: ' . $equation);
            } catch (InfiniteSolutionSetException) {
