            }
        }

        self::assertSame([], Math::solve('sin(exp(x)) = 2', 'x', -\INF, \INF));
    }

    public function testOneSidedUnboundedExponentialTrigonometricPhasesRespectGrowthDirection(): void
    {
        foreach (
            [
                ['sin(exp(x)) = 1', 0.0, \INF],
                ['sin(exp(-x)) = 0.5', -\INF, 0.0],
                ['cos(2*exp(3*x) - 1) = 0', 0.0, \INF],
                ['tan(4 - exp(-2*x)) = 1', -\INF, 0.0],
            ] as [$equation, $lowerBound, $upperBound]
        ) {
            try {
                Math::solve($equation, 'x', $lowerBound, $upperBound);
                self::fail('An exponential phase grows without bound on this half-line: ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        foreach (
            [
                ['sin(exp(-x)) = 0.5', 0.0, \INF, [-\log(\asin(0.5))]],
                ['cos(exp(x)) = 0', -\INF, 0.0, []],
                [
                    'cos(2*exp(-x) + 1) = 0',
                    0.0,
                    \INF,
                    [-\log((\M_PI / 2.0 - 1.0) / 2.0)],
                ],
                ['csc(exp(-x)) = 2', 0.0, \INF, [-\log(\M_PI / 6.0)]],
                ['cot(exp(-x)) = 1', 0.0, \INF, [-\log(\M_PI / 4.0)]],
                ['sec(exp(-x)) = 2', 0.0, \INF, []],
                ['sin(exp(-x)) = sin(1)', 0.0, \INF, [0.0]],
                ['sin(-exp(-x)) = -0.5', 0.0, \INF, [-\log(\M_PI / 6.0)]],
            ] as [$equation, $lowerBound, $upperBound, $expectedRoots]
        ) {
            $solutions = Math::solve($equation, 'x', $lowerBound, $upperBound);
            self::assertEqualsWithDelta(
                $expectedRoots,
                \array_map(static fn (EquationSolution $solution): float => $solution->value, $solutions),
                1.0E-10,
                $equation,
            );
        }
    }

    public function testPolynomialExponentialPhasesEnumerateBoundedPeriodicLevels(): void
    {
        $principal = \asin(0.5);
        $roots = Math::solve('sin(exp(-x^2)) = 0.5', 'x', -\INF, \INF);
        $expectedMagnitude = \sqrt(-\log($principal));
        self::assertEqualsWithDelta(
            [-$expectedMagnitude, $expectedMagnitude],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $roots),
            1.0E-10,
        );

        $tangentRoot = Math::solve('cos(exp(-x^2)) = cos(1)', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [0.0],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $tangentRoot),
            1.0E-12,
        );

        $shiftedRoots = Math::solve('sin(2*exp(-x^2) + 1) = 0.25', 'x', -\INF, \INF);
        $shiftedPhase = \M_PI - \asin(0.25);
        $shiftedMagnitude = \sqrt(-\log(($shiftedPhase - 1.0) / 2.0));
        self::assertEqualsWithDelta(
            [-$shiftedMagnitude, $shiftedMagnitude],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $shiftedRoots),
            1.0E-10,
        );

        $quarticLevel = Math::solve(
            'sin(exp(-(x^2 - 1)^2)) = sin(exp(-1))',
            'x',
            -\INF,
            \INF,
        );
        self::assertEqualsWithDelta(
            [-\sqrt(2.0), 0.0, \sqrt(2.0)],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $quarticLevel),
            1.0E-9,
        );

        $multipleTangencies = Math::solve(
            'cos(exp(-(x^2 - 1)^2)) = cos(1)',
            'x',
            -\INF,
            \INF,
        );
        self::assertEqualsWithDelta(
            [-1.0, 1.0],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $multipleTangencies),
            1.0E-9,
        );
        self::assertSame([], Math::solve('sin(exp(-x^2)) = 2', 'x', -\INF, \INF));

        try {
            Math::solve('sin(exp(x^2)) = 1', 'x', -\INF, \INF);
            self::fail('A growing polynomial exponential phase has infinitely many periodic roots.');
        } catch (InfiniteSolutionSetException) {
            self::assertTrue(true);
        }

    }

    public function testUnboundedPolynomialTrigPhaseCrossesInteriorRationalLimitsInfinitelyOften(): void
    {
