    public function testUnboundedPolynomialTrigWithRationalTargetRestrictsToFiniteFeasibleRegions(): void
    {
        $solutions = Math::solve(
            'cos(x^2) = (2*x^2) / (1 + x^2)',
            'x',
            -\INF,
            \INF,
        );

        self::assertCount(2, $solutions);
        self::assertEqualsWithDelta(-0.804, $solutions[0]->value, 0.01);
        self::assertEqualsWithDelta(0.804, $solutions[1]->value, 0.01);
        foreach ($solutions as $solution) {
            self::assertLessThanOrEqual(1.0E-8, $solution->residual);
        }

        $infiniteAsymptoteSolution = Math::solve(
            'cos(x^2) = x^2 / x',
            'x',
            -\INF,
            \INF,
        );
        self::assertCount(1, $infiniteAsymptoteSolution);
        self::assertEqualsWithDelta(0.8010707652, $infiniteAsymptoteSolution[0]->value, 1.0E-8);

        self::assertSame(
            [],
            Math::solve('sin(x^2) = 2 + 1 / (1 + x^2)', 'x', -\INF, \INF),
        );

        $removableHoleSolutions = Math::solve(
            'cos((x - 1)^2) = (x^2 - 1) / (x - 1) - 1',
            'x',
            -\INF,
            \INF,
        );
        self::assertCount(2, $removableHoleSolutions);
        foreach ($removableHoleSolutions as $solution) {
            self::assertNotEqualsWithDelta(1.0, $solution->value, 1.0E-8);
            self::assertLessThanOrEqual(1.0E-8, $solution->residual);
        }
    }

