    public function testUnboundedSecantAndCosecantWithRationalTargetsRespectTheirRanges(): void
    {
        foreach (
            [
                'sec(x^2) = 2 + 1 / (1 + x^2)',
                'csc(x^2) = 2',
                'sec(x^2) = x',
                'sec(x^2) = 1 + 1 / (1 + x^2)',
                'csc(x^2) = -1 - 1 / (1 + x^2)',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', 0.0, \INF);
                self::fail('Expected infinitely many reciprocal-trigonometric roots: ' . $equation);
            } catch (InfiniteSolutionSetException $exception) {
                self::assertStringContainsString('infinitely many', $exception->getMessage());
            }
        }

        $boundaryRoot = Math::solve('sec(x^2) = 1 / (1 + x^2)', 'x', 0.0, \INF);
        self::assertCount(1, $boundaryRoot);
        self::assertSame(0.0, $boundaryRoot[0]->value);

        self::assertSame(
            [],
            Math::solve('csc(x^2) = x / (1 + x^2)', 'x', 0.0, \INF),
        );
        self::assertSame(
            [],
            Math::solve('sec(x^2) = 1 - 1 / (1 + x^2)', 'x', 0.0, \INF),
        );
        self::assertSame(
            [],
            Math::solve('csc(x^2) = -1 + 1 / (1 + x^2)', 'x', 0.0, \INF),
        );
    }

    public function testScaledUnboundedTrigonometricFunctionsNormalizeRationalTargets(): void
    {
        foreach (
            [
                '2 * sec(x^2) = 4',
                '2 * sin(x^2) = 1 / (1 + x^2)',
                '-2 * csc(x^2) = 4',
                '3 + 2 * sec(x^2) = 7',
                '2 + 3 * sin(x^2) = 2 + 3 / (1 + x^2)',
                '2 - 3 * sec(x^2) = -4',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', 0.0, \INF);
                self::fail('Expected infinitely many roots for ' . $equation);
            } catch (InfiniteSolutionSetException $exception) {
                self::assertStringContainsString('infinitely many', $exception->getMessage());
            }
        }

        $finiteRoot = Math::solve('2 * sec(x^2) = 2 / (1 + x^2)', 'x', 0.0, \INF);
        self::assertCount(1, $finiteRoot);
        self::assertSame(0.0, $finiteRoot[0]->value);

        $offsetFiniteRoot = Math::solve(
            '1 + sec(x^2) = 1 + 1 / (1 + x^2)',
            'x',
            0.0,
            \INF,
        );
        self::assertCount(1, $offsetFiniteRoot);
        self::assertSame(0.0, $offsetFiniteRoot[0]->value);

        $scaledOffsetFiniteRoot = Math::solve(
            '3 + 2 * sec(x^2) = 3 + 2 / (1 + x^2)',
            'x',
            0.0,
            \INF,
        );
        self::assertCount(1, $scaledOffsetFiniteRoot);
        self::assertSame(0.0, $scaledOffsetFiniteRoot[0]->value);
    }

    public function testPolynomialOffsetsWithUnboundedTrigonometricRationalTargets(): void
    {
        foreach (
            [
                'sin(x^2) + x^2 = 1 / (1 + x^2)' => 0.6077130759,
                'sin(x^2) + x = 1 / (1 + x^2)' => 0.5200138776,
                'x^2 - sin(x^2) = 1 / (1 + x^2)' => 1.1841059297,
