    public function testUnboundedCommensurateTrigonometricSumsUsePeriodicWitnesses(): void
    {
        foreach (
            [
                'sin(x^2) + sin(2*x^2) = 1 / (1 + x^2)',
                'sin(x^2) + sin(3*x^2/2) = 1 / (1 + x^2)',
                'sin(x^2) + cos(2*x^2 + pi / 3) = 1 / (1 + x^2)',
                'sin(x^2) + cos(3*x^2/2 + pi / 4) = 1 / (1 + x^2)',
                '2 * (sin(x^2) + sin(2*x^2)) + 3 = 3 + 1 / (1 + x^2)',
                'sin(x^2) + sin(2*x^2) = 0',
                'sin(x^2) * cos(2*x^2) = 1 / (1 + x^2)',
                'sin(x^2) * sin(2*x^2) = 1 / (1 + x^2)',
                '(sin(x^2) + 0.5) * cos(2*x^2) = 0.25 / (1 + x^2)',
                'sin(x^2) * sin(x^2) = 1 / (2 + x^2)',
                'sin(x^2)^2 = 1 / (2 + x^2)',
                'sin(x^2)^3 = 1 / (2 + x^2)',
                'sin(x^2)^4 = 1 / (2 + x^2)',
                'cos(x^2)^6 = 1 / (2 + x^2)',
                '2 * sin(x^2)^4 = 1 / (2 + x^2)',
                '-2 * sin(x^2)^4 = -1 / (2 + x^2)',
                '3 + 2 * sin(x^2)^4 = 3 + 1 / (2 + x^2)',
                '3 - 2 * sin(x^2)^4 = 3 - 1 / (2 + x^2)',
                'sin(x^2)^4 / (1 + x^2) = 1 / (2 + x^2)',
                'sin(x^2)^4 / (1 + x^2) = 0',
                'sin(x^2)^4 / (1 + x^2) = 1 / (1 + x^2)',
                'sin(x^2)^4 / (x - 1) = 1 / (1 + x^2)',
                'sin(x^2)^3 = (x - 1) / (x + 1)',
                'sin(x^2)^3 = 1 - 1 / (1 + x^2)',
                'cos(x^2) * cos(x^2) = 1 - 1 / (1 + x^2)',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', 0.0, \INF);
                self::fail('Periodic witnesses straddle the target limit for ' . $equation);
            } catch (InfiniteSolutionSetException $exception) {
                self::assertStringContainsString('infinitely many', $exception->getMessage());
            }
        }

        try {
            Math::solve('cos(x^3 + 2)^4 = 1 / (2 + x^2)', 'x', -\INF, 0.0);
            self::fail('The negative infinite tail still crosses the positive target.');
        } catch (InfiniteSolutionSetException $exception) {
            self::assertStringContainsString('infinitely many', $exception->getMessage());
        }

        $finiteSolutions = Math::solve(
            'sin(x^2) + sin(2*x^2) = 3 - 4 / (1 + x^2)',
            'x',
            0.0,
            \INF,
        );
        self::assertCount(1, $finiteSolutions);
        self::assertGreaterThan(0.0, $finiteSolutions[0]->value);
        self::assertLessThan(\sqrt(3.0), $finiteSolutions[0]->value);
        self::assertLessThanOrEqual(1.0E-8, $finiteSolutions[0]->residual);

        $rationalHarmonicSolution = Math::solve(
            'sin(x^2) + sin(3*x^2/2) = 3 - 4 / (1 + x^2)',
            'x',
            0.0,
            \INF,
        );
        self::assertCount(1, $rationalHarmonicSolution);
        self::assertLessThan(\sqrt(3.0), $rationalHarmonicSolution[0]->value);
        self::assertLessThanOrEqual(1.0E-8, $rationalHarmonicSolution[0]->residual);

        $productSolution = Math::solve(
            'sin(x^2) * cos(2*x^2) = 3 - 4 / (1 + x^2)',
            'x',
            0.0,
            \INF,
        );
        self::assertCount(1, $productSolution);
        self::assertLessThan(\sqrt(3.0), $productSolution[0]->value);
        self::assertLessThanOrEqual(1.0E-8, $productSolution[0]->residual);

        $finiteEvenPowerSolutions = Math::solve(
            'sin(x^2)^4 = 0.1 * (1 + x^2)',
            'x',
            0.0,
            \INF,
        );
        self::assertCount(6, $finiteEvenPowerSolutions);
        foreach ($finiteEvenPowerSolutions as $solution) {
            self::assertLessThan(3.0, $solution->value);
            self::assertLessThanOrEqual(1.0E-8, $solution->residual);
        }
        $finiteOddPowerSolutions = Math::solve(
            'sin(x^2)^3 = 0.1 * (1 + x^2)',
            'x',
            0.0,
            \INF,
        );
        self::assertCount(4, $finiteOddPowerSolutions);
        foreach ($finiteOddPowerSolutions as $solution) {
            self::assertLessThan(3.0, $solution->value);
            self::assertLessThanOrEqual(1.0E-8, $solution->residual);
        }

        self::assertSame(
            [],
            Math::solve('sin(x^2) + sin(2*x^2) = 3 + 1 / (1 + x^2)', 'x', 0.0, \INF),
        );
        self::assertSame(
            [],
            Math::solve('sin(x^2) * cos(2*x^2) = 3 + 1 / (1 + x^2)', 'x', 0.0, \INF),
        );
        self::assertSame(
            [],
            Math::solve('sin(x^2)^4 = (x + 1) / (x - 1)', 'x', 0.0, \INF),
        );
        self::assertSame(
            [],
            Math::solve('sin(x^2)^3 = (x + 1) / (x - 1)', 'x', 0.0, \INF),
        );
        self::assertSame(
            [],
            Math::solve('sin(x^2)^3 = -1 - 1 / (1 + x^2)', 'x', 0.0, \INF),
        );
        self::assertSame(
            [],
            Math::solve('sin(x^2)^4 = -1 / (2 + x^2)', 'x', 0.0, \INF),
        );
        self::assertSame(
            [],
            Math::solve('2 * sin(x^2)^4 = -1 / (2 + x^2)', 'x', 0.0, \INF),
        );
        self::assertSame(
            [],
            Math::solve('-2 * sin(x^2)^4 = 1 / (2 + x^2)', 'x', 0.0, \INF),
        );
        self::assertSame(
            [],
            Math::solve('3 + 2 * sin(x^2)^4 = 3 - 1 / (2 + x^2)', 'x', 0.0, \INF),
        );
        self::assertSame(
            [],
            Math::solve('3 - 2 * sin(x^2)^4 = 3 + 1 / (2 + x^2)', 'x', 0.0, \INF),
        );
        self::assertSame(
            [],
            Math::solve('sin(x^2)^4 / (1 + x^2) = -1 / (2 + x^2)', 'x', 0.0, \INF),
        );
        self::assertSame(
            [],
            Math::solve('sin(x^2)^4 / (1 + x^2)^2 = 2 / (1 + x^2)', 'x', 0.0, \INF),
        );
        self::assertSame(
            [],
            Math::solve('sin(x^2)^4 / (1 + x^2)^2 = 2', 'x', 0.0, \INF),
        );
        $negativeTargetBoundaryRoot = Math::solve(
            'sin(x^2)^2 = -x^2 / (1 + x^2)',
            'x',
            0.0,
            \INF,
        );
        self::assertCount(1, $negativeTargetBoundaryRoot);
        self::assertSame(0.0, $negativeTargetBoundaryRoot[0]->value);
    }

    public function testRationallyScaledEvenTrigonometricPowerExcludesPoleFromFiniteRoots(): void
    {
        $solutions = Math::solve(
            'sin(x^2)^4 / (x - 1) = 1 / (1 + x^2)',
            'x',
            0.0,
            2.0,
        );

        self::assertCount(2, $solutions);
        foreach ($solutions as $solution) {
            self::assertNotEqualsWithDelta(1.0, $solution->value, 1.0E-10);
