    public function testNegativeIntegerTrigonometricPowersReduceToReciprocalRationalTargets(): void
    {
        $boundedRoots = Math::solve('sin(x)^-2 = 4', 'x', 0.0, \M_PI);
        self::assertCount(2, $boundedRoots);
        self::assertEqualsWithDelta(\M_PI / 6.0, $boundedRoots[0]->value, 1.0E-8);
        self::assertEqualsWithDelta(5.0 * \M_PI / 6.0, $boundedRoots[1]->value, 1.0E-8);

        $nonlinearPhaseRoots = Math::solve('sin(x^2)^-2 = 1', 'x', 0.0, 2.0);
        self::assertCount(1, $nonlinearPhaseRoots);
        self::assertEqualsWithDelta(\sqrt(\M_PI / 2.0), $nonlinearPhaseRoots[0]->value, 1.0E-8);

        $turningPhaseRoots = Math::solve(
            'sin((x - 1)^2)^-2 = 1 / sin(0.25)^2',
            'x',
            0.0,
            2.0,
        );
        self::assertCount(2, $turningPhaseRoots);
        self::assertEqualsWithDelta(0.5, $turningPhaseRoots[0]->value, 1.0E-8);
        self::assertEqualsWithDelta(1.5, $turningPhaseRoots[1]->value, 1.0E-8);

        $negativeOddRoots = Math::solve('sin(x)^-3 = -8', 'x', 0.0, 2.0 * \M_PI);
        self::assertCount(2, $negativeOddRoots);
        self::assertEqualsWithDelta(7.0 * \M_PI / 6.0, $negativeOddRoots[0]->value, 1.0E-8);
        self::assertEqualsWithDelta(11.0 * \M_PI / 6.0, $negativeOddRoots[1]->value, 1.0E-8);

        $cosineRoots = Math::solve('cos(x)^-2 = 4', 'x', 0.0, 2.0 * \M_PI);
        self::assertCount(4, $cosineRoots);
        foreach ($cosineRoots as $root) {
            self::assertLessThanOrEqual(1.0E-8, $root->residual);
        }

        $highFrequencyRoots = Math::solve('sin(200 * x)^-2 = 4', 'x', 0.0, 2.0 * \M_PI);
        self::assertCount(800, $highFrequencyRoots);
        foreach ([0, 399, 799] as $index) {
            self::assertLessThanOrEqual(1.0E-8, $highFrequencyRoots[$index]->residual);
        }

        foreach (
            [
                '2 + 3 * sin(x)^-2 = 14' => 4,
                '2 - sin(x)^-3 = 10' => 2,
                '-2 * sin(x)^-2 = -8' => 4,
                'sin(x)^-2 / 4 = 1' => 4,
            ] as $equation => $expectedCount
        ) {
            $solutions = Math::solve($equation, 'x', 0.0, 2.0 * \M_PI);
            self::assertCount($expectedCount, $solutions, $equation);
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-8, $solution->residual, $equation);
            }
        }

        self::assertSame(
            [],
            Math::solve('sin(x^2)^-2 = 2 / (1 + x^2)', 'x', 0.0, \INF),
        );

        $finiteRoots = Math::solve('sin(x^2)^-2 = 10 / (1 + x^2)', 'x', 0.0, \INF);
        self::assertGreaterThan(0, \count($finiteRoots));
        foreach ($finiteRoots as $root) {
            self::assertGreaterThan(0.0, \abs(\sin($root->value ** 2)));
            self::assertLessThanOrEqual(1.0E-8, $root->residual);
        }

        $cosineRoots = Math::solve('cos(x^2)^-2 = 10 / (1 + x^2)', 'x', 0.0, \INF);
        self::assertNotEmpty($cosineRoots);
        foreach ($cosineRoots as $root) {
            self::assertGreaterThan(0.0, \abs(\cos($root->value ** 2)));
            self::assertLessThanOrEqual(1.0E-8, $root->residual);
        }

        foreach (
            [
                'sin(x^2)^-2 = 1 + 1 / (1 + x^2)',
                'sin(x^2)^-3 = 2 + x^2',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', 0.0, \INF);
                self::fail('An attainable rational target along an unbounded phase has infinitely many roots.');
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }
    }

    public function testBoundedNegativeTrigonometricPowersHandleVariableRationalTargets(): void
    {
        foreach (
            [
                'sin(x)^-2 = 2 + x' => 4,
                'sin(x)^-2 = 1 + x^2' => 4,
                'sin(x)^-2 = 4 / (1 + x)' => 2,
