    public function testReciprocalTrigonometricPowersOnBothSidesExcludeTheirPoles(): void
    {
        $evenPowerRoots = Math::solve('sin(x)^-2 = cos(x)^-2', 'x', 0.0, 2.0 * \M_PI);
        self::assertCount(4, $evenPowerRoots);
        foreach ($evenPowerRoots as $index => $root) {
            self::assertEqualsWithDelta(
                (\M_PI / 4.0) + ($index * \M_PI / 2.0),
                $root->value,
                1.0E-9,
            );
            self::assertNotEquals(0.0, \sin($root->value));
            self::assertNotEquals(0.0, \cos($root->value));
        }

        $oddPowerRoots = Math::solve('sin(x)^-3 = cos(x)^-3', 'x', 0.0, 2.0 * \M_PI);
        self::assertCount(2, $oddPowerRoots);
        self::assertEqualsWithDelta(\M_PI / 4.0, $oddPowerRoots[0]->value, 1.0E-9);
        self::assertEqualsWithDelta(5.0 * \M_PI / 4.0, $oddPowerRoots[1]->value, 1.0E-9);
    }

    public function testUnboundedPolynomialPhaseTrigonometricEquationsAreClassified(): void
    {
        foreach (
            [
                'sin(3*x + 1) = 0.5',
                'sin(x) = sin(2*x)',
                'sin(x) = sin(2*x) + 0.5',
                'sin(x + 1) = cos(3*x - 2)',
                'cos(-x) = sin(x/3)',
                '-sin(2*x) = cos(x)',
                'tan(x) = tan(2*x)',
                'tan(2*x) = tan(3*x)',
                'tan(x) + tan(2*x) = 0.5',
                'tan(x) + sin(2*x) = 0.5',
                'sec(x) + sin(2*x) = 0.5',
                'csc(x) + cot(2*x) = 2',
                'sin(pi*x) = 0.5',
                'tan(x^2) = 17',
                'csc(2*x) = 1',
                'sin(0*x) = 0',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', -\INF, \INF);
                self::fail('An attainable unbounded trigonometric equation has infinitely many roots: ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        self::assertSame([], Math::solve('sin(x) = sin(2*x) + 2', 'x', -\INF, \INF));
        try {
            Math::solve(
                'sin(a*x) + cos(3*a*x) = 0.4',
                'x',
                -\INF,
                \INF,
                parameters: ['a' => 2],
            );
            self::fail('A parameterized common period repeats any root indefinitely.');
        } catch (InfiniteSolutionSetException) {
            self::assertTrue(true);
        }
        try {
            Math::solve('sin(x) = sin(2*x) + 0.5', 'x', 0.0, \INF);
            self::fail('An unbounded half-line repeats the affine trigonometric roots.');
        } catch (InfiniteSolutionSetException) {
            self::assertTrue(true);
        }

        foreach (
            [
                'sin(x) = 2',
                'sec(x) = 0.5',
                'cos(x^2) = -2',
                'sin(0*x) = 1',
                'sec(x) = 0',
                'csc(x) = 0',
                'tan(2*x + pi/2) = tan(x + pi/2)',
            ] as $equation
        ) {
            self::assertSame([], Math::solve($equation, 'x', -\INF, \INF), $equation);
        }

        try {
            Math::solve('sin(4*x) = 0.25', 'x', 0.0, \INF);
            self::fail('A half-line still contains infinitely many polynomial-phase roots.');
        } catch (InfiniteSolutionSetException) {
            self::assertTrue(true);
        }

    }

