    public function testUnboundedAbsolutePeriodicLevelsAreClassified(): void
    {
        foreach (
            [
                'abs(sin(x)) = 0.5',
                'abs(cos(x^2 + 1)) = 0',
                'abs(sin(3*x^2)) = 1',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', -\INF, \INF);
                self::fail('Expected infinitely many roots for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        try {
            Math::solve('abs(cos(x^2)) = 0.25', 'x', 2.0, \INF);
            self::fail('A one-sided unbounded interval contains infinitely many roots.');
        } catch (InfiniteSolutionSetException) {
            self::assertTrue(true);
        }

        self::assertSame([], Math::solve('abs(sin(x)) = 1.01', 'x', -\INF, \INF));
        self::assertSame([], Math::solve('abs(cos(x^2)) = -1', 'x', -\INF, \INF));
    }

    public function testUnboundedLogOnePlusIdentitiesReduceToPolynomialZeros(): void
    {
        foreach (
            [
                ['ln(1 + x^2) = x^2', [0.0]],
                ['x = ln(1 + x)', [0.0]],
                ['log1p(x^2) = x^2', [0.0]],
