    public function testFiniteLogarithmIsolationHandlesAnOpenDomainAtTheIntervalBoundary(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $solutions = Math::solve('ln(x) = x - 2', 'x', 0.0, 10.0, solverOptions: $options);

        self::assertEqualsWithDelta(
            [0.15859433956303937, 3.1461932206205834],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $solutions),
            1.0E-10,
        );
        self::assertSame(
            [],
            Math::solve('ln(x) = x - 2', 'x', 0.0, 0.1, solverOptions: $options),
        );
        $closedEndpointRoot = 3.1461932206205834;
        $endpointSolution = Math::solve(
            'ln(x) = x - 2',
            'x',
            $closedEndpointRoot,
            4.0,
            solverOptions: $options,
        );
        self::assertCount(1, $endpointSolution);
        self::assertSame($closedEndpointRoot, $endpointSolution[0]->value);
        foreach ($solutions as $solution) {
            self::assertLessThanOrEqual(1.0E-9, $solution->residual);
        }
    }

    public function testFiniteLogarithmIsolationScalesFixedBasesAndLogOnePlus(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $cases = [
            ['log10(x) = x - 2', 0.0, 10.0, [0.010238552281443275, 2.3758120875934265]],
            ['log2(x) = x - 2', 0.0, 10.0, [0.3099069323806906, 4.0]],
            ['log1p(x) = x - 2', -1.0, 10.0, [-0.9475309025422851, 3.505241495792884]],
            ['log(x, 0.5) = x - 2', 0.0, 5.0, [1.4569995591345914]],
            ['log10(3 - 2*x) = x - 2', -10.0, 10.0, [1.3800457252000342]],
            ['log2(3 - 2*x) = x - 2', -10.0, 10.0, [1.2106896819532265]],
            ['log1p(3 - 2*x) = x - 2', -10.0, 10.0, [1.6482662887574404]],
        ];
        foreach ($cases as [$equation, $lowerBound, $upperBound, $expectedRoots]) {
            $solutions = Math::solve(
                $equation,
                'x',
                $lowerBound,
                $upperBound,
                solverOptions: $options,
            );
            self::assertEqualsWithDelta(
                $expectedRoots,
                \array_map(static fn (EquationSolution $solution): float => $solution->value, $solutions),
                1.0E-8,
                $equation,
            );
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-8, $solution->residual, $equation);
            }
        }
    }

    public function testDescendingLogarithmRationalTargetsRespectOpenDomainsAndPoles(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        self::assertSame(
            [],
            Math::solve(
                'log1p(3 - 2*x) = 1/(x - 2)',
