    public function testUnboundedPolynomialLogarithmsWithPolynomialTargetsAreIsolatedByMonotonicity(): void
    {
        foreach (
            [
                ['ln(x) = x^2 - 3', [0.049911249177841364, 1.9096975943778491]],
                ['ln(x) = x^2', []],
                ['ln(x) = x^2 - 1', [0.4507636520173071, 1.0]],
                ['ln(2*x + 1) = x^2 - 3', [-0.4689824661703565, 2.161488550079796]],
                ['ln(-2*x + 3) = x^2 - 3', [-2.2387255223654106, 1.3471538787906738]],
                ['log1p(x) = x^2 - 3', [-0.8900574880065384, 2.0266892632665945]],
                ['log1p(-2*x + 3) = x^2 - 3', [-2.2681089108971397, 1.6370042687874728]],
                ['log(x, 0.5) = x^2 - 3', [1.5413613669504855]],
                ['log2(x) = x^2 - 3', [0.1263918102201061, 2.0]],
                ['log10(x) = x^2 - 3', [0.0010000023025983486, 1.8045405645418375]],
                ['ln(x) = x^3 - 2*x', [0.4471405783831851, 1.5073974688442766]],
                ['ln(x^2 + 1) = x^2 - 3', [-2.179227245151983, 2.179227245151983]],
                ['ln(x^2 + 1) = x^4 - 3', [-1.4236183699445315, 1.4236183699445315]],
                ['ln(2*x^2 + 3) = x^2 - 2', [-2.1170457004931156, 2.1170457004931156]],
                ['ln(x^4 + 1) = x^2 - 1', [-1.9167838463748488, 1.9167838463748488]],
                ['ln(x^2 + 1) = x^2 + 1', []],
                [
                    'ln(x^2 - 1) = x^2 - 3',
                    [-2.0362203271307804, -1.0763802021419009, 1.0763802021419009, 2.0362203271307804],
                ],
                ['ln(x^2 - 1) = x^2 - 2', [-1.4142135623730951, 1.414213562373095]],
                [
                    'ln(x^2 - 1) = x^4 - 3',
                    [-1.2448843112394052, -1.105082981481035, 1.105082981481035, 1.2448843112394052],
                ],
                ['ln(1 - x^2) = x^2 - 3', [-0.9380681004129491, 0.9380681004129491]],
                ['ln(x^3 - 1) = x^2 - 3', [1.0474271189143092, 2.3380504993474993]],
                [
                    'ln(x^3 - 3*x) = x^2 - 3',
                    [-1.6087944969519106, -0.016601789439030627],
                ],
                [
                    'ln((x - 1)*(x + 1)*(x - 3)) = x^2 - 5',
                    [-0.9977170554401594, 0.995462340561478],
                ],
                ['ln((x - 1)^2) = x^2 - 3', [-2.3243365112215026, 0.7124139554284411]],
            ] as [$equation, $expectedRoots]
        ) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF);
            self::assertEqualsWithDelta(
                $expectedRoots,
                \array_map(
                    static fn (EquationSolution $solution): float => $solution->value,
                    $solutions,
                ),
                1.0E-8,
                $equation,
            );
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-9, $solution->residual, $equation);
            }
        }

        $tangentPoint = 1.0 / \sqrt(2.0);
        $tangentOffset = \log($tangentPoint) - ($tangentPoint * $tangentPoint);
        $tangentEquation = 'ln(x) = x^2 + (' . \sprintf('%.17g', $tangentOffset) . ')';
        $tangentSolutions = Math::solve($tangentEquation, 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [$tangentPoint],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                $tangentSolutions,
            ),
            1.0E-8,
        );

        $finitePositiveDomainRoots = Math::solve('ln(x^2 - 1) = x^2 - 3', 'x', 1.0, 2.0);
        self::assertEqualsWithDelta(
            [1.076380202139262],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                $finitePositiveDomainRoots,
            ),
            1.0E-8,
        );
        $finiteBoundedDomainRoots = Math::solve('ln(1 - x^2) = x^2 - 3', 'x', -2.0, 0.0);
        self::assertEqualsWithDelta(
            [-0.9380681004113285],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                $finiteBoundedDomainRoots,
            ),
            1.0E-8,
        );
    }

