    public function testGammaRecurrenceIsRecognizedAsAnInfiniteSolutionSet(): void
    {
        $equations = [
            'gamma(x + 1) = x * gamma(x)',
            'gamma(1 + x) = gamma(x) * x',
            'x * gamma(x) = gamma(x + 1)',
            'gamma(x + 2) = x * (x + 1) * gamma(x)',
            'gamma(3 + x) = gamma(x) * (x + 2) * (x + 1) * x',
            'gamma(x) = gamma(x + 1) / x',
            'gamma(x) = gamma(x + 2) / (x * (x + 1))',
        ];
        foreach ($equations as $equation) {
            try {
                Math::solve($equation, 'x', -5.0, 5.0);
                self::fail('Expected an infinite solution set for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }
    }

    public function testRegularizedIncompleteGammaShapeRecurrencesAreIdentities(): void
    {
        foreach (
            [
                'gammainc(x + 1, 0.5) = gammainc(x, 0.5) - 0.5^x * exp(-0.5) / gamma(x + 1)',
                'gammaincc(x + 1, 0.5) = gammaincc(x, 0.5) + 0.5^x * exp(-0.5) / gamma(x + 1)',
                'gammainc(x + 1, 2) = gammainc(x, 2) - 2^x * exp(-2) / gamma(x + 1)',
                'gammainc(x, 0.5) = gammainc(x + 1, 0.5) + 0.5^x * exp(-0.5) / gamma(x + 1)',
                'gammaincc(x, 0.5) = gammaincc(x + 1, 0.5) - 0.5^x * exp(-0.5) / gamma(x + 1)',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', -2.0, 5.0);
                self::fail('Expected infinitely many shape-recurrence solutions for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        self::assertCount(
            1,
            Math::solve(
                'gammainc(x + 1, 0.5) = gammainc(x, 0.5) - 0.5^x * exp(-0.5) / gamma(x + 1)',
                'x',
                2.0,
                2.0,
            ),
        );

        try {
            Math::solve(
                'gammainc(x + 1, 0.5) = gammainc(x, 0.5) - 0.5^x * exp(-0.5) / gamma(x)',
                'x',
                0.1,
                5.0,
            );
        } catch (InfiniteSolutionSetException) {
            self::fail('The recurrence denominator must use gamma(x + 1).');
        } catch (RootSearchLimitException) {
            self::assertTrue(true);
        }

        try {
            Math::solve(
                'gammainc(x, 0.5) = gammainc(x + 1, 0.5) - 0.5^x * exp(-0.5) / gamma(x + 1)',
                'x',
                0.1,
                5.0,
            );
        } catch (InfiniteSolutionSetException) {
            self::fail('The reverse lower-Gamma recurrence correction has the wrong sign.');
        } catch (RootSearchLimitException) {
            self::assertTrue(true);
        }
    }

    public function testDigammaRecurrenceIsRecognizedAsAnInfiniteSolutionSet(): void
    {
        foreach (
            [
                'digamma(x + 1) = digamma(x) + 1/x',
                'digamma(1 + x) = 1/x + digamma(x)',
                'digamma(x + 2) = 1/(x + 1) + digamma(x) + 1/x',
                'trigamma(x + 1) = trigamma(x) - 1/x^2',
                'tetragamma(x + 1) = tetragamma(x) + 2/x^3',
                'polygamma(3, x + 1) = polygamma(3, x) - 6/x^4',
                'polygamma(0, x + 2) = polygamma(0, x) + 1/(x + 1) + 1/x',
                'digamma(x) = digamma(x + 1) - 1/x',
                'trigamma(x) = trigamma(x + 1) + 1/x^2',
                'tetragamma(x) = tetragamma(x + 1) - 2/x^3',
                'polygamma(3, x) = polygamma(3, x + 1) + 6/x^4',
                'digamma(x) = digamma(x + 2) - 1/x - 1/(x + 1)',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', -5.0, 5.0);
                self::fail('Expected an infinite solution set for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        try {
            Math::solve('digamma(x + 1) = digamma(x) + 2/x', 'x', -5.0, 5.0);
        } catch (InfiniteSolutionSetException) {
            self::fail('A scaled reciprocal term is not the digamma recurrence.');
        } catch (RootSearchLimitException) {
            self::assertTrue(true);
        }

        try {
            Math::solve('digamma(x) = digamma(x + 1) + 1/x', 'x', -5.0, 5.0);
        } catch (InfiniteSolutionSetException) {
            self::fail('The reverse recurrence correction has the wrong sign.');
        } catch (RootSearchLimitException) {
            self::assertTrue(true);
        }

    }

    public function testSpecialFunctionRecurrencesRemainPointwiseOnSingletonIntervals(): void
    {
        foreach (
            [
                'gamma(x + 1) = x * gamma(x)',
                'digamma(x + 1) = digamma(x) + 1/x',
                'trigamma(x) = trigamma(x + 1) + 1/x^2',
            ] as $equation
        ) {
            self::assertCount(1, Math::solve($equation, 'x', 1.0, 1.0), $equation);
        }
    }

    public function testLogGammaRecurrenceHonorsItsPositiveLogarithmDomain(): void
    {
        foreach (
            [
                'lgamma(x + 1) = lgamma(x) + ln(x)',
                'lgamma(1 + x) = ln(x) + lgamma(x)',
                'lgamma(x) + ln(x) = lgamma(x + 1)',
                'lgamma(x) = lgamma(x + 1) - ln(x)',
                'lgamma(x) = lgamma(x + 1) - ln(abs(x))',
                'lgamma(x + 2) = lgamma(x) + ln(x) + ln(x + 1)',
                'lgamma(x) = lgamma(x + 2) - ln(x) - ln(x + 1)',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', -2.0, 5.0);
                self::fail('Expected infinitely many positive-domain solutions for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        self::assertSame([], Math::solve('lgamma(x + 1) = lgamma(x) + ln(x)', 'x', -5.0, -0.1));
        self::assertCount(1, Math::solve('lgamma(x + 1) = lgamma(x) + ln(x)', 'x', 1.0, 1.0));
    }

    public function testLogGammaRecurrenceWithAbsoluteArgumentCoversNegativeIntervals(): void
    {
        foreach (
            [
                'lgamma(x + 1) = lgamma(x) + ln(abs(x))',
                'lgamma(x + 1) = ln(abs(x)) + lgamma(x)',
                'lgamma(x) + ln(abs(x)) = lgamma(x + 1)',
                'lgamma(x) = lgamma(x + 1) - ln(abs(x))',
                'lgamma(x + 2) = lgamma(x) + ln(abs(x)) + ln(abs(x + 1))',
                'lgamma(x) = lgamma(x + 2) - ln(abs(x)) - ln(abs(x + 1))',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', -5.0, -0.1);
                self::fail('Expected infinitely many non-pole solutions for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        self::assertCount(1, Math::solve('lgamma(x + 1) = lgamma(x) + ln(abs(x))', 'x', -0.5, -0.5));

        try {
            Math::solve('lgamma(x + 1) = lgamma(x) + ln(abs(2*x))', 'x', -5.0, -0.1);
        } catch (InfiniteSolutionSetException) {
            self::fail('The shifted logarithm argument does not match the recurrence.');
        } catch (RootSearchLimitException) {
            self::assertTrue(true);
        }

    }

    public function testUnboundedInvertibleFunctionLevelsReduceToPolynomialRoots(): void
    {
        foreach (
            [
                'gamma(x) = 0',
                '0 = gamma(x)',
                'gamma(x^2 + 1) = 0',
                'gamma(x) = x - x',
            ] as $equation
        ) {
            self::assertSame([], Math::solve($equation, 'x', -\INF, \INF), $equation);
        }
        foreach (
            [
                'sinh(x) = x',
                'x = sinh(x)',
                'sinh(x) = -x',
                'tanh(x) = -x',
                'atan(x) = x',
                'arcsinh(x) = x',
                'asin(x) = -x',
                'atanh(x) = x',
                'dawson(x) = x',
                'dawson(x) = -x',
                'x = dawson(x)',
                '-x = dawson(x)',
                'erfi(x) = x',
                'erfi(x) = -x',
                'x = erfi(x)',
                '-x = erfi(x)',
                'lambertw(x) = x',
                'lambertw(x) = -x',
                'x = lambertw(x)',
                '-x = lambertw(x)',
                'expm1(x) = x',
                'x = expm1(x)',
                'expm1(x) = -x',
                'log1p(x) = -x',
                'ln(1 + x) = x',
                'ln(x + 1) = -x',
                'ln(1 - x) = x',
                'ln(1 - x) = -x',
                'exp(x) = x + 1',
                '1 + x = exp(x)',
                'exp(x) = 1 - x',
                '1 - x = exp(x)',
            ] as $equation
        ) {
            $roots = Math::solve($equation, 'x', -\INF, \INF);
            self::assertCount(1, $roots, $equation);
            self::assertSame(0.0, $roots[0]->value, $equation);
        }
        self::assertSame([], Math::solve('sinh(x) = x', 'x', 1.0, \INF));
        self::assertSame([], Math::solve('dawson(x) = x', 'x', 1.0, \INF));
        self::assertSame([], Math::solve('dawson(x) = -x', 'x', -\INF, -1.0));
        self::assertSame([], Math::solve('erfi(x) = x', 'x', 1.0, \INF));
        self::assertSame([], Math::solve('erfi(x) = -x', 'x', -\INF, -1.0));
        self::assertSame([], Math::solve('lambertw(x) = x', 'x', 0.1, \INF));
        self::assertSame([], Math::solve('lambertw(x) = -x', 'x', -\INF, -0.1));
        self::assertSame([], Math::solve('ln(x) = x', 'x', -\INF, \INF));
        self::assertSame([], Math::solve('exp(x) = x', 'x', -\INF, \INF));

        $exponentialRoots = Math::solve('exp(x^2) = 2', 'x', -\INF, \INF);
        self::assertCount(2, $exponentialRoots);
        self::assertEqualsWithDelta(-\sqrt(\log(2.0)), $exponentialRoots[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(\sqrt(\log(2.0)), $exponentialRoots[1]->value, 1.0E-10);

        $noExponentialRoots = Math::solve('exp(x^2) = 0.5', 'x', -\INF, \INF);
        self::assertSame([], $noExponentialRoots);

        $logarithmRoots = Math::solve('ln(x) = 1', 'x', -\INF, \INF);
        self::assertCount(1, $logarithmRoots);
        self::assertEqualsWithDelta(\M_E, $logarithmRoots[0]->value, 1.0E-10);

        $quadraticLogarithmRoots = Math::solve('ln(x^2) = 0', 'x', -\INF, \INF);
        self::assertCount(2, $quadraticLogarithmRoots);
        self::assertSame(-1.0, $quadraticLogarithmRoots[0]->value);
        self::assertSame(1.0, $quadraticLogarithmRoots[1]->value);

        $squareRootRoots = Math::solve('sqrt(x^2) = 1', 'x', -\INF, \INF);
        self::assertCount(2, $squareRootRoots);
        self::assertSame(-1.0, $squareRootRoots[0]->value);
        self::assertSame(1.0, $squareRootRoots[1]->value);

        $halfLineRoots = Math::solve('2 = exp(x)', 'x', 0.0, \INF);
        self::assertCount(1, $halfLineRoots);
        self::assertEqualsWithDelta(\log(2.0), $halfLineRoots[0]->value, 1.0E-10);

        foreach (['-exp(x) = -2', '-2 = -exp(x)'] as $equation) {
            $negativeExponentialRoot = Math::solve($equation, 'x', -\INF, \INF);
            self::assertCount(1, $negativeExponentialRoot, $equation);
            self::assertEqualsWithDelta(\log(2.0), $negativeExponentialRoot[0]->value, 1.0E-10);
        }

        foreach (['-ln(x) = 1', '1 = -ln(x)'] as $equation) {
            $negativeLogarithmRoot = Math::solve(
                $equation,
                'x',
                -\INF,
                \INF,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertCount(1, $negativeLogarithmRoot, $equation);
            self::assertEqualsWithDelta(\exp(-1.0), $negativeLogarithmRoot[0]->value, 1.0E-10);
        }

        $gammaLevel = Math::evaluate('gammaincinv(2, 0.5)');
        $gammaRoots = Math::solve('gammainc(2, x^2) = 0.5', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [-\sqrt($gammaLevel), \sqrt($gammaLevel)],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $gammaRoots),
            1.0E-9,
        );
        $gammaComplementLevel = Math::evaluate('gammainccinv(2, 0.5)');
        $gammaComplementRoots = Math::solve('0.5 = gammaincc(2, x^2)', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [-\sqrt($gammaComplementLevel), \sqrt($gammaComplementLevel)],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                $gammaComplementRoots,
            ),
            1.0E-9,
        );
        self::assertSame([], Math::solve('gammainc(2, x) = 1', 'x', -\INF, \INF));
        self::assertSame([], Math::solve('gammainc(2, x) = 2', 'x', -\INF, \INF));

        $betaLevel = Math::evaluate('betaincinv(2, 3, 0.4)');
        $betaRoots = Math::solve('betainc(2, 3, x^2) = 0.4', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [-\sqrt($betaLevel), \sqrt($betaLevel)],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $betaRoots),
            1.0E-9,
        );
        $betaComplementLevel = Math::evaluate('betainccinv(2, 3, 0.4)');
        $betaComplementRoots = Math::solve('betaincc(2, 3, x^2) = 0.4', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [-\sqrt($betaComplementLevel), \sqrt($betaComplementLevel)],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                $betaComplementRoots,
            ),
            1.0E-9,
        );

        $erfiRoot = Math::solve('erfi(x) = erfi(1)', 'x', -\INF, \INF);
        self::assertCount(1, $erfiRoot);
        self::assertEqualsWithDelta(1.0, $erfiRoot[0]->value, 1.0E-9);

        $erfcxRoot = Math::solve('erfcx(x) = 2', 'x', -\INF, \INF);
        self::assertCount(1, $erfcxRoot);
        self::assertEqualsWithDelta(
            SpecialFunctions::inverseErfcx(2.0),
            $erfcxRoot[0]->value,
            1.0E-9,
        );

        $dawsonLevels = SpecialFunctions::inverseDawson(0.2);
        $dawsonRoots = Math::solve('dawson(x) = 0.2', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            $dawsonLevels,
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $dawsonRoots),
            1.0E-9,
        );
        self::assertSame([], Math::solve('dawson(x) = 1', 'x', -\INF, \INF));

        $evenBesselLevel = Math::evaluate('besseli(0, 1)');
        $evenBesselRoots = Math::solve(
            'besseli(0, x) = ' . \sprintf('%.17g', $evenBesselLevel),
            'x',
            -\INF,
            \INF,
        );
        self::assertEqualsWithDelta(
            [-1.0, 1.0],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $evenBesselRoots),
            1.0E-8,
        );

        $oddBesselLevel = Math::evaluate('besseli(1, 1)');
        $oddBesselRoot = Math::solve(
            'besseli(1, x) = ' . \sprintf('%.17g', -$oddBesselLevel),
            'x',
            -\INF,
            \INF,
        );
        self::assertCount(1, $oddBesselRoot);
        self::assertEqualsWithDelta(-1.0, $oddBesselRoot[0]->value, 1.0E-8);
        self::assertSame([], Math::solve('besseli(0, x) = 0.5', 'x', -\INF, \INF));
    }

