    public function testUnboundedDawsonIntersectionsWithLinesThroughTheOrigin(): void
    {
        foreach (
            [
                'dawson(x) = 0.5*x' => [-1.063061065530679, 0.0, 1.063061065530679],
                'dawson(x) = 0.9*x' => [-0.39969898889864, 0.0, 0.39969898889864],
                'dawson(x) = 2*x' => [0.0],
                'dawson(x) = -0.5*x' => [0.0],
            ] as $equation => $expectedRoots
        ) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF);
            self::assertEqualsWithDelta(
                $expectedRoots,
                \array_map(static fn (EquationSolution $solution): float => $solution->value, $solutions),
                1.0E-8,
                $equation,
            );
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-10, $solution->residual, $equation);
            }
        }

        self::assertEqualsWithDelta(
            [0.0, 1.063061065530679],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve('dawson(x) = 0.5*x', 'x', 0.0, \INF),
            ),
            1.0E-8,
        );
        self::assertEqualsWithDelta(
            [-1.063061065530679, 0.0],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve('dawson(x) = 0.5*x', 'x', -\INF, 0.0),
            ),
            1.0E-8,
        );
    }

