    public function testUnboundedAffineHyperbolicEquationsSplitAtCriticalPoints(): void
    {
        foreach (['cosh(x) = x', 'cosh(x) = -x'] as $equation) {
            self::assertSame([], Math::solve($equation, 'x', -\INF, \INF), $equation);
        }

        foreach (
            [
                'cosh(x) = x + 1' => [0.0, 1.6161375137503418],
                'sinh(x) = x + 1' => [1.729116898208941],
                'sinh(x) = x - 1' => [-1.729116898208941],
