    public function testAcotAffineArgumentsAcceptPolynomialTargetsOnFiniteIntervals(): void
    {
        foreach (
            [
                [-3.0, 3.0, [-1.607853070067069, 0.9118509636399549]],
                [-3.0, 0.0, [-1.607853070067069]],
                [0.0, 3.0, [0.9118509636399549]],
                [-0.5, 0.5, []],
            ] as [$lowerBound, $upperBound, $expectedRoots]
        ) {
            $solutions = Math::solve('acot(x) = x^2', 'x', $lowerBound, $upperBound);
            self::assertEqualsWithDelta(
                $expectedRoots,
                \array_map(static fn (EquationSolution $solution): float => $solution->value, $solutions),
                1.0E-9,
            );
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-9, $solution->residual);
            }
        }

        $affine = Math::solve('acot(2*x - 1) = x^2', 'x', -2.0, 2.0);
        foreach ($affine as $solution) {
            self::assertLessThanOrEqual(1.0E-9, $solution->residual);
        }
        self::assertNotEmpty($affine);

        $unbounded = Math::solve('acot(x) = x^2', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [-1.607853070067069, 0.9118509636399549],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $unbounded),
            1.0E-9,
        );
    }

