    public function testUnboundedBoundedFunctionRangesConfinePolynomialTargets(): void
    {
        foreach (
            [
                'atan(x) = x' => [0.0],
                'atan2(x, 1) = x' => [0.0],
                'acos(x) = x' => [0.7390851332],
                'tanh(x) = x' => [0.0],
                'erf(x) = x' => [-0.6179, 0.0, 0.6179],
            ] as $equation => $expectedRoots
        ) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF);
            self::assertCount(\count($expectedRoots), $solutions, $equation);
            foreach ($expectedRoots as $index => $expectedRoot) {
                self::assertEqualsWithDelta($expectedRoot, $solutions[$index]->value, 1.0E-3, $equation);
                self::assertLessThanOrEqual(1.0E-9, $solutions[$index]->residual, $equation);
            }
        }

        $complementaryErrorRoot = Math::solve('erfc(x) = x', 'x', -\INF, \INF);
        self::assertCount(1, $complementaryErrorRoot);
        self::assertEqualsWithDelta(0.4891163, $complementaryErrorRoot[0]->value, 1.0E-6);
        self::assertLessThanOrEqual(1.0E-9, $complementaryErrorRoot[0]->residual);

        $regularizedGammaRoot = Math::solve('gammainc(2, x) = x', 'x', -\INF, \INF);
        self::assertCount(1, $regularizedGammaRoot);
        self::assertSame(0.0, $regularizedGammaRoot[0]->value);
        self::assertLessThanOrEqual(1.0E-9, $regularizedGammaRoot[0]->residual);
    }

