                'sqrt(x^2 + 1) = cos(x)' => [0.0],
                'sqrt(2 - x^2) = sin(x)' => [1.0985868748532166],
                'abs(x) = cos(x)' => [-0.7390851332165767, 0.7390851332165767],
                'sin(x) = abs(x)' => [0.0],
                'abs(x^2 - 1) = sin(x)' => [0.6367326508085575, 1.4096240040037071],
                'cbrt(x) = cos(x)' => [0.5824400711589678],
                'root(x, 3) = sin(x)' => [0.0],
                'root(x^2, 3) = sin(x)' => [0.0],
                'root(x, 4) = sin(x)' => [0.0],
                'root(x, 5) = cos(x)' => [0.5084822745702695],
                'abs(x) = sin(10*x)' => [
                    -0.5679207796288818,
                    -0.349906381990877,
                    0.0,
                    0.2852341894449637,
                    0.7068174358136199,
                    0.8423203932325123,
                ],
            ] as $equation => $expectedRoots
        ) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF);
            self::assertEqualsWithDelta(
                $expectedRoots,
                \array_map(static fn (EquationSolution $solution): float => $solution->value, $solutions),
                1.0E-9,
                $equation,
            );
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-9, $solution->residual, $equation);
            }
        }

        self::assertSame([], Math::solve('sqrt(x^2 + 1) = sin(x)', 'x', -\INF, \INF));
        self::assertSame([], Math::solve('root(x^2 + 1, 3) = sin(x)', 'x', -\INF, \INF));
        self::assertSame([], Math::solve('abs(x) = -cos(x)', 'x', -\INF, \INF));
    }

