    public function testGloballyValidHyperbolicInverseCompositionsReportInfiniteSolutions(): void
    {
        foreach (
            [
                'asinh(sinh(x)) = x',
                'arcsinh(sinh(2*x + 1)) = 2*x + 1',
                'atanh(tanh(x)) = x',
                'arctanh(tanh(x - 3)) = x - 3',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', -2.0, 4.0);
                self::fail('Expected an infinite solution set for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        foreach (['asinh(sinh(x)) = -x', 'atanh(tanh(x)) = -x'] as $equation) {
            self::assertEqualsWithDelta(
                [0.0],
                \array_map(
                    static fn (EquationSolution $solution): float => $solution->value,
                    Math::solve($equation, 'x', -1.0, 0.0),
                ),
                1.0E-9,
                $equation,
            );
        }
    }

    public function testAcoshCoshIdentitiesRespectTheirRealBranchesAndInterval(): void
    {
        foreach (
            [
                ['acosh(cosh(x)) = abs(x)', -\INF, \INF],
                ['acosh(cosh(x)) = x', 0.0, \INF],
                ['acosh(cosh(x)) = -x', -\INF, 0.0],
            ] as [$equation, $lowerBound, $upperBound]
        ) {
            try {
                Math::solve($equation, 'x', $lowerBound, $upperBound);
                self::fail('Expected an infinite solution set for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        self::assertEqualsWithDelta(
            [0.0],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve('acosh(cosh(x)) = x', 'x', -\INF, 0.0),
            ),
            1.0E-9,
        );
        self::assertSame([], Math::solve('acosh(cosh(x)) = x', 'x', -2.0, -1.0));

        foreach (
            [
                ['acosh(cosh(2*x + 1)) = 2*x + 1', -1.0, 0.0],
                ['acosh(cosh(2*x + 1)) = -(2*x + 1)', -1.0, 0.0],
            ] as [$equation, $lowerBound, $upperBound]
        ) {
            try {
                Math::solve($equation, 'x', $lowerBound, $upperBound);
                self::fail('Expected an infinite solution set for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        self::assertEqualsWithDelta(
            [-0.5],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve('acosh(cosh(2*x + 1)) = 2*x + 1', 'x', -1.0, -0.5),
            ),
            1.0E-9,
        );
        self::assertSame(
            [],
            Math::solve('acosh(cosh(2*x + 1)) = 2*x + 1', 'x', -1.0, -0.75),
        );

        foreach (
            [
                ['acosh(cosh(x - x + 2)) = x - x + 2', -\INF, \INF],
                ['acosh(cosh(x - x)) = -(x - x)', -\INF, \INF],
                ['acosh(cosh(x^2 + 1)) = x^2 + 1', -2.0, 2.0],
                ['acosh(cosh(1e-300*(x^2 + 1))) = 1e-300*(x^2 + 1)', -2.0, 2.0],
                [
                    'acosh(cosh(-((x^2 - 1)^2) + 1e-15)) = -((x^2 - 1)^2) + 1e-15',
                    -2.0,
                    2.0,
                ],
                ['acosh(cosh(x^2 - 1)) = x^2 - 1', 2.0, 3.0],
                ['acosh(cosh(x^2 - 1)) = -(x^2 - 1)', -0.5, 0.5],
                ['acosh(cosh(x^3 + x)) = x^3 + x', 0.0, \INF],
                ['acosh(cosh(x^3 + x)) = -(x^3 + x)', -\INF, 0.0],
            ] as [$equation, $lowerBound, $upperBound]
        ) {
            try {
                Math::solve($equation, 'x', $lowerBound, $upperBound);
                self::fail('Expected an infinite solution set for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }
        self::assertSame(
            [],
            Math::solve('acosh(cosh(x - x - 2)) = x - x - 2', 'x', -\INF, \INF),
        );
        self::assertSame(
            [],
            Math::solve('acosh(cosh(x^2 + 1)) = -(x^2 + 1)', 'x', -\INF, \INF),
        );
        self::assertEqualsWithDelta(
            [-1.0, 1.0],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve('acosh(cosh(x^2 - 1)) = x^2 - 1', 'x', -1.0, 1.0),
            ),
            1.0E-9,
        );
        self::assertEqualsWithDelta(
            [-1.0],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve(
                    'acosh(cosh(((x^2 - 2)*(x + 1))/((x^2 - 2)*(x^2 + 1))))'
                        . ' = ((x^2 - 2)*(x + 1))/((x^2 - 2)*(x^2 + 1))',
                    'x',
                    -2.0,
                    -1.0,
                ),
            ),
            1.0E-9,
        );
        self::assertEqualsWithDelta(
            [-\sqrt(2.0), \sqrt(2.0)],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve(
                    'acosh(cosh(-(x^4 - 4*x^2 + 4))) = -(x^4 - 4*x^2 + 4)',
                    'x',
                    -2.0,
                    2.0,
                ),
            ),
            1.0E-9,
        );
        self::assertSame(
            [],
            Math::solve(
                'acosh(cosh(-1e30*(x^2 - 2)^2)) = -1e30*(x^2 - 2)^2',
                'x',
                -2.0,
                2.0,
            ),
        );
        $looseToleranceBoundaryRoots = Math::solve(
            'acosh(cosh(-1e30*(x^2 - 2)^2)) = -1e30*(x^2 - 2)^2',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(residualTolerance: 0.5),
        );
        self::assertEqualsWithDelta(
            [-\sqrt(2.0), \sqrt(2.0)],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                $looseToleranceBoundaryRoots,
            ),
            1.0E-9,
        );
        foreach ($looseToleranceBoundaryRoots as $solution) {
            self::assertLessThanOrEqual(0.5, $solution->residual);
        }
        self::assertEqualsWithDelta(
            [1.0],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve('acosh(cosh(x^2 - 1)) = -(x^2 - 1)', 'x', 1.0, 2.0),
            ),
            1.0E-9,
        );
        self::assertEqualsWithDelta(
            [-1.0, 1.0],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve(
                    'acosh(cosh((x^2 - 1)^2)) = -((x^2 - 1)^2)',
                    'x',
                    -2.0,
                    2.0,
                ),
            ),
            1.0E-9,
        );
        self::assertEqualsWithDelta(
            [0.0],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve('acosh(cosh(x^3 + x)) = -(x^3 + x)', 'x', 0.0, \INF),
            ),
            1.0E-9,
        );
        self::assertEqualsWithDelta(
            [0.0],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve('acosh(cosh(x^3 + x)) = x^3 + x', 'x', -\INF, 0.0),
            ),
            1.0E-9,
        );
        self::assertSame(
            [],
            Math::solve('acosh(cosh(x^3 + x)) = -(x^3 + x)', 'x', 1.0, \INF),
        );

        foreach (
            [
                ['acosh(cosh(1/(x - 1))) = 1/(x - 1)', 1.0, \INF],
                ['acosh(cosh(1/(x - 1))) = -(1/(x - 1))', -\INF, 1.0],
                [
                    'acosh(cosh((x + 1)/(x - 1))) = (x + 1)/(x - 1)',
                    -\INF,
                    \INF,
                ],
                [
                    'acosh(cosh((x^2 - 1)/(x^2 + 1))) = (x^2 - 1)/(x^2 + 1)',
                    -\INF,
                    \INF,
                ],
                [
                    'acosh(cosh(((x^2 - 2)*(x + 1))/((x^2 - 2)*(x^2 + 1))))'
                        . ' = ((x^2 - 2)*(x + 1))/((x^2 - 2)*(x^2 + 1))',
                    -\INF,
                    \INF,
                ],
                [
                    'acosh(cosh((x^2 - 1)/(x^2 + 1))) = -((x^2 - 1)/(x^2 + 1))',
                    -1.0,
                    1.0,
                ],
            ] as [$equation, $lowerBound, $upperBound]
        ) {
            try {
                Math::solve($equation, 'x', $lowerBound, $upperBound);
                self::fail('Expected an infinite rational-domain solution set for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }
        self::assertSame(
            [],
            Math::solve('acosh(cosh(1/(x - 1))) = -(1/(x - 1))', 'x', 2.0, \INF),
        );
        self::assertSame(
            [],
            Math::solve(
                'acosh(cosh((x^2 - 1)/(x^2 - 1))) = -((x^2 - 1)/(x^2 - 1))',
                'x',
                -\INF,
                \INF,
            ),
        );
        self::assertEqualsWithDelta(
            [1.0],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve(
                    'acosh(cosh((x - 1)/(x + 1))) = (x - 1)/(x + 1)',
                    'x',
                    -1.0,
                    1.0,
                ),
            ),
            1.0E-9,
        );
        self::assertEqualsWithDelta(
            [-1.0, 1.0],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve(
                    'acosh(cosh((x^2 - 1)/(x^2 + 1))) = (x^2 - 1)/(x^2 + 1)',
                    'x',
                    -1.0,
                    1.0,
                ),
            ),
            1.0E-9,
        );
    }

    public function testInverseTrigonometricCompositionsAreInfiniteOnTheirPrincipalBranches(): void
    {
        foreach (
            [
                ['asin(sin(x)) = x', -\M_PI_2, \M_PI_2],
                ['asin(sin(x)) = x', -\INF, \INF],
                ['asin(sin(x)) = x', -3.0, 0.0],
                ['arcsin(sin(x)) = x', -1.0, 1.0],
                ['acos(cos(x)) = x', 0.0, \M_PI],
                ['acos(cos(x)) = x', -\INF, \INF],
                ['acos(cos(x)) = x', 2.0, 4.0],
                ['arccos(cos(x)) = x', 0.25, 2.75],
                ['atan(tan(x)) = x', -1.0, 1.0],
                ['atan(tan(x)) = x', -\INF, \INF],
                ['atan(tan(x)) = x', 0.5, 2.0],
                ['arctan(tan(x)) = x', -0.5, 0.5],
                ['asec(sec(x)) = x', 0.0, \M_PI],
                ['asec(sec(x)) = x', -\INF, \INF],
                ['asec(sec(x)) = x', 2.0, 4.0],
                ['acsc(csc(x)) = x', -\M_PI_2, \M_PI_2],
                ['acsc(csc(x)) = x', -\INF, \INF],
                ['acsc(csc(x)) = x', -4.0, 0.0],
                ['acot(cot(x)) = x', 0.0, \M_PI],
                ['acot(cot(x)) = x', -\INF, \INF],
                ['acot(cot(x)) = x', 2.0, 4.0],
            ] as [$equation, $lowerBound, $upperBound]
        ) {
            try {
                Math::solve($equation, 'x', $lowerBound, $upperBound);
                self::fail('Expected an infinite solution set for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        self::assertEqualsWithDelta(
            [\M_PI_2],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve('asin(sin(x)) = x', 'x', \M_PI_2, 2.0),
            ),
            1.0E-9,
        );
    }

    public function testPolynomialInverseTrigonometricCompositionsUsePrincipalBranchRanges(): void
    {
        try {
            Math::solve(
                'asin(sin(x^2)) = x^2',
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::fail('Expected infinitely many solutions where x^2 lies within the asin principal branch.');
        } catch (InfiniteSolutionSetException) {
            self::assertTrue(true);
        }

        self::assertSame(
            [],
            Math::solve(
                'asin(sin(x^2)) = x^2',
                'x',
                2.0,
                3.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );

        $branchEndpoint = \sqrt(\M_PI_2);
        $endpointSolution = Math::solve(
            'asin(sin(x^2)) = x^2',
            'x',
            $branchEndpoint,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $endpointSolution);
        self::assertEqualsWithDelta($branchEndpoint, $endpointSolution[0]->value, 1.0E-10);

        try {
            Math::solve(
                'asin(sin(1e-12*x)) = 1e-12*x',
                'x',
                -1.0,
                1.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::fail('Expected the small but positive principal-branch interval to contain infinitely many roots.');
        } catch (InfiniteSolutionSetException) {
            self::assertTrue(true);
        }
    }

    public function testRationalInverseTrigonometricCompositionsPartitionPolesAndBranches(): void
    {
        try {
            Math::solve(
                'asin(sin(1/x)) = 1/x',
                'x',
                1.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::fail('Expected infinitely many roots where 1/x lies inside the asin principal branch.');
        } catch (InfiniteSolutionSetException) {
            self::assertTrue(true);
        }

        self::assertSame(
            [],
            Math::solve(
                'asin(sin(1/x)) = 1/x',
                'x',
                0.1,
                0.5,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
        self::assertSame(
            [],
            Math::solve(
                'asin(sin((x+1)/(x-1))) = (x+1)/(x-1)',
                'x',
                2.0,
                3.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );

        try {
            Math::solve(
                'asin(sin(1/x)) = 1/x',
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::fail('Expected infinitely many roots on the valid pieces around the pole.');
        } catch (InfiniteSolutionSetException) {
            self::assertTrue(true);
        }
    }

    public function testNonRationalInverseTrigonometricCompositionsUseCertifiedRanges(): void
    {
        foreach (
            [
                ['asin(sin(2*sin(x))) = 2*sin(x)', -10.0, 10.0],
                ['asin(sin(exp(x))) = exp(x)', -10.0, 10.0],
            ] as [$equation, $lowerBound, $upperBound]
        ) {
            try {
                Math::solve(
                    $equation,
                    'x',
                    $lowerBound,
                    $upperBound,
                    solverOptions: new SolverOptions(scanSteps: 1),
                );
                self::fail('Expected a nonempty open principal-branch interval for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        self::assertSame(
            [],
            Math::solve(
                'asin(sin(10+sin(x))) = 10+sin(x)',
                'x',
                -10.0,
                10.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
        self::assertSame(
            [],
            Math::solve(
                'asin(sin(exp(x))) = exp(x)',
                'x',
                1.0,
                10.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );

        self::assertSame(
            [],
            Math::solve(
                'asin(sin(sqrt(x))) = sqrt(x)',
                'x',
                -10.0,
                -1.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
        try {
            Math::solve(
                'asin(sin(sqrt(x))) = sqrt(x)',
                'x',
                -1.0,
                4.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::fail('Expected infinitely many roots on the defined portion of the square-root domain.');
        } catch (InfiniteSolutionSetException) {
            self::assertTrue(true);
        }

        $domainBoundaryRoot = Math::solve(
            'asin(sin(sqrt(ln(x)))) = sqrt(ln(x))',
            'x',
            0.0,
            1.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertSame([1.0], \array_map(
            static fn (EquationSolution $solution): float => $solution->value,
            $domainBoundaryRoot,
        ));
        self::assertSame(
            [],
            Math::solve(
                'asin(sin(sqrt(ln(x)))) = sqrt(ln(x))',
                'x',
                0.1,
                0.9,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
        try {
            Math::solve(
                'asin(sin(sqrt(ln(x)))) = sqrt(ln(x))',
                'x',
                0.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::fail('Expected infinitely many solutions on the nonempty nested domain interval.');
        } catch (InfiniteSolutionSetException) {
            self::assertTrue(true);
        }

        self::assertSame(
            [1.0, 2.0],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve(
                    'asin(sin(sqrt((x-1)*(x-2)))) = sqrt((x-1)*(x-2))',
                    'x',
                    1.0,
                    2.0,
                    solverOptions: new SolverOptions(scanSteps: 1),
                ),
            ),
        );
        self::assertSame(
            [],
            Math::solve(
                'asin(sin(sqrt((x-1)*(x-2)))) = sqrt((x-1)*(x-2))',
                'x',
                1.1,
                1.9,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
        try {
            Math::solve(
                'asin(sin(sqrt((x-1)*(x-2)))) = sqrt((x-1)*(x-2))',
                'x',
                0.0,
                3.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::fail('Expected infinitely many solutions on the two defined domain components.');
        } catch (InfiniteSolutionSetException) {
            self::assertTrue(true);
        }
    }

