    public function testDecayingExponentialsAgainstRecurringPeriodicTargetsHaveInfiniteRoots(): void
    {
        foreach (
            [
                'exp(x) = sin(x)',
                'sin(x) = exp(x)',
                'exp(-x^2) = sin(x)',
                'exp(x) = 1 + cos(x)',
                'exp(x) = 1 - cos(x)',
                'exp(x) = sin(x) + cos(x)',
                'exp(x) = 1 + sin(x) + cos(x)',
                'exp(x) = sin(x)^2',
                'exp(x) = abs(sin(x))',
                'exp(x) = sin(x)^3',
                'exp(x) = 2*sin(x)^2',
                'exp(x) = tan(x)',
                'exp(x) = abs(tan(x))',
                'exp(x) = tan(x)^2',
                'exp(x) = tan(x)^3',
                'exp(-x^2) = tan(x)^2',
                'exp(x) = 2 + tan(x)',
                'exp(x) = cot(x)',
                'exp(x) = abs(cot(x))',
                'exp(x) = cot(x)^2',
                'exp(-x^2) = cot(x)^3',
                'exp(x) = sin(x) + sin(2*x)',
                'exp(x) = sin(x)*cos(x)',
                'exp(x) = sin(x) + cos(2*x)',
                'exp(-x^2) = sin(x) + sin(2*x)',
                'exp(x) = sin(x) + cos(3*x/2 + pi/4)',
                'exp(-x^2) = sin(x^2) + sin(3*x^2/2)',
                'exp(x) = sin(x)^2 + sin(2*x)^2',
                'exp(-x^2) = sin(x^2)^2 + sin(2*x^2)^2',
                'exp(x) = sin(x + pi/2)^2 + sin(2*x + pi)^2',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', -\INF, \INF);
                self::fail('Expected an infinite solution set for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        foreach (
            [
                'exp(x) = 2 + sin(x)' => [1.054127124091213],
                'exp(x) = 2 + sin(x) + cos(x)' => [1.1933617065923603],
                'exp(x) = 2 + sin(x) - cos(x)' => [0.0],
                'exp(x) = 3 + sin(x) + sin(2*x)' => [1.4448666306786317],
            ] as $equation => $expectedRoots
        ) {
            $finiteSolutions = Math::solve($equation, 'x', -\INF, \INF);
            self::assertEqualsWithDelta(
                $expectedRoots,
                \array_map(static fn (EquationSolution $solution): float => $solution->value, $finiteSolutions),
                1.0E-9,
                $equation,
            );
        }
    }

    public function testAffineExponentialsEqualMonomialsUseEveryRealLambertWBranch(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        foreach (['2^x = x^2', 'x^2 = 2^x'] as $equation) {
            $solutions = Math::solve($equation, 'x', -10.0, 10.0, solverOptions: $options);

            self::assertCount(3, $solutions, $equation);
            self::assertEqualsWithDelta(-0.766664695962123, $solutions[0]->value, 1.0E-10, $equation);
            self::assertEqualsWithDelta(2.0, $solutions[1]->value, 1.0E-10, $equation);
            self::assertEqualsWithDelta(4.0, $solutions[2]->value, 1.0E-10, $equation);
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-10, $solution->residual, $equation);
            }
        }

        self::assertSame(
            [],
            Math::solve('2^x = -x^2', 'x', -10.0, 10.0, solverOptions: $options),
        );

        $decreasingBase = Math::solve('0.5^x = x^2', 'x', -10.0, 10.0, solverOptions: $options);
        self::assertCount(3, $decreasingBase);
        self::assertEqualsWithDelta(-4.0, $decreasingBase[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(-2.0, $decreasingBase[1]->value, 1.0E-10);
        self::assertEqualsWithDelta(0.766664695962123, $decreasingBase[2]->value, 1.0E-10);

        $affineExponential = Math::solve(
            'exp(2*x+1) = x^2',
            'x',
            -10.0,
            10.0,
            solverOptions: $options,
        );
        self::assertCount(1, $affineExponential);
        self::assertEqualsWithDelta(-0.76624860816175, $affineExponential[0]->value, 1.0E-10);

        $tangentCoefficient = ((\log(2.0) * \M_E) / 2.0) ** 2;
        $tangent = Math::solve(
            '2^x = ' . \sprintf('%.17g', $tangentCoefficient) . '*x^2',
            'x',
            -10.0,
            10.0,
            solverOptions: $options,
        );
        self::assertCount(2, $tangent);
        self::assertEqualsWithDelta(-0.80347882980963, $tangent[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(2.0 / \log(2.0), $tangent[1]->value, 1.0E-10);

        $unbounded = Math::solve('2^x = x^2', 'x', -\INF, \INF, solverOptions: $options);
        self::assertCount(3, $unbounded);
        self::assertEqualsWithDelta(-0.766664695962123, $unbounded[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(2.0, $unbounded[1]->value, 1.0E-10);
        self::assertEqualsWithDelta(4.0, $unbounded[2]->value, 1.0E-10);

        foreach (['1e-309', '5e-324'] as $smallSlope) {
            $solutions = Math::solve(
                'exp(' . $smallSlope . '*x) = x^2',
                'x',
                -2.0,
                2.0,
                solverOptions: $options,
            );
            self::assertEqualsWithDelta(
                [-1.0, 1.0],
                \array_map(static fn (EquationSolution $solution): float => $solution->value, $solutions),
                1.0E-10,
                $smallSlope,
            );
        }

        $underflowedLambertArgument = Math::solve(
            'exp(x - 2000) = x^2',
            'x',
            2000.0,
            2020.0,
            solverOptions: $options,
        );
        self::assertCount(1, $underflowedLambertArgument);
        self::assertEqualsWithDelta(2015.2169642863366, $underflowedLambertArgument[0]->value, 1.0E-8);

        foreach (
            [
                ['exp(x) = x^3', [1.8571838602078354, 4.536403654973528]],
                ['exp(x) = -x^3', [-0.7728829591492101]],
                ['exp(-x) = x^3', [0.7728829591492101]],
                ['exp(x) = 4*x^3', [0.8310314521082454, 7.384405662196099]],
            ] as [$equation, $expectedRoots]
        ) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF, solverOptions: $options);

            self::assertEqualsWithDelta(
                $expectedRoots,
                \array_map(static fn (EquationSolution $solution): float => $solution->value, $solutions),
                1.0E-10,
                $equation,
            );
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-10, $solution->residual, $equation);
            }
        }

        $parameterized = Math::solve(
            'b^x = c*x^3',
            'x',
            -\INF,
            \INF,
            parameters: ['b' => 2.0, 'c' => 3.0],
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [0.8423288246175503, 12.525272895060693],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $parameterized),
            1.0E-10,
        );
    }

    public function testUnboundedAffineExponentialEquationsUseRealLambertWBranches(): void
    {
        foreach (['exp(x) = x + 2', 'x + 2 = exp(x)'] as $equation) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF);

            self::assertCount(2, $solutions, $equation);
            self::assertEqualsWithDelta(-1.84140566043696, $solutions[0]->value, 1.0E-12, $equation);
            self::assertEqualsWithDelta(1.14619322062058, $solutions[1]->value, 1.0E-12, $equation);
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-12, $solution->residual, $equation);
            }
        }

        foreach (
            [
                ['-exp(x) = x + 2', [-2.12002823898764]],
                ['exp(x) = -(x + 2)', [-2.12002823898764]],
                ['-exp(x) = -(x + 2)', [-1.84140566043696, 1.14619322062058]],
                ['x + 2 = -exp(x)', [-2.12002823898764]],
            ] as [$equation, $expectedRoots]
        ) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF);
            self::assertEqualsWithDelta(
                $expectedRoots,
                \array_map(static fn (EquationSolution $solution): float => $solution->value, $solutions),
                1.0E-12,
                $equation,
            );
        }

        $branchPoint = Math::solve('exp(x) = x + 1', 'x', -\INF, \INF);
        self::assertCount(1, $branchPoint);
        self::assertSame(0.0, $branchPoint[0]->value);

        self::assertSame([], Math::solve('exp(x) = x + 0.5', 'x', -\INF, \INF));

        $shifted = Math::solve('exp(2*x + 1) = 3*x + 4', 'x', -\INF, \INF);
        self::assertCount(2, $shifted);
        self::assertEqualsWithDelta(-1.26050262020173, $shifted[0]->value, 1.0E-12);
        self::assertEqualsWithDelta(0.292234846113674, $shifted[1]->value, 1.0E-12);

        $halfLine = Math::solve('exp(x) = x + 2', 'x', 0.0, \INF);
        self::assertCount(1, $halfLine);
        self::assertEqualsWithDelta(1.14619322062058, $halfLine[0]->value, 1.0E-12);

        $oppositeSlopes = Math::solve('exp(-x) = x + 2', 'x', -\INF, \INF);
        self::assertCount(1, $oppositeSlopes);
        self::assertEqualsWithDelta(-0.442854401002389, $oppositeSlopes[0]->value, 1.0E-12);

        $constantExponent = Math::solve('exp(0*x + 1) = 2*x + 4', 'x', -\INF, \INF);
        self::assertCount(1, $constantExponent);
        self::assertEqualsWithDelta((\M_E - 4.0) / 2.0, $constantExponent[0]->value, 1.0E-12);

        $underflowedNegativeWArgument = Math::solve('exp(x - 1000) = x', 'x', -\INF, \INF);
        self::assertCount(1, $underflowedNegativeWArgument);
        self::assertEqualsWithDelta(1006.91464612858, $underflowedNegativeWArgument[0]->value, 1.0E-9);

        $overflowedPositiveWArgument = Math::solve('exp(-x + 1000) = x', 'x', -\INF, \INF);
        self::assertCount(1, $overflowedPositiveWArgument);
        self::assertEqualsWithDelta(993.099169472389, $overflowedPositiveWArgument[0]->value, 1.0E-9);

        foreach (
            [
                'exp(x) = x^2' => [-0.7034674224983917],
                'x^2 = exp(x)' => [-0.7034674224983917],
                'exp(-x) = x^2' => [0.7034674224983917],
                'exp(x) = x^2 + 10' => [2.9188269823063453],
                'exp(x) = x^2 - 2' => [-1.4916441946682422],
                'exp(-x^2) = x' => [0.6529186404089905],
                'exp(-x^2) = x^2' => [-0.7530891649890692, 0.7530891649890692],
            ] as $equation => $expectedRoots
        ) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF);
            self::assertEqualsWithDelta(
                $expectedRoots,
                \array_map(static fn (EquationSolution $solution): float => $solution->value, $solutions),
                1.0E-9,
                $equation,
            );
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-9, $solution->residual, $equation);
            }
        }

        self::assertSame([], Math::solve('exp(x) = -x^2 - 1', 'x', -\INF, \INF));
        self::assertSame([], Math::solve('exp(x^2) = x^2', 'x', -\INF, \INF));
    }

    public function testUnboundedLogarithmEqualsRationalPowerUsesRealBranches(): void
    {
        self::assertSame([], Math::solve('ln(x) = sqrt(x)', 'x', -\INF, \INF));
        self::assertSame([], Math::solve('ln(x) = root(x, 2)', 'x', -\INF, \INF));
        self::assertSame([], Math::solve('ln(x) = root(x, 1)', 'x', -\INF, \INF));
        self::assertSame([], Math::solve('ln(x) = x^(2/5)', 'x', -\INF, \INF));
        self::assertEqualsWithDelta(
            [2.0207473586118576],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve('ln(x) = x^(-1/2)', 'x', -\INF, \INF),
            ),
            1.0E-12,
        );
        self::assertEqualsWithDelta(
            [1.7632228343518968],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve('ln(x) = x^-1', 'x', -\INF, \INF),
            ),
            1.0E-12,
        );
        $zeroExponentSolutions = Math::solve('ln(x) = x^0', 'x', -\INF, \INF);
        self::assertCount(1, $zeroExponentSolutions);
        self::assertEqualsWithDelta(
            \M_E,
            $zeroExponentSolutions[0]->value,
            1.0E-15,
        );

        foreach (
            [
                ['ln(x) = root(x, 3)', [6.405672078981056, 93.35446083500369]],
                ['root(x, 3) = ln(x)', [6.405672078981056, 93.35446083500369]],
                ['ln(x) = cbrt(x)', [6.405672078981056, 93.35446083500369]],
                ['ln(x) = x^(1/3)', [6.405672078981056, 93.35446083500369]],
                ['ln(x) = x^(2/7)', [4.7726389899972785, 742.5505447552592]],
                ['ln(x) = x^(-2/5)', [2.1020632800399324]],
                ['ln(x) = root(x, 4)', [4.177077439000158, 5503.664689076719]],
            ] as [$equation, $expectedRoots]
        ) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF);
            self::assertEqualsWithDelta(
                $expectedRoots,
                \array_map(static fn (EquationSolution $solution): float => $solution->value, $solutions),
                1.0E-10,
                $equation,
            );
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-10, $solution->residual, $equation);
            }
        }

        $upperBranchOnly = Math::solve('ln(x) = root(x, 3)', 'x', 10.0, \INF);
        self::assertCount(1, $upperBranchOnly);
        self::assertEqualsWithDelta(93.35446083500369, $upperBranchOnly[0]->value, 1.0E-10);

        self::assertSame([], Math::solve('ln(x) = root(x, 3)', 'x', 10.0, 20.0));

        $finiteBranchWithOverflowingCompanion = Math::solve(
            'ln(x) = root(x, 110)',
            'x',
            -\INF,
            \INF,
        );
        self::assertCount(1, $finiteBranchWithOverflowingCompanion);
        self::assertEqualsWithDelta(
            2.7434518198441222,
            $finiteBranchWithOverflowingCompanion[0]->value,
            1.0E-12,
        );

        $largeReciprocalExponent = Math::solve(
            'ln(x) = x^(1/1000000000000000000)',
            'x',
            -\INF,
            \INF,
        );
        self::assertCount(1, $largeReciprocalExponent);
        self::assertEqualsWithDelta(\M_E, $largeReciprocalExponent[0]->value, 1.0E-12);

        foreach (
            [
                ['log2(x) = x^(1/3)', [2.590924758528201, 981.9700013422708]],
                ['log2(x) = sqrt(x)', [4.0, 16.0]],
                ['log10(x) = x^(1/3)', []],
                ['log10(x) = x^(-1/2)', [3.452761407185685]],
                ['log(x, 2) = x^(1/3)', [2.590924758528201, 981.9700013422708]],
                ['log(x, 0.5) = x^(1/3)', [0.5640059120652321]],
                ['log(x, 0.5) = x^(-1/2)', [0.0625, 0.25]],
                ['log(x, 0.5) = x^(-1/3)', [0.0010183610483345557, 0.3859625783066195]],
                ['log(x, 0.1) = x^(-1/2)', []],
                ['ln(x) = 0.5*x^(1/3)', [1.8467814145798798, 4912.035397576528]],
                ['ln(x) = x^(1/3)/2', [1.8467814145798798, 4912.035397576528]],
                ['ln(x) = 2*x^(1/3)', []],
                ['ln(x) = 2*sqrt(x)', []],
                ['log2(x) = 2*x^(-1/2)', [2.4323848164566324]],
                ['ln(x) = 0*x^(1/3)', [1.0]],
                ['ln(x) = -0.5*x^(1/3)', [0.6486740957209505]],
                ['ln(x) = x^(1/3)/-2', [0.6486740957209505]],
                ['ln(x) = x^(1/3) + 1', []],
                ['ln(x) = x^(1/3) - 2', [0.255201955032402, 587.6747193440052]],
                ['ln(x) = 2*x^(1/3) - 2', [1.0, 9.855854878957526]],
                ['ln(x) = x^(1/3) + x^(1/3) - 2', [1.0, 9.855854878957526]],
                ['ln(x) = cbrt(x) + x^(1/3) - 2', [1.0, 9.855854878957526]],
                ['log2(x) = cbrt(x) + x^(1/3) - 2', [1.0, 64.0]],
                ['ln(x) = x^(1/3) - 1 - 2', [0.07605349710610525, 960.8749193050689]],
                ['ln(x) = 2*(x^(1/3) - 2)', [0.035297715863693756, 70.23751303285873]],
                ['ln(x) = 3*x^(1/3) - 3', [1.0]],
                ['ln(x) = 4*sqrt(x) - 2*(1 + ln(2))', [0.25]],
                ['ln(x) = 0.5*x^(1/3) + 1', [7.109449539103814, 2575.7375053052824]],
                ['log2(x) = 2*x^(-1/2) + 1', [4.0]],
                ['ln(x) = 2*x^0 + 3', [148.4131591025766]],
            ] as [$equation, $expectedRoots]
        ) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF);
            self::assertEqualsWithDelta(
                $expectedRoots,
                \array_map(static fn (EquationSolution $solution): float => $solution->value, $solutions),
                1.0E-10,
                $equation,
            );
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-10, $solution->residual, $equation);
            }
        }
    }

