    public function testUnboundedCommensurateExponentialSumsReduceToPositivePolynomialRoots(): void
    {
        $hyperbolicLevel = Math::solve('exp(x) + exp(-x) = 3', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [-0.962423650119207, 0.962423650119207],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $hyperbolicLevel),
            1.0E-12,
        );

        $tangentLevel = Math::solve('exp(x) + exp(-x) = 2', 'x', -\INF, \INF);
        self::assertCount(1, $tangentLevel);
        self::assertSame(0.0, $tangentLevel[0]->value);

        self::assertSame([], Math::solve('exp(x) + exp(-x) = 1', 'x', -\INF, \INF));

        $differentFrequencies = Math::solve('exp(2*x) + exp(x) = 6', 'x', -\INF, \INF);
        self::assertCount(1, $differentFrequencies);
        self::assertEqualsWithDelta(\log(2.0), $differentFrequencies[0]->value, 1.0E-12);

        $halfLine = Math::solve('exp(x) + exp(-x) = 3', 'x', 0.0, \INF);
        self::assertCount(1, $halfLine);
        self::assertEqualsWithDelta(0.962423650119207, $halfLine[0]->value, 1.0E-12);

        $smallLeadingCoefficient = Math::solve('1e-300*exp(x) + exp(-x) = 2', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [-0.693147180559945, 691.468675078774],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $smallLeadingCoefficient),
            1.0E-10,
        );

        $smallConstantCoefficient = Math::solve('exp(x) + 1e-300*exp(-x) = 2', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [-691.468675078774, 0.693147180559945],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $smallConstantCoefficient),
            1.0E-10,
        );

        $cubicRoots = Math::solve(
            'exp(3*x) - 6*exp(2*x) + 11*exp(x) = 6',
            'x',
            -\INF,
            \INF,
        );
        self::assertEqualsWithDelta(
            [0.0, \log(2.0), \log(3.0)],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $cubicRoots),
            1.0E-12,
        );

        $zeroRightHandSide = Math::solve(
            'exp(3*x) - 6*exp(2*x) + 11*exp(x) - 6 = 0',
            'x',
            -\INF,
            \INF,
        );
        self::assertEqualsWithDelta(
            [0.0, \log(2.0), \log(3.0)],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $zeroRightHandSide),
            1.0E-12,
        );
    }

    public function testExponentialIdentitiesDistinguishExactAndNearCancellation(): void
    {
        foreach (['exp(x) - exp(x) = 0', '0*exp(x) = 0'] as $equation) {
            try {
                Math::solve($equation, 'x', -1.0, 1.0);
                self::fail('Expected an infinite solution set for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::addToAssertionCount(1);
            }
        }

        self::assertSame([], Math::solve('exp(x) = (1 - 1e-15)*exp(x)', 'x', -1.0, 1.0));
        self::assertSame([], Math::solve('exp(x) - exp(x) = 1', 'x', -1.0, 1.0));
    }

