    public function testUnboundedIncommensurateExponentialSumsUseDominanceBounds(): void
    {
        $lowScanOptions = new SolverOptions(scanSteps: 1);
        $stationaryRoot = Math::solve(
            'sqrt(2)*exp(x) + exp(-sqrt(2)*x) = sqrt(2) + 1',
            'x',
            -1.0,
            1.0,
            solverOptions: $lowScanOptions,
        );
        self::assertCount(1, $stationaryRoot);
        self::assertEqualsWithDelta(0.0, $stationaryRoot[0]->value, 1.0E-12);
        self::assertLessThanOrEqual(1.0E-12, $stationaryRoot[0]->residual);

        $rootsNearStationaryLevel = Math::solve(
            'sqrt(2)*exp(x) + exp(-sqrt(2)*x) = sqrt(2) + 1 + 1e-8',
            'x',
            -1.0,
            1.0,
            solverOptions: $lowScanOptions,
        );
        self::assertCount(2, $rootsNearStationaryLevel);
        self::assertLessThan(0.0, $rootsNearStationaryLevel[0]->value);
        self::assertGreaterThan(0.0, $rootsNearStationaryLevel[1]->value);
        foreach ($rootsNearStationaryLevel as $solution) {
            self::assertLessThanOrEqual(1.0E-12, $solution->residual);
        }

        $solutions = Math::solve('exp(x) + exp(sqrt(2)*x) = 3', 'x', -\INF, \INF);
        self::assertCount(1, $solutions);
        self::assertLessThanOrEqual(1.0E-9, $solutions[0]->residual);
        $largeNegativeRoot = Math::solve(
            'exp(x + 710) + exp(sqrt(2)*x + 710) = 1',
            'x',
            -\INF,
            \INF,
        );
        self::assertCount(1, $largeNegativeRoot);
        self::assertEqualsWithDelta(-710.0, $largeNegativeRoot[0]->value, 1.0E-9);
        self::assertLessThanOrEqual(1.0E-10, $largeNegativeRoot[0]->residual);
        self::assertCount(
            1,
            Math::solve(
                'exp(x) + exp(sqrt(2)*x) = 3',
                'x',
                $solutions[0]->value,
                $solutions[0]->value,
            ),
        );

        self::assertSame([], Math::solve('exp(x) + exp(sqrt(2)*x) = -3', 'x', -\INF, \INF));

        $reflected = Math::solve('exp(-x) + exp(-sqrt(2)*x) = 3', 'x', -\INF, \INF);
        self::assertCount(1, $reflected);
        self::assertEqualsWithDelta(-$solutions[0]->value, $reflected[0]->value, 1.0E-9);

        $crossing = Math::solve('exp(x) - exp(sqrt(2)*x) = 0', 'x', -\INF, \INF);
        self::assertCount(1, $crossing);
        self::assertEqualsWithDelta(0.0, $crossing[0]->value, 1.0E-9);
        self::assertSame([], Math::solve('exp(x) + exp(sqrt(2)*x) = 0', 'x', -\INF, \INF));

        $twoRoots = Math::solve('exp(x) + exp(-sqrt(2)*x) = 3', 'x', -\INF, \INF);
        self::assertCount(2, $twoRoots);
        self::assertEqualsWithDelta(-0.6401807297506371, $twoRoots[0]->value, 1.0E-8);
        self::assertEqualsWithDelta(1.0160817999445175, $twoRoots[1]->value, 1.0E-8);
        foreach ($twoRoots as $solution) {
            self::assertLessThanOrEqual(1.0E-9, $solution->residual);
        }
        self::assertCount(1, Math::solve('exp(x) + exp(-sqrt(2)*x) = 3', 'x', 0.0, \INF));

        $restricted = Math::solve('exp(x) + exp(sqrt(2)*x) = 3', 'x', -2.0, 0.0);
        self::assertSame([], $restricted);
    }

