    public function testNumericalZeroAtAnExtremumDoesNotHideCloseDistinctRoots(): void
    {
        foreach ([1, 256] as $scanSteps) {
            $roots = Math::solve(
                'sqrt(2)*exp(x) + exp(-sqrt(2)*x) = sqrt(2) + 1 + 1e-15',
                'x',
                -1.0,
                1.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );

            self::assertCount(2, $roots);
            self::assertLessThan(0.0, $roots[0]->value);
            self::assertGreaterThan(0.0, $roots[1]->value);
            self::assertLessThan(1.0E-7, $roots[1]->value - $roots[0]->value);
            foreach ($roots as $solution) {
                self::assertLessThanOrEqual(1.0E-12, $solution->residual);
            }
        }
    }

    public function testExponentialDominanceBoundsStayFiniteWhenOriginAmplitudesOverflow(): void
    {
        $solver = new EquationSolver();
        $method = new \ReflectionMethod($solver, 'exponentialSumRootBounds');
        $bounds = $method->invoke(
            $solver,
            [
                ['coefficient' => 1.0, 'slope' => 1.0, 'offset' => 710.0],
                ['coefficient' => 1.0, 'slope' => \sqrt(2.0), 'offset' => 710.0],
                ['coefficient' => -1.0, 'slope' => 0.0, 'offset' => 0.0],
            ],
        );

        self::assertIsArray($bounds);
        self::assertCount(2, $bounds);
        self::assertTrue(\is_finite($bounds[0]));
        self::assertTrue(\is_finite($bounds[1]));
        self::assertLessThan($bounds[1], $bounds[0]);
        self::assertLessThan(-710.0, $bounds[0]);
        self::assertGreaterThan(-710.0, $bounds[1]);
    }

    public function testUnboundedIncommensurateExponentialSumsWithPolynomialPhases(): void
    {
        $sameDirection = Math::solve('exp(x^2) + exp(sqrt(2)*x^2) = 3', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [-0.5778570964088743, 0.5778570964088743],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $sameDirection),
            1.0E-9,
        );

        $opposedDirection = Math::solve('exp(x^2) + exp(-sqrt(2)*x^2) = 3', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [-1.0080088292988894, 1.0080088292988894],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $opposedDirection),
            1.0E-9,
        );

        self::assertCount(
            1,
            Math::solve('exp(x^2) + exp(sqrt(2)*x^2) = 3', 'x', 0.0, \INF),
        );

        $shiftedQuadratic = Math::solve(
            'exp(x^2 + x) + exp(sqrt(2)*(x^2 + x)) = 3',
            'x',
            -\INF,
            \INF,
        );
        self::assertEqualsWithDelta(
            [-1.2641458132474415, 0.2641458132474413],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $shiftedQuadratic),
            1.0E-9,
        );

        $cubicPhase = Math::solve('exp(x^3) + exp(sqrt(2)*x^3) = 3', 'x', -\INF, \INF);
        self::assertCount(1, $cubicPhase);
        self::assertEqualsWithDelta(0.6937669933865197, $cubicPhase[0]->value, 1.0E-9);
    }

    public function testUnboundedTwoTermExponentialEquationsWithDifferentPhases(): void
    {
        $roots = Math::solve('exp(x^2) - exp(x) = 0', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [0.0, 1.0],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $roots),
            1.0E-9,
        );

        $roots = Math::solve('exp(x^2) - exp(2*x) = 0', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [0.0, 2.0],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $roots),
