            ),
            1.0E-9,
        );
        self::assertSame([], Math::solve('exp(x^2) + exp(x) = 0', 'x', -\INF, \INF));
    }

    public function testUnboundedPositiveExponentialSumsUseGlobalPolynomialLowerBounds(): void
    {
        self::assertSame([], Math::solve('exp(x^2) + exp(x) = 1', 'x', -\INF, \INF));
        self::assertSame([], Math::solve('exp(x^2) + exp(x) = 0.5 + 0.5', 'x', -\INF, \INF));
        self::assertSame([], Math::solve('exp((x - 3)^2) + exp(x) = 1', 'x', -\INF, \INF));
        self::assertSame([], Math::solve('2 * exp((x - 3)^2) = 1', 'x', -\INF, \INF));
        self::assertSame(
            [],
            Math::solve('exp(x^2 - 0.3) + exp((x - 1)^2 - 0.3) = 1', 'x', -\INF, \INF),
        );
        self::assertSame(
            [],
            Math::solve('exp(x^2 - 0.3) + exp((x - 1)^2 - 0.3) = 1.5', 'x', -\INF, \INF),
        );
        self::assertSame(
            [],
            Math::solve('exp(x^4 - 0.3) + exp((x - 1)^4 - 0.3) = 1.5', 'x', -\INF, \INF),
        );
        self::assertSame(
            [],
            Math::solve('exp(x^6 - 0.3) + exp((x - 1)^6 - 0.3) = 1.5', 'x', -\INF, \INF),
        );
        self::assertSame(
            [],
            Math::solve(
                'exp(x^4 + x^2 - 0.3) + exp((x - 1)^4 + (x - 1)^2 - 0.3) = 1.3',
                'x',
                -\INF,
                \INF,
            ),
        );

        try {
            Math::solve('exp(x^2) + exp(x) = 2', 'x', -\INF, \INF);
            self::fail('The quadratic lower bound does not decide the equation near its minimum.');
        } catch (\InvalidArgumentException $exception) {
            self::assertStringContainsString('exact rational-function', $exception->getMessage());
        }
        try {
            Math::solve(
                'exp(x^4 + x^2 - 0.3) + exp((x - 1)^4 + (x - 1)^2 - 0.3) = 1.41',
                'x',
                -\INF,
                \INF,
            );
            self::fail('The quadratic lower bound is below this target.');
        } catch (\InvalidArgumentException $exception) {
            self::assertStringContainsString('exact rational-function', $exception->getMessage());
        }
        try {
            Math::solve('exp(x^2 - 0.3) + exp((x - 1)^2 - 0.3) = 1.9', 'x', -\INF, \INF);
            self::fail('The sum of quadratic lower bounds is below this target.');
        } catch (\InvalidArgumentException $exception) {
            self::assertStringContainsString('exact rational-function', $exception->getMessage());
        }
        try {
            Math::solve('exp(x^4 - 0.3) + exp((x - 1)^4 - 0.3) = 1.6', 'x', -\INF, \INF);
            self::fail('The quartic lower bound is below this target.');
        } catch (\InvalidArgumentException $exception) {
            self::assertStringContainsString('exact rational-function', $exception->getMessage());
        }
        try {
            Math::solve('exp(x^6 - 0.3) + exp((x - 1)^6 - 0.3) = 1.51', 'x', -\INF, \INF);
            self::fail('The sixth-degree lower bound is below this target.');
        } catch (\InvalidArgumentException $exception) {
            self::assertStringContainsString('exact rational-function', $exception->getMessage());
        }
    }

    public function testUnboundedSineAndCosineWithAffineTargetsReduceToFiniteIntervals(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $positiveSine = Math::solve('sin(x) = x/2', 'x', 0.0, \INF, solverOptions: $options);
        self::assertEqualsWithDelta(
            [0.0, 1.895494267033981],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $positiveSine),
            1.0E-9,
        );

        $negativeSine = Math::solve('sin(x) = x/2', 'x', -\INF, 0.0, solverOptions: $options);
        self::assertEqualsWithDelta(
            [-1.895494267033981, 0.0],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $negativeSine),
            1.0E-9,
        );

        $cosineFixedPoint = Math::solve('cos(x) = x', 'x', 0.0, \INF, solverOptions: $options);
        self::assertCount(1, $cosineFixedPoint);
        self::assertEqualsWithDelta(0.739085133215161, $cosineFixedPoint[0]->value, 1.0E-9);

        self::assertSame([], Math::solve('cos(x) = x', 'x', -\INF, 0.0, solverOptions: $options));

        $negatedCosine = Math::solve('-cos(x) = x', 'x', -\INF, \INF, solverOptions: $options);
        self::assertCount(1, $negatedCosine);
        self::assertEqualsWithDelta(-0.739085133215161, $negatedCosine[0]->value, 1.0E-9);
    }

