    public function testUnboundedSineAndCosineWithNonlinearPolynomialPhasesAndTargets(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $sineRoots = Math::solve(
            'sin(x^2) = x/2',
            'x',
            -\INF,
            \INF,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [0.0, 0.505482272338061, 1.511542718551481],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $sineRoots),
