        );

        $cosineRoots = Math::solve(
            'cos(x^2) = x',
            'x',
            -\INF,
            \INF,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [0.801070765217819],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $cosineRoots),
            1.0E-8,
        );

        $cubicPhaseRoots = Math::solve(
            'sin(x^3) = x/2',
            'x',
            -\INF,
            \INF,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [
                -1.994175999222856,
                -1.974060956567583,
                -1.340211156569493,
                -0.715063834247192,
                0.0,
                0.715063834247192,
                1.340211156569493,
                1.974060956567583,
                1.994175999222856,
            ],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $cubicPhaseRoots),
            1.0E-8,
        );

        $scaledSineRoots = Math::solve(
            '2*sin(x^2) = x',
            'x',
            -\INF,
            \INF,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [0.0, 0.505482272338061, 1.511542718551481],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $scaledSineRoots),
            1.0E-8,
        );

        $negativeScaledCosineRoots = Math::solve(
            '-2*cos(x^2) = x',
            'x',
            -\INF,
            \INF,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [-1.018171830314465, 1.573679779148237, 1.871402519800860],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                $negativeScaledCosineRoots,
            ),
            1.0E-8,
        );

        $parameterScaledSineRoots = Math::solve(
            'scale*sin(x^2) = x',
            'x',
            -\INF,
            \INF,
            parameters: ['scale' => 2.0],
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [0.0, 0.505482272338061, 1.511542718551481],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                $parameterScaledSineRoots,
            ),
            1.0E-8,
        );

        $dividedSineRoots = Math::solve(
            'x/4 = sin(x^2)/2',
            'x',
            -\INF,
            \INF,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [0.0, 0.505482272338061, 1.511542718551481],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                $dividedSineRoots,
            ),
            1.0E-8,
        );
    }

    public function testUnboundedSineAndCosineWithPolynomialOffsets(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $sineWithOffset = Math::solve(
            'sin(x^2) + x = x^2',
            'x',
            -\INF,
            \INF,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [0.0, 1.507159306352581],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $sineWithOffset),
            1.0E-8,
        );

        $scaledSineWithOffset = Math::solve(
            '2*(sin(x^2) + x) = x^2',
            'x',
            -\INF,
            \INF,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [0.0, 1.818597982822070],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                $scaledSineWithOffset,
            ),
            1.0E-8,
        );

        $cosineOnRight = Math::solve(
            'x^2 = cos(x^2) + x',
            'x',
            -\INF,
            \INF,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [-0.590744010950731, 1.170447902330945],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $cosineOnRight),
            1.0E-8,
        );

        $subtractedCosine = Math::solve(
            'x^2 = 2*(x - cos(x^2))',
            'x',
            -\INF,
            \INF,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [1.023482233207010, 2.136761677216794],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $subtractedCosine),
            1.0E-8,
        );
    }

    public function testUnboundedBoundedTrigonometricExpressionsAgainstPolynomials(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $mixedSum = Math::solve(
            'sin(x) + cos(x) = x',
            'x',
            -\INF,
            \INF,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [1.258728177477675],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $mixedSum),
            1.0E-8,
        );

        $harmonicSum = Math::solve(
            'sin(x) + sin(2*x) = x',
            'x',
            -\INF,
            \INF,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [-1.370300112413216, 0.0, 1.370300112413216],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $harmonicSum),
            1.0E-8,
        );

        $scaledExpression = Math::solve(
            '(sin(x) + 0.5)/2 = x',
            'x',
            -\INF,
            \INF,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [0.481598002894316],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $scaledExpression),
            1.0E-8,
        );

        $squaredSine = Math::solve(
            'sin(x)^2 = x/2',
            'x',
            -\INF,
            \INF,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [0.0, 0.554572090825021, 1.849076836447542],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $squaredSine),
            1.0E-8,
        );

        $reciprocalSquaredSine = Math::solve(
            '1/(sin(x)^2 + 2) = x',
            'x',
            -\INF,
            \INF,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [0.455833120387979],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                $reciprocalSquaredSine,
            ),
            1.0E-8,
        );

        $squareRootExpression = Math::solve(
            'sqrt(sin(x)^2) = x/2',
            'x',
            -\INF,
            \INF,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [0.0, 1.895494266956424],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                $squareRootExpression,
            ),
            1.0E-8,
        );

        $exponentialExpression = Math::solve(
            'exp(sin(x)) = x',
            'x',
            -\INF,
            \INF,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [2.219107148925641],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                $exponentialExpression,
            ),
            1.0E-8,
        );

        $logarithmicExpression = Math::solve(
            'ln(2 + sin(x)) = x',
            'x',
            -\INF,
            \INF,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [1.054127124098787],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                $logarithmicExpression,
            ),
            1.0E-8,
        );

        foreach (
            [
                'erfc(sin(x)) = x' => [0.498749872133260],
                'sech(sin(x)) = x' => [0.791275176488708],
                'acos(sin(x)) = x' => [\M_PI / 4.0],
                'expm1(sin(x)) = x' => [0.0, 1.696812386826548],
                'log2(2 + sin(x)) = x' => [1.584914573230539],
                'log10(2 + sin(x)) = x' => [0.373872042717336],
                'log(2 + sin(x), 2) = x' => [1.584914573230539],
                'log(2 + sin(x), 0.5) = x' => [-0.557080919876643],
                'log(2 + sin(x), 2 + 0.2*cos(x)) = x' => [1.589076601222731],
                'atan2(sin(x), cos(x)) = x^2' => [0.0, 1.0],
                'atan2(1 + sin(x), 2 + cos(x)) = x' => [0.463647609009534],
                'atan2(1 + sin(x), -2 + 0.1*cos(x)) = x' => [2.481754956245467],
                'tan(sin(x)) = x' => [-1.557085815545559, 0.0, 1.557085815545559],
                'sec(sin(x)) = x' => [1.786699685339653],
                'csc(1 + 0.2*sin(x)) = x' => [1.083030675077656],
                'cot(1 + 0.2*sin(x)) = x' => [0.511597143888661],
                'sinc(x) = x' => [0.876726215433640],
                'sincpi(x) = x' => [0.559289004189200],
                'csch(sin(x) + 2) = x' => [0.220172055733920],
                'coth(sin(x) + 2) = x' => [1.006780539661003],
                'min(sin(x), cos(x)) = x' => [0.0],
                'max(sin(x), cos(x)) = x' => [0.739085133226278],
                'hypot(sin(x), cos(x)) = x' => [1.0],
                'sign(sin(x)) = x' => [-1.0, 0.0, 1.0],
                '(sin(x)^2)^(1/3) = x/2' => [0.0, 1.919109527409697],
                'cbrt(sin(x)) = x/2' => [-1.951168468299632, 0.0, 1.951168468299632],
                'root(sin(x), 3) = x/2' => [-1.951168468299632, 0.0, 1.951168468299632],
            ] as $equation => $expectedRoots
        ) {
            $roots = Math::solve(
                $equation,
                'x',
                -\INF,
                \INF,
                solverOptions: $options,
            );
            self::assertEqualsWithDelta(
                $expectedRoots,
                \array_map(static fn (EquationSolution $solution): float => $solution->value, $roots),
                1.0E-8,
                $equation,
            );
        }
    }

    public function testUnboundedIncommensurateAffineTrigonometricSumsHaveInfiniteZeroSets(): void
    {
        foreach (
            [
                'sin(x) + sin(sqrt(2)*x) = 0',
                'sin(3*x + 1) - sin(sqrt(2)*x - 4) = 0',
                'cos(x) + cos(sqrt(2)*x) = 0',
                'cos(2*x + 0.3) - cos(sqrt(3)*x) = 0',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', -\INF, \INF);
                self::fail('Expected infinitely many roots for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::addToAssertionCount(1);
            }
        }

        self::expectException(\InvalidArgumentException::class);
        Math::solve('sin(x) + sin(sqrt(2)*x) = 1', 'x', -\INF, \INF);
    }

    public function testUnboundedPolynomialPhaseCrossesGloballyUnitBoundedTargetsInfinitelyOften(): void
    {
        foreach (
            [
                'sin(x) = tanh(x)',
                'sin(x) = erf(x)',
                'cos(2*x + 0.3) = 0.5*tanh(x)',
                'sin(x^2) = -erf(2*x)',
                'cos(x) = erf(x)/2',
                'sin(x) = x/sqrt(x^2 + 1)',
                'cos(x) = (x + 1)/sqrt((x + 1)^2 + 4)',
                'sin(x) = 2*atan(x)/pi',
                'cos(x) = arctan(x)/(pi/2)',
                'sin(x) = sin(atan(x))',
                'sin(x) = sin(sin(x) + cos(x))',
                'sin(x) = tanh(x)*cos(x)',
                'sin(x) = abs(tanh(x))',
                'cos(x) = sqrt(tanh(x)^2)',
                'sin(x) = abs(sin(atan(x)))',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', -\INF, \INF);
                self::fail('Expected infinitely many roots for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::addToAssertionCount(1);
            }
        }

        foreach (
            [
                'sin(x) = 2*tanh(x)',
                'cos(x) = atan(x)',
                'sin(x) = 2*x/sqrt(x^2 + 1)',
                'sin(x) = x/sqrt(x^2 - 1)',
                'sin(x) = 2*atan(x)',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', -\INF, \INF);
                self::fail('Expected this equation to remain outside the unit-bound proof: ' . $equation);
            } catch (InfiniteSolutionSetException $exception) {
                self::fail('The unit-bound proof overclaimed for ' . $equation . ': ' . $exception->getMessage());
            } catch (\InvalidArgumentException) {
                self::addToAssertionCount(1);
            }
        }
    }

    public function testUnboundedOscillationCrossesTargetsWithInteriorTailLimits(): void
    {
        foreach (
            [
                ['sin(x) = tanh(x) + 0.1', -\INF, \INF],
                ['sin(x) = tanh(x) - 0.1', -\INF, \INF],
                ['sin(x) = 0.5 + tanh(x)/2', -\INF, \INF],
                ['sin(x) = tanh(-x) + 0.1', -\INF, \INF],
                ['sin(x) = 1 - 1/(x^2 + 1) + tanh(x)/100', -\INF, \INF],
                ['sin(x) = tanh(x)/(x^2 + 1)', -\INF, \INF],
                ['sin(x) = tanh(x) - 0.1', 0.0, \INF],
                ['sin(x) = tanh(x) + 0.1', -\INF, 0.0],
            ] as [$equation, $lowerBound, $upperBound]
        ) {
            try {
                Math::solve($equation, 'x', $lowerBound, $upperBound);
                self::fail('Expected infinitely many roots on an unbounded tail: ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::addToAssertionCount(1);
            }
        }

        $poleSolutions = Math::solve('sin(x) = 1 + 1/(x^2 - 1)', 'x', -\INF, \INF);
        self::assertCount(2, $poleSolutions);

        self::expectException(\InvalidArgumentException::class);
        Math::solve('sin(x) = atan(x)', 'x', -\INF, \INF);
    }

    public function testUnboundedOscillationCrossesExponentiallyApproachedRangeBoundaries(): void
    {
        foreach (
            [
                'sin(x) = 1 - exp(-x)',
                'cos(x) = 1 - 2*exp(-x^2)',
                'sin(x) = -1 + exp(x)',
                'cos(x) = -1 + 0.25*exp(-x^2)',
                'sin(x) = 1 - exp(-x) + exp(-x)/2',
                'sin(x) = -1 + exp(x) - exp(x)/4',
                'sin(x) = 1 - exp(-x) + exp(-2*x)',
                'sin(x) = 1 - exp(-x) - exp(-2*x)',
                'sin(x) = -1 + exp(x) - exp(2*x)',
                'sin(x) = 1 - exp(-x^2) + exp(-x^2 - x)',
                'sin(x) = 1 - exp(-x^2) + exp(-x^2 + x)',
                'sin(x) = 1 - exp(-x^2) - exp(-x^2 + 1)',
                'sin(x) = -1 + exp(-x^2) + exp(-x^2 - 1)',
                'sin(x) = 1 - x*exp(-x^2)',
                'sin(x) = 1 - x^2*exp(-x^2)',
                'sin(x) = 1 + x*exp(-x^2)',
                'sin(x) = 1 - x*exp(-x) - exp(-2*x)',
                'sin(x) = -1 + x*exp(-x) + exp(-2*x)',
                'sin(x) = 1 - (1/x)*exp(-x) - exp(-2*x)',
                'sin(x) = 1 - (1/(x^2 + 1))*exp(-x^2) - exp(-2*x^2)',
                'sin(x) = 1 - x*exp(-x^2) + exp(-x^2 + 1)',
                'sin(x) = 1 - x*exp(-x^2) + (x - 1)*exp(-x^2)',
                'sin(x) = 1 - x*exp(-x^2) - x*exp(-x^2 + 1)',
                'sin(x) = 1 - exp(-x^2) + exp(-1.00000000000000000001*x^2)',
                'sin(x) = 1 - exp(-sqrt(2)*x^2) + exp(-2*sqrt(2)*x^2)',
                'sin(x) = 1 - exp(-x^3/(x^2 + 1))',
                'sin(x) = -1 + exp(x^3/(x^2 + 1))',
                'sin(x) = 1 - (1/x)*exp(-x^3/(x^2 + 1))',
                'sin(x) = 1 - exp(-x^3/(x^2 + 1)) + exp(-2*x^3/(x^2 + 1))',
                'sin(x) = 1 - exp(-x^3/(x^2 + 1)) - exp(-x^3/(x^2 + 1) + 1)',
                'sin(x) = -1 + exp(x^3/(x^2 + 1)) - exp(2*x^3/(x^2 + 1))',
                'sin(x) = 1 - (1/x)*exp(-x^3/(x^2 + 1)) - exp(-2*x^3/(x^2 + 1))',
                'sin(x) = 1 - x*exp(-x^3/(x^2 + 1)) - exp(-x^3/(x^2 + 1) + 1)',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', -\INF, \INF);
                self::fail('Expected infinitely many roots near the trigonometric boundary: ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::addToAssertionCount(1);
            }
        }

        foreach ([
            'sin(x) = 1 + exp(-x)',
            'sin(x) = -1 - exp(x)',
            'sin(x) = 1 + exp(-x) - exp(-x)/2',
            'sin(x) = 1 + exp(-x) - exp(-2*x)',
            'sin(x) = 1 + exp(-x^2) + exp(-x^2 - x)',
            'sin(x) = 1 + exp(-x^2) - exp(-x^2 + 1)',
            'sin(x) = 1 + x^2*exp(-x^2)',
            'sin(x) = 1 + x^2*exp(-x^2) + x^4*exp(-2*x^2)',
            'sin(x) = 1 + (1/(x^2 + 1))*exp(-x^2) + exp(-2*x^2)',
            'sin(x) = 1 + x^2*exp(-x^2) - exp(-x^2 + 1)',
            'sin(x) = 1 + x*exp(-x^2) - (x - 1)*exp(-x^2)',
            'sin(x) = 1 + x^2*exp(-x^2) + x^2*exp(-x^2 + 1)',
            'sin(x) = 1 - x^2*exp(-x^2) + x^2*exp(-x^2 + 1)',
            'sin(x) = 1 + exp(-x^2) - exp(-1.00000000000000000001*x^2)',
            'sin(x) = 1 + exp(-sqrt(2)*x^2) + exp(-2*sqrt(2)*x^2)',
            'sin(x) = 1 + exp(-x^3/(x^2 + 1))',
            'sin(x) = 1 + exp(-x^3/(x^2 + 1)) - exp(-2*x^3/(x^2 + 1))',
            'sin(x) = 1 + exp(-x^3/(x^2 + 1)) + exp(-x^3/(x^2 + 1) + 1)',
        ] as $equation) {
            try {
                Math::solve($equation, 'x', -\INF, \INF);
                self::fail('Expected no roots for the outward boundary approach: ' . $equation);
            } catch (InfiniteSolutionSetException $exception) {
                self::fail('The boundary proof used the wrong approach direction: ' . $exception->getMessage());
            } catch (\InvalidArgumentException) {
                self::addToAssertionCount(1);
            }
        }
    }

    public function testUnboundedOscillationCrossesElementaryInteriorLimits(): void
    {
        foreach (
            [
                'sin(x) = 1 - exp(-1/x)',
                'sin(x) = 1 - exp(1/x)',
                'sin(x) = 1 - exp(-1/(x^2 + 1))',
                'sin(x) = 1 - exp(-x/(x^2 + 1))',
                'cos(x) = 1 - exp(-1 - 1/x)',
                'sin(sqrt(x)) = 1/4 + exp(-x)',
                'sin(ln(x)) = 1/4 + 1/x',
                'sin(exp(x)) = 1/4 + exp(-x)',
                'sin(1 - sqrt(x)) = 1/4 + exp(-x)',
                'sin(ln(x) + 1) = 1/4 + 1/x',
                'sin(sqrt(x)) = 1/4 + exp(-sqrt(x))',
                'sin(exp(x)) = 1/4 + exp(-ln(x))',
                'sin(sqrt(-x)) = 1/4 + exp(x)',
                'sin(log(x, 10)) = 1/4 + 1/x',
                'sin(log(x, 0.5)) = 1/4 + 1/x',
                'sin(log(x, 1 + 1/x)) = 1/4 + 1/x',
                'sin(log(x, 1 - 1/x)) = 1/4 + 1/x',
                'sin(log(exp(x), x)) = 1/4 + 1/x',
                'sin(log(exp(-x), x)) = 1/4 + 1/x',
                'sin(log(exp(x^2), exp(x))) = 1/4 + 1/x',
                'sin(log(exp(-x^2), exp(x))) = 1/4 + 1/x',
                'sin(x + log(x^2 + 1, x)) = 1/4 + 1/x',
                'sin(x + log(1/(x^2), 1/x)) = 1/4 + 1/x',
                'sin(x + log(x^2 + 1, -x)) = 1/4 + 1/x',
                'sin(x*sqrt(x)) = 1/4 + 1/x',
                'sin(exp(x)*exp(-x/2)) = 1/4 + 1/x',
