    public function testFiniteOverflowingExponentialPhaseIsNotClassifiedAsDivergent(): void
    {
        try {
            Math::solve('sin(exp(1000 + x - x)) = 1/4', 'x', -\INF, \INF);
            self::fail('A finite exponential phase cannot produce infinitely many roots through phase divergence.');
        } catch (InfiniteSolutionSetException) {
            self::fail('Float overflow was mistaken for a mathematically divergent phase.');
        } catch (\InvalidArgumentException) {
            self::addToAssertionCount(1);
        }
    }

    public function testDecayingCompositePhasesAreNotClassifiedAsDivergent(): void
    {
        foreach (
            [
                'sin(x^2*exp(-x)) = 1/4 + 1/x',
                'sin((1/2)^x) = 1/4 + 1/x',
                'sin(exp(x)^exp(-x)) = 1/4 + 1/x',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', 1.0, \INF);
                self::addToAssertionCount(1);
            } catch (InfiniteSolutionSetException) {
                self::fail('A decaying phase was mistaken for an unbounded oscillation: ' . $equation);
            } catch (\InvalidArgumentException) {
                self::addToAssertionCount(1);
            }
        }
    }

    public function testUnboundedTrigonometricPolynomialTargetsRetainRangeTangencies(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $upperBoundaryTangency = Math::solve(
            'sin(pi/2 + x - 2) = 1 - (x - 2)^2',
            'x',
            -\INF,
            \INF,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [2.0],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $upperBoundaryTangency),
            1.0E-8,
        );

        $lowerBoundaryTangency = Math::solve(
            'sin(x - 2 - pi/2) = -1 + (x - 2)^2',
            'x',
            -\INF,
            \INF,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [2.0],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $lowerBoundaryTangency),
            1.0E-8,
        );

        $quarticContacts = Math::solve(
            'sin(x - 2 + pi/2) = 1 - (x - 2)^4',
            'x',
            -\INF,
            \INF,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [1.306959621477915, 2.0, 2.693040378522085],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $quarticContacts),
            1.0E-8,
        );
    }

