    public function testUnboundedBesselZeroLevelsRespectFiniteEvaluatorDomains(): void
    {
        $jRoots = Math::solve('besselj(0, x) = 0', 'x', 900.0, \INF);
        self::assertCount(32, $jRoots);
        self::assertEqualsWithDelta(900.85183217434, $jRoots[0]->value, 1.0E-7);
        self::assertEqualsWithDelta(998.24119089823, $jRoots[31]->value, 1.0E-7);

        $yRoots = Math::solve('bessely(0, x) = 0', 'x', 900.0, \INF);
        self::assertCount(32, $yRoots);
        self::assertEqualsWithDelta(902.42262825959, $yRoots[0]->value, 1.0E-7);
        self::assertEqualsWithDelta(999.81198702846, $yRoots[31]->value, 1.0E-7);

        $quadraticJRoots = Math::solve('besselj(0, x^2) = 0', 'x', 30.0, \INF);
        self::assertCount(32, $quadraticJRoots);
        self::assertEqualsWithDelta(30.014193845153, $quadraticJRoots[0]->value, 1.0E-7);
        self::assertEqualsWithDelta(31.594955149491, $quadraticJRoots[31]->value, 1.0E-7);

        $quadraticYRoots = Math::solve('bessely(0, x^2) = 0', 'x', 30.0, \INF);
        self::assertCount(32, $quadraticYRoots);
        self::assertEqualsWithDelta(30.040350002282, $quadraticYRoots[0]->value, 1.0E-7);
        self::assertEqualsWithDelta(31.619803715843, $quadraticYRoots[31]->value, 1.0E-7);

        $negativeYRoots = Math::solve('bessely(0, -x) = 0', 'x', -\INF, -999.0);
        self::assertCount(1, $negativeYRoots);
        self::assertEqualsWithDelta(-999.81198702846, $negativeYRoots[0]->value, 1.0E-7);

        foreach (['besselj(2, 0*x) = 0', 'bessely(0, 0*x) = 0'] as $identity) {
            if (str_starts_with($identity, 'besselj')) {
                try {
                    Math::solve($identity, 'x', -\INF, \INF);
                    self::fail('Expected an infinite Bessel identity.');
                } catch (InfiniteSolutionSetException) {
                    self::assertTrue(true);
                }
            } else {
                self::assertSame([], Math::solve($identity, 'x', -\INF, \INF));
            }
        }

        self::assertSame([], Math::solve('besselj(0, 0*x) = 0', 'x', -\INF, \INF));
    }

