    public function testUnboundedCauchyRatiosAreRoundedOutwardAgainstExactIntegers(): void
    {
        $solver = new EquationSolver();
        $upperBoundMethod = new \ReflectionMethod($solver, 'upperFloatBoundForIntegerRatio');
        $upperBoundMethod->setAccessible(true);
        $floatRatioMethod = new \ReflectionMethod($solver, 'positiveFloatAsExactRatio');
        $floatRatioMethod->setAccessible(true);
        $integerArithmetic = new \MathPHP\Solver\IntegerPolynomialExtractor('', []);
        $ratios = [
            ['1', '3'],
            [
                '1' . \str_repeat('0', 100),
                '9' . \str_repeat('9', 99),
            ],
            ['1', '1' . \str_repeat('0', 400)],
        ];

        foreach ($ratios as [$numerator, $denominator]) {
            $upperBound = $upperBoundMethod->invoke(
                $solver,
                $numerator,
                $denominator,
                $integerArithmetic,
            );
            self::assertIsFloat($upperBound);
            $exactFloatRatio = $floatRatioMethod->invoke($solver, $upperBound, $integerArithmetic);
            self::assertIsArray($exactFloatRatio);
            $comparison = $integerArithmetic->compareIntegerRatioToFraction(
                $numerator,
                $denominator,
                $exactFloatRatio[0],
                $exactFloatRatio[1],
            );
            self::assertNotNull($comparison);
            self::assertLessThanOrEqual(0, $comparison);
        }
    }

