    public function testBoundaryContinuityRequiresExponentIndependentOfSolvedVariable(): void
    {
        $evaluationOptions = new EvaluationOptions();
        $solver = new EquationSolver();
        $isLocallyContinuous = new \ReflectionMethod($solver, 'isLocallyContinuous');
        $isLocallyContinuous->setAccessible(true);

        foreach (
            [
                '(-1)^(x^2 + 1)' => false,
                '(-1)^3' => true,
            ] as $expression => $expected
        ) {
            $node = (new Parser(
                (new Lexer($expression, $evaluationOptions->limits))->tokenize(),
                $evaluationOptions->limits,
            ))->parse();

            self::assertSame(
                $expected,
                $isLocallyContinuous->invoke($solver, $node, 0.0, $evaluationOptions, [], 'x'),
                $expression,
            );
        }

        $fractionalPowerOnPositiveBase = (new Parser(
            (new Lexer('x^0.5', $evaluationOptions->limits))->tokenize(),
            $evaluationOptions->limits,
        ))->parse();
        self::assertTrue(
            $isLocallyContinuous->invoke(
                $solver,
                $fractionalPowerOnPositiveBase,
                1.0,
                $evaluationOptions,
                [],
                'x',
            ),
        );

        $fractionalPowerAtZero = (new Parser(
            (new Lexer('x^0.5', $evaluationOptions->limits))->tokenize(),
            $evaluationOptions->limits,
        ))->parse();
        $limitAtBoundary = new \ReflectionMethod($solver, 'continuousExpressionLimitAt');
        $limitAtBoundary->setAccessible(true);
        self::assertSame(
            0.0,
            $limitAtBoundary->invoke(
                $solver,
                $fractionalPowerAtZero,
                'x',
                0.0,
                1,
                new PolynomialExtractor('x', [], $evaluationOptions),
                $evaluationOptions,
                [],
            ),
        );

        $negativeFractionalPower = (new Parser(
            (new Lexer('(-x)^0.5', $evaluationOptions->limits))->tokenize(),
            $evaluationOptions->limits,
        ))->parse();
        self::assertNull(
            $limitAtBoundary->invoke(
                $solver,
                $negativeFractionalPower,
                'x',
                0.0,
                1,
                new PolynomialExtractor('x', [], $evaluationOptions),
                $evaluationOptions,
                [],
            ),
        );
        self::assertSame(
            0.0,
            $limitAtBoundary->invoke(
                $solver,
                $negativeFractionalPower,
                'x',
                0.0,
                -1,
                new PolynomialExtractor('x', [], $evaluationOptions),
                $evaluationOptions,
                [],
            ),
        );

        $negativeFractionalReciprocal = (new Parser(
            (new Lexer('sin(x)^-0.5', $evaluationOptions->limits))->tokenize(),
            $evaluationOptions->limits,
        ))->parse();
        self::assertSame(
            \INF,
            $limitAtBoundary->invoke(
                $solver,
                $negativeFractionalReciprocal,
                'x',
                0.0,
                1,
                new PolynomialExtractor('x', [], $evaluationOptions),
                $evaluationOptions,
                [],
            ),
        );
        self::assertNull(
            $limitAtBoundary->invoke(
                $solver,
                $negativeFractionalReciprocal,
                'x',
                0.0,
                -1,
                new PolynomialExtractor('x', [], $evaluationOptions),
                $evaluationOptions,
                [],
            ),
        );

        $fractionalPowerOfNegative = (new Parser(
            (new Lexer('(-1)^0.5', $evaluationOptions->limits))->tokenize(),
            $evaluationOptions->limits,
        ))->parse();
        self::assertFalse(
            $isLocallyContinuous->invoke($solver, $fractionalPowerOfNegative, 0.0, $evaluationOptions, [], 'x'),
        );
    }

    public function testRationalRootAtExtremeScaleSurvivesOverflowSafePolynomialEvaluation(): void
    {
        $polynomialSolver = new PolynomialSolver();
        $polynomialValue = $polynomialSolver->evaluatePolynomial([1.0, -1.0E308], 1.0E-308);

        self::assertNotNull($polynomialValue);
        self::assertLessThan(1.0E-16, \abs($polynomialValue));
        self::assertNotNull(
            $polynomialSolver->evaluatePolynomial(
                [1.0, -\PHP_FLOAT_MAX],
                1.0 / \PHP_FLOAT_MAX,
            ),
        );

        $solutions = Math::solve(
            '1/x = 1e308',
            'x',
            5.0E-324,
            1.0E-300,
            solverOptions: new SolverOptions(scanSteps: 8),
        );

        self::assertCount(1, $solutions);
        self::assertSame(1.0E-308, $solutions[0]->value);
        self::assertSame(0.0, $solutions[0]->residual);

        $maximumCoefficientSolutions = Math::solve(
            'scale*x = 1',
            'x',
            5.0E-309,
            6.0E-309,
            ['scale' => \PHP_FLOAT_MAX],
            solverOptions: new SolverOptions(scanSteps: 8),
        );

        self::assertCount(1, $maximumCoefficientSolutions);
        self::assertSame(1.0 / \PHP_FLOAT_MAX, $maximumCoefficientSolutions[0]->value);
        self::assertLessThan(1.0E-15, $maximumCoefficientSolutions[0]->residual);
    }

    public function testMaximumFloatPowerEquationKeepsFiniteRoots(): void
    {
        $expected = \sqrt(\PHP_FLOAT_MAX);
        $equation = 'x^2 = 1.7976931348623157e308';

        foreach ([[-2.0E154, 2.0E154], [-1.79E308, 1.79E308]] as [$lower, $upper]) {
            $solutions = Math::solve($equation, 'x', $lower, $upper);

            self::assertCount(2, $solutions);
            self::assertEqualsWithDelta(-$expected, $solutions[0]->value, $expected * 1.0E-12);
            self::assertEqualsWithDelta($expected, $solutions[1]->value, $expected * 1.0E-12);
        }
    }

