    public function testBetaZeroLevelsWithMixedExponentialAndTrigonometricArguments(): void
    {
        $solutions = Math::solve(
            'beta(sin(x), exp(x)) = 0',
            'x',
            -5.0,
            -2.0,
            solverOptions: new SolverOptions(scanSteps: 8),
        );

        self::assertCount(1, $solutions);
        self::assertEqualsWithDelta(-3.096363932409986, $solutions[0]->value, 1.0E-8);
        self::assertLessThan(1.0E-8, $solutions[0]->residual);

        $tangentSolutions = Math::solve(
            'beta(sin(x) + 0.5, (x - 0.137)^2 - sin(x) - 0.5) = 0',
            'x',
            -1.0,
            1.0,
            solverOptions: new SolverOptions(scanSteps: 4),
        );

        self::assertCount(1, $tangentSolutions);
        self::assertEqualsWithDelta(0.137, $tangentSolutions[0]->value, 1.0E-8);
        self::assertSame(0.0, $tangentSolutions[0]->residual);

        $cancelledTargetSolutions = Math::solve(
            'beta(sin(x) + 0.5, (x - 0.137)^2 - sin(x) - 0.5) = sin(x) - sin(x)',
            'x',
            -1.0,
            1.0,
            solverOptions: new SolverOptions(scanSteps: 4),
        );

        self::assertCount(1, $cancelledTargetSolutions);
        self::assertEqualsWithDelta(0.137, $cancelledTargetSolutions[0]->value, 1.0E-8);

        $identityTargetSolutions = Math::solve(
            'beta(sin(x) + 0.5, (x - 0.137)^2 - sin(x) - 0.5)'
                . ' = sin(x)^2 + cos(x)^2 - 1',
            'x',
            -1.0,
            1.0,
            solverOptions: new SolverOptions(scanSteps: 4),
        );

        self::assertCount(1, $identityTargetSolutions);
        self::assertEqualsWithDelta(0.137, $identityTargetSolutions[0]->value, 1.0E-8);
    }

