    public function testRealPolynomialRootsSurviveCoefficientUnderflow(): void
    {
        $noRealRoots = Math::solve('x^2 + 1e-400 = 0', 'x', -1.0, 1.0);
        $twoRealRoots = Math::solve('x^2 - 1e-400 = 0', 'x', -1.0, 1.0);
        $repeatedTinyRoot = Math::solve(
            'x^2 + 2e-200*x + 1e-400 = 0',
            'x',
            -1.0,
            1.0,
        );
        $subnormalRealRoots = Math::solve('x^2 - 1e-646 = 0', 'x', -1.0E-300, 1.0E-300);
        $subnormalNoRealRoots = Math::solve('x^2 + 1e-646 = 0', 'x', -1.0E-300, 1.0E-300);

        self::assertSame([], $noRealRoots);
        self::assertCount(2, $twoRealRoots);
        self::assertEqualsWithDelta(-1.0E-200, $twoRealRoots[0]->value, 1.0E-214);
        self::assertEqualsWithDelta(1.0E-200, $twoRealRoots[1]->value, 1.0E-214);
        self::assertCount(1, $repeatedTinyRoot);
        self::assertEqualsWithDelta(-1.0E-200, $repeatedTinyRoot[0]->value, 1.0E-214);
        self::assertCount(2, $subnormalRealRoots);
        self::assertSame(-1.0E-323, $subnormalRealRoots[0]->value);
        self::assertSame(1.0E-323, $subnormalRealRoots[1]->value);
        self::assertSame([], $subnormalNoRealRoots);
    }

    public function testQuadraticRootsSurviveExtremeExactCoefficientRatios(): void
    {
        $largeRoots = Math::solve('1e-200*x^2 = 1e100', 'x', -1.0E300, 1.0E300);
        $largerRoots = Math::solve('x*1e-300*x = 1e100', 'x', -1.0E300, 1.0E300);

        self::assertCount(2, $largeRoots);
        self::assertEqualsWithDelta(-1.0E150, $largeRoots[0]->value, 1.0E138);
        self::assertEqualsWithDelta(1.0E150, $largeRoots[1]->value, 1.0E138);
        foreach ($largeRoots as $root) {
            self::assertLessThan(1.0E-12, $root->residual / 1.0E100);
        }

        self::assertCount(2, $largerRoots);
        self::assertEqualsWithDelta(-1.0E200, $largerRoots[0]->value, 1.0E188);
        self::assertEqualsWithDelta(1.0E200, $largerRoots[1]->value, 1.0E188);
    }

    public function testHigherDegreeRootsSurviveExtremeExactCoefficientRatios(): void
    {
        $widelySeparatedRoots = Math::solve(
            'x^3 - 1e300*x = 0',
            'x',
            -1.0E300,
            1.0E300,
        );
        $smallQuarticRoots = Math::solve(
            'x^4 - 1e-300 = 0',
            'x',
            -1.0E300,
            1.0E300,
        );
        $repeatedLargeQuarticRoots = Math::solve(
            '(x^2 - 1e300)^2 = 0',
            'x',
            -1.0E200,
            1.0E200,
        );
        $ninthDegreeRoot = Math::solve('x^9 - 1e-300 = 0', 'x', -1.0E300, 1.0E300);
        $tenthDegreeRoots = Math::solve(
            'x^10 - 1e300*x^5 = 0',
            'x',
            -1.0E300,
            1.0E300,
        );
        $twelfthDegreeRoots = Math::solve('x^12 - 1e-300 = 0', 'x', -1.0E300, 1.0E300);
        $thirteenthDegreeRoot = Math::solve('x^13 - 1e-300 = 0', 'x', -1.0E300, 1.0E300);
        $fifteenthDegreeRoots = Math::solve(
            'x^15 - 1e300*x^5 = 0',
            'x',
            -1.0E300,
            1.0E300,
        );
        $twentiethDegreeRoots = Math::solve('x^20 - 1e300 = 0', 'x', -1.0E300, 1.0E300);

        self::assertCount(3, $widelySeparatedRoots);
        self::assertEqualsWithDelta(-1.0E150, $widelySeparatedRoots[0]->value, 1.0E138);
        self::assertSame(0.0, $widelySeparatedRoots[1]->value);
        self::assertEqualsWithDelta(1.0E150, $widelySeparatedRoots[2]->value, 1.0E138);
        self::assertCount(2, $smallQuarticRoots);
        self::assertEqualsWithDelta(-1.0E-75, $smallQuarticRoots[0]->value, 1.0E-89);
        self::assertEqualsWithDelta(1.0E-75, $smallQuarticRoots[1]->value, 1.0E-89);
        self::assertCount(2, $repeatedLargeQuarticRoots);
        self::assertEqualsWithDelta(-1.0E150, $repeatedLargeQuarticRoots[0]->value, 1.0E138);
        self::assertEqualsWithDelta(1.0E150, $repeatedLargeQuarticRoots[1]->value, 1.0E138);
        self::assertCount(1, $ninthDegreeRoot);
        self::assertEqualsWithDelta(10.0 ** (-300.0 / 9.0), $ninthDegreeRoot[0]->value, 1.0E-45);
        self::assertCount(2, $tenthDegreeRoots);
        self::assertSame(0.0, $tenthDegreeRoots[0]->value);
        self::assertEqualsWithDelta(1.0E60, $tenthDegreeRoots[1]->value, 1.0E48);
        self::assertCount(2, $twelfthDegreeRoots);
        self::assertEqualsWithDelta(-1.0E-25, $twelfthDegreeRoots[0]->value, 1.0E-39);
        self::assertEqualsWithDelta(1.0E-25, $twelfthDegreeRoots[1]->value, 1.0E-39);
        self::assertCount(1, $thirteenthDegreeRoot);
        self::assertEqualsWithDelta(10.0 ** (-300.0 / 13.0), $thirteenthDegreeRoot[0]->value, 1.0E-36);
        self::assertCount(3, $fifteenthDegreeRoots);
        self::assertEqualsWithDelta(-1.0E30, $fifteenthDegreeRoots[0]->value, 1.0E18);
        self::assertSame(0.0, $fifteenthDegreeRoots[1]->value);
        self::assertEqualsWithDelta(1.0E30, $fifteenthDegreeRoots[2]->value, 1.0E18);
        self::assertCount(2, $twentiethDegreeRoots);
        self::assertEqualsWithDelta(-1.0E15, $twentiethDegreeRoots[0]->value, 1.0E3);
        self::assertEqualsWithDelta(1.0E15, $twentiethDegreeRoots[1]->value, 1.0E3);
    }

