    public function testFlatTranscendentalTangencyDoesNotSelectAnEdgeOfTheRoundedZeroPlateau(): void
    {
        $expected = 0.123456789;
        foreach (
            [
                'ln(1+(x-0.123456789)^2)=0',
                'log10(1+(x-0.123456789)^2)=0',
                'log2(1+(x-0.123456789)^2)=0',
                'log(1+(x-0.123456789)^2,10)=0',
                'acosh(1+(x-0.123456789)^2)=0',
                'asech(1-(x-0.123456789)^2)=0',
                'asec(1+(x-0.123456789)^2)=0',
                'acos(1+(x-0.123456789)^2)=0',
                'sqrt((x-0.123456789)^2)=0',
                'sqrt(1+(x-0.123456789)^2)=1',
                'asin(1-(x-0.123456789)^2)=pi/2',
                'acsc(1+(x-0.123456789)^2)=pi/2',
            ] as $equation
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                -1.0,
                1.0,
                solverOptions: new SolverOptions(scanSteps: 8),
            );

            self::assertCount(1, $solutions, $equation);
            self::assertEqualsWithDelta($expected, $solutions[0]->value, 1.0E-9, $equation);
            self::assertLessThanOrEqual(1.0E-15, $solutions[0]->residual, $equation);
        }
    }

    public function testSmallLogarithmicLevelsRetainTheirOffsetFromOne(): void
    {
        $center = 0.123456789;
        $argument = '1+(x-0.123456789)^2';
        $logarithms = [
            ['ln(' . $argument . ')', 1.0],
            ['log10(' . $argument . ')', \log(10.0)],
            ['log2(' . $argument . ')', \log(2.0)],
            ['log(' . $argument . ',10)', \log(10.0)],
            ['log(' . $argument . ',2)', \log(2.0)],
        ];
        foreach ([1.0E-16, 1.0E-20, 1.0E-24] as $target) {
            foreach ($logarithms as [$logarithm, $scale]) {
                $offset = \sqrt(\expm1($target * $scale));
                $equation = $logarithm . '=' . \json_encode(
                    $target,
                    \JSON_PRESERVE_ZERO_FRACTION | \JSON_THROW_ON_ERROR,
                );
                $solutions = Math::solve(
                    $equation,
                    'x',
                    0.0,
                    0.25,
                    solverOptions: new SolverOptions(scanSteps: 8),
                );

                self::assertCount(2, $solutions, $equation);
                self::assertEqualsWithDelta($center - $offset, $solutions[0]->value, 2.0E-12, $equation);
                self::assertEqualsWithDelta($center + $offset, $solutions[1]->value, 2.0E-12, $equation);
            }
        }
    }

    public function testSmallAcoshLevelsRetainTheirOffsetFromOne(): void
    {
        $center = 0.123456789;
        foreach ([1.0E-8, 1.0E-12, 1.0E-16] as $target) {
            $offset = \sqrt(2.0) * \sinh($target / 2.0);
            $equation = 'acosh(1+(x-0.123456789)^2)='
                . \json_encode($target, \JSON_PRESERVE_ZERO_FRACTION | \JSON_THROW_ON_ERROR);
            $solutions = Math::solve(
                $equation,
                'x',
                0.0,
                0.25,
                solverOptions: new SolverOptions(scanSteps: 8),
            );

            self::assertCount(2, $solutions, $equation);
            foreach ($solutions as $index => $solution) {
                $expected = $center + ($index === 0 ? -$offset : $offset);
                self::assertEqualsWithDelta($expected, $solution->value, 2.0E-12, $equation);
                self::assertLessThanOrEqual(
                    \sqrt(2.0 * \PHP_FLOAT_EPSILON),
                    $solution->residual,
                    $equation,
                );
                self::assertSame(
                    \abs(
                        Math::evaluate('acosh(1+(x-0.123456789)^2)', ['x' => $solution->value])
                            - $target,
                    ),
                    $solution->residual,
                    $equation,
                );
            }
        }
    }

    public function testInverseFunctionsRetainSmallOffsetsNearUnitEndpoints(): void
    {
        $center = 0.123456789;
        $smallAngle = 1.0E-8;
        $nearHalfPi = (\M_PI / 2.0) - $smallAngle;
        $complement = (\M_PI / 2.0) - $nearHalfPi;
        $nearPi = \M_PI - $smallAngle;
        $nearNegativeHalfPi = (-\M_PI / 2.0) + $smallAngle;
        $cases = [
            [
                'asech(1-(x-0.123456789)^2)',
                $smallAngle,
                (2.0 * (\sinh($smallAngle / 2.0) ** 2)) / \cosh($smallAngle),
            ],
            [
                'asec(1+(x-0.123456789)^2)',
                $smallAngle,
                (2.0 * (\sin($smallAngle / 2.0) ** 2)) / \cos($smallAngle),
            ],
            [
                'acos(1-(x-0.123456789)^2)',
                $smallAngle,
                2.0 * (\sin($smallAngle / 2.0) ** 2),
            ],
            [
                'asin(1-(x-0.123456789)^2)',
                $nearHalfPi,
                2.0 * (\sin($complement / 2.0) ** 2),
            ],
            [
                'acsc(1+(x-0.123456789)^2)',
                $nearHalfPi,
                (2.0 * (\sin($complement / 2.0) ** 2)) / \sin($nearHalfPi),
            ],
            [
                'acos(-1+(x-0.123456789)^2)',
                $nearPi,
                2.0 * (\sin($smallAngle / 2.0) ** 2),
            ],
            [
                'asin(-1+(x-0.123456789)^2)',
                $nearNegativeHalfPi,
                2.0 * (\sin($smallAngle / 2.0) ** 2),
            ],
            [
                'asec(-1-(x-0.123456789)^2)',
                $nearPi,
                (2.0 * (\sin($smallAngle / 2.0) ** 2)) / \cos($smallAngle),
            ],
            [
                'acsc(-1-(x-0.123456789)^2)',
                $nearNegativeHalfPi,
                (2.0 * (\sin($smallAngle / 2.0) ** 2)) / \cos($smallAngle),
            ],
        ];

        foreach ($cases as [$leftSide, $target, $offset]) {
            $equation = $leftSide . '='
                . \json_encode($target, \JSON_PRESERVE_ZERO_FRACTION | \JSON_THROW_ON_ERROR);
            $solutions = Math::solve(
                $equation,
                'x',
                0.0,
                0.25,
                solverOptions: new SolverOptions(scanSteps: 8),
            );
            $expectedOffset = \sqrt($offset);

            self::assertCount(2, $solutions, $equation);
            foreach ($solutions as $index => $solution) {
                $expectedRoot = $center + ($index === 0 ? -$expectedOffset : $expectedOffset);
                self::assertEqualsWithDelta($expectedRoot, $solution->value, 2.0E-12, $equation);
                self::assertLessThanOrEqual(
                    \sqrt(2.0 * \PHP_FLOAT_EPSILON),
                    $solution->residual,
                    $equation,
                );
                self::assertSame(
                    \abs(Math::evaluate($leftSide, ['x' => $solution->value]) - $target),
                    $solution->residual,
                    $equation,
                );
            }
        }
    }

    public function testAcothLevelsNearTheUnitPolesRetainPolynomialOffsets(): void
    {
        $center = 0.123456789;
        $targets = [
            10.0, -10.0, 14.0, -14.0, 16.0, -16.0, 17.0, -17.0, 18.0, -18.0,
            19.0, -19.0, 20.0, -20.0, 24.0, -24.0, 28.0, -28.0, 30.0, -30.0, 32.0, -32.0,
            33.0, -33.0, 34.0, -34.0, 35.0, -35.0, 36.0, -36.0,
        ];
        foreach ($targets as $target) {
            $unit = $target > 0.0 ? '1+' : '-1-';
            $argument = 'acoth(' . $unit . '(x-0.123456789)^2)';
            $equation = $argument . '=' . \sprintf('%.1f', $target);
            $offsetSquared = 2.0 / \expm1(2.0 * \abs($target));
            $rootOffset = \sqrt($offsetSquared);
            $solutions = Math::solve(
                $equation,
                'x',
                0.0,
                0.25,
                solverOptions: new SolverOptions(scanSteps: 8),
            );

            self::assertCount(2, $solutions, $equation);
            foreach ($solutions as $index => $solution) {
                $expectedRoot = $center + ($index === 0 ? -$rootOffset : $rootOffset);
                self::assertEqualsWithDelta($expectedRoot, $solution->value, 2.0E-12, $equation);
                self::assertLessThanOrEqual(
                    2.0 * \PHP_FLOAT_EPSILON / $offsetSquared,
                    $solution->residual,
                    $equation,
                );
                self::assertLessThanOrEqual(0.03, $solution->residual, $equation);
                self::assertSame(
                    \abs(Math::evaluate($argument, ['x' => $solution->value]) - $target),
                    $solution->residual,
                    $equation,
                );
            }
        }
    }

