    public function testInverseFunctionsRetainResidualsNearUnitBoundaries(): void
    {
        $center = 0.123456789;
        $smallAngle = 1.0E-8;
        $nearHalfPi = (\M_PI / 2.0) - $smallAngle;
        $cases = [
            ['acos(1-(x-0.123456789)^2)=' . \sprintf('%.17g', $smallAngle), 2.0 * (\sin($smallAngle / 2.0) ** 2)],
            ['acosh(1+(x-0.123456789)^2)=' . \sprintf('%.17g', $smallAngle), 2.0 * (\sinh($smallAngle / 2.0) ** 2)],
            [
                'asech(1-(x-0.123456789)^2)=' . \sprintf('%.17g', $smallAngle),
                (2.0 * (\sinh($smallAngle / 2.0) ** 2)) / \cosh($smallAngle),
            ],
            [
                'asin(1-(x-0.123456789)^2)=' . \sprintf('%.17g', $nearHalfPi),
                2.0 * (\sin($smallAngle / 2.0) ** 2),
            ],
        ];

        foreach ($cases as [$equation, $offset]) {
            $solutions = Math::solve(
                $equation,
                'x',
                0.0,
                0.25,
                solverOptions: new SolverOptions(scanSteps: 8),
            );

            self::assertCount(2, $solutions, $equation);
            foreach ($solutions as $index => $solution) {
                $expectedRoot = $center + ($index === 0 ? -\sqrt($offset) : \sqrt($offset));
                self::assertEqualsWithDelta($expectedRoot, $solution->value, 2.0E-12, $equation);
                self::assertLessThanOrEqual(2.0E-14, $solution->residual, $equation);
                self::assertSame(
                    \abs(Math::evaluate(\explode('=', $equation)[0], ['x' => $solution->value])
                        - (\str_starts_with($equation, 'asin(') ? $nearHalfPi : $smallAngle)),
                    $solution->residual,
                    $equation,
                );
            }
        }
    }

    public function testTruncationEquationsDistinguishPointAndIntervalSolutionSets(): void
    {
        self::assertSame(
            [-3.0, -2.0, -1.0, 0.0, 1.0, 2.0, 3.0],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve('trunc(x)=x', 'x', -3.0, 3.0),
            ),
        );
        self::assertSame(
            [-2.5, -1.5, -0.5],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve('trunc(x)=x+0.5', 'x', -3.0, 3.0),
            ),
        );

        $this->expectException(InfiniteSolutionSetException::class);
        Math::solve('trunc(x)=0', 'x', -2.0, 2.0);
    }

    public function testPoweredLinearFactorsFindNearbyRepeatedRootsQuickly(): void
    {
        $equation = '(1000000*x - 123457)^2 * (1000000*x - 123456)^2 * (2*x + 1) = 0';
        $options = new SolverOptions(scanSteps: 1);
        $solutions = Math::solve($equation, 'x', -1.0, 1.0, solverOptions: $options);

        self::assertSame(
            3,
            Math::countPolynomialRootsInInterval(
                $equation,
                'x',
                -1.0,
                1.0,
                solverOptions: $options,
            ),
        );
        self::assertCount(3, $solutions);
        foreach ([-0.5, 0.123456, 0.123457] as $index => $expectedRoot) {
            self::assertEqualsWithDelta($expectedRoot, $solutions[$index]->value, 1.0E-12);
            self::assertLessThanOrEqual(1.0E-12, $solutions[$index]->residual);
        }

        $oddPowerEquation = '(1000000*x - 123457)^3 * (1000000*x - 123456)^2 * (2*x + 1) = 0';
        $oddPowerSolutions = Math::solve(
            $oddPowerEquation,
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        self::assertSame(
            3,
            Math::countPolynomialRootsInInterval(
                $oddPowerEquation,
                'x',
                -1.0,
                1.0,
                solverOptions: $options,
            ),
        );
        self::assertCount(3, $oddPowerSolutions);
        foreach ([-0.5, 0.123456, 0.123457] as $index => $expectedRoot) {
            self::assertEqualsWithDelta($expectedRoot, $oddPowerSolutions[$index]->value, 1.0E-12);
        }

        $negativePowerEquation = '(1000000*x - 123457)^-2 * (1000000*x - 123456)^2 = 0';
        $negativePowerSolutions = Math::solve(
            $negativePowerEquation,
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        self::assertSame(
            1,
            Math::countPolynomialRootsInInterval(
                $negativePowerEquation,
                'x',
                -1.0,
                1.0,
                solverOptions: $options,
            ),
        );
        self::assertCount(1, $negativePowerSolutions);
        self::assertEqualsWithDelta(0.123456, $negativePowerSolutions[0]->value, 1.0E-12);
    }

