    public function testTanhLevelRootsAreFoundOnIntervalsNotContainingZero(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $root = \atanh(0.5);
        $solutions = Math::solve('tanh(x)=0.5', 'x', 0.5, 1.0, solverOptions: $options);

        self::assertCount(1, $solutions);
        self::assertEqualsWithDelta($root, $solutions[0]->value, 1.0E-10);

        $center = 0.713714;
        foreach (['tanh', 'sech', 'csch', 'coth'] as $function) {
            $target = Math::evaluate($function . '(x)', ['x' => $center]);
            $roots = Math::solve(
                $function . '(x)=' . \sprintf('%.17g', $target),
                'x',
                0.6,
                0.8,
                solverOptions: $options,
            );

            self::assertCount(1, $roots, $function);
            self::assertEqualsWithDelta($center, $roots[0]->value, 1.0E-10, $function);
        }

        $target = \tanh($center);
        $shifted = Math::solve(
            'tanh(2*x+1)=' . \sprintf('%.17g', $target),
            'x',
            ($center - 1.1) / 2.0,
            ($center - 0.9) / 2.0,
            solverOptions: $options,
        );

        self::assertCount(1, $shifted);
        self::assertEqualsWithDelta(($center - 1.0) / 2.0, $shifted[0]->value, 1.0E-10);
    }

    public function testAffineVariableBaseLogarithmSolvesDirectlyOnNarrowIntervals(): void
    {
        $center = 0.713714;
        $target = Math::evaluate('log(x, 1+x)', ['x' => $center]);
        $equation = 'log(x, 1+x)=' . \sprintf('%.17g', $target);
        $options = new SolverOptions(scanSteps: 1, maxIterations: 24);

        foreach ([[0.1, 1.0], [0.6, 0.8]] as [$lower, $upper]) {
            $solutions = Math::solve(
                $equation,
                'x',
                $lower,
                $upper,
                solverOptions: $options,
            );

            self::assertCount(1, $solutions);
            self::assertEqualsWithDelta($center, $solutions[0]->value, 1.0E-9);
        }

        $tangentRoot = 0.731;
        $tangentRoots = Math::solve(
            'log(x+1.269,4*x+1.076)=0.5',
            'x',
            0.5,
            1.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(1, $tangentRoots);
        self::assertEqualsWithDelta($tangentRoot, $tangentRoots[0]->value, 1.0E-12);

        foreach (
            [
                ['log(x+1,0.5-0.25*x)=-0.5', 1.0],
                ['log(x+3,(x+7)/4)=2', 1.0],
            ] as [$equation, $expected]
        ) {
            $roots = Math::solve(
                $equation,
                'x',
                0.5,
                1.5,
                solverOptions: new SolverOptions(scanSteps: 1),
            );

            self::assertCount(1, $roots, $equation);
            self::assertEqualsWithDelta($expected, $roots[0]->value, 1.0E-12, $equation);
        }
    }

