    public function testAffineHyperbolicFunctionsUseExponentialPolynomialIsolation(): void
    {
        foreach (
            [
                ['cosh(x) = 3', 0.0, 1.0],
                ['sinh(x) + exp(-x) = 3', 0.0, 1.0],
                ['cosh(2*x + 1) = 3', -0.5, 0.5],
                ['sinh(x - 1) + exp(1 - x) = 3', 1.0, 1.0],
            ] as [$equation, $center, $scale]
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                -3.0,
                3.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );

            self::assertCount(2, $solutions, $equation);
            self::assertEqualsWithDelta(
                $center - ($scale * \acosh(3.0)),
                $solutions[0]->value,
                1.0E-10,
                $equation,
            );
            self::assertEqualsWithDelta(
                $center + ($scale * \acosh(3.0)),
                $solutions[1]->value,
                1.0E-10,
                $equation,
            );
        }

        $fixedComplementaryError = Math::solve(
            'erfc(x) + erfc(1) = 2',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $fixedComplementaryError);
        self::assertEqualsWithDelta(-1.0, $fixedComplementaryError[0]->value, 1.0E-10);
    }

    public function testReciprocalHyperbolicFormsPreserveTheirDomains(): void
    {
        $tanhRoots = Math::solve(
            'tanh(x) = exp(-2*x)',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        $sechRoots = Math::solve(
            'sech(x) = exp(-x)',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        $cschRoots = Math::solve(
            'csch(x) = 1',
            'x',
            0.1,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        $poleOnlyRoot = Math::solve(
            'csch(x) = coth(x)',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        $poweredRoots = Math::solve(
            'tanh(x)^2 = 1 - exp(-2*x)',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        $reciprocalPowerRoots = Math::solve(
            'tanh(x)^-1 = 2',
            'x',
            0.1,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        $highExponentialPowerRoots = Math::solve(
            'exp(x)^100 = 2',
            'x',
            0.0,
            1.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(1, $tanhRoots);
        self::assertEqualsWithDelta(0.5 * \log(1.0 + \sqrt(2.0)), $tanhRoots[0]->value, 1.0E-10);
        self::assertCount(1, $sechRoots);
        self::assertEqualsWithDelta(0.0, $sechRoots[0]->value, 1.0E-12);
        self::assertCount(1, $cschRoots);
        self::assertEqualsWithDelta(\log(1.0 + \sqrt(2.0)), $cschRoots[0]->value, 1.0E-10);
        self::assertSame([], $poleOnlyRoot);
        self::assertCount(1, $poweredRoots);
        self::assertEqualsWithDelta(0.0, $poweredRoots[0]->value, 1.0E-12);
        self::assertCount(1, $reciprocalPowerRoots);
        self::assertEqualsWithDelta(0.5 * \log(3.0), $reciprocalPowerRoots[0]->value, 1.0E-10);
        self::assertCount(1, $highExponentialPowerRoots);
        self::assertEqualsWithDelta(\log(2.0) / 100.0, $highExponentialPowerRoots[0]->value, 1.0E-10);
    }

    public function testReciprocalNormalizationFallsBackWhenItMissesRationalRoots(): void
    {
        $solutions = Math::solve(
            '1/(1 + 1000000*x^2) = 0.999999',
            'x',
            -0.01,
            0.01,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(2, $solutions);
        self::assertEqualsWithDelta(-1.0000005E-6, $solutions[0]->value, 1.0E-14);
        self::assertEqualsWithDelta(1.0000005E-6, $solutions[1]->value, 1.0E-14);
        foreach ($solutions as $solution) {
            self::assertLessThanOrEqual(1.0E-14, $solution->residual);
        }
    }

    public function testExactRationalRecoveryRespectsInclusiveIntervalBounds(): void
    {
        foreach (
            [
                'x^5 - 3.00001*x^4 + 4.00002*x^3 - 4.00002*x^2 + 3.00002*x - 1.00001 = 0',
                'x^5 - (300001/100000)*x^4 + (200001/50000)*x^3'
                    . ' - (200001/50000)*x^2 + (150001/50000)*x - 100001/100000 = 0',
            ] as $equation
        ) {
            foreach (
                [
                    [1.0, 1.01, [1.0, 1.00001]],
                    [0.99, 1.0, [1.0]],
                    [1.000001, 1.01, [1.00001]],
                    [0.99, 0.999, []],
                ] as [$lowerBound, $upperBound, $expectedRoots]
            ) {
                $solutions = Math::solve($equation, 'x', $lowerBound, $upperBound);
                self::assertCount(\count($expectedRoots), $solutions, $equation);
                foreach ($expectedRoots as $index => $expectedRoot) {
                    self::assertEqualsWithDelta($expectedRoot, $solutions[$index]->value, 1.0E-9);
                    self::assertLessThanOrEqual(1.0E-10, $solutions[$index]->residual);
                }
            }
        }

    }

    public function testAffineEquationsSupportFiniteBoundsWhoseDifferenceOverflows(): void
    {
        foreach (
            [
                ['x = 0', 0.0],
                ['0.5*x = 1', 2.0],
                ['x/3 = 2', 6.0],
                ['x = 1e308', 1.0E308],
            ] as [$equation, $expected]
        ) {
            $solutions = Math::solve($equation, 'x', -1.0E308, 1.0E308);

            self::assertCount(1, $solutions, $equation);
            self::assertSame($expected, $solutions[0]->value, $equation);
            self::assertSame(0.0, $solutions[0]->residual, $equation);
        }
    }

