    public function testSupportedNonOscillatoryEquationsSplitOverflowingFiniteIntervals(): void
    {
        $options = new SolverOptions(scanSteps: 8);
        foreach (
            [
                ['exp(x) = 2', \log(2.0)],
                ['ln(x) = 1', \M_E],
                ['log10(x) = 2', 100.0],
                ['sqrt(x) = 3', 9.0],
            ] as [$equation, $expected]
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                -1.0E308,
                1.0E308,
                solverOptions: $options,
            );

            self::assertCount(1, $solutions, $equation);
            self::assertEqualsWithDelta($expected, $solutions[0]->value, 1.0E-8, $equation);
            self::assertLessThanOrEqual(1.0E-9, $solutions[0]->residual, $equation);
        }

        $absoluteValues = Math::solve(
            'abs(x) = 1',
            'x',
            -1.0E308,
            1.0E308,
            solverOptions: $options,
        );
        self::assertCount(2, $absoluteValues);
        self::assertSame(-1.0, $absoluteValues[0]->value);
        self::assertSame(1.0, $absoluteValues[1]->value);

        $nestedLogarithm = Math::solve(
            'ln(abs(x) + 1) = 1',
            'x',
            -1.0E308,
            1.0E308,
            solverOptions: $options,
        );
        self::assertCount(2, $nestedLogarithm);
        self::assertEqualsWithDelta(1.0 - \M_E, $nestedLogarithm[0]->value, 1.0E-8);
        self::assertEqualsWithDelta(\M_E - 1.0, $nestedLogarithm[1]->value, 1.0E-8);

        $tangent = Math::solve(
            'exp(-((x - 100)^2)) = 1',
            'x',
            -1.0E308,
            1.0E308,
        );
        self::assertCount(1, $tangent);
        self::assertEqualsWithDelta(100.0, $tangent[0]->value, 1.0E-8);
    }

    public function testResidualMinimizationReportsIterationsActuallyPerformed(): void
    {
        $solutions = Math::solve('ln(x) = x - 2', 'x', 0.0, 1.0);

        self::assertCount(1, $solutions);
        self::assertEqualsWithDelta(0.158594339573, $solutions[0]->value, 1.0E-9);
        self::assertGreaterThan(0, $solutions[0]->iterations);
        self::assertLessThan((new SolverOptions())->maxIterations, $solutions[0]->iterations);
    }

    public function testFloatingPointSaturationAtFiniteAsymptotesDoesNotCreateRoots(): void
    {
