            );
        }
    }

    public function testFlatNonPolynomialRootIsNotDuplicatedByResidualPlateauMinimization(): void
    {
        $solutions = Math::solve(
            'exp((x - 0.123)^4) = 1',
            'x',
            -1.0,
            1.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(1, $solutions);
        self::assertEqualsWithDelta(0.123, $solutions[0]->value, 1.0E-12);
        self::assertSame(0.0, $solutions[0]->residual);

        $inverseCosine = Math::solve(
            'acos((x - 0.123)^4) = pi / 2',
            'x',
            -1.0,
            1.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $inverseCosine);
        self::assertEqualsWithDelta(0.123, $inverseCosine[0]->value, 1.0E-12);

        $degree = 18;
        $nextDegree = 19;
        $firstOffset = (2 ** $degree) - 1;
        $secondOffset = (2 ** $nextDegree) - 1;
        $tangent = Math::solve(
            sprintf(
                'root(x + %d, %d) - (%d/%d)*root(x + %d, %d) = %d/%d',
                $firstOffset,
                $degree,
                $nextDegree,
                $degree,
                $secondOffset,
                $nextDegree,
                2 * ($degree - $nextDegree),
                $degree,
            ),
            'x',
            0.0,
            4.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(1, $tangent);
        self::assertEqualsWithDelta(1.0, $tangent[0]->value, 1.0E-6);
        self::assertLessThanOrEqual(1.0E-12, $tangent[0]->residual);

        $nearbyInverseCosineLevel = Math::solve(
            'acos((x - 0.123)^4) = pi / 2 - 1e-12',
            'x',
            -1.0,
            1.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(2, $nearbyInverseCosineLevel);
        self::assertEqualsWithDelta(0.1219999624475, $nearbyInverseCosineLevel[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(0.1240000375531, $nearbyInverseCosineLevel[1]->value, 1.0E-10);
    }

    public function testExactZeroInverseLevelsRetainRationalRootsAndExcludeDomainHoles(): void
    {
        $validRoot = Math::solve(
            'exp((x^2 - 1) / (x - 1) - 3) = 1',
            'x',
            -3.0,
            3.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $validRoot);
        self::assertSame(2.0, $validRoot[0]->value);

        $rootAtHole = Math::solve(
            'exp((x^2 - 1) / (x - 1) - 2) = 1',
            'x',
            -3.0,
            3.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertSame([], $rootAtHole);
    }

