    public function testInvertiblePolynomialFunctionLevelsFindRootsAroundLargeCenters(): void
    {
        $equation = 'exp(-((x - 1e100) / 1e90)^2) = 0.5';
        $solutions = Math::solve($equation, 'x', 0.0, 1.0E308);
        $radius = \sqrt(\log(2.0)) * 1.0E90;

        self::assertCount(2, $solutions);
        self::assertEqualsWithDelta(1.0E100 - $radius, $solutions[0]->value, 1.0E85);
        self::assertEqualsWithDelta(1.0E100 + $radius, $solutions[1]->value, 1.0E85);

        $reversed = Math::solve(
            '0.5 = exp(-((x - 1e100) / 1e90)^2)',
            'x',
            0.0,
            1.0E308,
        );
        self::assertSame(
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $solutions),
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $reversed),
        );

        foreach (
            [
                ['atan', \tan(0.5)],
                ['asin', \sin(0.5)],
                ['asinh', \sinh(0.5)],
                ['atanh', \tanh(0.5)],
                ['sinh', \asinh(0.5)],
                ['tanh', \atanh(0.5)],
                ['acosh', \cosh(0.5)],
                ['cbrt', 0.125],
                ['sqrt', 0.25],
            ] as [$function, $argument]
        ) {
            $solutionsForFunction = Math::solve(
                $function . '((x - 1e100) / 1e90) = 0.5',
                'x',
                0.0,
                1.0E308,
            );
            self::assertCount(1, $solutionsForFunction, $function);
            self::assertEqualsWithDelta(
                1.0E100 + ($argument * 1.0E90),
                $solutionsForFunction[0]->value,
                1.0E85,
                $function,
            );
        }

        $nestedNaturalLog = Math::solve(
            'ln(exp((x - 1e100) / 1e90)) = 0.5',
            'x',
            0.0,
            1.0E308,
        );
        self::assertCount(1, $nestedNaturalLog);
        self::assertEqualsWithDelta(1.0E100 + (0.5 * 1.0E90), $nestedNaturalLog[0]->value, 1.0E85);

        $nestedHyperbolic = Math::solve(
            'atan(sinh((x - 1e100) / 1e90)) = 0.5',
            'x',
            0.0,
            1.0E308,
        );
        self::assertCount(1, $nestedHyperbolic);
        self::assertEqualsWithDelta(1.0E100 + (\asinh(\tan(0.5)) * 1.0E90), $nestedHyperbolic[0]->value, 1.0E85);

        $inverseHyperbolicComposition = Math::solve(
            'asinh(tanh((x - 1e100) / 1e90)) = 0.4',
            'x',
            0.0,
            1.0E308,
        );
        self::assertCount(1, $inverseHyperbolicComposition);
        self::assertEqualsWithDelta(
            1.0E100 + (\atanh(\sinh(0.4)) * 1.0E90),
            $inverseHyperbolicComposition[0]->value,
            1.0E85,
        );

        foreach (
            [
                ['log10(exp((x - 1e100) / 1e90)) = -0.5', -0.5 * \log(10.0)],
                ['log2(exp((x - 1e100) / 1e90)) = -0.5', -0.5 * \log(2.0)],
            ] as [$equation, $level]
        ) {
            $nestedLogarithm = Math::solve($equation, 'x', 0.0, 1.0E308);
            self::assertCount(1, $nestedLogarithm, $equation);
            self::assertEqualsWithDelta(1.0E100 + ($level * 1.0E90), $nestedLogarithm[0]->value, 1.0E85);
        }

        foreach (
            [
                'exp(ln((x - 1e100) / 1e90)) = 0.5',
                'expm1(log1p((x - 1e100) / 1e90)) = 0.5',
                'asinh(sinh((x - 1e100) / 1e90)) = 0.5',
                'atanh(tanh((x - 1e100) / 1e90)) = 0.5',
                'sin(asin((x - 1e100) / 1e90)) = 0.5',
                'cos(acos((x - 1e100) / 1e90)) = 0.5',
                'tan(atan((x - 1e100) / 1e90)) = 0.5',
                'cot(acot((x - 1e100) / 1e90)) = 0.5',
            ] as $equation
        ) {
            $identityComposition = Math::solve($equation, 'x', 0.0, 1.0E308);
            self::assertCount(1, $identityComposition, $equation);
            self::assertEqualsWithDelta(1.0E100 + (0.5 * 1.0E90), $identityComposition[0]->value, 1.0E85);
        }

        foreach (
            [
                ['csch(acsch((x - 1e100) / 1e90)) = 0.5', 0.5],
                ['acsch(csch((x - 1e100) / 1e90)) = 0.5', 0.5],
                ['coth(acoth((x - 1e100) / 1e90)) = 2', 2.0],
                ['acoth(coth((x - 1e100) / 1e90)) = 0.5', 0.5],
                ['sech(asech((x - 1e100) / 1e90)) = 0.5', 0.5],
                ['cosh(acosh((x - 1e100) / 1e90)) = 2', 2.0],
                ['coth(atanh((x - 1e100) / 1e90)) = 2', 0.5],
                ['tanh(acoth((x - 1e100) / 1e90)) = 0.5', 2.0],
                ['csch(asinh((x - 1e100) / 1e90)) = 2', 0.5],
                ['sinh(acsch((x - 1e100) / 1e90)) = 2', 0.5],
                ['asinh(csch((x - 1e100) / 1e90)) = 0.5', \asinh(1.0 / \sinh(0.5))],
                ['acsch(sinh((x - 1e100) / 1e90)) = 0.5', \asinh(1.0 / \sinh(0.5))],
                ['sech(acosh((x - 1e100) / 1e90)) = 0.5', 2.0],
                ['cosh(asech((x - 1e100) / 1e90)) = 2', 0.5],
                ['sec(asec((x - 1e100) / 1e90)) = 2', 2.0],
                ['csc(acsc((x - 1e100) / 1e90)) = 2', 2.0],
            ] as [$equation, $level]
        ) {
            $specialFunctionComposition = Math::solve($equation, 'x', 0.0, 1.0E308);
            self::assertCount(1, $specialFunctionComposition, $equation);
            self::assertEqualsWithDelta(
                1.0E100 + ($level * 1.0E90),
                $specialFunctionComposition[0]->value,
                1.0E85,
            );
        }
        foreach (
            [
                ['cosh(asinh((x - 1e100) / 1e90)) = 1.4142135623730951', 1.0],
                ['sech(asinh((x - 1e100) / 1e90)) = 0.7071067811865476', 1.0],
                ['cosh(atanh((x - 1e100) / 1e90)) = 2', \sqrt(3.0) / 2.0],
                ['acosh(cosh((x - 1e100) / 1e90)) = 0.5', 0.5],
                ['asech(sech((x - 1e100) / 1e90)) = 0.5', 0.5],
                ['sqrt(abs((x - 1e100) / 1e90)) = 0.5', 0.25],
                ['cbrt(abs((x - 1e100) / 1e90)) = 0.5', 0.125],
                ['abs(cbrt((x - 1e100) / 1e90)) = 0.5', 0.125],
                ['sqrt(sqrt(abs((x - 1e100) / 1e90))) = 0.5', 0.0625],
                ['sqrt(cbrt(abs((x - 1e100) / 1e90))) = 0.5', 0.015625],
                ['cbrt(sqrt(abs((x - 1e100) / 1e90))) = 0.5', 0.015625],
                ['abs(sqrt(abs((x - 1e100) / 1e90))) = 0.5', 0.25],
            ] as [$equation, $magnitude]
        ) {
            $twoBranchSolutions = Math::solve($equation, 'x', 0.0, 1.0E308);
            self::assertCount(2, $twoBranchSolutions, $equation);
            self::assertEqualsWithDelta(
                1.0E100 - ($magnitude * 1.0E90),
                $twoBranchSolutions[0]->value,
                1.0E85,
            );
            self::assertEqualsWithDelta(
                1.0E100 + ($magnitude * 1.0E90),
                $twoBranchSolutions[1]->value,
                1.0E85,
            );
        }
        foreach (
            [
                'cosh(asinh((x - 1e100) / 1e90)) = 1',
                'acosh(cosh((x - 1e100) / 1e90)) = 0',
                'asech(sech((x - 1e100) / 1e90)) = 0',
                'asech(cosh((x - 1e100) / 1e90)) = 0',
                'acosh(sech((x - 1e100) / 1e90)) = 0',
                'sqrt(abs((x - 1e100) / 1e90)) = 0',
                'cbrt(abs((x - 1e100) / 1e90)) = 0',
                'abs(cbrt((x - 1e100) / 1e90)) = 0',
            ] as $equation
        ) {
            $singleBranchSolution = Math::solve($equation, 'x', 0.0, 1.0E308);
            self::assertCount(1, $singleBranchSolution, $equation);
            self::assertEqualsWithDelta(1.0E100, $singleBranchSolution[0]->value, 1.0E85);
        }
        foreach (
            [
                ['sqrt(sqrt((x - 1e100) / 1e90)) = 0.5', 0.0625],
                ['cbrt(cbrt((x - 1e100) / 1e90)) = 0.5', 1.0 / 512.0],
                ['sqrt(cbrt((x - 1e100) / 1e90)) = 0.5', 1.0 / 64.0],
                ['cbrt(sqrt((x - 1e100) / 1e90)) = 0.5', 1.0 / 64.0],
                ['abs(sqrt((x - 1e100) / 1e90)) = 0.5', 0.25],
            ] as [$equation, $level]
        ) {
            $radicalComposition = Math::solve($equation, 'x', 0.0, 1.0E308);
            self::assertCount(1, $radicalComposition, $equation);
            self::assertEqualsWithDelta(
                1.0E100 + ($level * 1.0E90),
                $radicalComposition[0]->value,
                1.0E85,
            );
        }
        foreach (
            [
                'coth(acoth((x - 1e100) / 1e90)) = 1',
                'sech(asech((x - 1e100) / 1e90)) = 0',
                'cosh(acosh((x - 1e100) / 1e90)) = 0.5',
                'coth(atanh((x - 1e100) / 1e90)) = 1',
                'tanh(acoth((x - 1e100) / 1e90)) = 1',
                'sech(acosh((x - 1e100) / 1e90)) = 0',
                'cosh(asech((x - 1e100) / 1e90)) = 0.5',
                'sin(asin((x - 1e100) / 1e90)) = 2',
                'cos(acos((x - 1e100) / 1e90)) = -2',
                'sec(asec((x - 1e100) / 1e90)) = 0.5',
                'csc(acsc((x - 1e100) / 1e90)) = -0.5',
                'acosh(cosh((x - 1e100) / 1e90)) = -1',
                'asech(sech((x - 1e100) / 1e90)) = -1',
            ] as $equation
        ) {
            self::assertSame([], Math::solve($equation, 'x', 0.0, 1.0E308), $equation);
        }

        $periodicInverseBranches = Math::solve('atan(tan(x)) = 0.2', 'x', -10.0, 10.0);
        self::assertCount(7, $periodicInverseBranches);
        foreach ([-3, -2, -1, 0, 1, 2, 3] as $index => $period) {
            self::assertEqualsWithDelta(
                ($period * \M_PI) + 0.2,
                $periodicInverseBranches[$index]->value,
                1.0E-10,
            );
        }

        self::assertSame([], Math::solve(
            'exp(ln((x - 1e100) / 1e90)) = 0',
            'x',
            0.0,
            1.0E308,
        ));
        self::assertSame([], Math::solve(
            'atan(sinh((x - 1e100) / 1e90)) = pi/2',
            'x',
            0.0,
            1.0E308,
        ));
        self::assertSame([], Math::solve(
            'asin(sinh((x - 1e100) / 1e90)) = 2',
            'x',
            0.0,
            1.0E308,
        ));

        $absoluteValues = Math::solve('abs((x - 1e100) / 1e90) = 0.5', 'x', 0.0, 1.0E308);
        self::assertCount(2, $absoluteValues);
        self::assertEqualsWithDelta(1.0E100 - (0.5 * 1.0E90), $absoluteValues[0]->value, 1.0E85);
        self::assertEqualsWithDelta(1.0E100 + (0.5 * 1.0E90), $absoluteValues[1]->value, 1.0E85);

        $hyperbolicCosines = Math::solve('cosh((x - 1e100) / 1e90) = 2', 'x', 0.0, 1.0E308);
        $hyperbolicRadius = \acosh(2.0) * 1.0E90;
        self::assertCount(2, $hyperbolicCosines);
        self::assertEqualsWithDelta(1.0E100 - $hyperbolicRadius, $hyperbolicCosines[0]->value, 1.0E85);
        self::assertEqualsWithDelta(1.0E100 + $hyperbolicRadius, $hyperbolicCosines[1]->value, 1.0E85);

        $hyperbolicSecants = Math::solve('sech((x - 1e100) / 1e90) = 0.5', 'x', 0.0, 1.0E308);
        self::assertCount(2, $hyperbolicSecants);
        self::assertEqualsWithDelta(1.0E100 - $hyperbolicRadius, $hyperbolicSecants[0]->value, 1.0E85);
        self::assertEqualsWithDelta(1.0E100 + $hyperbolicRadius, $hyperbolicSecants[1]->value, 1.0E85);

        foreach (
            [
                ['csch', '0.5', \asinh(2.0)],
                ['coth', '2', \atanh(0.5)],
                ['asech', '0.5', 1.0 / \cosh(0.5)],
                ['acsch', '0.5', 1.0 / \sinh(0.5)],
                ['acoth', '0.5', \cosh(0.5) / \sinh(0.5)],
                ['erf', '0.5', 0.4769362762044699],
                ['erfc', '0.5', 0.4769362762044699],
            ] as [$function, $target, $argument]
        ) {
            $solutionsForFunction = Math::solve(
                $function . '((x - 1e100) / 1e90) = ' . $target,
                'x',
                0.0,
                1.0E308,
            );
            self::assertCount(1, $solutionsForFunction, $function);
            self::assertEqualsWithDelta(
                1.0E100 + ($argument * 1.0E90),
                $solutionsForFunction[0]->value,
                1.0E85,
                $function,
            );
        }

        $logarithmRoots = Math::solve('ln((x - 1e100)^2) = 400', 'x', 0.0, 1.0E308);
        $logarithmRadius = \exp(200.0);
        self::assertCount(2, $logarithmRoots);
        self::assertEqualsWithDelta(1.0E100 - $logarithmRadius, $logarithmRoots[0]->value, 1.0E85);
        self::assertEqualsWithDelta(1.0E100 + $logarithmRadius, $logarithmRoots[1]->value, 1.0E85);

        $arbitraryBaseLogarithm = Math::solve(
            'log((x - 1e100)^2, 10) = 180',
            'x',
            0.0,
            1.0E308,
        );
        self::assertCount(2, $arbitraryBaseLogarithm);
        self::assertEqualsWithDelta(1.0E100 - 1.0E90, $arbitraryBaseLogarithm[0]->value, 1.0E85);
        self::assertEqualsWithDelta(1.0E100 + 1.0E90, $arbitraryBaseLogarithm[1]->value, 1.0E85);

        $commonLogarithmRoots = Math::solve('log10((x - 1e100)^2) = 200', 'x', 0.0, 1.0E308);
        self::assertSame([0.0, 2.0E100], \array_map(
            static fn (EquationSolution $solution): float => $solution->value,
            $commonLogarithmRoots,
        ));

        $translatedCubeRoot = Math::solve(
            'root((x - 1e100)^3, 3) = 1e90',
            'x',
            0.0,
            1.0E308,
        );
        self::assertCount(1, $translatedCubeRoot);
        self::assertEqualsWithDelta(1.0E100 + 1.0E90, $translatedCubeRoot[0]->value, 1.0E85);

        $translatedEvenRoot = Math::solve(
            'root((x - 1e100)^2, -2) = 1e-90',
            'x',
            0.0,
            1.0E308,
        );
        self::assertCount(2, $translatedEvenRoot);
        self::assertEqualsWithDelta(1.0E100 - 1.0E90, $translatedEvenRoot[0]->value, 1.0E85);
        self::assertEqualsWithDelta(1.0E100 + 1.0E90, $translatedEvenRoot[1]->value, 1.0E85);

        foreach (
            [
                ['lambertw((x - 1e100) / 1e90) = 1', \M_E],
                ['lambertw((x - 1e100) / 1e90) = -0.2', -0.2 * \exp(-0.2)],
                ['lambertw((x - 1e100) / 1e90, -1) = -2', -2.0 * \exp(-2.0)],
            ] as [$equation, $argument]
        ) {
            $solutionsForBranch = Math::solve($equation, 'x', 0.0, 1.0E308);
            self::assertCount(1, $solutionsForBranch, $equation);
            self::assertEqualsWithDelta(
                1.0E100 + ($argument * 1.0E90),
                $solutionsForBranch[0]->value,
                1.0E85,
                $equation,
            );
        }

        self::assertSame([], Math::solve('lambertw((x - 1e100) / 1e90) = -1', 'x', 0.0, 1.0E308));
        self::assertSame(
            [],
            Math::solve('lambertw((x - 1e100) / 1e90, -1) = -0.2', 'x', 0.0, 1.0E308),
        );
    }

    public function testInverseCosecantHyperbolicCompositionsRespectZeroTargets(): void
    {
        self::assertSame([], Math::solve('asinh(csch(x)) = 0', 'x', -2.0, 2.0));
        self::assertSame([], Math::solve('acsch(sinh(x)) = 0', 'x', -2.0, 2.0));

        foreach (
            [
                ['asinh(csch(x)) = -0.5', -\asinh(1.0 / \sinh(0.5))],
                ['acsch(sinh(x)) = -0.5', -\asinh(1.0 / \sinh(0.5))],
            ] as [$equation, $expected]
        ) {
            $solutions = Math::solve($equation, 'x', -2.0, 2.0);
