        }
    }

    public function testHyperbolicFunctionsOfPeriodicExpressionsAreInvertedByLevels(): void
    {
        $options = new \MathPHP\Solver\SolverOptions(scanSteps: 32);
        $equations = [
            'cosh(sin(x)) = 6/5' => 8,
            'sech(sin(x)) = 4/5' => 8,
            'csch(sin(x)) = 2' => 4,
            'coth(sin(x)) = 2' => 4,
        ];

        foreach ($equations as $equation => $expectedCount) {
            $solutions = Math::solve($equation, 'x', -6.3, 6.3, solverOptions: $options);
            self::assertCount($expectedCount, $solutions, $equation);
            foreach ($solutions as $solution) {
                [$left, $right] = \explode('=', $equation, 2);
                self::assertEqualsWithDelta(
                    (float) Math::evaluate(\trim($right)),
                    (float) Math::evaluate(\trim($left), ['x' => $solution->value]),
                    1.0E-8,
                    $equation,
                );
            }
        }

        self::assertSame(
            [],
            Math::solve('cosh(sin(x)) = 2', 'x', -6.3, 6.3, solverOptions: $options),
        );
    }

    public function testReciprocalTrigonometricFunctionsOfBoundedPeriodicExpressions(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $equations = [
            'sec(sin(x)) = 3/2' => 8,
            'csc(sin(x)) = 2' => 4,
            'cot(sin(x)) = 2' => 4,
            'sec(tanh(x)) = 3/2' => 2,
            'csc(tanh(x)) = 2' => 1,
            'cot(tanh(x)) = 2' => 1,
            'sec(erf(x)) = 3/2' => 2,
            'csc(erf(x)) = 2' => 1,
            'cot(erf(x)) = 2' => 1,
            'sec(atan(x)) = 2' => 2,
            'csc(atan(x)) = 2' => 1,
            'cot(atan(x)) = 2' => 1,
            'sin(exp(sin(x))) = 0.5' => 8,
            'cos(exp(sin(x))) = 0.5' => 4,
            'cot(exp(sin(x))) = 2' => 4,
        ];

        foreach ($equations as $equation => $expectedCount) {
            $solutions = Math::solve($equation, 'x', -6.3, 6.3, solverOptions: $options);
            self::assertCount($expectedCount, $solutions, $equation);
            [$left, $right] = \explode('=', $equation, 2);
            foreach ($solutions as $solution) {
                self::assertEqualsWithDelta(
                    (float) Math::evaluate(\trim($right)),
                    (float) Math::evaluate(\trim($left), ['x' => $solution->value]),
                    1.0E-8,
                    $equation,
                );
            }
        }

        self::assertSame([], Math::solve('cot(sin(x)) = 0', 'x', -6.3, 6.3, solverOptions: $options));
        self::assertSame([], Math::solve('sec(sin(x)) = -2', 'x', -6.3, 6.3, solverOptions: $options));
        self::assertSame([], Math::solve('csc(tanh(x)) = 1', 'x', -6.3, 6.3, solverOptions: $options));
        self::assertSame([], Math::solve('csc(erf(x)) = 1', 'x', -6.3, 6.3, solverOptions: $options));
        self::assertSame([], Math::solve('csc(atan(x)) = 1', 'x', -6.3, 6.3, solverOptions: $options));
    }

