    public function testPolynomialRootsAreFoundAcrossAnUnrepresentableIntervalWidth(): void
    {
        $solutions = Math::solve('x^2 = 1', 'x', -1.0E308, 1.0E308);

        self::assertCount(2, $solutions);
        self::assertSame(-1.0, $solutions[0]->value);
        self::assertSame(1.0, $solutions[1]->value);

        $quarticRoots = Math::solve(
            '(x^2 - 1) * (x^2 - 4) = 0',
            'x',
            -1.0E308,
            1.0E308,
        );
        self::assertCount(4, $quarticRoots);
        self::assertSame([-2.0, -1.0, 1.0, 2.0], \array_map(
            static fn (EquationSolution $solution): float => $solution->value,
            $quarticRoots,
        ));

        $repeatedRoots = Math::solve(
            '(x - 1)^2 * (x + 2)^2 = 0',
            'x',
            -1.0E308,
            1.0E308,
        );
        self::assertSame([-2.0, 1.0], \array_map(
            static fn (EquationSolution $solution): float => $solution->value,
            $repeatedRoots,
        ));
    }

    public function testRationalIdentityOnWideIntervalRemainsAnInfiniteSolutionSet(): void
    {
        $infiniteSets = 0;
        foreach (
            [
                'x/x = 1',
                '(x^2 - 1)/(x - 1) = x + 1',
            ] as $equation
        ) {
            $infiniteRootsReported = false;
            try {
                Math::solve($equation, 'x', -1.0E308, 1.0E308);
                self::fail('Expected an infinite solution set for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                ++$infiniteSets;
            }
        }

        self::assertSame(2, $infiniteSets);
    }

    public function testWideIntervalRationalLinearRootsPreserveDenominatorHoles(): void
    {
        foreach (
            [
                ['x/(x - 1) = 2', [2.0]],
                ['x/x = 2', []],
                ['(x - 1)/(x - 1) = 2', []],
                ['1/x = 0', []],
                ['(x^2 - 1)/(x - 1) = 0', [-1.0]],
            ] as [$equation, $expectedRoots]
        ) {
            $solutions = Math::solve($equation, 'x', -1.0E308, 1.0E308);

            self::assertCount(\count($expectedRoots), $solutions, $equation);
            foreach ($expectedRoots as $index => $root) {
                self::assertSame($root, $solutions[$index]->value, $equation);
                self::assertSame(0.0, $solutions[$index]->residual, $equation);
            }
        }
    }

    public function testExactRationalRecoveryValidatesRootsWithPolynomialMagnitude(): void
    {
        $equation =
            'x^5 - 1.50001*x^4 + 1.75001*x^3 - 1.6250125*x^2 + 0.75001*x - 0.1250025 = 0';
        $solutions = Math::solve($equation, 'x', 0.49, 0.51);

        self::assertCount(2, $solutions);
        self::assertEqualsWithDelta(0.5, $solutions[0]->value, 1.0E-9);
        self::assertEqualsWithDelta(0.50001, $solutions[1]->value, 1.0E-9);
        foreach ($solutions as $solution) {
            self::assertLessThanOrEqual(1.0E-10, $solution->residual);
        }

        $clippedSolutions = Math::solve($equation, 'x', 0.500001, 0.51);
        self::assertCount(1, $clippedSolutions);
        self::assertEqualsWithDelta(0.50001, $clippedSolutions[0]->value, 1.0E-9);
    }

    public function testDecimalFloatParametersUseExactPolynomialRecovery(): void
    {
