        }
    }

    public function testFloatParameterRecoveryIgnoresSerializePrecisionSetting(): void
    {
        $precision = \ini_get('serialize_precision');
        self::assertNotFalse($precision);

        try {
            self::assertNotFalse(\ini_set('serialize_precision', '3'));
            $solutions = Math::solve(
                'x^5 - p*x^4 + q*x^3 - r*x^2 + s*x - t = 0',
                'x',
                0.99,
                1.01,
                [
                    'p' => 3.00001,
                    'q' => 4.00002,
                    'r' => 4.00002,
                    's' => 3.00002,
                    't' => 1.00001,
                ],
            );
        } finally {
