    public function testOpaqueOscillatoryFunctionNeverReturnsAnUncertifiedRootList(): void
    {
        $functions = FunctionRegistry::defaults()->with(new FunctionDefinition(
            'wave',
            1,
            1,
            static function (array $arguments): float {
                $scaled = ($arguments[0] - 0.123) / 0.0001;

                return \exp(-($scaled ** 2))
                    * \sin(100_000.0 * ($arguments[0] - 0.123));
            },
        ));
        $evaluationOptions = new EvaluationOptions(functions: $functions);
        $equation = 'wave(x) = 0.5';

        foreach ([4096, 8192, 16384] as $scanSteps) {
            try {
                Math::solve(
                    $equation,
                    'x',
                    0.0,
                    1.0,
                    evaluationOptions: $evaluationOptions,
                    solverOptions: new SolverOptions(scanSteps: $scanSteps),
                );
                self::fail('An incomplete custom-function scan must not claim an empty root set.');
            } catch (RootSearchLimitException $exception) {
                self::assertStringContainsString('cannot certify', $exception->getMessage());
            }
        }

        try {
            Math::solve(
                $equation,
                'x',
                0.0,
                1.0,
                evaluationOptions: $evaluationOptions,
                solverOptions: new SolverOptions(scanSteps: SolverOptions::MAX_SCAN_STEPS),
            );
            self::fail('Even a dense scan cannot certify that it found every root of an opaque function.');
        } catch (RootSearchLimitException $exception) {
            self::assertStringContainsString('cannot certify', $exception->getMessage());
        }
    }

    public function testCustomGradientFindsOffGridEvenMultiplicityRoot(): void
    {
        $center = 0.123456789;
        $bump = new FunctionDefinition(
            'bump',
            1,
            1,
            static fn (array $arguments): float => ($arguments[0] - $center) ** 2,
            static fn (array $arguments): array => [2.0 * ($arguments[0] - $center)],
            range: static function (array $arguments) use ($center): array {
                [$lower, $upper] = $arguments[0];
                $left = ($lower - $center) ** 2;
                $right = ($upper - $center) ** 2;
                $minimum = $lower <= $center && $center <= $upper ? 0.0 : \min($left, $right);

                return [$minimum, \max($left, $right)];
            },
        );
        $solutions = Math::solve(
            'bump(x) = 0',
            'x',
            0.0,
            1.0,
            evaluationOptions: new EvaluationOptions(
                functions: FunctionRegistry::defaults()->with($bump),
            ),
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(1, $solutions);
        self::assertEqualsWithDelta($center, $solutions[0]->value, 1.0E-8);
        self::assertLessThanOrEqual(1.0E-15, $solutions[0]->residual);

        $radius = 1.0E-5;
        $nearbyRoots = new FunctionDefinition(
            'nearbyRoots',
            1,
            1,
            static fn (array $arguments): float => (($arguments[0] - $center) ** 2) - ($radius ** 2),
            static fn (array $arguments): array => [2.0 * ($arguments[0] - $center)],
            range: static function (array $arguments) use ($center, $radius): array {
                [$lower, $upper] = $arguments[0];
                $left = ($lower - $center) ** 2;
                $right = ($upper - $center) ** 2;
                $minimum = $lower <= $center && $center <= $upper ? 0.0 : \min($left, $right);

                return [$minimum - ($radius ** 2), \max($left, $right) - ($radius ** 2)];
            },
        );
        $pairedSolutions = Math::solve(
            'nearbyRoots(x) = 0',
            'x',
            0.0,
            1.0,
            evaluationOptions: new EvaluationOptions(
                functions: FunctionRegistry::defaults()->with($nearbyRoots),
            ),
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(2, $pairedSolutions);
        self::assertEqualsWithDelta($center - $radius, $pairedSolutions[0]->value, 1.0E-8);
        self::assertEqualsWithDelta($center + $radius, $pairedSolutions[1]->value, 1.0E-8);
    }

    public function testCustomIntervalExtensionFindsNarrowRootsMissedByTheScan(): void
    {
        $center = 0.125;
        $radius = 1.0E-6;
        $bump = new FunctionDefinition(
            'enclosedBump',
            1,
            1,
            static fn (array $arguments): float => 1.0
                - ((($arguments[0] - $center) / $radius) ** 2),
            range: static function (array $arguments) use ($center, $radius): array {
                [$lower, $upper] = $arguments[0];
                $left = ($lower - $center) / $radius;
                $right = ($upper - $center) / $radius;
                $containsCenter = $lower <= $center && $center <= $upper;
                $maximum = $containsCenter
                    ? 1.0
                    : 1.0 - \min($left ** 2, $right ** 2);
                $minimum = 1.0 - \max($left ** 2, $right ** 2);

                return [$minimum, $maximum];
            },
        );
        $solutions = Math::solve(
            'enclosedBump(x) = 0',
            'x',
            0.0,
            1.0,
            evaluationOptions: new EvaluationOptions(
                functions: FunctionRegistry::defaults()->with($bump),
            ),
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(2, $solutions);
        self::assertEqualsWithDelta($center - $radius, $solutions[0]->value, 1.0E-9);
        self::assertEqualsWithDelta($center + $radius, $solutions[1]->value, 1.0E-9);
        self::assertLessThanOrEqual(1.0E-10, $solutions[0]->residual);
        self::assertLessThanOrEqual(1.0E-10, $solutions[1]->residual);

        self::assertSame([], Math::solve(
            'enclosedBump(x) = 2',
            'x',
            0.0,
            1.0,
            evaluationOptions: new EvaluationOptions(
                functions: FunctionRegistry::defaults()->with($bump),
            ),
            solverOptions: new SolverOptions(scanSteps: 1),
        ));

        $arithmeticSolutions = Math::solve(
            '2 * enclosedBump(x) = 0',
            'x',
            0.0,
            1.0,
            evaluationOptions: new EvaluationOptions(
                functions: FunctionRegistry::defaults()->with($bump),
            ),
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(2, $arithmeticSolutions);
        self::assertEqualsWithDelta($center - $radius, $arithmeticSolutions[0]->value, 1.0E-9);
        self::assertEqualsWithDelta($center + $radius, $arithmeticSolutions[1]->value, 1.0E-9);
    }

    public function testBuiltInIntervalsComposeWithCustomFunctionEnclosures(): void
    {
        $center = 0.125;
        $radius = 1.0E-6;
        $phase = new FunctionDefinition(
            'narrowPhase',
            1,
            1,
            static fn (array $arguments): float => 0.1
                - ((($arguments[0] - $center) / $radius) ** 2),
            range: static function (array $arguments) use ($center, $radius): array {
                [$lower, $upper] = $arguments[0];
                $left = 0.1 - ((($lower - $center) / $radius) ** 2);
                $right = 0.1 - ((($upper - $center) / $radius) ** 2);

                return [
                    \min($left, $right),
                    $lower <= $center && $center <= $upper ? 0.1 : \max($left, $right),
                ];
            },
        );
        $options = new EvaluationOptions(functions: FunctionRegistry::defaults()->with($phase));
        $lower = $center - ($radius / 2.0);
        $upper = $center + ($radius / 2.0);
        $expectedOffset = \sqrt(0.1) * $radius;

        foreach (['sin(narrowPhase(x)) = 0', 'exp(narrowPhase(x)) = 1'] as $equation) {
            $solutions = Math::solve(
                $equation,
                'x',
                $lower,
                $upper,
                evaluationOptions: $options,
                solverOptions: new SolverOptions(scanSteps: 1),
            );

            self::assertCount(2, $solutions, $equation);
            self::assertEqualsWithDelta($center - $expectedOffset, $solutions[0]->value, 1.0E-9);
            self::assertEqualsWithDelta($center + $expectedOffset, $solutions[1]->value, 1.0E-9);
        }

        self::assertSame([], Math::solve(
            'narrowPhase(x) % 2 = 2',
            'x',
            0.0,
            1.0,
            evaluationOptions: $options,
            solverOptions: new SolverOptions(scanSteps: 1),
        ));

        $boundedValue = new FunctionDefinition(
            'boundedValue',
            1,
            1,
            static fn (array $arguments): float => $arguments[0],
            range: static fn (array $arguments): array => $arguments[0],
        );
        self::assertSame([], Math::solve(
            'boundedValue(x) % 100 = 2',
            'x',
            0.0,
            1.0,
            evaluationOptions: new EvaluationOptions(
                functions: FunctionRegistry::defaults()->with($boundedValue),
            ),
            solverOptions: new SolverOptions(scanSteps: 1),
        ));
        self::assertSame([], Math::solve(
            'boundedValue(x)! = 3',
            'x',
            0.0,
            1.0,
            evaluationOptions: new EvaluationOptions(
                functions: FunctionRegistry::defaults()->with($boundedValue),
            ),
            solverOptions: new SolverOptions(scanSteps: 1),
        ));
        self::assertSame([], Math::solve(
            'binomial(boundedValue(x), 2) = 1',
            'x',
            0.0,
            1.0,
            evaluationOptions: new EvaluationOptions(
                functions: FunctionRegistry::defaults()->with($boundedValue),
            ),
            solverOptions: new SolverOptions(scanSteps: 1),
        ));
        foreach (
            [
                'gcd(boundedValue(x), 2) = 3',
                'lcm(boundedValue(x), 2) = 3',
                'doublefactorial(boundedValue(x)) = 2',
                'besselj(0, boundedValue(x)) = 2',
                'besseli(0, boundedValue(x)) = 3',
                'besseli(0, boundedValue(x)) = 2',
            ] as $equation
        ) {
            self::assertSame([], Math::solve(
                $equation,
                'x',
                0.0,
                1.0,
                evaluationOptions: new EvaluationOptions(
                    functions: FunctionRegistry::defaults()->with($boundedValue),
                ),
                solverOptions: new SolverOptions(scanSteps: 1),
            ), $equation);
        }

        $positivePhase = new FunctionDefinition(
            'positivePhase',
            1,
            1,
            static fn (array $arguments): float => $arguments[0],
            range: static fn (array $arguments): array => $arguments[0],
        );
        $positivePhaseOptions = new EvaluationOptions(
            functions: FunctionRegistry::defaults()->with($positivePhase),
        );
        $reciprocalEquations = [
            'sec(positivePhase(x)) = -1',
            'csc(positivePhase(x)) = -1',
            'cot(positivePhase(x)) = -1',
        ];
        foreach ($reciprocalEquations as $equation) {
            self::assertSame([], Math::solve(
                $equation,
                'x',
                0.1,
                1.0,
                evaluationOptions: $positivePhaseOptions,
                solverOptions: new SolverOptions(scanSteps: 1),
            ), $equation);
        }
        $inverseEquations = ['asec(positivePhase(x)) = -1', 'acsc(positivePhase(x)) = 1', 'acot(positivePhase(x)) = 2'];
        foreach ($inverseEquations as $equation) {
            self::assertSame([], Math::solve(
                $equation,
                'x',
                2.0,
                3.0,
                evaluationOptions: $positivePhaseOptions,
                solverOptions: new SolverOptions(scanSteps: 1),
            ), $equation);
        }
        $inverseHyperbolicEquations = [
            ['asech(positivePhase(x)) = -1', 0.1, 1.0],
            ['acsch(positivePhase(x)) = 2', 2.0, 3.0],
            ['acoth(positivePhase(x)) = -1', 2.0, 3.0],
        ];
        foreach ($inverseHyperbolicEquations as [$equation, $lowerBound, $upperBound]) {
            self::assertSame([], Math::solve(
                $equation,
                'x',
                $lowerBound,
                $upperBound,
                evaluationOptions: $positivePhaseOptions,
                solverOptions: new SolverOptions(scanSteps: 1),
            ), $equation);
        }
        foreach (['sinc(positivePhase(x)) = 2', 'sincpi(positivePhase(x)) = -2'] as $equation) {
            self::assertSame([], Math::solve(
                $equation,
                'x',
                0.1,
                1.0,
                evaluationOptions: $positivePhaseOptions,
                solverOptions: new SolverOptions(scanSteps: 1),
            ), $equation);
        }
        $errorInverseEquations = [
            ['erfcx(positivePhase(x)) = 10', 0.1, 0.9],
            ['erfinv(positivePhase(x)) = 2', 0.1, 0.9],
            ['erfcinv(positivePhase(x)) = 2', 0.1, 0.9],
        ];
        foreach ($errorInverseEquations as [$equation, $lowerBound, $upperBound]) {
            self::assertSame([], Math::solve(
                $equation,
                'x',
                $lowerBound,
                $upperBound,
                evaluationOptions: $positivePhaseOptions,
                solverOptions: new SolverOptions(scanSteps: 1),
            ), $equation);
        }
        $rootEquations = [
            'root(positivePhase(x), 5) = 2',
            'root(positivePhase(x), 2 + 2) = 2',
            'root(positivePhase(x), -2) = 10',
            'root(positivePhase(x), 4) = -1',
        ];
        foreach ($rootEquations as $equation) {
            self::assertSame([], Math::solve(
                $equation,
                'x',
                0.1,
                0.9,
                evaluationOptions: $positivePhaseOptions,
                solverOptions: new SolverOptions(scanSteps: 1),
            ), $equation);
        }
        $degreePhase = new FunctionDefinition(
            'degreePhase',
            1,
            1,
            static fn (array $arguments): float => 2.0 + (2.0 * $arguments[0]),
            range: static fn (array $arguments): array => [
                2.0 + (2.0 * $arguments[0][0]),
                2.0 + (2.0 * $arguments[0][1]),
            ],
        );
        $variableDegreeOptions = new EvaluationOptions(
            functions: FunctionRegistry::defaults()->with($positivePhase)->with($degreePhase),
        );
        self::assertSame([], Math::solve(
            'root(positivePhase(x), degreePhase(x)) = 2',
            'x',
            0.1,
            0.9,
            evaluationOptions: $variableDegreeOptions,
            solverOptions: new SolverOptions(scanSteps: 1),
        ));
        $variableDegreeRoot = Math::solve(
            'root(positivePhase(x), degreePhase(x)) = 0.7937005259840998',
            'x',
            0.1,
            0.9,
            evaluationOptions: $variableDegreeOptions,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $variableDegreeRoot);
        self::assertEqualsWithDelta(0.5, $variableDegreeRoot[0]->value, 1.0E-10);
        self::assertSame([], Math::solve(
            'lambertw(positivePhase(x)) = 10',
            'x',
            0.1,
            0.9,
            evaluationOptions: $positivePhaseOptions,
            solverOptions: new SolverOptions(scanSteps: 1),
        ));
        $negativePhase = new FunctionDefinition(
            'negativePhase',
            1,
            1,
            static fn (array $arguments): float => -0.1 - (0.2 * $arguments[0]),
            range: static function (array $arguments): array {
                [$lower, $upper] = $arguments[0];

                return [-0.1 - (0.2 * $upper), -0.1 - (0.2 * $lower)];
            },
        );
        self::assertSame([], Math::solve(
            'lambertw(negativePhase(x), -1) = 0',
            'x',
            0.0,
            1.0,
            evaluationOptions: new EvaluationOptions(
                functions: FunctionRegistry::defaults()->with($negativePhase),
            ),
            solverOptions: new SolverOptions(scanSteps: 1),
        ));
        $incompleteFunctionEquations = [
            'gammainc(2, positivePhase(x)) = 2',
            'gammainc(1 + 1, positivePhase(x)) = 2',
            'gammaincc(2, positivePhase(x)) = -1',
            'betainc(2, 3, positivePhase(x)) = 2',
            'betainc(1 + 1, 2 + 1, positivePhase(x)) = 2',
            'betaincc(2, 3, positivePhase(x)) = -1',
        ];
        foreach ($incompleteFunctionEquations as $equation) {
            self::assertSame([], Math::solve(
                $equation,
                'x',
                0.1,
                0.9,
                evaluationOptions: $positivePhaseOptions,
                solverOptions: new SolverOptions(scanSteps: 1),
            ), $equation);
        }
        $gammaTarget = SpecialFunctions::regularizedGammaP(2.0, 0.5);
        $gammaRoot = Math::solve(
            'gammainc(2, positivePhase(x)) = ' . \sprintf('%.17g', $gammaTarget),
            'x',
            0.1,
            0.9,
            evaluationOptions: $positivePhaseOptions,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $gammaRoot);
        self::assertEqualsWithDelta(0.5, $gammaRoot[0]->value, 1.0E-9);

        $betaTarget = SpecialFunctions::regularizedBeta(2.0, 3.0, 0.5);
        $betaRoot = Math::solve(
            'betainc(2, 3, positivePhase(x)) = ' . \sprintf('%.17g', $betaTarget),
            'x',
            0.1,
            0.9,
            evaluationOptions: $positivePhaseOptions,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $betaRoot);
        self::assertEqualsWithDelta(0.5, $betaRoot[0]->value, 1.0E-9);

        $inverseIncompleteEquations = [
            'gammaincinv(2, positivePhase(x)) + 1 = 11',
            'gammaincinv(1 + 1, positivePhase(x)) + 1 = 11',
            'gammainccinv(2, positivePhase(x)) + 1 = 1',
            'betaincinv(2, 3, positivePhase(x)) + 1 = 3',
            'betaincinv(1 + 1, 2 + 1, positivePhase(x)) + 1 = 3',
            'betainccinv(2, 3, positivePhase(x)) + 1 = 0',
        ];
        foreach ($inverseIncompleteEquations as $equation) {
            self::assertSame([], Math::solve(
                $equation,
                'x',
                0.1,
                0.9,
                evaluationOptions: $positivePhaseOptions,
                solverOptions: new SolverOptions(scanSteps: 1),
            ), $equation);
        }
        $inverseGammaProbability = SpecialFunctions::regularizedGammaP(2.0, 0.5);
        $inverseGammaRoot = Math::solve(
            'gammaincinv(2, positivePhase(x)) + 1 = 1.5',
            'x',
            0.01,
            0.99,
            evaluationOptions: $positivePhaseOptions,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $inverseGammaRoot);
        self::assertEqualsWithDelta($inverseGammaProbability, $inverseGammaRoot[0]->value, 1.0E-8);
        $inverseGammaComplementProbability = SpecialFunctions::regularizedGammaQ(2.0, 0.5);
        $inverseGammaComplementRoot = Math::solve(
            'gammainccinv(2, positivePhase(x)) + 1 = 1.5',
            'x',
            0.01,
            0.99,
            evaluationOptions: $positivePhaseOptions,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $inverseGammaComplementRoot);
        self::assertEqualsWithDelta(
            $inverseGammaComplementProbability,
            $inverseGammaComplementRoot[0]->value,
            1.0E-8,
        );

        $inverseBetaProbability = SpecialFunctions::regularizedBeta(2.0, 3.0, 0.5);
        $inverseBetaRoot = Math::solve(
            'betaincinv(2, 3, positivePhase(x)) + 1 = 1.5',
            'x',
            0.01,
            0.99,
            evaluationOptions: $positivePhaseOptions,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $inverseBetaRoot);
        self::assertEqualsWithDelta($inverseBetaProbability, $inverseBetaRoot[0]->value, 1.0E-8);
        $inverseBetaComplementProbability = SpecialFunctions::regularizedBetaComplement(2.0, 3.0, 0.5);
        $inverseBetaComplementRoot = Math::solve(
            'betainccinv(2, 3, positivePhase(x)) + 1 = 1.5',
            'x',
            0.01,
            0.99,
            evaluationOptions: $positivePhaseOptions,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $inverseBetaComplementRoot);
        self::assertEqualsWithDelta(
            $inverseBetaComplementProbability,
            $inverseBetaComplementRoot[0]->value,
            1.0E-8,
        );

        $shapePhase = new FunctionDefinition(
            'shapePhase',
            1,
            1,
            static fn (array $arguments): float => 1.0 + $arguments[0],
            range: static fn (array $arguments): array => [
                1.0 + $arguments[0][0],
                1.0 + $arguments[0][1],
            ],
        );
        $shapeOptions = new EvaluationOptions(
            functions: FunctionRegistry::defaults()->with($shapePhase),
        );
        $varyingShapeCases = [
            [
                'gammainc(shapePhase(x), 0.5)',
                SpecialFunctions::regularizedGammaP(1.5, 0.5),
            ],
            [
                'betainc(shapePhase(x), 3, 0.5)',
                SpecialFunctions::regularizedBeta(1.5, 3.0, 0.5),
            ],
            [
                'gammaincinv(shapePhase(x), 0.5)',
                SpecialFunctions::inverseRegularizedGammaP(1.5, 0.5),
            ],
            [
                'betaincinv(shapePhase(x), 3, 0.5)',
                SpecialFunctions::inverseRegularizedBeta(1.5, 3.0, 0.5),
            ],
        ];
        foreach ($varyingShapeCases as [$expression, $target]) {
            $solutions = Math::solve(
                $expression . ' = ' . \sprintf('%.17g', $target),
                'x',
                0.1,
                0.9,
                evaluationOptions: $shapeOptions,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertCount(1, $solutions, $expression);
            self::assertEqualsWithDelta(0.5, $solutions[0]->value, 1.0E-8, $expression);
        }

        $shiftedPhase = new FunctionDefinition(
            'shiftedPhase',
            1,
            1,
            static fn (array $arguments): float => 1.0 + $arguments[0],
            range: static fn (array $arguments): array => [
                1.0 + $arguments[0][0],
                1.0 + $arguments[0][1],
            ],
        );
        $atan2Options = new EvaluationOptions(
            functions: FunctionRegistry::defaults()->with($positivePhase)->with($shiftedPhase),
        );
        $atan2Target = \atan2(0.5, 1.5);
        $atan2Roots = Math::solve(
            'atan2(positivePhase(x), shiftedPhase(x)) = ' . \sprintf('%.17g', $atan2Target),
            'x',
            0.1,
            0.9,
            evaluationOptions: $atan2Options,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $atan2Roots);
        self::assertEqualsWithDelta(0.5, $atan2Roots[0]->value, 1.0E-8);
        self::assertSame([], Math::solve(
            'atan2(positivePhase(x), shiftedPhase(x)) = 4',
            'x',
            0.1,
            0.9,
            evaluationOptions: $atan2Options,
            solverOptions: new SolverOptions(scanSteps: 1),
        ));
    }

    public function testGammaIntervalEnclosureIncludesNegativeExtremaAndRejectsPoles(): void
    {
        $solver = new EquationSolver();
        $rangeMethod = new \ReflectionMethod($solver, 'gammaIntervalRange');
        $rangeMethod->setAccessible(true);
        $options = new EvaluationOptions();
        foreach (
            [
                [-3.8, -3.2],
                [-2.9, -2.1],
                [-1.9, -1.1],
                [-0.9, -0.1],
                [0.01, 0.99],
                [1.1, 2.1],
            ] as [$lower, $upper]
        ) {
            $range = $rangeMethod->invoke($solver, [$lower, $upper], $options);
            if (
                !\is_array($range)
                || \count($range) !== 2
                || !\is_float($range[0])
                || !\is_float($range[1])
            ) {
                self::fail('Expected a two-bound Gamma interval enclosure.');
            }
            for ($index = 0; $index <= 100; ++$index) {
                $value = $lower + (($upper - $lower) * $index / 100.0);
                $gamma = Math::evaluate('gamma(x)', ['x' => $value]);
                self::assertGreaterThanOrEqual($range[0], $gamma);
                self::assertLessThanOrEqual($range[1], $gamma);
            }
        }
        foreach ([[-2.5, -1.5], [-1.0, -0.5], [-0.5, 0.1]] as $poleInterval) {
            self::assertNull($rangeMethod->invoke($solver, $poleInterval, $options));
        }
    }

    public function testPositivePolygammaAndLogGammaIntervalEnclosures(): void
    {
        $solver = new EquationSolver();
        $rangeMethod = new \ReflectionMethod($solver, 'builtInIntervalRange');
        $rangeMethod->setAccessible(true);
        $options = new EvaluationOptions();
        foreach (
            [
                'digamma' => [0.2, 4.0],
                'trigamma' => [0.2, 4.0],
                'tetragamma' => [0.2, 4.0],
                'lgamma' => [0.2, 4.0],
                'zeta' => [1.01, 8.0],
                'dawson' => [-10.0, 10.0],
                'dawson_positive_tail' => [10.0, 10.1],
                'dawson_negative_tail' => [-10.1, -10.0],
            ] as $name => [$lower, $upper]
        ) {
            $function = str_starts_with($name, 'dawson_') ? 'dawson' : $name;
            $range = $rangeMethod->invoke($solver, $function, [[$lower, $upper]], $options);
            self::assertIsArray($range, $function);
            for ($index = 0; $index <= 100; ++$index) {
                $value = $lower + (($upper - $lower) * $index / 100.0);
                $expression = $function . '(x)';
                $actual = Math::evaluate($expression, ['x' => $value]);
                self::assertGreaterThanOrEqual($range[0], $actual, $expression);
                self::assertLessThanOrEqual($range[1], $actual, $expression);
            }
        }

        $betaRange = $rangeMethod->invoke(
            $solver,
            'beta',
            [[0.2, 3.0], [0.4, 2.0]],
            $options,
        );
        self::assertIsArray($betaRange);
        for ($firstIndex = 0; $firstIndex <= 20; ++$firstIndex) {
            $first = 0.2 + (2.8 * $firstIndex / 20.0);
            for ($secondIndex = 0; $secondIndex <= 20; ++$secondIndex) {
                $second = 0.4 + (1.6 * $secondIndex / 20.0);
                $actual = Math::evaluate('beta(a, b)', ['a' => $first, 'b' => $second]);
                self::assertGreaterThanOrEqual($betaRange[0], $actual);
                self::assertLessThanOrEqual($betaRange[1], $actual);
            }
        }

        foreach ([0, 1, 2, 8] as $order) {
            $lower = 0.2;
            $upper = 4.0;
            $range = $rangeMethod->invoke(
                $solver,
                'polygamma',
                [[$order, $order], [$lower, $upper]],
                $options,
            );
            self::assertIsArray($range, 'polygamma order ' . $order);
            for ($index = 0; $index <= 100; ++$index) {
                $value = $lower + (($upper - $lower) * $index / 100.0);
                $actual = Math::evaluate('polygamma(' . $order . ', x)', ['x' => $value]);
                self::assertGreaterThanOrEqual($range[0], $actual, 'polygamma order ' . $order);
                self::assertLessThanOrEqual($range[1], $actual, 'polygamma order ' . $order);
            }
        }

        foreach ([[-10.0, 10.0], [-5.0, -4.0], [0.2, 0.21], [0.9, 1.0], [4.0, 5.0]] as [$lower, $upper]) {
            $range = $rangeMethod->invoke($solver, 'dawson', [[$lower, $upper]], $options);
            self::assertIsArray($range);
            for ($index = 0; $index <= 50; ++$index) {
                $value = $lower + (($upper - $lower) * $index / 50.0);
                $actual = Math::evaluate('dawson(x)', ['x' => $value]);
                self::assertGreaterThanOrEqual($range[0], $actual);
                self::assertLessThanOrEqual($range[1], $actual);
            }
        }
        $localDawsonRange = $rangeMethod->invoke($solver, 'dawson', [[0.2, 0.21]], $options);
        if (
            !\is_array($localDawsonRange)
            || \count($localDawsonRange) !== 2
            || !\is_float($localDawsonRange[0])
            || !\is_float($localDawsonRange[1])
        ) {
            self::fail('Expected a two-bound local Dawson enclosure.');
        }
        self::assertLessThan(1.0, $localDawsonRange[1] - $localDawsonRange[0]);

        foreach (
            [
                ['digamma', [[-0.1, 0.1]]],
                ['trigamma', [[-1.1, -0.9]]],
                ['tetragamma', [[-2.1, -1.9]]],
                ['lgamma', [[-0.1, 0.1]]],
                ['zeta', [[1.0, 2.0]]],
                ['beta', [[-0.1, 1.0], [0.2, 2.0]]],
                ['polygamma', [[1.0, 2.0], [1.0, 2.0]]],
            ] as [$name, $arguments]
        ) {
            self::assertNull($rangeMethod->invoke($solver, $name, $arguments, $options));
        }
    }

    public function testRegularizedGammaAndBetaIntervalEnclosuresContainGridSamples(): void
    {
        $solver = new EquationSolver();
        $rangeMethod = new \ReflectionMethod($solver, 'builtInIntervalRange');
        $rangeMethod->setAccessible(true);
        $options = new EvaluationOptions();
        $cases = [
            'gammainc' => [[0.2, 4.0], [0.1, 9.0]],
            'gammaincc' => [[0.2, 4.0], [0.1, 9.0]],
            'gammaincinv' => [[0.2, 4.0], [0.01, 0.99]],
            'gammainccinv' => [[0.2, 4.0], [0.01, 0.99]],
            'betainc' => [[0.2, 4.0], [0.3, 3.0], [0.05, 0.95]],
            'betaincc' => [[0.2, 4.0], [0.3, 3.0], [0.05, 0.95]],
            'betaincinv' => [[0.2, 4.0], [0.3, 3.0], [0.01, 0.99]],
            'betainccinv' => [[0.2, 4.0], [0.3, 3.0], [0.01, 0.99]],
        ];

        foreach ($cases as $name => $argumentRanges) {
            $range = $rangeMethod->invoke($solver, $name, $argumentRanges, $options);
            if (
                !\is_array($range)
                || \count($range) !== 2
                || !\is_float($range[0])
                || !\is_float($range[1])
            ) {
                self::fail('Expected a two-bound interval enclosure for ' . $name . '.');
            }
            $variableNames = ['a', 'b', 'x'];
            $expression = $name . '(' . \implode(', ', \array_slice($variableNames, 0, \count($argumentRanges))) . ')';
            $lastThirdIndex = \count($argumentRanges) === 3 ? 4 : 0;
            for ($firstIndex = 0; $firstIndex <= 4; ++$firstIndex) {
                for ($secondIndex = 0; $secondIndex <= 4; ++$secondIndex) {
                    for ($thirdIndex = 0; $thirdIndex <= $lastThirdIndex; ++$thirdIndex) {
                        $sampleIndices = [$firstIndex, $secondIndex, $thirdIndex];
                        $variables = [];
                        foreach ($argumentRanges as $argumentIndex => [$lower, $upper]) {
                            $variables[$variableNames[$argumentIndex]] = $lower
                                + (($upper - $lower) * $sampleIndices[$argumentIndex] / 4.0);
                        }
                        $actual = Math::evaluate($expression, $variables);
                        self::assertGreaterThanOrEqual($range[0], $actual, $expression);
                        self::assertLessThanOrEqual($range[1], $actual, $expression);
                    }
                }
            }
        }
    }

    public function testSpecialFunctionIntervalsCertifyClusteredCustomFunctionRoots(): void
    {
        $centers = [1.2, 1.35, 1.65, 1.8];
        $cluster = new FunctionDefinition(
            'polygammaRootCluster',
            1,
            1,
            static function (array $arguments) use ($centers): float {
                $product = 100.0;
                foreach ($centers as $center) {
                    $product *= $arguments[0] - $center;
                }

                return $product;
            },
            range: static function (array $arguments) use ($centers): array {
                [$lower, $upper] = $arguments[0];
                $product = [100.0, 100.0];
                foreach ($centers as $center) {
                    $factor = [$lower - $center, $upper - $center];
                    $products = [
                        $product[0] * $factor[0],
                        $product[0] * $factor[1],
                        $product[1] * $factor[0],
                        $product[1] * $factor[1],
                    ];
                    $product = [\min(...$products), \max(...$products)];
                }

                return $product;
            },
        );
        $options = new EvaluationOptions(
            functions: FunctionRegistry::defaults()->with($cluster),
        );
        $target = (0.000001 * SpecialFunctions::digamma(1.5))
            + (0.0000001 * Math::evaluate('zeta(1.5)'))
            + (0.0000001 * Math::evaluate('beta(1.5, 2)'))
            + (0.0000001 * Math::evaluate('dawson(1.5)'));
        $solutions = Math::solve(
            'polygammaRootCluster(x) + 0.000001 * digamma(x) + 0.0000001 * zeta(x) '
                . '+ 0.0000001 * beta(x, 2) + 0.0000001 * dawson(x) = '
                . \sprintf('%.17g', $target),
            'x',
            1.05,
            2.0,
            evaluationOptions: $options,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(4, $solutions);
        foreach ($centers as $index => $center) {
            self::assertEqualsWithDelta($center, $solutions[$index]->value, 1.0E-5);
            self::assertLessThanOrEqual(1.0E-10, $solutions[$index]->residual);
        }
    }

    public function testPositiveBaseVariablePowerIntervalsCertifyClusteredRoots(): void
    {
        $options = new EvaluationOptions();
        $solver = new EquationSolver();
        $powerMethod = new \ReflectionMethod($solver, 'powerInterval');
        $powerMethod->setAccessible(true);
        foreach (
            [
                [[0.1, 2.0], [-3.0, 4.0]],
                [[0.2, 0.8], [-2.0, 2.0]],
                [[1.0, 3.0], [-4.0, -0.5]],
            ] as [$baseRange, $exponentRange]
        ) {
            $powerRange = $powerMethod->invoke($solver, $baseRange, $exponentRange);
            self::assertIsArray($powerRange);
            for ($baseIndex = 0; $baseIndex <= 20; ++$baseIndex) {
                $base = $baseRange[0]
                    + (($baseRange[1] - $baseRange[0]) * $baseIndex / 20.0);
                for ($exponentIndex = 0; $exponentIndex <= 20; ++$exponentIndex) {
                    $exponent = $exponentRange[0]
                        + (($exponentRange[1] - $exponentRange[0]) * $exponentIndex / 20.0);
                    $actual = $base ** $exponent;
                    self::assertGreaterThanOrEqual($powerRange[0], $actual);
                    self::assertLessThanOrEqual($powerRange[1], $actual);
                }
            }
        }

        $expression = 'x^x';
        $node = (new Parser(
            (new Lexer($expression, $options->limits))->tokenize(),
            $options->limits,
        ))->parse();
        $rangeMethod = new \ReflectionMethod($solver, 'evaluateIntervalExpression');
        $rangeMethod->setAccessible(true);
        $range = $rangeMethod->invoke($solver, $node, 'x', 0.2, 3.0, [], $options);
        self::assertIsArray($range);
        for ($index = 0; $index <= 100; ++$index) {
            $value = 0.2 + (2.8 * $index / 100.0);
            $actual = $value ** $value;
            self::assertGreaterThanOrEqual($range[0], $actual);
            self::assertLessThanOrEqual($range[1], $actual);
        }
        self::assertNull($rangeMethod->invoke($solver, $node, 'x', -1.0, 1.0, [], $options));

        $centers = [0.6, 0.8, 1.2, 1.4];
        $cluster = new FunctionDefinition(
            'variablePowerRootCluster',
            1,
            1,
            static function (array $arguments) use ($centers): float {
                $product = 100.0;
                foreach ($centers as $center) {
                    $product *= $arguments[0] - $center;
                }

                return $product;
            },
            range: static function (array $arguments) use ($centers): array {
                [$lower, $upper] = $arguments[0];
                $product = [100.0, 100.0];
                foreach ($centers as $center) {
                    $factor = [$lower - $center, $upper - $center];
                    $products = [
                        $product[0] * $factor[0],
                        $product[0] * $factor[1],
                        $product[1] * $factor[0],
                        $product[1] * $factor[1],
                    ];
                    $product = [\min(...$products), \max(...$products)];
                }

                return $product;
            },
        );
        $solutions = Math::solve(
            'variablePowerRootCluster(x) + 0.000001 * x^x = 0.000001',
            'x',
            0.5,
            1.5,
            evaluationOptions: new EvaluationOptions(
                functions: FunctionRegistry::defaults()->with($cluster),
            ),
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(4, $solutions);
        foreach ($centers as $index => $center) {
            self::assertEqualsWithDelta($center, $solutions[$index]->value, 1.0E-5);
            self::assertLessThanOrEqual(1.0E-10, $solutions[$index]->residual);
        }
    }

    public function testGammaIntervalIsolationDoesNotInventNearbyRootAtExactFlatExtremum(): void
    {
        $lower = -2.9;
        $upper = -2.5;
        for ($iteration = 0; $iteration < 100; ++$iteration) {
            $middle = $lower + (($upper - $lower) / 2.0);
            if (SpecialFunctions::digamma($lower) * SpecialFunctions::digamma($middle) <= 0.0) {
                $upper = $middle;
            } else {
                $lower = $middle;
            }
        }
        $criticalPoint = $lower + (($upper - $lower) / 2.0);
        $gamma = FunctionRegistry::defaults()->find('gamma');
        self::assertNotNull($gamma);
        $target = $gamma->invoke([$criticalPoint]);
        $phase = new FunctionDefinition(
            'negativeExtremumPhase',
            1,
            1,
            static fn (array $arguments): float => $criticalPoint + (0.05 * ($arguments[0] + 0.5)),
            range: static fn (array $arguments): array => [
                $criticalPoint + (0.05 * ($arguments[0][0] + 0.5)),
                $criticalPoint + (0.05 * ($arguments[0][1] + 0.5)),
            ],
        );

        $solutions = Math::solve(
            'gamma(negativeExtremumPhase(x)) = ' . \sprintf('%.17g', $target),
            'x',
            -1.0,
            1.0,
            evaluationOptions: new EvaluationOptions(
                functions: FunctionRegistry::defaults()->with($phase),
            ),
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(1, $solutions);
        self::assertSame(-0.5, $solutions[0]->value);
        foreach ($solutions as $solution) {
            self::assertSame(0.0, $solution->residual);
        }
    }

    public function testGammaIntervalEnclosuresFindClusteredRootsHiddenFromSampling(): void
    {
        $centers = [-0.30, -0.28, -0.26, -0.24];
        $cluster = new FunctionDefinition(
            'rootCluster',
            1,
            1,
            static function (array $arguments) use ($centers): float {
                $product = 1.0;
                foreach ($centers as $center) {
                    $product *= $arguments[0] - $center;
                }

                return 0.5 + $product;
            },
            range: static function (array $arguments) use ($centers): array {
                [$lower, $upper] = $arguments[0];
                if ($upper - $lower > 0.1) {
                    return [0.49, 4.5];
                }
                $product = [1.0, 1.0];
                foreach ($centers as $center) {
                    $factor = [$lower - $center, $upper - $center];
                    $products = [
                        $product[0] * $factor[0],
                        $product[0] * $factor[1],
                        $product[1] * $factor[0],
                        $product[1] * $factor[1],
                    ];
                    $product = [\min(...$products), \max(...$products)];
                }

                return [0.5 + $product[0], 0.5 + $product[1]];
            },
        );
        $solutions = Math::solve(
            'gamma(rootCluster(x)) + sin(x) * 0.000001 = gamma(0.5)',
            'x',
            -0.875,
            1.125,
            evaluationOptions: new EvaluationOptions(
                functions: FunctionRegistry::defaults()->with($cluster),
            ),
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(5, $solutions);
        foreach (
            [
                -0.29784058535,
                -0.28477985539,
                -0.25569998455,
                -0.24167962087,
                0.97032422660,
            ] as $index => $expected
        ) {
            self::assertEqualsWithDelta($expected, $solutions[$index]->value, 1.0E-7);
            self::assertLessThanOrEqual(1.0E-9, $solutions[$index]->residual);
        }

        $negativeCluster = new FunctionDefinition(
            'negativeRootCluster',
            1,
            1,
            static function (array $arguments) use ($centers): float {
                $product = 1.0;
                foreach ($centers as $center) {
                    $product *= $arguments[0] - $center;
                }

                return -1.3 + (0.8 * $product);
            },
            range: static function (array $arguments) use ($centers): array {
                [$lower, $upper] = $arguments[0];
                if ($upper - $lower > 0.1) {
                    return [-1.4, -1.01];
                }
                $product = [1.0, 1.0];
                foreach ($centers as $center) {
                    $factor = [$lower - $center, $upper - $center];
                    $products = [
                        $product[0] * $factor[0],
                        $product[0] * $factor[1],
                        $product[1] * $factor[0],
                        $product[1] * $factor[1],
                    ];
                    $product = [\min(...$products), \max(...$products)];
                }

                return [
                    -1.3 + (0.8 * $product[0]),
                    -1.3 + (0.8 * $product[1]),
                ];
            },
        );
        $negativeSolutions = Math::solve(
            'gamma(negativeRootCluster(x)) + sin(x) * 0.000000001 = gamma(-1.3)',
            'x',
            -0.5,
            0.5,
            evaluationOptions: new EvaluationOptions(
                functions: FunctionRegistry::defaults()->with($negativeCluster),
            ),
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(4, $negativeSolutions);
        foreach (
            [
                -0.30000080206,
                -0.27999774952,
                -0.26000209354,
                -0.23999935482,
            ] as $index => $expected
        ) {
            self::assertEqualsWithDelta($expected, $negativeSolutions[$index]->value, 1.0E-7);
            self::assertLessThanOrEqual(1.0E-9, $negativeSolutions[$index]->residual);
        }
    }

    public function testGcdPairsTwoCustomIntervalBackedIntegerPreimages(): void
