    public function testCustomGradientFindsVeryFlatOffGridRoots(): void
    {
        $center = 0.123456789;
        foreach ([4, 8, 12, 20] as $degree) {
            $function = new FunctionDefinition(
                'flatroot',
                1,
                1,
                static fn (array $arguments): float => ($arguments[0] - $center) ** $degree,
                static fn (array $arguments): array => [
                    $degree * (($arguments[0] - $center) ** ($degree - 1)),
                ],
                range: static function (array $arguments) use ($center, $degree): array {
                    [$lower, $upper] = $arguments[0];
                    $left = \abs($lower - $center) ** $degree;
                    $right = \abs($upper - $center) ** $degree;
                    $minimum = $lower <= $center && $center <= $upper ? 0.0 : \min($left, $right);

                    return [$minimum, \max($left, $right)];
                },
            );
            $solutions = Math::solve(
                'flatroot(x) = 0',
                'x',
                0.0,
                1.0,
                evaluationOptions: new EvaluationOptions(
                    functions: FunctionRegistry::defaults()->with($function),
                ),
                solverOptions: new SolverOptions(scanSteps: 1),
            );

            self::assertCount(1, $solutions, 'multiplicity=' . $degree);
            self::assertEqualsWithDelta($center, $solutions[0]->value, 1.0E-8);
            self::assertLessThanOrEqual(1.0E-15, $solutions[0]->residual);
        }
    }

    public function testCustomGradientDoesNotCertifyAFlatPositiveMinimumAsRootFree(): void
    {
        $center = 0.123456789;
        $minimum = 1.0E-8;
        $function = new FunctionDefinition(
            'flatpositive',
            1,
            1,
            static fn (array $arguments): float => (($arguments[0] - $center) ** 8) + $minimum,
            static fn (array $arguments): array => [
                8.0 * (($arguments[0] - $center) ** 7),
            ],
        );

        try {
            Math::solve(
                'flatpositive(x) = 0',
                'x',
                0.0,
                1.0,
                evaluationOptions: new EvaluationOptions(
                    functions: FunctionRegistry::defaults()->with($function),
                ),
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::fail('A custom gradient alone cannot certify that the interval contains no root.');
        } catch (RootSearchLimitException $exception) {
            self::assertStringContainsString('cannot certify', $exception->getMessage());
        }
    }

