    public function testCustomFunctionGradientFeedsStationaryPointIsolation(): void
    {
        $product = new FunctionDefinition(
            'product',
            2,
            2,
            static fn (array $arguments): float => $arguments[0] * $arguments[1],
            static fn (array $arguments): array => [$arguments[1], $arguments[0]],
            range: static function (array $arguments): array {
                [$firstLower, $firstUpper] = $arguments[0];
                [$secondLower, $secondUpper] = $arguments[1];
                $products = [
                    $firstLower * $secondLower,
                    $firstLower * $secondUpper,
                    $firstUpper * $secondLower,
                    $firstUpper * $secondUpper,
                ];

                return [\min(...$products), \max(...$products)];
            },
        );
        $solutions = Math::solve(
            'product(x^2, 1) = 0.25',
