        }
    }

    public function testCustomFunctionDomainTransitionFindsNearBoundaryRoot(): void
    {
        $rightDomain = new FunctionDefinition(
            'rightdomain',
            1,
            1,
            static function (array $arguments): float {
                if ($arguments[0] <= 0.123) {
                    throw new FunctionDomainException('outside domain');
                }

                return $arguments[0] - 0.123;
            },
        );
        try {
            Math::solve(
                'rightdomain(x) = 0.000001',
                'x',
                0.0,
                1.0,
                evaluationOptions: new EvaluationOptions(
                    functions: FunctionRegistry::defaults()->with($rightDomain),
                ),
            );
            self::fail('A callback without interval bounds cannot certify a complete root list.');
        } catch (RootSearchLimitException $exception) {
            self::assertStringContainsString('cannot certify', $exception->getMessage());
        }
    }

    public function testRootBracketCanRecoverAcrossNarrowCustomFunctionDomainHole(): void
    {
        $holeCenter = 32.0 / 256.0 - (1.0 / 512.0);
        $function = new FunctionDefinition(
            'holelinear',
            1,
            1,
            static function (array $arguments) use ($holeCenter): float {
                if (\abs($arguments[0] - $holeCenter) < 1.0E-6) {
                    throw new FunctionDomainException('inside a narrow domain hole');
                }

                return $arguments[0] - $holeCenter;
            },
        );
        try {
            Math::solve(
                'holelinear(x) = 0.00005',
                'x',
                0.0,
                1.0,
                evaluationOptions: new EvaluationOptions(
                    functions: FunctionRegistry::defaults()->with($function),
                ),
            );
            self::fail('A callback without interval bounds cannot certify a complete root list.');
        } catch (RootSearchLimitException $exception) {
            self::assertStringContainsString('cannot certify', $exception->getMessage());
        }
    }

    public function testRootBracketRecoversRootsOnBothSidesOfCustomFunctionDomainHole(): void
    {
        $holeCenter = 31.5 / 256.0;
        $leftRoot = $holeCenter - 0.0002;
        $rightRoot = $holeCenter + 0.0002;
        $function = new FunctionDefinition(
            'splitdomain',
            1,
            1,
            static function (array $arguments) use ($holeCenter, $leftRoot, $rightRoot): float {
                if (\abs($arguments[0] - $holeCenter) < 1.0E-6) {
                    throw new FunctionDomainException('inside a narrow domain hole');
                }

                return $arguments[0] < $holeCenter
                    ? $leftRoot - $arguments[0]
                    : $rightRoot - $arguments[0];
            },
        );
        try {
            Math::solve(
                'splitdomain(x) = 0',
                'x',
                0.0,
                1.0,
                evaluationOptions: new EvaluationOptions(
                    functions: FunctionRegistry::defaults()->with($function),
                ),
            );
            self::fail('A callback without interval bounds cannot certify a complete root list.');
        } catch (RootSearchLimitException $exception) {
            self::assertStringContainsString('cannot certify', $exception->getMessage());
        }
    }

