    public function testFiniteIntegerOrderBesselJLevelsUseMonotonePhaseSegments(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $constantExpressionTarget = Math::solve(
            'besselj(0, x) = besselj(0, 1)',
            'x',
            -1.5,
            1.5,
            solverOptions: $options,
        );
        self::assertCount(2, $constantExpressionTarget);
        self::assertEqualsWithDelta(-1.0, $constantExpressionTarget[0]->value, 1.0E-9);
        self::assertEqualsWithDelta(1.0, $constantExpressionTarget[1]->value, 1.0E-9);

        $reversedConstantExpressionTarget = Math::solve(
            'besselj(0, 1) = besselj(0, x)',
            'x',
            -1.5,
            1.5,
            solverOptions: $options,
        );
        self::assertCount(2, $reversedConstantExpressionTarget);
        self::assertEqualsWithDelta(-1.0, $reversedConstantExpressionTarget[0]->value, 1.0E-9);
        self::assertEqualsWithDelta(1.0, $reversedConstantExpressionTarget[1]->value, 1.0E-9);

        foreach (
            [
                ['besselj(0, x) = besselj(0, a)', ['a' => 1]],
                ['besselj(0, x) = 2 * besselj(0, 1) - besselj(0, 1)', []],
            ] as [$equation, $parameters]
        ) {
            $parameterizedTarget = Math::solve(
                $equation,
                'x',
                -1.5,
                1.5,
                $parameters,
                solverOptions: $options,
            );
            self::assertCount(2, $parameterizedTarget, $equation);
            self::assertEqualsWithDelta(-1.0, $parameterizedTarget[0]->value, 1.0E-9, $equation);
            self::assertEqualsWithDelta(1.0, $parameterizedTarget[1]->value, 1.0E-9, $equation);
            foreach ($parameterizedTarget as $solution) {
                self::assertLessThanOrEqual(1.0E-9, $solution->residual, $equation);
            }
        }

        $solutions = Math::solve('besselj(0, x) = 0.5', 'x', -3.0, 3.0, solverOptions: $options);

        self::assertCount(2, $solutions);
        self::assertEqualsWithDelta(-1.521144057668765, $solutions[0]->value, 1.0E-9);
        self::assertEqualsWithDelta(1.521144057668765, $solutions[1]->value, 1.0E-9);
        foreach ($solutions as $solution) {
            self::assertLessThanOrEqual(1.0E-10, $solution->residual);
        }

        $translated = Math::solve(
            '0.5 = besselj(0, 2*x - 2)',
            'x',
            -0.5,
            2.0,
            solverOptions: $options,
        );
        self::assertCount(2, $translated);
        self::assertEqualsWithDelta(0.2394279711656175, $translated[0]->value, 1.0E-9);
        self::assertEqualsWithDelta(1.7605720288343825, $translated[1]->value, 1.0E-9);

        $quadraticPhase = Math::solve(
            'besselj(0, x^2) = 0.5',
            'x',
            -1.5,
            1.5,
            solverOptions: $options,
        );
        self::assertCount(2, $quadraticPhase);
        self::assertEqualsWithDelta(-1.233346689973571, $quadraticPhase[0]->value, 1.0E-9);
        self::assertEqualsWithDelta(1.233346689973571, $quadraticPhase[1]->value, 1.0E-9);

        $cubicPhase = Math::solve(
            'besselj(0, x^3) = 0.5',
            'x',
            -1.3,
            1.3,
            solverOptions: $options,
        );
        self::assertCount(2, $cubicPhase);
        self::assertEqualsWithDelta(-1.150067811418781, $cubicPhase[0]->value, 1.0E-9);
        self::assertEqualsWithDelta(1.150067811418781, $cubicPhase[1]->value, 1.0E-9);

        $highPhaseTarget = \sprintf('%.17g', SpecialFunctions::besselJ(0, 3.5));
        $highPhase = Math::solve(
            'besselj(0, x) = ' . $highPhaseTarget,
            'x',
            -3.8,
            3.8,
            solverOptions: $options,
        );
        self::assertCount(2, $highPhase);
        self::assertEqualsWithDelta(-3.5, $highPhase[0]->value, 1.0E-9);
        self::assertEqualsWithDelta(3.5, $highPhase[1]->value, 1.0E-9);

        $firstOrder = Math::solve(
            'besselj(1, x) = 0.2',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        self::assertCount(1, $firstOrder);
        self::assertEqualsWithDelta(0.4084593602576767, $firstOrder[0]->value, 1.0E-10);

        $negativeFirstOrder = Math::solve(
            'besselj(-1, x) = 0.2',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        self::assertCount(1, $negativeFirstOrder);
        self::assertEqualsWithDelta(-0.4084593602576767, $negativeFirstOrder[0]->value, 1.0E-10);

        $firstOrderHighLevel = \sprintf('%.17g', SpecialFunctions::besselJ(1, 1.5));
        $firstOrderHighArgument = Math::solve(
            'besselj(1, x) = ' . $firstOrderHighLevel,
            'x',
            -1.6,
            1.6,
            solverOptions: $options,
        );
        self::assertCount(1, $firstOrderHighArgument);
        self::assertEqualsWithDelta(1.5, $firstOrderHighArgument[0]->value, 1.0E-10);

        $secondOrderHighLevel = \sprintf('%.17g', SpecialFunctions::besselJ(2, 2.3));
        $secondOrderHighArgument = Math::solve(
            'besselj(2, x) = ' . $secondOrderHighLevel,
            'x',
            -2.4,
            2.4,
            solverOptions: $options,
        );
        self::assertCount(2, $secondOrderHighArgument);
        self::assertEqualsWithDelta(-2.3, $secondOrderHighArgument[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(2.3, $secondOrderHighArgument[1]->value, 1.0E-10);

        $secondOrderLimit = 2.0 * \sqrt(1.5) * (1.0 - (16.0 * \PHP_FLOAT_EPSILON));
        $secondOrderBoundaryLevel = \sprintf(
            '%.17g',
            SpecialFunctions::besselJ(2, $secondOrderLimit),
        );
        $secondOrderBoundary = Math::solve(
            'besselj(2, x) = ' . $secondOrderBoundaryLevel,
            'x',
            -$secondOrderLimit,
            $secondOrderLimit,
            solverOptions: $options,
        );
        self::assertCount(2, $secondOrderBoundary);
        self::assertEqualsWithDelta(-$secondOrderLimit, $secondOrderBoundary[0]->value, 1.0E-12);
        self::assertEqualsWithDelta($secondOrderLimit, $secondOrderBoundary[1]->value, 1.0E-12);

        $maximumOrderLevel = \sprintf('%.17g', SpecialFunctions::besselJ(256, 20.0));
        $maximumOrderRoots = Math::solve(
            'besselj(256, x) = ' . $maximumOrderLevel,
            'x',
            -31.0,
            31.0,
            solverOptions: $options,
        );
        self::assertCount(2, $maximumOrderRoots);
        self::assertEqualsWithDelta(-20.0, $maximumOrderRoots[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(20.0, $maximumOrderRoots[1]->value, 1.0E-10);

        $secondOrderQuadraticPhase = Math::solve(
            'besselj(2, x^2) = 0.1',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        self::assertCount(2, $secondOrderQuadraticPhase);
        self::assertEqualsWithDelta(-0.962996439260317, $secondOrderQuadraticPhase[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(0.962996439260317, $secondOrderQuadraticPhase[1]->value, 1.0E-10);
        self::assertSame([], Math::solve('besselj(2, x) = -0.1', 'x', -1.0, 1.0, solverOptions: $options));

        self::assertSame([], Math::solve('besselj(0, x) = 1.1', 'x', -3.0, 3.0));
        $maximum = Math::solve('besselj(0, x^2) = 1', 'x', -0.5, 0.5, solverOptions: $options);
        self::assertCount(1, $maximum);
        self::assertSame(0.0, $maximum[0]->value);

        $oneArgumentLevel = \sprintf('%.17g', SpecialFunctions::besselJ(0, 1.0));
        $levelBoundary = Math::solve(
            'besselj(0, (x - 1)^2) = ' . $oneArgumentLevel,
            'x',
            0.0,
            2.0,
            solverOptions: $options,
        );
        self::assertCount(2, $levelBoundary);
        self::assertSame(0.0, $levelBoundary[0]->value);
        self::assertSame(2.0, $levelBoundary[1]->value);

        $repeatedPhaseRoot = Math::solve(
            'besselj(0, (x - 1)^2) = 1',
            'x',
            0.0,
            2.0,
            solverOptions: $options,
        );
        self::assertCount(1, $repeatedPhaseRoot);
        self::assertSame(1.0, $repeatedPhaseRoot[0]->value);
    }

