    public function testBesselJStationaryLevelRootIsStableAcrossScanGrids(): void
    {
        $lower = 3.8;
        $upper = 3.9;
        for ($iteration = 0; $iteration < 64; ++$iteration) {
            $midpoint = ($lower + $upper) / 2.0;
            if (SpecialFunctions::besselJ(1, $midpoint) > 0.0) {
                $lower = $midpoint;
            } else {
                $upper = $midpoint;
            }
        }
        $stationaryPoint = ($lower + $upper) / 2.0;
        $target = \sprintf('%.17g', SpecialFunctions::besselJ(0, $stationaryPoint));

        foreach ([1, 2, 8, 64, 1024] as $scanSteps) {
            $solutions = Math::solve(
                'besselj(0, x) = ' . $target,
                'x',
                0.0,
                8.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );

            self::assertCount(1, $solutions, 'scanSteps=' . $scanSteps);
            self::assertEqualsWithDelta(
                $stationaryPoint,
                $solutions[0]->value,
                1.0E-9,
                'scanSteps=' . $scanSteps,
            );
            self::assertLessThanOrEqual(1.0E-10, $solutions[0]->residual);
        }
    }

