    public function testOrderZeroBesselLevelsSupportPolynomialPhases(): void
    {
        $cases = [
            [
                'besselj(0, x^2) = 0',
                -4.0,
                4.0,
                [
                    -3.8640545685184,
                    -3.4338803763403,
                    -2.9417219299096,
                    -2.3494846478082,
                    -1.550749998451,
                    1.550749998451,
                    2.3494846478082,
                    2.9417219299096,
                    3.4338803763403,
                    3.8640545685184,
                ],
            ],
            [
                'bessely(0, x^2) = 0',
                -3.0,
                3.0,
                [
                    -2.6619637601406,
                    -1.9893914695994,
                    -0.94529200053696,
                    0.94529200053696,
                    1.9893914695994,
                    2.6619637601406,
                ],
            ],
        ];

        foreach ($cases as [$equation, $lowerBound, $upperBound, $expectedRoots]) {
            $solutions = Math::solve($equation, 'x', $lowerBound, $upperBound);

            self::assertCount(\count($expectedRoots), $solutions, $equation);
            foreach ($expectedRoots as $index => $expectedRoot) {
                self::assertEqualsWithDelta($expectedRoot, $solutions[$index]->value, 1.0E-9, $equation);
                self::assertLessThanOrEqual(1.0E-10, $solutions[$index]->residual, $equation);
            }
        }
    }

    public function testPolynomialTrigonometricFallbackReportsScanLimitInsteadOfPartialRoots(): void
    {
        try {
            Math::solve(
                'sin(1000000*x^2) + x = 0',
                'x',
                0.0,
                1.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::fail('A polynomial phase beyond the adaptive scan limit must be reported.');
        } catch (RootSearchLimitException $exception) {
            self::assertStringContainsString('trigonometric phase', $exception->getMessage());
        }
    }

