    public function testBesselFunctionsEnumerateVariableIntegerOrders(): void
    {
        $modifiedTarget = Math::evaluate('besseli(1, 1)');
        $modifiedTargetText = \sprintf('%.17g', $modifiedTarget);
        $modifiedRoots = Math::solve(
            'besseli(x^2, 1) = ' . $modifiedTargetText,
            'x',
            -2.0,
            2.0,
        );

        self::assertCount(2, $modifiedRoots);
        self::assertEqualsWithDelta(-1.0, $modifiedRoots[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(1.0, $modifiedRoots[1]->value, 1.0E-10);
        foreach ($modifiedRoots as $root) {
            self::assertLessThanOrEqual(1.0E-10, $root->residual);
        }

        $affineRoots = Math::solve(
            'besseli(2*x + 1, 1) = ' . $modifiedTargetText,
            'x',
            -2.0,
            2.0,
        );
        self::assertCount(2, $affineRoots);
        self::assertEqualsWithDelta(-1.0, $affineRoots[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(0.0, $affineRoots[1]->value, 1.0E-10);

        $besselJTarget = Math::evaluate('besselj(1, 1)');
        $besselJRoots = Math::solve(
            'besselj(x, 1) = ' . \sprintf('%.17g', $besselJTarget),
            'x',
            -2.0,
            2.0,
        );
        self::assertCount(1, $besselJRoots);
        self::assertEqualsWithDelta(1.0, $besselJRoots[0]->value, 1.0E-10);

        $polygammaTarget = (\M_PI ** 2) / 6.0;
        $polygammaRoots = Math::solve(
            'polygamma(x^2, 1) = ' . \sprintf('%.17g', $polygammaTarget),
            'x',
            -2.0,
            2.0,
        );
        self::assertCount(2, $polygammaRoots);
        self::assertEqualsWithDelta(-1.0, $polygammaRoots[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(1.0, $polygammaRoots[1]->value, 1.0E-10);
    }

