    public function testIntegerFunctionArgumentsUseRecursiveNonPolynomialLevels(): void
    {
        $modifiedTarget = \sprintf('%.17g', Math::evaluate('besseli(1, 1)'));
        $modifiedRoots = Math::solve(
            'besseli(sin(x), 1) = ' . $modifiedTarget,
            'x',
            -5.0,
            5.0,
        );
        $modifiedValues = \array_map(
            static fn (EquationSolution $solution): float => $solution->value,
            $modifiedRoots,
        );
        \sort($modifiedValues);
        self::assertCount(4, $modifiedValues);
        foreach ([-(3.0 * \M_PI / 2.0), -\M_PI / 2.0, \M_PI / 2.0, 3.0 * \M_PI / 2.0] as $index => $expected) {
            self::assertEqualsWithDelta($expected, $modifiedValues[$index], 1.0E-10);
        }

        $lowerBranchTarget = \sprintf('%.17g', Math::evaluate('lambertw(-0.1, -1)'));
        $branchRoots = Math::solve(
            'lambertw(-0.1, sin(x)) = ' . $lowerBranchTarget,
            'x',
            -5.0,
            5.0,
        );
        self::assertCount(2, $branchRoots);
        self::assertEqualsWithDelta(-\M_PI / 2.0, $branchRoots[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(3.0 * \M_PI / 2.0, $branchRoots[1]->value, 1.0E-10);

        $polygammaRoots = Math::solve(
            'polygamma(abs(x), 1) = ' . \sprintf('%.17g', (\M_PI ** 2) / 6.0),
            'x',
            -2.0,
            2.0,
        );
        self::assertCount(2, $polygammaRoots);
        self::assertEqualsWithDelta(-1.0, $polygammaRoots[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(1.0, $polygammaRoots[1]->value, 1.0E-10);
    }

