    public function testNearTangentCrossingsDoNotAddTheirCriticalPointAsAThirdRoot(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $detected = 0;
        $nearTangentRoots = Math::solve(
            'x^x = 0.6922006276',
            'x',
            0.000001,
            1.0,
            solverOptions: $options,
        );
        $tangentRoot = Math::solve(
            'x^x = exp(-1/e)',
            'x',
            0.000001,
            1.0,
            solverOptions: $options,
        );
        $closeRoots = Math::solve(
            'exp(x) - x = 1 + 1e-15',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $roundoffCloseRoots = Math::solve(
            'exp(x) - x = 1 + 1e-14',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $belowTangentLevel = Math::solve(
            'exp(x) - x = 1 - 1e-12',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1, residualTolerance: 1.0E-12),
        );
        $sampledNearMinimum = Math::solve(
            'exp(x - 1e-5) = x - 1e-5 + 1 - 1e-12',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 256),
        );

        self::assertCount(2, $nearTangentRoots);
        self::assertLessThan($nearTangentRoots[1]->value, $nearTangentRoots[0]->value);
        foreach ($nearTangentRoots as $root) {
            self::assertLessThanOrEqual(1.0E-10, $root->residual);
        }
        self::assertCount(1, $tangentRoot);
        self::assertEqualsWithDelta(1.0 / \M_E, $tangentRoot[0]->value, 1.0E-8);
        self::assertCount(2, $closeRoots);
        self::assertLessThan(0.0, $closeRoots[0]->value);
        self::assertGreaterThan(0.0, $closeRoots[1]->value);
        foreach ($closeRoots as $root) {
            self::assertLessThan(1.0E-7, \abs($root->value));
            self::assertLessThanOrEqual(1.0E-10, $root->residual);
        }
        self::assertCount(2, $roundoffCloseRoots);
        self::assertLessThan(0.0, $roundoffCloseRoots[0]->value);
        self::assertGreaterThan(0.0, $roundoffCloseRoots[1]->value);
        foreach ($roundoffCloseRoots as $root) {
            self::assertLessThanOrEqual(1.0E-10, $root->residual);
        }
        self::assertSame([], $belowTangentLevel);
        self::assertSame([], $sampledNearMinimum);
    }

    public function testAffineExponentialMinusIdentityFindsBothNearTangentRoots(): void
    {
        foreach (
            [
                ['exp(2*x + 1) - (2*x + 1) = 1 + 1e-12', -2.0, 1.0, 2],
                ['1 + 1e-12 = exp(2*x + 1) - (2*x + 1)', -2.0, 1.0, 2],
                ['2*exp(x) - 2*x = 2*(1 + 1e-12)', -2.0, 2.0, 2],
                ['-2*exp(x) + 2*x = -2*(1 + 1e-12)', -2.0, 2.0, 2],
                ['exp(x) - 2*x = 2*(1 - ln(2)) + 1e-12', -2.0, 3.0, 2],
                ['exp(x) - 2*x = 2*(1 - ln(2))', -2.0, 3.0, 1],
                ['exp(x) - 2*x = 0.5', -2.0, 3.0, 0],
                ['exp(x) + x = 0', -5.0, 5.0, 1],
                ['exp(x) - x = 2', -\INF, \INF, 2],
                ['exp(x) + x = 0', -\INF, \INF, 1],
                ['exp(x) + 2*x = 0', -5.0, 5.0, 1],
                ['exp(x) + x = 3', -5.0, 5.0, 1],
                ['exp(x) = 2', -5.0, 5.0, 1],
                ['exp(2*x + 1) = 2', -5.0, 5.0, 1],
                ['exp(x) = 0', -5.0, 5.0, 0],
                ['exp(x) = -2', -5.0, 5.0, 0],
                ['exp(x) + x = 0', 0.0, 5.0, 0],
                ['exp(-3*x + 0.2) - (-3*x + 0.2) = 1.1', -0.1, 0.0, 1],
                ['exp(2*x + 1) - (2*x + 1) = 1 + 1e-12', -0.5, -0.49, 1],
            ] as [$equation, $lowerBound, $upperBound, $rootCount]
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                $lowerBound,
                $upperBound,
                solverOptions: new SolverOptions(scanSteps: 1),
            );

            self::assertCount($rootCount, $solutions, $equation);
            if ($rootCount === 2) {
                self::assertLessThan($solutions[1]->value, $solutions[0]->value, $equation);
            }
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-10, $solution->residual, $equation);
            }
        }

    }

    public function testSelfPowerLevelsAboveMinimumRetainBothNearbyRoots(): void
    {
        $tangentPoint = 1.0 / \M_E;
        $rationalTangentPoint = 1.0 / (\M_E - 1.0);
        foreach (['0.6922006275553465', '0.69220062755534695'] as $target) {
            $solutions = Math::solve(
                'x^x = ' . $target,
                'x',
                0.1,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );

            self::assertCount(2, $solutions, $target);
            self::assertLessThan($tangentPoint, $solutions[0]->value, $target);
            self::assertGreaterThan($tangentPoint, $solutions[1]->value, $target);
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-12, $solution->residual, $target);
            }

            $rationalSolutions = Math::solve(
                '(x/(x+1))^(x/(x+1)) = ' . $target,
                'x',
                0.1,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertCount(2, $rationalSolutions, $target);
            self::assertLessThan($rationalTangentPoint, $rationalSolutions[0]->value, $target);
            self::assertGreaterThan($rationalTangentPoint, $rationalSolutions[1]->value, $target);
        }

        foreach (
            [
                ['(x/(x+1))^(2*x/(x+1)) = 0.47914170878801538', $rationalTangentPoint],
                ['(x/(x+1))^(-2*x/(x+1)) = 2.0870652286345326', $rationalTangentPoint],
                ['x^(2*x) = 0.47914170878801538', $tangentPoint],
                ['exp(2*x*ln(x)) = 0.47914170878801538', $tangentPoint],
                ['x^(-2*x) = 2.0870652286345326', $tangentPoint],
            ] as [$equation, $center]
        ) {
            $scaledSolutions = Math::solve(
                $equation,
                'x',
                0.1,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertCount(2, $scaledSolutions, $equation);
            self::assertLessThan($center, $scaledSolutions[0]->value, $equation);
            self::assertGreaterThan($center, $scaledSolutions[1]->value, $equation);
        }

        $tangent = Math::solve(
            'x^x = exp(-1/e)',
            'x',
            0.1,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $tangent);
        self::assertEqualsWithDelta($tangentPoint, $tangent[0]->value, 1.0E-12);

        $rationalTangent = Math::solve(
            '(x/(x+1))^(x/(x+1)) = exp(-1/e)',
            'x',
            0.1,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $rationalTangent);
        self::assertEqualsWithDelta($rationalTangentPoint, $rationalTangent[0]->value, 1.0E-12);

        foreach (['x^(2*x) = exp(-2/e)', 'x^(-2*x) = exp(2/e)'] as $equation) {
            $scaledTangent = Math::solve(
                $equation,
                'x',
                0.1,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertCount(1, $scaledTangent, $equation);
            self::assertEqualsWithDelta($tangentPoint, $scaledTangent[0]->value, 1.0E-12);
        }
    }

