        self::assertCount(1, $negativeUnitRoot);
        self::assertEqualsWithDelta(-1.0, $negativeUnitRoot[0]->value, 1.0E-8);
        self::assertCount(2, $zeroAndOne);
        self::assertSame(0.0, $zeroAndOne[0]->value);
        self::assertEqualsWithDelta(1.0, $zeroAndOne[1]->value, 1.0E-8);
