    public function testSelfPowerTangenciesKeepBothPolynomialPreimages(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $equation = '(x^2 + 0.1)^(x^2 + 0.1) = exp(-1/e)';
        $bothRoots = Math::solve($equation, 'x', -1.0, 1.0, solverOptions: $options);
        $negativeRoot = Math::solve($equation, 'x', -1.0, 0.0, solverOptions: $options);
        $positiveRoot = Math::solve($equation, 'x', 0.0, 1.0, solverOptions: $options);
        $scaledExponentialRoots = Math::solve(
            'exp(3*(x^2 + 0.1)*ln(x^2 + 0.1)) = exp(-3/e)',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        $dividedExponentialRoots = Math::solve(
            'exp(((x^2 + 0.1)*ln(x^2 + 0.1))/2) = exp(-1/(2*e))',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        $expectedMagnitude = \sqrt((1.0 / \M_E) - 0.1);

        self::assertCount(2, $bothRoots);
        self::assertEqualsWithDelta(-$expectedMagnitude, $bothRoots[0]->value, 1.0E-8);
        self::assertEqualsWithDelta($expectedMagnitude, $bothRoots[1]->value, 1.0E-8);
        self::assertCount(1, $negativeRoot);
        self::assertEqualsWithDelta(-$expectedMagnitude, $negativeRoot[0]->value, 1.0E-8);
        self::assertCount(1, $positiveRoot);
        self::assertEqualsWithDelta($expectedMagnitude, $positiveRoot[0]->value, 1.0E-8);
        self::assertCount(2, $scaledExponentialRoots);
        self::assertEqualsWithDelta(-$expectedMagnitude, $scaledExponentialRoots[0]->value, 1.0E-8);
        self::assertEqualsWithDelta($expectedMagnitude, $scaledExponentialRoots[1]->value, 1.0E-8);
        self::assertCount(2, $dividedExponentialRoots);
        self::assertEqualsWithDelta(-$expectedMagnitude, $dividedExponentialRoots[0]->value, 1.0E-8);
        self::assertEqualsWithDelta($expectedMagnitude, $dividedExponentialRoots[1]->value, 1.0E-8);
    }

    public function testScaledSelfPowerTangenciesAcrossEquivalentForms(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $level = 1.0 / \M_E;
        $offset = $level - 0.1;
        $cases = [
            ['x^2 + 0.1', [-\sqrt($offset), \sqrt($offset)]],
            [
                '(x^2 - 1)^2 + 0.1',
                [
                    -\sqrt(1.0 + \sqrt($offset)),
                    -\sqrt(1.0 - \sqrt($offset)),
                    \sqrt(1.0 - \sqrt($offset)),
                    \sqrt(1.0 + \sqrt($offset)),
                ],
            ],
            ['(x - 0.2)^2 + 0.1', [0.2 - \sqrt($offset), 0.2 + \sqrt($offset)]],
            ['x^4 + 0.1', [-\sqrt(\sqrt($offset)), \sqrt(\sqrt($offset))]],
        ];

        foreach ($cases as [$base, $expectedRoots]) {
            foreach ([-3.0, -1.0, -0.5, 0.5, 1.0, 2.0, 3.0] as $scale) {
                $scaleSource = \sprintf('%.17g', $scale);
                $targetSource = \sprintf('%.17g', \exp(-$scale / \M_E));
                $equations = [
                    '(' . $base . ')^(' . $scaleSource . '*(' . $base . '))='
                        . $targetSource,
                    'exp((' . $scaleSource . '*(' . $base . '))*ln(' . $base . '))='
                        . 'exp(' . $scaleSource . '*(-1/e))',
                ];
                foreach ($equations as $equation) {
                    $solutions = Math::solve(
                        $equation,
                        'x',
                        -2.0,
                        2.0,
                        solverOptions: $options,
                    );
                    $actualRoots = \array_map(
                        static fn (EquationSolution $solution): float => $solution->value,
                        $solutions,
                    );

                    self::assertCount(\count($expectedRoots), $actualRoots, $equation);
                    foreach ($expectedRoots as $index => $expectedRoot) {
                        self::assertEqualsWithDelta(
                            $expectedRoot,
                            $actualRoots[$index],
                            1.0E-8,
                            $equation,
                        );
                    }
                    foreach ($solutions as $solution) {
                        self::assertLessThanOrEqual(1.0E-9, $solution->residual, $equation);
                    }
                }
            }
        }
    }

    public function testRationalSelfPowerTangenciesAndRemovableHoles(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        foreach (
            [
                '((x^2 + 0.1)/(x^2 + 1))^((x^2 + 0.1)/(x^2 + 1)) = exp(-1/e)',
                'exp(((x^2 + 0.1)/(x^2 + 1))*ln((x^2 + 0.1)/(x^2 + 1))) = exp(-1/e)',
                '((x^2 + 1)/(x^2 + 4))^((x^2 + 1)/(x^2 + 4)) = exp(-1/e)',
                'exp(((x^2 + 1)/(x^2 + 4))*ln((x^2 + 1)/(x^2 + 4))) = exp(-1/e)',
            ] as $equation
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                -3.0,
                3.0,
                solverOptions: $options,
            );
            self::assertCount(2, $solutions, $equation);
            self::assertEqualsWithDelta(-$solutions[1]->value, $solutions[0]->value, 1.0E-8);
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-9, $solution->residual, $equation);
            }
        }

        $level = 1.0 / \M_E;
        foreach (
            [
                [
                    '(x^2 + 0.1)/(x^2 + 1)',
                    \sqrt(($level - 0.1) / (1.0 - $level)),
                ],
                [
                    '(x^2 + 1)/(x^2 + 4)',
                    \sqrt(((4.0 * $level) - 1.0) / (1.0 - $level)),
                ],
            ] as [$base, $expectedMagnitude]
        ) {
            foreach (
                [
                    '(' . $base . ')^(2*(' . $base . '))=exp(-2/e)',
                    'exp(2*(' . $base . ')*ln(' . $base . '))=exp(-2/e)',
                    '(' . $base . ')^(-2*(' . $base . '))=exp(2/e)',
                    'exp(-2*(' . $base . ')*ln(' . $base . '))=exp(2/e)',
                ] as $equation
            ) {
                $solutions = Math::solve(
                    $equation,
                    'x',
                    -2.0,
                    2.0,
                    solverOptions: $options,
                );
                self::assertCount(2, $solutions, $equation);
                self::assertEqualsWithDelta(-$expectedMagnitude, $solutions[0]->value, 1.0E-8);
                self::assertEqualsWithDelta($expectedMagnitude, $solutions[1]->value, 1.0E-8);
            }
        }

        foreach (
            [
                ['(x^2 + 0.1)/(x^2 + 1)', \sqrt(($level - 0.1) / (1.0 - $level))],
                ['(x^2 + 1)/(x^2 + 4)', \sqrt(((4.0 * $level) - 1.0) / (1.0 - $level))],
            ] as [$base, $expectedMagnitude]
        ) {
            foreach ([-1.5, -0.5, 0.5, 1.5] as $scale) {
                $scaleSource = \sprintf('%.17g', $scale);
                $targetSource = \sprintf('%.17g', \exp(-$scale / \M_E));
                foreach (
                    [
                        '(' . $base . ')^(' . $scaleSource . '*(' . $base . '))='
                            . $targetSource,
                        'exp(' . $scaleSource . '*(' . $base . ')*ln(' . $base . '))='
                            . 'exp(' . $scaleSource . '*(-1/e))',
                    ] as $equation
                ) {
                    $solutions = Math::solve(
                        $equation,
                        'x',
                        -2.0,
                        2.0,
                        solverOptions: $options,
                    );
                    self::assertCount(2, $solutions, $equation);
                    self::assertEqualsWithDelta(-$expectedMagnitude, $solutions[0]->value, 1.0E-8);
                    self::assertEqualsWithDelta($expectedMagnitude, $solutions[1]->value, 1.0E-8);
                }
            }
        }

        $removableHole = '((x^2 - 0.0025)/(x - 0.05))^((x^2 - 0.0025)/(x - 0.05))'
            . '=0.79432823472428149';
        $holeSolutions = Math::solve(
            $removableHole,
            'x',
            -0.04,
            1.0,
            solverOptions: $options,
        );
        self::assertCount(1, $holeSolutions);
        self::assertEqualsWithDelta(0.6792411085356171, $holeSolutions[0]->value, 1.0E-8);
    }

    public function testPolynomialLogProductBranchPointDoesNotDuplicateTangencies(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $branchPoint = -1.0 / \M_E;

        $tangentSolutions = Math::solve(
            'x^2 * ln(x^2) = -1/e',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $tangent = \exp(-0.5);
        self::assertCount(2, $tangentSolutions);
        self::assertEqualsWithDelta(-$tangent, $tangentSolutions[0]->value, 1.0E-9);
        self::assertEqualsWithDelta($tangent, $tangentSolutions[1]->value, 1.0E-9);

        $below = Math::solve(
            'x^2 * ln(x^2) = ' . \sprintf('%.17g', $branchPoint - 1.0E-6),
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        self::assertSame([], $below);

        $above = Math::solve(
            'x^2 * ln(x^2) = ' . \sprintf('%.17g', $branchPoint + 1.0E-6),
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        self::assertCount(4, $above);

        $scaled = Math::solve(
            '2 * x^2 * ln(x^2) = -2/e',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        self::assertCount(2, $scaled);
        foreach ([...$tangentSolutions, ...$above, ...$scaled] as $solution) {
            self::assertLessThanOrEqual(1.0E-9, $solution->residual);
        }
    }

    public function testShiftedPolynomialLogProductFindsBranchPointAndBothBranches(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $tangentLevel = \exp(-3.0);

        $linearTangent = Math::solve(
            'x * ln(x) + 2*x = -exp(-3)',
            'x',
            -4.0,
            4.0,
            solverOptions: $options,
        );
        self::assertCount(1, $linearTangent);
        self::assertEqualsWithDelta($tangentLevel, $linearTangent[0]->value, 1.0E-9);

        $polynomialTangent = Math::solve(
            'x^2 * ln(x^2) + 2*x^2 = -exp(-3)',
            'x',
            -4.0,
            4.0,
            solverOptions: $options,
        );
        self::assertCount(2, $polynomialTangent);
        self::assertEqualsWithDelta(-\sqrt($tangentLevel), $polynomialTangent[0]->value, 1.0E-9);
        self::assertEqualsWithDelta(\sqrt($tangentLevel), $polynomialTangent[1]->value, 1.0E-9);

        $reordered = Math::solve(
            '2*x^2 + x^2*ln(x^2) = -exp(-3) + 1e-6',
            'x',
            -4.0,
            4.0,
            solverOptions: $options,
        );
        self::assertCount(4, $reordered);

        $belowMinimum = Math::solve(
            'x^2*ln(x^2) + 2*x^2 = -exp(-3) - 1e-6',
            'x',
            -4.0,
            4.0,
            solverOptions: $options,
        );
        self::assertSame([], $belowMinimum);

        $rationalTangent = Math::solve(
            '((x^2+0.1)/(x^2+1))*ln((x^2+0.1)/(x^2+1))'
                . ' + 0.5*((x^2+0.1)/(x^2+1)) = -exp(-1.5)',
            'x',
            -3.0,
            3.0,
            solverOptions: $options,
        );
        $rationalLevel = \exp(-1.5);
        $rationalRoot = \sqrt(($rationalLevel - 0.1) / (1.0 - $rationalLevel));
        self::assertCount(2, $rationalTangent);
        self::assertEqualsWithDelta(-$rationalRoot, $rationalTangent[0]->value, 1.0E-8);
        self::assertEqualsWithDelta($rationalRoot, $rationalTangent[1]->value, 1.0E-8);

        $scaledCoefficients = Math::solve(
            '3*x^2*ln(x^2) + 5*x^2 = -3*exp(-8/3)',
            'x',
            -3.0,
            3.0,
            solverOptions: $options,
        );
        $scaledLevel = \exp(-8.0 / 3.0);
        self::assertCount(2, $scaledCoefficients);
        self::assertEqualsWithDelta(-\sqrt($scaledLevel), $scaledCoefficients[0]->value, 1.0E-8);
        self::assertEqualsWithDelta(\sqrt($scaledLevel), $scaledCoefficients[1]->value, 1.0E-8);

        $baseTwoTangent = Math::solve(
            'x^2*log(x^2,2) + 2*x^2 = -1/(4*e*ln(2))',
            'x',
            -3.0,
            3.0,
            solverOptions: $options,
        );
        $baseTwoLevel = 1.0 / (4.0 * \M_E);
        self::assertCount(2, $baseTwoTangent);
        self::assertEqualsWithDelta(-\sqrt($baseTwoLevel), $baseTwoTangent[0]->value, 1.0E-8);
        self::assertEqualsWithDelta(\sqrt($baseTwoLevel), $baseTwoTangent[1]->value, 1.0E-8);

        $rationalAboveMinimum = Math::solve(
            '0.5*((x^2+0.1)/(x^2+1))'
                . ' + ((x^2+0.1)/(x^2+1))*ln((x^2+0.1)/(x^2+1))'
                . ' = -exp(-1.5) + 1e-6',
            'x',
            -3.0,
            3.0,
            solverOptions: $options,
        );
        self::assertCount(4, $rationalAboveMinimum);

        foreach (
            [
                ...$linearTangent,
                ...$polynomialTangent,
                ...$reordered,
                ...$rationalTangent,
                ...$scaledCoefficients,
                ...$baseTwoTangent,
                ...$rationalAboveMinimum,
            ] as $solution
        ) {
            self::assertLessThanOrEqual(1.0E-9, $solution->residual);
        }
    }

    public function testHigherPowerLogProductsResolveLambertBranchTangencies(): void
    {
        $options = new SolverOptions(scanSteps: 1);

        $quadraticPowerTangent = Math::solve(
            'x^2*ln(x) + x^2 = -0.5*exp(-3)',
            'x',
            -3.0,
            3.0,
            solverOptions: $options,
        );
        self::assertCount(1, $quadraticPowerTangent);
        self::assertEqualsWithDelta(\exp(-1.5), $quadraticPowerTangent[0]->value, 1.0E-9);

        $cubicPowerTangent = Math::solve(
            'x^3*ln(x) + x^3 = -(1/3)*exp(-4)',
            'x',
            -3.0,
            3.0,
            solverOptions: $options,
        );
        self::assertCount(1, $cubicPowerTangent);
        self::assertEqualsWithDelta(\exp(-4.0 / 3.0), $cubicPowerTangent[0]->value, 1.0E-9);

        $squareBaseTangent = Math::solve(
            '(x^2)^2*ln(x^2) + (x^2)^2 = -0.5*exp(-3)',
            'x',
            -3.0,
            3.0,
            solverOptions: $options,
        );
        self::assertCount(2, $squareBaseTangent);
        self::assertEqualsWithDelta(-\exp(-0.75), $squareBaseTangent[0]->value, 1.0E-9);
        self::assertEqualsWithDelta(\exp(-0.75), $squareBaseTangent[1]->value, 1.0E-9);

        $rational = '(x^2+0.1)/(x^2+1)';
        $rationalPowerTangent = Math::solve(
            '(' . $rational . ')^2*ln(' . $rational . ')'
                . ' + (' . $rational . ')^2 = -0.5*exp(-3)',
            'x',
            -3.0,
            3.0,
            solverOptions: $options,
        );
        $rationalBaseLevel = \exp(-1.5);
        $rationalTangentRoot = \sqrt(
            ($rationalBaseLevel - 0.1) / (1.0 - $rationalBaseLevel),
        );
        self::assertCount(2, $rationalPowerTangent);
        self::assertEqualsWithDelta(-$rationalTangentRoot, $rationalPowerTangent[0]->value, 1.0E-8);
        self::assertEqualsWithDelta($rationalTangentRoot, $rationalPowerTangent[1]->value, 1.0E-8);

        $hole = \exp(-1.5) / 2.0;
        $holeSource = \sprintf('%.17g', $hole);
        $holeBase = '((x^2-' . \sprintf('%.17g', $hole * $hole) . ')/(x-' . $holeSource . '))';
        $removableHoleOnly = Math::solve(
            '(' . $holeBase . ')^2*ln(' . $holeBase . ')'
                . ' + (' . $holeBase . ')^2 = -0.5*exp(-3)',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        self::assertSame([], $removableHoleOnly);

        $above = Math::solve(
            '(x^2)^2*ln(x^2) + (x^2)^2 = -0.5*exp(-3) + 1e-6',
            'x',
            -3.0,
            3.0,
            solverOptions: $options,
        );
        self::assertCount(4, $above);

        $below = Math::solve(
            '(x^2)^2*ln(x^2) + (x^2)^2 = -0.5*exp(-3) - 1e-6',
            'x',
            -3.0,
            3.0,
            solverOptions: $options,
        );
        self::assertSame([], $below);

        $negativePowerTangent = Math::solve(
            'x^-2*ln(x) + x^-2 = e/2',
            'x',
            0.01,
            4.0,
            solverOptions: $options,
        );
        self::assertCount(1, $negativePowerTangent);
        self::assertEqualsWithDelta(\exp(-0.5), $negativePowerTangent[0]->value, 1.0E-12);

        $negativeCubicTangent = Math::solve(
            'x^-3*ln(x) + x^-3 = e^2/3',
            'x',
            0.01,
            4.0,
            solverOptions: $options,
        );
        self::assertCount(1, $negativeCubicTangent);
        self::assertEqualsWithDelta(\exp(-2.0 / 3.0), $negativeCubicTangent[0]->value, 1.0E-12);

        $negativePowerTwoBranches = Math::solve(
            'x^-2*ln(x) + x^-2 = e/2 - 1e-6',
            'x',
            0.01,
            4.0,
            solverOptions: $options,
        );
        self::assertCount(2, $negativePowerTwoBranches);

        $negativePowerAboveMaximum = Math::solve(
            'x^-2*ln(x) + x^-2 = e/2 + 1e-6',
            'x',
            0.01,
            4.0,
            solverOptions: $options,
        );
        self::assertSame([], $negativePowerAboveMaximum);

        foreach (
            [
                ...$quadraticPowerTangent,
                ...$cubicPowerTangent,
                ...$squareBaseTangent,
                ...$rationalPowerTangent,
                ...$negativePowerTangent,
                ...$negativeCubicTangent,
                ...$negativePowerTwoBranches,
                ...$removableHoleOnly,
                ...$above,
            ] as $solution
        ) {
            self::assertLessThanOrEqual(1.0E-9, $solution->residual);
        }
    }

    public function testFractionalLogProductPowersUseLambertWLevels(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $squareRootTangent = Math::solve(
            'sqrt(x)*ln(x) + sqrt(x) = -2*exp(-1.5)',
            'x',
            0.001,
            4.0,
            solverOptions: $options,
        );
        self::assertCount(1, $squareRootTangent);
        self::assertEqualsWithDelta(\exp(-3.0), $squareRootTangent[0]->value, 1.0E-12);

        $cubeRootTangent = Math::solve(
            'cbrt(x)*ln(x) + cbrt(x) = -3*exp(-4/3)',
            'x',
            0.001,
            4.0,
            solverOptions: $options,
        );
        self::assertCount(1, $cubeRootTangent);
        self::assertEqualsWithDelta(\exp(-4.0), $cubeRootTangent[0]->value, 1.0E-12);

        $fourthRootTangent = Math::solve(
            'root(x,4)*ln(x) + root(x,4) = -4*exp(-1.25)',
            'x',
            0.001,
            4.0,
            solverOptions: $options,
        );
        self::assertCount(1, $fourthRootTangent);
        self::assertEqualsWithDelta(\exp(-5.0), $fourthRootTangent[0]->value, 1.0E-12);

        $negativeFractionalTangent = Math::solve(
            'x^(-1/2)*ln(x) + x^(-1/2) = 2/sqrt(e)',
            'x',
            0.001,
            4.0,
            solverOptions: $options,
        );
        self::assertCount(1, $negativeFractionalTangent);
        self::assertEqualsWithDelta(\M_E, $negativeFractionalTangent[0]->value, 1.0E-12);

        $quotientNegativeFractionalTangent = Math::solve(
            'ln(x)/sqrt(x) + 1/sqrt(x) = 2/sqrt(e)',
            'x',
            0.001,
            4.0,
            solverOptions: $options,
        );
        self::assertCount(1, $quotientNegativeFractionalTangent);
        self::assertEqualsWithDelta(\M_E, $quotientNegativeFractionalTangent[0]->value, 1.0E-12);

        $fractionalTwoBranches = Math::solve(
            'sqrt(x)*ln(x) + sqrt(x) = -2*exp(-1.5) + 1e-6',
            'x',
            0.001,
            4.0,
            solverOptions: $options,
        );
        self::assertCount(2, $fractionalTwoBranches);

        $rationalBase = '(x^2+0.01)/(x^2+1)';
        $rationalFractionalTangent = Math::solve(
            'sqrt(' . $rationalBase . ')*ln(' . $rationalBase . ')'
                . ' + sqrt(' . $rationalBase . ') = -2*exp(-1.5)',
            'x',
            -3.0,
            3.0,
            solverOptions: $options,
        );
        $baseLevel = \exp(-3.0);
        $rationalRoot = \sqrt(($baseLevel - 0.01) / (1.0 - $baseLevel));
        self::assertCount(2, $rationalFractionalTangent);
        self::assertEqualsWithDelta(-$rationalRoot, $rationalFractionalTangent[0]->value, 1.0E-8);
        self::assertEqualsWithDelta($rationalRoot, $rationalFractionalTangent[1]->value, 1.0E-8);

        foreach (
            [
                ...$squareRootTangent,
                ...$cubeRootTangent,
                ...$fourthRootTangent,
                ...$negativeFractionalTangent,
                ...$quotientNegativeFractionalTangent,
                ...$fractionalTwoBranches,
                ...$rationalFractionalTangent,
            ] as $solution
        ) {
            self::assertLessThanOrEqual(1.0E-9, $solution->residual);
        }
    }

    public function testNonnegativeBaseVariablePowersEqualOneUseExactFactors(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        foreach (
            [
                '(x^2 + 1)^x = 1' => [0.0],
                '(x^2 + 1)^(x^2) = 1' => [0.0],
                '(x^2)^abs(x) = 1' => [-1.0, 0.0, 1.0],
                '(1 + (x - 2)^2)^x = 1' => [0.0, 2.0],
                '1 = (x^2 + 2)^(x - 1)' => [1.0],
            ] as $equation => $expectedRoots
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                -3.0,
                3.0,
                solverOptions: $options,
            );
            self::assertSame(
                $expectedRoots,
                \array_map(static fn ($solution): float => $solution->value, $solutions),
                $equation,
            );
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-10, $solution->residual, $equation);
            }
        }
    }

    public function testNonnegativeBaseVariablePowersNearOneUseLogarithmicReduction(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $aboveOne = Math::solve(
            '(x^2 + 1)^(x^2) = 1.000000000000001',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        $belowOneImpossible = Math::solve(
            '(x^2 + 1)^(x^2) = 0.999999999999999',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        $aboveOneOdd = Math::solve(
            '(x^2 + 1)^x = 1.000000000000001',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        $belowOneOdd = Math::solve(
            '(x^2 + 1)^x = 0.999999999999999',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );

        self::assertCount(2, $aboveOne);
        self::assertLessThan(0.0, $aboveOne[0]->value);
        self::assertGreaterThan(0.0, $aboveOne[1]->value);
        self::assertEqualsWithDelta(0.00018253768, \abs($aboveOne[0]->value), 2.0E-7);
        self::assertSame([], $belowOneImpossible);
        self::assertCount(1, $aboveOneOdd);
        self::assertGreaterThan(0.0, $aboveOneOdd[0]->value);
        self::assertCount(1, $belowOneOdd);
        self::assertLessThan(0.0, $belowOneOdd[0]->value);
    }

    public function testIntegerPolynomialPowersUseDirectIsolation(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $largeRoot = Math::solve('x^2 = 171', 'x', 13.0, 14.0, solverOptions: $options);
        $reciprocalRoots = Math::solve('x^-2 = 171', 'x', -1.0, 1.0, solverOptions: $options);
        $rationalPowerRoot = Math::solve(
            '((x - 1) / (x + 1))^2 = 1e-20',
            'x',
            1.0,
            4.0,
            solverOptions: $options,
        );
        $rationalReciprocalPowerRoot = Math::solve(
            '((x - 1) / (x + 1))^-2 = 1e20',
            'x',
            1.0,
            4.0,
            solverOptions: $options,
        );
        $closeRoots = Math::solve(
            '(x - 0.123456789)^2 = 1e-20',
            'x',
            0.1,
            0.15,
            solverOptions: $options,
        );

        self::assertCount(1, $largeRoot);
        self::assertEqualsWithDelta(\sqrt(171.0), $largeRoot[0]->value, 1.0E-12);
        self::assertCount(2, $reciprocalRoots);
        self::assertEqualsWithDelta(-1.0 / \sqrt(171.0), $reciprocalRoots[0]->value, 1.0E-12);
        self::assertEqualsWithDelta(1.0 / \sqrt(171.0), $reciprocalRoots[1]->value, 1.0E-12);
        self::assertCount(1, $rationalPowerRoot);
        self::assertEqualsWithDelta(1.0000000002, $rationalPowerRoot[0]->value, 1.0E-12);
        self::assertCount(1, $rationalReciprocalPowerRoot);
        self::assertEqualsWithDelta(1.0000000002, $rationalReciprocalPowerRoot[0]->value, 1.0E-12);
        self::assertSame(
            \abs(Math::evaluate(
                '((x - 1) / (x + 1))^-2 - 1e20',
                ['x' => $rationalReciprocalPowerRoot[0]->value],
            )),
            $rationalReciprocalPowerRoot[0]->residual,
        );
        self::assertCount(2, $closeRoots);
        self::assertEqualsWithDelta(0.1234567889, $closeRoots[0]->value, 2.0E-12);
        self::assertEqualsWithDelta(0.1234567891, $closeRoots[1]->value, 2.0E-12);
    }

    public function testVariableExponentIntegerDomainRootsDoNotDependOnScanGrid(): void
    {
        foreach ([1, 2, 3, 17, 256] as $scanSteps) {
            $solutions = Math::solve(
                'x^x = x',
                'x',
                -3.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );

            self::assertCount(2, $solutions, 'scanSteps=' . $scanSteps);
            self::assertEqualsWithDelta(-1.0, $solutions[0]->value, 1.0E-10);
            self::assertSame(0.0, $solutions[0]->residual);
            self::assertEqualsWithDelta(1.0, $solutions[1]->value, 1.0E-8);
            self::assertLessThanOrEqual(1.0E-10, $solutions[1]->residual);
        }
    }

