    public function testSecantAndCosecantExponentRangesIncludeInteriorExtrema(): void
    {
        $cases = [
            ['(-x)^sec(x-0.123456789) = -0.123456789', 0.123456789],
            ['(-x)^sec(x+pi-0.123456789) = -1/0.123456789', 0.123456789],
            ['(-x)^csc(x+pi/2-0.123456789) = -0.123456789', 0.123456789],
            ['(-x)^csc(x-pi/2-0.123456789) = -1/0.123456789', 0.123456789],
        ];
        foreach ($cases as [$equation, $expectedRoot]) {
            foreach ([1, 256] as $scanSteps) {
                $solutions = Math::solve(
                    $equation,
                    'x',
                    $expectedRoot - 0.01,
                    $expectedRoot + 0.01,
                    solverOptions: new SolverOptions(scanSteps: $scanSteps),
                );

                self::assertCount(1, $solutions, $equation . ', scanSteps=' . $scanSteps);
                self::assertEqualsWithDelta($expectedRoot, $solutions[0]->value, 1.0E-9);
                self::assertLessThanOrEqual(1.0E-10, $solutions[0]->residual);
            }
        }
    }

    public function testSincExponentRangesIncludeTheirCentralMaximum(): void
    {
