    public function testConstantBasePowerEquationSolvesPolynomialExponentExactly(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $symmetric = Math::solve('2^(x^2) = 4', 'x', -2.0, 2.0, solverOptions: $options);
        $reversed = Math::solve('81 = 3^(x^2)', 'x', -3.0, 3.0, solverOptions: $options);
        $repeated = Math::solve(
            '2^((x - 0.25)^2) = 1',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );

        self::assertCount(2, $symmetric);
        self::assertEqualsWithDelta(-\sqrt(2.0), $symmetric[0]->value, 1.0E-8);
        self::assertEqualsWithDelta(\sqrt(2.0), $symmetric[1]->value, 1.0E-8);
        self::assertCount(2, $reversed);
        self::assertEqualsWithDelta(-2.0, $reversed[0]->value, 1.0E-8);
        self::assertEqualsWithDelta(2.0, $reversed[1]->value, 1.0E-8);
        self::assertCount(1, $repeated);
        self::assertEqualsWithDelta(0.25, $repeated[0]->value, 1.0E-8);
        self::assertSame(
            [],
            Math::solve('2^(x^2) = 0.5', 'x', -2.0, 2.0, solverOptions: $options),
        );
    }

