        self::assertSame(
            [],
            Math::solve('(-2)^floor(x) = 2', 'x', -2.0, 2.0, solverOptions: $options),
        );
        self::assertSame(
            [2.0],
            \array_map(
                static fn ($solution): float => $solution->value,
                Math::solve('(-2)^floor(x) = 4', 'x', -2.0, 2.0, solverOptions: $options),
            ),
        );
        $withinTolerance = Math::solve(
            '(-2)^floor(x) = 3.99999999995',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        self::assertCount(1, $withinTolerance);
        self::assertSame(2.0, $withinTolerance[0]->value);
        self::assertEqualsWithDelta(5.0E-11, $withinTolerance[0]->residual, 1.0E-15);

        $this->expectException(InfiniteSolutionSetException::class);
        Math::solve('(-2)^floor(x) = -2', 'x', -2.0, 2.0, solverOptions: $options);
    }

