    public function testSignOfPolynomialEquationsUseExactLevelSets(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $isolatedZero = Math::solve(
            'sign((x - 0.123)^2) = 0',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        $reversedZero = Math::solve(
            '0 = sign((x - 0.123)^2)',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );

        self::assertCount(1, $isolatedZero);
        self::assertEqualsWithDelta(0.123, $isolatedZero[0]->value, 1.0E-8);
        self::assertCount(1, $reversedZero);
        self::assertEqualsWithDelta(0.123, $reversedZero[0]->value, 1.0E-8);
        self::assertSame(
            [],
            Math::solve('sign(x^2 + 1) = 0', 'x', -1.0, 1.0, solverOptions: $options),
        );
        self::assertSame(
            [],
            Math::solve('sign(x^2 + 1) = -1', 'x', -1.0, 1.0, solverOptions: $options),
        );
        self::assertSame(
            [],
            Math::solve('sign(x^2 + 1) = 0.5', 'x', -1.0, 1.0, solverOptions: $options),
        );

        $infiniteSetsDetected = 0;
        try {
            Math::solve('sign(x^2 + 1) = 1', 'x', -1.0, 1.0, solverOptions: $options);
            self::fail('Expected an infinite solution set for sign(x^2 + 1) = 1');
        } catch (\MathPHP\Solver\InfiniteSolutionSetException) {
            ++$infiniteSetsDetected;
        }

        try {
            Math::solve('sign(x - x) = 0', 'x', -1.0, 1.0, solverOptions: $options);
            self::fail('Expected an infinite solution set for sign(x - x) = 0');
        } catch (\MathPHP\Solver\InfiniteSolutionSetException) {
            ++$infiniteSetsDetected;
        }
        self::assertSame(2, $infiniteSetsDetected);
    }

    public function testSignOfRationalEquationsClassifiesRootsAndIntervals(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        foreach (
            [
                'sign((x^2 - 1) / (x - 1)) = 0',
                '0 = sign((x^2 - 1) / (x - 1))',
            ] as $equation
        ) {
            $solutions = Math::solve($equation, 'x', -2.0, 2.0, solverOptions: $options);
            self::assertCount(1, $solutions);
            self::assertEqualsWithDelta(-1.0, $solutions[0]->value, 1.0E-10);
        }

        self::assertSame(
            [],
            Math::solve('sign(1 / x) = 0', 'x', -2.0, 2.0, solverOptions: $options),
        );

        try {
            Math::solve('sign(1 / x) = 1', 'x', -2.0, 2.0, solverOptions: $options);
            self::fail('Expected an infinite solution set for sign(1 / x) = 1');
        } catch (InfiniteSolutionSetException) {
            self::assertSame(
                [],
                Math::solve('sign(1 / x) = 0.5', 'x', -2.0, 2.0, solverOptions: $options),
            );
        }
    }

    public function testRationalSignEquationsDetectInfiniteIntervalsBetweenAdjacentRoots(): void
    {
        $zeroLevel = \sprintf(
            'sign(((x - %.17g) * (x - %.17g)) / (x + 2)) = 0',
            1.0,
            1.0000000000000002,
        );
        $zeroSolutions = Math::solve(
            $zeroLevel,
            'x',
            0.9,
            1.1,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(2, $zeroSolutions);
        self::assertSame(1.0, $zeroSolutions[0]->value);
        self::assertSame(1.0000000000000002, $zeroSolutions[1]->value);

        $adjacentPoleZeroLevel = \sprintf(
            'sign((x - %.17g) / (x - %.17g)) = 0',
            1.0,
            1.0000000000000002,
        );
        $adjacentPoleSolutions = Math::solve(
            $adjacentPoleZeroLevel,
            'x',
            0.9,
            1.1,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $adjacentPoleSolutions);
        self::assertSame(1.0, $adjacentPoleSolutions[0]->value);

        $nonzeroLevel = \sprintf(
            'sign(((x - %.17g) * (x - %.17g)) / (x + 2)) = -1',
            1.0,
            1.0000000000000002,
        );

        $this->expectException(InfiniteSolutionSetException::class);
        Math::solve(
            $nonzeroLevel,
            'x',
            0.9,
            1.1,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
    }

