            ['a' => 0.3, 'b' => 0.300000000000002, 'c' => 1.0E-30],
        );
        self::assertCount(2, $translated);
        self::assertEqualsWithDelta(0.2999999683772234, $translated[0]->value, 1.0E-14);
        self::assertEqualsWithDelta(0.3000000316227786, $translated[1]->value, 1.0E-14);
    }

