    public function testRationalPolynomialEquationsUseExactNumeratorRootIsolation(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $sumOfFractions = Math::solve(
            '1/x + 1/(x - 1) = 0',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        self::assertCount(1, $sumOfFractions);
        self::assertEqualsWithDelta(0.5, $sumOfFractions[0]->value, 1.0E-10);

        $reciprocalSquare = Math::solve(
            '1/(x - 1)^2 = 4',
            'x',
            -1.0,
            3.0,
            solverOptions: $options,
        );
        self::assertCount(2, $reciprocalSquare);
        self::assertEqualsWithDelta(0.5, $reciprocalSquare[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(1.5, $reciprocalSquare[1]->value, 1.0E-10);

        $negativePower = Math::solve(
            'x^-2 = 4',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        self::assertCount(2, $negativePower);
        self::assertEqualsWithDelta(-0.5, $negativePower[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(0.5, $negativePower[1]->value, 1.0E-10);

        $unaryRational = Math::solve(
            '-(1/x) = 2',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        self::assertCount(1, $unaryRational);
        self::assertEqualsWithDelta(-0.5, $unaryRational[0]->value, 1.0E-10);

        $nestedReciprocal = Math::solve(
            '(1/x + 1)^-1 = 2',
            'x',
            -3.0,
            0.0,
            solverOptions: $options,
        );
        self::assertCount(1, $nestedReciprocal);
        self::assertEqualsWithDelta(-2.0, $nestedReciprocal[0]->value, 1.0E-10);

        $divisionByRational = Math::solve(
            'x/(1/x) = 1',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        self::assertCount(2, $divisionByRational);
        self::assertEqualsWithDelta(-1.0, $divisionByRational[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(1.0, $divisionByRational[1]->value, 1.0E-10);

        $repeatedTerms = \implode(' + ', \array_fill(0, 40, '1/x'));
        $sharedDenominator = Math::solve(
            '(' . $repeatedTerms . ' - 8)^2 = 0',
            'x',
            4.0,
            6.0,
            solverOptions: $options,
        );
        self::assertCount(1, $sharedDenominator);
        self::assertEqualsWithDelta(5.0, $sharedDenominator[0]->value, 1.0E-9);

        $scaledDenominators = \implode(
            ' + ',
            [...\array_fill(0, 20, '1/x'), ...\array_fill(0, 20, '1/(2*x)')],
        );
        $proportionalDenominators = Math::solve(
            '(' . $scaledDenominators . ' - 9)^2 = 0',
            'x',
            3.0,
            4.0,
            solverOptions: $options,
        );
        self::assertCount(1, $proportionalDenominators);
        self::assertEqualsWithDelta(10.0 / 3.0, $proportionalDenominators[0]->value, 1.0E-9);

        $holeIsNotRoot = Math::solve(
            'x/x = 2',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        self::assertSame([], $holeIsNotRoot);

        foreach ([1.000000000001, 1.0000000000000002] as $nearbyRoot) {
            $equation = '((x - 1) * (x - ' . \sprintf('%.17g', $nearbyRoot) . ')) / (x - 1) = 0';
            $solutions = Math::solve($equation, 'x', 0.0, 2.0, solverOptions: $options);

            self::assertCount(1, $solutions, $equation);
            self::assertSame($nearbyRoot, $solutions[0]->value, $equation);
        }

        self::assertSame(
            [],
            Math::solve('(x - 1) / (x - 1) = 0', 'x', 0.0, 2.0, solverOptions: $options),
        );

        foreach ([[3.0, 1.0E-11], [-2.0, 1.0E-9], [0.25, 1.0E-8]] as [$pole, $offset]) {
            $target = (2.0 * $pole) + $offset;
            $equation = '(x^2-(' . $pole . ')^2)/(x-(' . $pole . '))='
                . \sprintf('%.17g', $target);
            $solutions = Math::solve($equation, 'x', $pole - 1.0, $pole + 1.0, solverOptions: $options);

            self::assertCount(1, $solutions, $equation);
            self::assertEqualsWithDelta($pole + $offset, $solutions[0]->value, 2.0E-14, $equation);
        }
    }

    public function testRationalIdentitiesWithDomainHolesReportInfiniteSolutions(): void
    {
        $detectedInfiniteSets = 0;
        foreach (
            [
                'x/x = 1',
                '(x^2 - 1) / (x - 1) = x + 1',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', 0.0, 2.0);
                self::fail('Expected an infinite solution set for ' . $equation);
            } catch (\MathPHP\Solver\InfiniteSolutionSetException) {
                ++$detectedInfiniteSets;
            }
        }
        self::assertSame(2, $detectedInfiniteSets);

        self::assertSame(
            [],
            Math::solve('(x^2 - 1) / (x - 1) = 2', 'x', 0.0, 2.0),
        );
    }

    public function testReversedReciprocalIsolationUsesSideLocalSourceSpans(): void
    {
        $solutions = Math::solve('2 = 1 / (x - 2)', 'x', -4.0, 4.0);

        self::assertCount(1, $solutions);
        self::assertEqualsWithDelta(2.5, $solutions[0]->value, 1.0E-12);
        self::assertLessThanOrEqual(1.0E-12, $solutions[0]->residual);

        $twoBranches = Math::solve('2 = 1 / (x - 2)^2', 'x', -4.0, 4.0);
        self::assertCount(2, $twoBranches);
        self::assertEqualsWithDelta(2.0 - (1.0 / \sqrt(2.0)), $twoBranches[0]->value, 1.0E-12);
        self::assertEqualsWithDelta(2.0 + (1.0 / \sqrt(2.0)), $twoBranches[1]->value, 1.0E-12);
    }

