    /** @return iterable<string, array{string, float, float, list<float>}> */
    public static function polynomialEquationProvider(): iterable
    {
        yield 'quadratic two roots' => ['x^2 = 4', -3.0, 3.0, [-2.0, 2.0]];
        yield 'close roots from separate factors remain distinct' => [
            '(x - 1) * (x - 1.000000000001) = 0',
            0.9,
            1.1,
            [1.0, 1.000000000001],
        ];
        yield 'close roots near a repeated factor remain distinct' => [
            '(x - 1)^2 * (x - 1.000000001) * (x - 1.000000002) = 0',
            0.99,
            1.01,
            [1.0, 1.000000001, 1.000000002],
        ];
        yield 'adjacent representable roots near a repeated factor remain distinct' => [
            '(x - 1)^2 * (x - 1.0000000000000002) * (x - 1.0000000000000004) = 0',
            0.99,
            1.01,
            [1.0, 1.0000000000000002, 1.0000000000000004],
        ];
        yield 'cubic three roots' => ['(x - 1)(x + 2)(x - 3) = 0', -4.0, 4.0, [-2.0, 1.0, 3.0]];
        yield 'quartic repeated roots' => ['(x - 1)^2(x + 2)^2 = 0', -3.0, 3.0, [-2.0, 1.0]];
        yield 'non-binary rational repeated root' => ['(3x - 1)^2 = 0', 0.0, 1.0, [1.0 / 3.0]];
        yield 'odd repeated roots do not create nearby roots' => [
            '(x + 1.5)^3 * x^3 * (x + 2.5) = 0',
            -5.0,
            5.0,
            [-2.5, -1.5, 0.0],
        ];
        yield 'factorized high-degree repeated roots' => [
            '(x - 3.5) * x^2 * (x + 1.5)^2 * (x - 3.5)^3 = 0',
            -5.0,
            5.0,
            [-1.5, 0.0, 3.5],
        ];
        yield 'reversed factorized high-degree repeated roots' => [
            '0 = (x - 3.5) * x^2 * (x + 1.5)^2 * (x - 3.5)^3',
            -5.0,
            5.0,
            [-1.5, 0.0, 3.5],
        ];
        yield 'expanded repeated roots use consistent polynomial evaluation' => [
            '648 + 1116*x - 733.5*x^2 - 625*x^3 + 291.625*x^4 '
                . '+ 79.625*x^5 - 32.75*x^6 - 2.5*x^7 + x^8 = 0',
            -5.0,
            5.0,
            [-4.5, -3.0, -1.5, -0.5, 2.0, 4.0],
        ];
        yield 'expanded repeated roots recover from derivative critical points' => [
            '42*x + 19*x^2 - 99.5*x^3 + 60.25*x^4 - 4.25*x^5 - 5*x^6 + x^7 = 0',
            -5.0,
            5.0,
            [-3.5, -0.5, 0.0, 2.0, 3.0],
        ];
        yield 'expanded repeated roots with even derivative multiplicity' => [
            '125*x^2 + 75*x^3 + 15*x^4 + x^5 = 0',
            -6.0,
            6.0,
            [-5.0, 0.0],
        ];
        yield 'expanded polynomial with clustered roots on a wide interval' => [
            '0.0014523856882177845 - 0.034510162892358559*x '
                . '+ 0.26520884665729638*x^2 - 0.57593455459199994*x^3 '
                . '- 0.77066800000000013*x^4 + x^5 = 0',
            -1.0,
            2.0,
            [-0.7, 0.123456, 0.123556, 0.123656, 1.1],
        ];
        yield 'quintic odd root' => ['x^5 = -32', -3.0, 3.0, [-2.0]];
        yield 'cubic roots around an exactly representable critical root' => [
            'x^3 + 7*x^2 - 8 = 0',
            -8.0,
            5.0,
            [-4.0 - \sqrt(8.0), -4.0 + \sqrt(8.0), 1.0],
        ];
        yield 'root at lower bound' => ['x^3 - x = 0', -1.0, 0.0, [-1.0, 0.0]];
        yield 'root at upper bound' => ['x^3 - x = 0', 0.0, 1.0, [0.0, 1.0]];
        yield 'even-multiplicity root at lower bound' => [
            '(x - 1)^4 * (x + 2)^2 = 0',
            1.0,
            3.0,
            [1.0],
        ];
        yield 'even-multiplicity root at upper bound' => [
            '(x - 1)^4 * (x - 2)^2 = 0',
            0.0,
            1.0,
            [1.0],
        ];
    }

