    public function testExpandedHighMultiplicityRootsRemainDistinct(): void
    {
        $coefficients = [
            -6697.6875,
            -26711.015625,
            -45437.203125,
            -42559.171875,
            -23336.859375,
            -6999.75,
            -598.3125,
            322.25,
            123.75,
            18.0,
            1.0,
        ];
        $solutions = Math::solve(
            '-6697.6875 - 26711.015625*x - 45437.203125*x^2 '
                . '- 42559.171875*x^3 - 23336.859375*x^4 - 6999.75*x^5 '
                . '- 598.3125*x^6 + 322.25*x^7 + 123.75*x^8 + 18*x^9 + x^10 = 0',
            'x',
            -6.0,
            6.0,
        );

        self::assertCount(4, $solutions);
        foreach ([-3.5, -3.0, -1.5, 4.0] as $index => $root) {
            self::assertEqualsWithDelta($root, $solutions[$index]->value, 1.0E-8);
            $magnitude = 0.0;
            foreach ($coefficients as $degree => $coefficient) {
                $magnitude += \abs($coefficient * ($root ** $degree));
            }
            self::assertLessThanOrEqual(
                1.0E-10 * \max(1.0, $magnitude),
                $solutions[$index]->residual,
            );
        }
    }

    public function testHighDegreeTranslatedPowersAreSolvedInAffineIntervalCoordinates(): void
    {
        $cases = [
            ['(x - 100)^10 - 1 = 0', 99.0, 101.0, [99.0, 101.0]],
            ['(x - 100)^12 - 1 = 0', 99.0, 101.0, [99.0, 101.0]],
            ['(x - 100)^16 - 1 = 0', 99.0, 101.0, [99.0, 101.0]],
            ['(x - 100)^10 - 1 = 0', -100.0, 100.0, [99.0]],
            ['(x + 100)^10 - 1 = 0', -100.0, 100.0, [-99.0]],
            ['(x - 10)^20 - 1 = 0', 9.0, 11.0, [9.0, 11.0]],
        ];

        foreach ($cases as [$equation, $lowerBound, $upperBound, $expectedRoots]) {
            [$left, $right] = \explode('=', $equation, 2);
            $solutions = Math::solve(
                $equation,
                'x',
                $lowerBound,
                $upperBound,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertCount(\count($expectedRoots), $solutions, $equation);
            foreach ($expectedRoots as $index => $expectedRoot) {
                self::assertEqualsWithDelta(
                    $expectedRoot,
                    $solutions[$index]->value,
                    1.0E-8,
                    $equation,
                );
                $leftValue = Math::evaluate($left, ['x' => $solutions[$index]->value]);
                $rightValue = Math::evaluate($right, ['x' => $solutions[$index]->value]);
                self::assertEqualsWithDelta($rightValue, $leftValue, 1.0E-8, $equation);
                self::assertLessThanOrEqual(1.0E-8, $solutions[$index]->residual, $equation);
            }
        }
    }

