        }
    }

    public function testAdditiveOffsetAroundPolynomialPowerIsNormalizedBeforeSolving(): void
    {
        foreach (
            [
                '(x^2 - 10000)^5 - 1 = 0',
                '0 = (x^2 - 10000)^5 - 1',
                '(x^2 - 10000)^5 + 1 = 2',
                '2 = 1 + (x^2 - 10000)^5',
                '1 = 2 - (x^2 - 10000)^5',
                '-(x^2 - 10000)^5 + 1 = 0',
                '0 = 1 - (x^2 - 10000)^5',
                '2*(x^2 - 10000)^5 - 2 = 0',
                '(x^2 - 10000)^5/2 - 0.5 = 0',
                '1e-20*(x^2 - 10000)^5 - 1e-20 = 0',
                '-2*(x^2 - 10000)^5 + 2 = 0',
                '(2 + 3)*(x^2 - 10000)^5 - 5 = 0',
                '(x^2 - 10000)^5/(2 + 3) - 0.2 = 0',
            ] as $equation
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                -101.0,
                101.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );

            self::assertCount(2, $solutions, $equation);
            self::assertEqualsWithDelta(-\sqrt(10001.0), $solutions[0]->value, 1.0E-8);
            self::assertEqualsWithDelta(\sqrt(10001.0), $solutions[1]->value, 1.0E-8);
            [$left, $right] = \explode('=', $equation, 2);
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-8, $solution->residual, $equation);
                $actualResidual = \abs(
                    Math::evaluate($left, ['x' => $solution->value])
                    - Math::evaluate($right, ['x' => $solution->value]),
                );
                self::assertEqualsWithDelta($actualResidual, $solution->residual, 1.0E-15);
            }
        }

        $parameterScaled = Math::solve(
            'scale*(x^2 - 10000)^5 - scale = 0',
            'x',
            -101.0,
            101.0,
            ['scale' => 2.0],
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(2, $parameterScaled);
        self::assertEqualsWithDelta(-\sqrt(10001.0), $parameterScaled[0]->value, 1.0E-8);
        self::assertEqualsWithDelta(\sqrt(10001.0), $parameterScaled[1]->value, 1.0E-8);

        foreach (
            [
                [
                    '(x^2 - 10000)^4 - 1 = 0',
                    [-\sqrt(10001.0), -\sqrt(9999.0), \sqrt(9999.0), \sqrt(10001.0)],
                ],
                ['(x^2 - 10000)^5 - 32 = 0', [-\sqrt(10002.0), \sqrt(10002.0)]],
            ] as [$equation, $expectedRoots]
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                -101.0,
                101.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );

            self::assertCount(\count($expectedRoots), $solutions, $equation);
            foreach ($expectedRoots as $index => $expectedRoot) {
                self::assertEqualsWithDelta($expectedRoot, $solutions[$index]->value, 1.0E-8);
                self::assertLessThanOrEqual(1.0E-8, $solutions[$index]->residual, $equation);
            }
        }

        $this->expectException(InfiniteSolutionSetException::class);
        Math::solve(
            '0*(x^2 - 10000)^5 = 0',
            'x',
            -101.0,
            101.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
    }

    public function testSquareRootsWithDifferentPolynomialRadicandsReduceToPolynomial(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $cases = [
            ['sqrt(x) + sqrt(x + 1) = 3', -2.0, 4.0, [16.0 / 9.0]],
            ['sqrt(x + 1) - sqrt(x) = 0.5', -2.0, 4.0, [0.5625]],
            ['sqrt(x^2) + sqrt(x^2 + 1) = 3', -2.0, 2.0, [-4.0 / 3.0, 4.0 / 3.0]],
            ['sqrt(x) + sqrt(x + 1) = x + 1', -2.0, 4.0, [0.0, 2.3829757679062373]],
            ['2*sqrt(x) + 3*sqrt(x + 1) = 8', -2.0, 4.0, [1.9844003281845446]],
            ['sqrt(x)/2 + 3*sqrt(x + 1) = 3', -2.0, 4.0, [0.0]],
            [
                'sqrt(x + 3) + sqrt(2*x + 7) + sqrt(3*x + 13) = x + 8',
                0.9,
                1.1,
                [1.0],
            ],
            [
                'sqrt(x + 3) + sqrt(2*x + 7) + sqrt(3*x + 13) + sqrt(4*x + 21) = x + 13',
                0.9,
                1.1,
                [1.0],
            ],
            [
                'sqrt(x + 3) + sqrt(2*x + 7) + sqrt(3*x + 13) '
                    . '+ sqrt(4*x + 21) + sqrt(5*x + 31) = x + 19',
                0.9,
                1.1,
                [1.0],
            ],
            [
                'sqrt(x + 3) - sqrt(2*x + 7) + sqrt(3*x + 13) '
                    . '- sqrt(4*x + 21) + sqrt(5*x + 31) = x + 3',
                0.9,
                1.1,
                [1.0],
            ],
            [
                'sqrt(x + 3) + sqrt(2*x + 7) + sqrt(3*x + 13) '
                    . '+ sqrt(4*x + 21) + sqrt(5*x + 31) + sqrt(6*x + 43) = x + 26',
                0.9,
                1.1,
                [1.0],
            ],
            [
                'sqrt(x^2 + 3) + sqrt(2*x^2 + 7) + sqrt(3*x^2 + 13) '
                    . '+ sqrt(4*x^2 + 21) + sqrt(5*x^2 + 31) + sqrt(6*x^2 + 43) '
                    . '= x^2 + 26',
                0.9,
                1.1,
                [1.0],
            ],
            ['sqrt(x) + sqrt(x + 1) = -3', -2.0, 4.0, []],
        ];

        foreach ($cases as [$equation, $lowerBound, $upperBound, $expected]) {
            $solutions = Math::solve(
                $equation,
                'x',
                $lowerBound,
                $upperBound,
                solverOptions: $options,
            );
            self::assertCount(\count($expected), $solutions, $equation);
            foreach ($expected as $index => $root) {
                self::assertEqualsWithDelta($root, $solutions[$index]->value, 1.0E-9, $equation);
                self::assertLessThanOrEqual(1.0E-10, $solutions[$index]->residual, $equation);
            }
        }
    }

