    public function testSevenSquareRootTermsAreEliminatedWithinThePolynomialDegreeLimit(): void
    {
        $radicands = [];
        $target = 0.0;
        for ($constant = 1; $constant <= 7; ++$constant) {
            $radicands[] = 'sqrt((x - 1)^2 + ' . $constant . ')';
            $target += \sqrt((float) $constant);
        }

        $solutions = Math::solve(
            \implode(' + ', $radicands) . ' = ' . \sprintf('%.17g', $target),
            'x',
            -2.0,
            4.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(1, $solutions);
        self::assertSame(1.0, $solutions[0]->value);
        self::assertSame(0.0, $solutions[0]->residual);
    }

