    public function testKnownCompositeIdentitiesReportInfiniteSolutionSets(): void
    {
        foreach (
            [
                'sin(x)^2 + cos(x)^2 = 1',
                '1 = cos(x + 1)^2 + sin(x + 1)^2',
                'sin(-x)^2 + cos(x)^2 = 1',
                'sin(x)^2 + cos(-x)^2 = 1',
                'sin(x + 1)^2 + cos(-x - 1)^2 = 1',
                'sqrt(x^2) = abs(x)',
                'abs(x) = sqrt(x^2)',
                'sqrt(x^2 + 1) = sqrt(x^2 + 1)',
                'sqrt(x)^2 = x',
                'sqrt(x + 1)^2 = x + 1',
                'x = sqrt(x)^2',
                'cbrt(x)^3 = x',
                'root(x, 5)^5 = x',
                'root(x + 1, 4)^4 = x + 1',
                'ln(x) = ln(x)',
                'abs(x) = x*sign(x)',
                'x*sign(x) = abs(x)',
                'sign(x) = x/abs(x)',
            ] as $equation
        ) {
            try {
                Math::solve(
                    $equation,
                    'x',
                    -2.0,
                    2.0,
                    solverOptions: new SolverOptions(scanSteps: 1),
                );
                self::fail('Expected a proven identity to have infinitely many solutions: ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::addToAssertionCount(1);
            }
        }

        foreach (
            [
                'sin(x)^2 + cos(2*x)^2 = 1',
                'sin(x + 1)^2 + cos(-x)^2 = 1',
                'sin(x)^2 + cos(x)^2 = 0',
            ] as $equation
        ) {
            try {
                Math::solve(
                    $equation,
                    'x',
                    -2.0,
                    2.0,
                    solverOptions: new SolverOptions(scanSteps: 1),
                );
            } catch (InfiniteSolutionSetException $exception) {
                self::fail('Expected the identity matcher not to claim this equation is an identity: ' . $equation);
            } catch (\DomainException) {
                self::addToAssertionCount(1);
            }
        }

        self::assertSame(
            [],
            Math::solve(
                'ln(-x^2 - 1) = ln(-x^2 - 1)',
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
        self::assertSame(
            [],
            Math::solve(
                'sqrt(x)^2 = x',
                'x',
                -2.0,
                -0.1,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
        self::assertSame(
            [],
            Math::solve(
                'root(x, 4)^4 = x',
                'x',
                -2.0,
                -0.1,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
        self::assertSame(
            [0.0],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve(
                    'abs(x) = x*sign(0)',
                    'x',
                    -2.0,
                    2.0,
                    solverOptions: new SolverOptions(scanSteps: 1),
                ),
            ),
        );
    }

