    public function testUnboundedIdenticallyUndefinedPolynomialFunctionsReturnNoSolutions(): void
    {
        self::assertSame(
            [],
            Math::solve('ln(-x^2 - 1) = ln(-x^2 - 1)', 'x', -\INF, \INF),
        );
        self::assertSame(
            [],
            Math::solve('sqrt(-x^2 - 1) = sqrt(-x^2 - 1)', 'x', -\INF, \INF),
        );
        self::assertSame(
            [],
            Math::solve('ln(-x^4 - x^2 - 1) = ln(-x^4 - x^2 - 1)', 'x', -\INF, \INF),
        );
        self::assertSame(
            [],
            Math::solve('sqrt(-x^4 - x^2 - 1) = sqrt(-x^4 - x^2 - 1)', 'x', -\INF, \INF),
        );
        self::assertSame(
            [],
            Math::solve('ln(-exp(x^2)) = ln(-exp(x^2))', 'x', -\INF, \INF),
        );
        self::assertSame(
            [],
            Math::solve('ln(-cosh(x)) = ln(-cosh(x))', 'x', -\INF, \INF),
        );
        self::expectException(\InvalidArgumentException::class);
        Math::solve('ln(-exp(ln(x))) = ln(-exp(ln(x)))', 'x', -\INF, \INF);
    }

    public function testUnboundedPolynomialDomainProofPreservesTinyPositiveMaximum(): void
    {
        foreach (['1e-16', '1e-20', '1e-30'] as $positiveMaximum) {
            $argument = '-x^2 + 2*x - 1 + ' . $positiveMaximum;
            foreach (['ln', 'sqrt'] as $function) {
                try {
                    Math::solve(
                        $function . '(' . $argument . ') = ' . $function . '(' . $argument . ')',
                        'x',
                        -\INF,
                        \INF,
                    );
                    self::fail('Expected an identity on the positive function domain.');
                } catch (InfiniteSolutionSetException) {
                    self::addToAssertionCount(1);
                }
            }

            $negativeArgument = '-x^2 + 2*x - 1 - ' . $positiveMaximum;
            foreach (['ln', 'sqrt'] as $function) {
                self::assertSame(
                    [],
                    Math::solve(
                        $function . '(' . $negativeArgument . ') = ' . $function . '(' . $negativeArgument . ')',
                        'x',
                        -\INF,
                        \INF,
                    ),
                );
            }
        }

        $parameterized = 'ln(-x^2 + 2*x - 1 + epsilon) = ln(-x^2 + 2*x - 1 + epsilon)';
        try {
            Math::solve($parameterized, 'x', -\INF, \INF, ['epsilon' => 1.0E-20]);
            self::fail('Expected an identity on the parameterized positive logarithm domain.');
        } catch (InfiniteSolutionSetException) {
            self::addToAssertionCount(1);
        }
        self::assertSame(
            [],
            Math::solve(
                $parameterized,
                'x',
                -\INF,
                \INF,
                ['epsilon' => -1.0E-20],
            ),
        );

        $shiftedQuadratic = '-x^2 + 2*a*x - a^2 + epsilon';
        foreach ([\sqrt(2.0), 1.0E100] as $center) {
            foreach (['ln', 'sqrt'] as $function) {
                $equation = $function . '(' . $shiftedQuadratic . ') = '
                    . $function . '(' . $shiftedQuadratic . ')';
                try {
                    Math::solve(
                        $equation,
                        'x',
                        -\INF,
                        \INF,
                        ['a' => $center, 'epsilon' => 1.0E-20],
                    );
                    self::fail('Expected a nonempty domain around the critical point.');
                } catch (InfiniteSolutionSetException) {
                    self::addToAssertionCount(1);
                }
            }
            foreach (['ln', 'sqrt'] as $function) {
                self::assertSame(
                    [],
                    Math::solve(
                        $function . '(' . $shiftedQuadratic . ') = '
                            . $function . '(' . $shiftedQuadratic . ')',
                        'x',
                        -\INF,
                        \INF,
                        ['a' => $center, 'epsilon' => -1.0E-20],
                    ),
                );
            }
        }
    }

    public function testAbsoluteValueBranchIdentitiesRespectTargetSignAndInterval(): void
    {
