    public function testThreeDistinctRationalRootDegreesFindOffGridStationaryRoot(): void
    {
        $expectedRoot = 1.23456789;
        $fifthRootCoefficient = (
            (1.0 / (2.0 * \sqrt($expectedRoot + 3.0)))
            + (1.0 / (3.0 * (($expectedRoot + 7.0) ** (2.0 / 3.0))))
        ) * 5.0 * (($expectedRoot + 31.0) ** (4.0 / 5.0));
        $target = \sqrt($expectedRoot + 3.0)
            + (($expectedRoot + 7.0) ** (1.0 / 3.0))
            - ($fifthRootCoefficient * (($expectedRoot + 31.0) ** (1.0 / 5.0)));
        $equation = \sprintf(
            'sqrt(x + 3) + cbrt(x + 7) - %.17g*root(x + 31, 5) = %.17g',
            $fifthRootCoefficient,
            $target,
        );
        $solutions = Math::solve(
            $equation,
            'x',
            0.0,
            4.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(1, $solutions, $equation);
        self::assertEqualsWithDelta($expectedRoot, $solutions[0]->value, 1.0E-8, $equation);
        self::assertLessThanOrEqual(1.0E-12, $solutions[0]->residual, $equation);
    }

    public function testRationalRootEliminationSupportsDegreesAboveTwelve(): void
    {
        $expectedStationaryRoot = 1.0;
        $coefficient = (
            (1.0 / (2.0 * \sqrt($expectedStationaryRoot + 1.0)))
            + (1.0 / (3.0 * (($expectedStationaryRoot + 2.0) ** (2.0 / 3.0))))
        ) * 13.0 * (($expectedStationaryRoot + 3.0) ** (12.0 / 13.0));
        $target = \sqrt($expectedStationaryRoot + 1.0)
            + (($expectedStationaryRoot + 2.0) ** (1.0 / 3.0))
            - ($coefficient * (($expectedStationaryRoot + 3.0) ** (1.0 / 13.0)));
        $equation = \sprintf(
            'sqrt(x + 1) + cbrt(x + 2) - %.17g*root(x + 3, 13) = %.17g',
            $coefficient,
            $target,
        );
        $solutions = Math::solve(
            $equation,
            'x',
            0.0,
            4.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(2, $solutions, $equation);
        self::assertEqualsWithDelta($expectedStationaryRoot, $solutions[0]->value, 1.0E-7, $equation);
        self::assertEqualsWithDelta(1.80132429, $solutions[1]->value, 1.0E-7, $equation);
        foreach ($solutions as $solution) {
            self::assertLessThanOrEqual(1.0E-10, $solution->residual, $equation);
        }
    }

    public function testRationalRootEliminationSupportsMaximumDegreeBudget(): void
    {
        $expectedStationaryRoot = 1.0;
        $degree = 26.0;
        $coefficient = (
            (1.0 / (2.0 * \sqrt($expectedStationaryRoot + 1.0)))
            + (1.0 / (2.0 * \sqrt($expectedStationaryRoot + 2.0)))
        ) * $degree * (($expectedStationaryRoot + 3.0) ** (($degree - 1.0) / $degree));
        $target = \sqrt($expectedStationaryRoot + 1.0)
            + \sqrt($expectedStationaryRoot + 2.0)
            - ($coefficient * (($expectedStationaryRoot + 3.0) ** (1.0 / $degree)));
        $equation = \sprintf(
            'sqrt(x + 1) + sqrt(x + 2) - %.17g*root(x + 3, 26) = %.17g',
            $coefficient,
            $target,
        );
        $solutions = Math::solve(
            $equation,
            'x',
            0.0,
            4.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertNotEmpty($solutions, $equation);
        $nearest = $solutions[0];
        foreach ($solutions as $solution) {
            if (\abs($solution->value - $expectedStationaryRoot) < \abs($nearest->value - $expectedStationaryRoot)) {
                $nearest = $solution;
            }
        }
        self::assertEqualsWithDelta($expectedStationaryRoot, $nearest->value, 1.0E-6, $equation);
        foreach ($solutions as $solution) {
            self::assertLessThanOrEqual(1.0E-10, $solution->residual, $equation);
        }
    }

