        self::assertLessThanOrEqual(1.0E-10, $solutions[0]->residual, $equation);
    }

    public function testThreeDistinctRationalRootDegreesFindSimpleRoot(): void
    {
        $target = \sqrt(2.0) + (3.0 ** (1.0 / 3.0)) + (4.0 ** (1.0 / 5.0));
        $equation = \sprintf(
            'sqrt(x + 1) + cbrt(x + 2) + root(x + 3, 5) = %.17g',
            $target,
        );
