    public function testFourRationalSquareRootsFindOffGridTangentRoot(): void
    {
        $expectedRoot = 1.0;
        $fourthRootCoefficient = (
            (1.0 / (2.0 * \sqrt($expectedRoot + 1.0)))
            + (1.0 / (2.0 * \sqrt($expectedRoot + 2.0)))
            + (1.0 / (2.0 * \sqrt($expectedRoot + 3.0)))
        ) * 2.0 * \sqrt($expectedRoot + 4.0);
        $target = \sqrt($expectedRoot + 1.0)
            + \sqrt($expectedRoot + 2.0)
            + \sqrt($expectedRoot + 3.0)
            - ($fourthRootCoefficient * \sqrt($expectedRoot + 4.0));
        $equation = \sprintf(
            'sqrt(x + 1) + sqrt(x + 2) + sqrt(x + 3) - %.17g*sqrt(x + 4) = %.17g',
            $fourthRootCoefficient,
            $target,
        );
        $solutions = Math::solve(
            $equation,
            'x',
            0.0,
            4.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(1, $solutions, $equation);
        self::assertEqualsWithDelta($expectedRoot, $solutions[0]->value, 1.0E-8, $equation);
        self::assertLessThanOrEqual(1.0E-12, $solutions[0]->residual, $equation);
    }

    public function testFiveRationalSquareRootsFindCloseTangentRoots(): void
    {
        $expectedRoot = 1.0;
        $fifthRootCoefficient = 0.0;
        $target = 0.0;
        for ($offset = 1; $offset <= 4; ++$offset) {
            $root = \sqrt($expectedRoot + $offset);
            $fifthRootCoefficient += 1.0 / (2.0 * $root);
            $target += $root;
        }
        $fifthRootCoefficient *= 2.0 * \sqrt($expectedRoot + 5.0);
        $target -= $fifthRootCoefficient * \sqrt($expectedRoot + 5.0);
        $equation = \sprintf(
            'sqrt(x + 1) + sqrt(x + 2) + sqrt(x + 3) + sqrt(x + 4) - %.17g*sqrt(x + 5) = %.17g',
            $fifthRootCoefficient,
            $target,
        );
        $solutions = Math::solve(
            $equation,
            'x',
            0.0,
            4.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(2, $solutions, $equation);
        self::assertEqualsWithDelta($expectedRoot, ($solutions[0]->value + $solutions[1]->value) / 2.0, 1.0E-6, $equation);
        foreach ($solutions as $solution) {
            self::assertEqualsWithDelta($expectedRoot, $solution->value, 1.0E-3, $equation);
            self::assertLessThanOrEqual(1.0E-9, $solution->residual, $equation);
        }
    }

