        ) {
            self::assertEqualsWithDelta(
                $expected,
                $parameterizedRadicalRoots[$index]->value,
                1.0E-9,
            );
            self::assertLessThanOrEqual(
                1.0E-10,
                $parameterizedRadicalRoots[$index]->residual,
            );
        }
