    public function testAdditiveRadicalDifferencesPreserveExactInverseLevels(): void
    {
        foreach (
            [
                'sqrt(x) - sqrt(2) = 0',
                'sqrt(2) - sqrt(x) = 0',
                '(sqrt(x) - sqrt(2))^2 = 0',
            ] as $equation
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                0.01,
                10.0,
                solverOptions: new SolverOptions(scanSteps: 8),
            );

            self::assertCount(1, $solutions, $equation);
            self::assertSame(2.0, $solutions[0]->value, $equation);
            self::assertSame(0.0, $solutions[0]->residual, $equation);
        }
    }

    public function testConstantIrrationalPowersReduceToPositiveBaseLevels(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $positivePower = Math::solve('x^sqrt(2) = 4', 'x', -5.0, 5.0, solverOptions: $options);
        $reversedPower = Math::solve('4 = x^sqrt(2)', 'x', -5.0, 5.0, solverOptions: $options);
        $negativePower = Math::solve('x^(-sqrt(2)) = 4', 'x', -5.0, 5.0, solverOptions: $options);
        $shiftedPower = Math::solve('(x - 1)^sqrt(2) = 4', 'x', -5.0, 5.0, solverOptions: $options);
        $zeroTarget = Math::solve('x^sqrt(2) = 0', 'x', -5.0, 5.0, solverOptions: $options);
        $negativePowerZeroTarget = Math::solve(
            'x^(-sqrt(2)) = 0',
            'x',
            -5.0,
            5.0,
            solverOptions: $options,
        );
        $shiftedZeroTarget = Math::solve('(x - 1)^sqrt(2) = 0', 'x', -5.0, 5.0, solverOptions: $options);
        $selfPower = Math::solve('x^sqrt(2) = x', 'x', -5.0, 5.0, solverOptions: $options);
        $negativeSelfPower = Math::solve('x^(-sqrt(2)) = x', 'x', -5.0, 5.0, solverOptions: $options);
        $absolutePower = Math::solve('|x|^sqrt(2) = 4', 'x', -5.0, 5.0, solverOptions: $options);
        $absoluteSelfPower = Math::solve('|x|^sqrt(2) = |x|', 'x', -5.0, 5.0, solverOptions: $options);
        $negativeAbsoluteSelfPower = Math::solve(
            '|x|^(-sqrt(2)) = |x|',
            'x',
            -5.0,
            5.0,
            solverOptions: $options,
        );
        $squareRootPower = Math::solve('sqrt(x)^sqrt(2) = 4', 'x', -5.0, 8.0, solverOptions: $options);
        $logarithmPower = Math::solve('ln(x)^sqrt(2) = 1', 'x', -5.0, 8.0, solverOptions: $options);
        $parameterPower = Math::solve(
            'x^a = 4',
            'x',
            -5.0,
            5.0,
            parameters: ['a' => \sqrt(2.0)],
            solverOptions: $options,
        );

        self::assertCount(1, $positivePower);
        self::assertEqualsWithDelta(4.0 ** (1.0 / \sqrt(2.0)), $positivePower[0]->value, 1.0E-12);
        self::assertSame($positivePower[0]->value, $reversedPower[0]->value);
        self::assertEqualsWithDelta(4.0 ** (-1.0 / \sqrt(2.0)), $negativePower[0]->value, 1.0E-12);
        self::assertEqualsWithDelta(1.0 + (4.0 ** (1.0 / \sqrt(2.0))), $shiftedPower[0]->value, 1.0E-12);
        self::assertSame(0.0, $zeroTarget[0]->value);
        self::assertSame([], $negativePowerZeroTarget);
        self::assertSame(1.0, $shiftedZeroTarget[0]->value);
        self::assertSame([0.0, 1.0], \array_map(static fn (EquationSolution $solution): float => $solution->value, $selfPower));
        self::assertSame([1.0], \array_map(static fn (EquationSolution $solution): float => $solution->value, $negativeSelfPower));
        self::assertSame(
            [-4.0 ** (1.0 / \sqrt(2.0)), 4.0 ** (1.0 / \sqrt(2.0))],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $absolutePower),
        );
        self::assertSame([-1.0, 0.0, 1.0], \array_map(
            static fn (EquationSolution $solution): float => $solution->value,
            $absoluteSelfPower,
        ));
        self::assertSame([-1.0, 1.0], \array_map(
            static fn (EquationSolution $solution): float => $solution->value,
            $negativeAbsoluteSelfPower,
        ));
        self::assertEqualsWithDelta(4.0 ** \sqrt(2.0), $squareRootPower[0]->value, 1.0E-12);
        self::assertEqualsWithDelta(\M_E, $logarithmPower[0]->value, 1.0E-12);
        self::assertSame($positivePower[0]->value, $parameterPower[0]->value);
        self::assertSame([], Math::solve('x^sqrt(2) = -4', 'x', -5.0, 5.0, solverOptions: $options));
        foreach (
            [
                $positivePower,
                $reversedPower,
                $negativePower,
                $shiftedPower,
                $zeroTarget,
                $shiftedZeroTarget,
                $selfPower,
                $negativeSelfPower,
                $parameterPower,
            ]
            as $solutions
        ) {
            self::assertLessThanOrEqual(1.0E-12, $solutions[0]->residual);
        }
        try {
            Math::solve('2^sqrt(2) = 4', 'x', -5.0, 5.0, solverOptions: $options);
            self::fail('A constant equation must still report its missing solved variable.');
        } catch (\InvalidArgumentException $exception) {
            self::assertStringContainsString('does not contain the solved variable', $exception->getMessage());
        }
    }

    public function testRationalPowerEquationsPreserveOddDenominatorBranchParity(): void
    {
        $cases = [
            ['x^(5/3) = -32', -10.0, 10.0, -8.0],
            ['x^(3/5) = -32', -500.0, 500.0, -(32.0 ** (5.0 / 3.0))],
            ['x^(4/3) = 16', -10.0, 10.0, -8.0],
            ['x^(4/3) = 16', -10.0, 10.0, 8.0],
        ];
        foreach ($cases as [$equation, $lowerBound, $upperBound, $expectedRoot]) {
            $solutions = Math::solve(
                $equation,
                'x',
                $lowerBound,
                $upperBound,
                solverOptions: new SolverOptions(scanSteps: 1),
            );

            $matches = \array_filter(
                $solutions,
                static fn (EquationSolution $solution): bool =>
                    \abs($solution->value - $expectedRoot) <= 1.0E-9 * \max(1.0, \abs($expectedRoot)),
            );
            self::assertNotEmpty($matches, $equation);
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-9, $solution->residual, $equation);
            }
        }
        self::assertSame(
            [],
            Math::solve('x^(3/2) = -8', 'x', -20.0, 20.0),
        );
    }

