    public function testSolvesErrorFunctionsOfPolynomialsAtCoarseScanResolution(): void
    {
        $target = \sprintf('%.17g', Math::evaluate('erf(0.75)'));
        $complementaryTarget = \sprintf('%.17g', Math::evaluate('erfc(0.75)'));
        $options = new SolverOptions(scanSteps: 1);
        $errorRoots = Math::solve(
            'erf(x^2) = ' . $target,
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $complementaryRoots = Math::solve(
            'erfc(x^2) = ' . $complementaryTarget,
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $zeroError = Math::solve(
            'erf(x) = 0',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        $unitComplementaryError = Math::solve(
            'erfc(x) = 1',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        $impossibleErrorTarget = Math::solve(
            'erf(x^2) = 2',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );

        foreach ([$errorRoots, $complementaryRoots] as $solutions) {
            self::assertCount(2, $solutions);
            self::assertEqualsWithDelta(-\sqrt(0.75), $solutions[0]->value, 1.0E-8);
            self::assertEqualsWithDelta(\sqrt(0.75), $solutions[1]->value, 1.0E-8);
        }
        self::assertCount(1, $zeroError);
        self::assertSame(0.0, $zeroError[0]->value);
        self::assertCount(1, $unitComplementaryError);
        self::assertSame(0.0, $unitComplementaryError[0]->value);
        self::assertSame([], $impossibleErrorTarget);
    }

