    public function testErrorIntegralFunctionsInvertBoundedTrigonometricArguments(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $cases = [
            ['erfi(sin(x)) = erfi(0.5)', 0.5],
            ['erfcx(sin(x)) = erfcx(0.5)', 0.5],
            ['dawson(sin(x)) = dawson(0.5)', 0.5],
        ];

        foreach ($cases as [$equation, $expectedArgument]) {
            $solutions = Math::solve(
                $equation,
                'x',
                -\M_PI,
                \M_PI,
                solverOptions: $options,
            );
            self::assertCount(2, $solutions, $equation);
            self::assertEqualsWithDelta(\asin($expectedArgument), $solutions[0]->value, 1.0E-9);
            self::assertEqualsWithDelta(\M_PI - \asin($expectedArgument), $solutions[1]->value, 1.0E-9);
        }

        $dawsonBranches = Math::solve(
            'dawson(2 * sin(x)) = dawson(0.5)',
            'x',
            -\M_PI_2,
            \M_PI_2,
            solverOptions: $options,
        );
        self::assertCount(2, $dawsonBranches);
        self::assertEqualsWithDelta(\asin(0.25), $dawsonBranches[0]->value, 1.0E-9);
        self::assertEqualsWithDelta(\asin(0.75669530555), $dawsonBranches[1]->value, 1.0E-8);

        $zeroLevels = [
            'erfi(sin(x)) = 0',
            'dawson(sin(x)) = 0',
        ];
        foreach ($zeroLevels as $equation) {
            $solutions = Math::solve(
                $equation,
                'x',
                -\M_PI,
                \M_PI,
                solverOptions: $options,
            );
            self::assertCount(3, $solutions, $equation);
            self::assertEqualsWithDelta([-\M_PI, 0.0, \M_PI], \array_map(
                static fn ($solution): float => $solution->value,
                $solutions,
            ), 1.0E-9);
        }

        foreach (
            [
                'erf(sin(x)) = erf(0.5)' => 0.5,
                'erfc(sin(x)) = erfc(0.5)' => 0.5,
                'erfinv(sin(x)) = 0.5' => SpecialFunctions::erf(0.5),
                'erfcinv(sin(x)) = 0.5' => SpecialFunctions::erfc(0.5),
            ] as $equation => $innerLevel
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                -\M_PI,
                \M_PI,
                solverOptions: $options,
            );
            self::assertCount(2, $solutions, $equation);
            self::assertEqualsWithDelta(\asin($innerLevel), $solutions[0]->value, 1.0E-9);
            self::assertEqualsWithDelta(\M_PI - \asin($innerLevel), $solutions[1]->value, 1.0E-9);
        }
    }

    public function testMonotoneElementaryFunctionsInvertBoundedTrigonometricArguments(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $gammaLevel = Math::evaluate('gammainc(2, 1.5)');
        $gammaComplementLevel = Math::evaluate('gammaincc(2, 1.5)');
        $betaLevel = Math::evaluate('betainc(2, 3, 0.75)');
        $betaComplementLevel = Math::evaluate('betaincc(2, 3, 0.75)');
        $cases = [
            'exp(sin(x)) = exp(0.5)' => 0.5,
            'expm1(sin(x)) = expm1(0.5)' => 0.5,
            'ln(1 + sin(x)) = ln(1.5)' => 0.5,
            'log(1 + sin(x), 2) = log(1.5, 2)' => 0.5,
            'root(sin(x), 3) = root(0.5, 3)' => 0.5,
            'sqrt(1 + sin(x)) = sqrt(1.5)' => 0.5,
            'cbrt(sin(x)) = cbrt(0.5)' => 0.5,
            'tanh(sin(x)) = tanh(0.5)' => 0.5,
            'asinh(sin(x)) = asinh(0.5)' => 0.5,
            'acosh(1 + sin(x)) = acosh(1.5)' => 0.5,
            'atanh(sin(x) / 2) = atanh(0.25)' => 0.5,
            'asech(0.5 + 0.5 * sin(x)) = asech(0.75)' => 0.5,
            'acsch(2 + sin(x)) = acsch(2.5)' => 0.5,
            'acoth(2 + sin(x)) = acoth(2.5)' => 0.5,
            'erfi(sin(x)) = erfi(0.5)' => 0.5,
            'atan(sin(x)) = atan(0.5)' => 0.5,
            'asin(sin(x)) = asin(0.5)' => 0.5,
            'gammainc(2, 1 + sin(x)) = gammainc(2, 1.5)' => 0.5,
            'gammaincc(2, 1 + sin(x)) = gammaincc(2, 1.5)' => 0.5,
            'betainc(2, 3, 0.5 + 0.5 * sin(x)) = betainc(2, 3, 0.75)' => 0.5,
            'betaincc(2, 3, 0.5 + 0.5 * sin(x)) = betaincc(2, 3, 0.75)' => 0.5,
            'gammaincinv(2, 0.5 + 0.5 * sin(x)) = 1.5' => 2.0 * $gammaLevel - 1.0,
            'gammainccinv(2, 0.5 + 0.5 * sin(x)) = 1.5' => 2.0 * $gammaComplementLevel - 1.0,
            'betaincinv(2, 3, 0.5 + 0.5 * sin(x)) = 0.75' => 2.0 * $betaLevel - 1.0,
            'betainccinv(2, 3, 0.5 + 0.5 * sin(x)) = 0.75' => 2.0 * $betaComplementLevel - 1.0,
            'digamma(2 + sin(x)) = digamma(2.5)' => 0.5,
            'trigamma(2 + sin(x)) = trigamma(2.5)' => 0.5,
            'tetragamma(2 + sin(x)) = tetragamma(2.5)' => 0.5,
            'polygamma(3, 2 + sin(x)) = polygamma(3, 2.5)' => 0.5,
            'polygamma(2, 2 + sin(x)) = polygamma(2, 2.5)' => 0.5,
            'polygamma(4, 2 + sin(x)) = polygamma(4, 2.5)' => 0.5,
            'zeta(2.25 + 0.75 * sin(x)) = zeta(2.5)' => 1.0 / 3.0,
            'lambertw(sin(x)) = -0.5' => -0.5 * \exp(-0.5),
            'lambertw(sin(x), -1) = -2' => -2.0 * \exp(-2.0),
            'lambertw(sin(x)) = -1' => -1.0 / \M_E,
            'lambertw(sin(x), -1) = -1' => -1.0 / \M_E,
        ];

        foreach ($cases as $equation => $innerLevel) {
            $solutions = Math::solve(
                $equation,
                'x',
                -\M_PI,
                \M_PI,
                solverOptions: $options,
            );
            $principal = \asin($innerLevel);
            $expectedValues = $innerLevel < 0.0
                ? [-\M_PI - $principal, $principal]
                : [$principal, \M_PI - $principal];

            self::assertCount(2, $solutions, $equation);
            self::assertEqualsWithDelta($expectedValues[0], $solutions[0]->value, 1.0E-9);
            self::assertEqualsWithDelta($expectedValues[1], $solutions[1]->value, 1.0E-9);
        }
    }

    public function testZetaEqualitiesCancelArgumentsOnlyAboveOne(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $shifted = Math::solve(
            'zeta(x + 2) = zeta(2.5)',
            'x',
            0.0,
            4.0,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [0.5],
            \array_map(static fn ($solution): float => $solution->value, $shifted),
            1.0E-10,
        );

        $quadratic = Math::solve(
            'zeta(2 + (x - 0.5)^2) = zeta(2.25)',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [0.0, 1.0],
            \array_map(static fn ($solution): float => $solution->value, $quadratic),
            1.0E-10,
        );

        self::assertEqualsWithDelta(
            [-0.87672621539833, 0.0, 0.87672621539833],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve('abs(min(x^2, 2)) = abs(sin(x))', 'x', -\INF, \INF),
            ),
            1.0E-8,
        );
    }

    public function testCoshAndSechEqualitiesRequireBothArgumentsToVanish(): void
    {
        foreach (
            [
                ['cosh(x + 1) = sech(2*x + 2)', [-1.0]],
                ['sech(2*x + 2) = cosh(x + 1)', [-1.0]],
            ] as [$equation, $expected]
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                -3.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                $expected,
                \array_map(static fn ($solution): float => $solution->value, $solutions),
                1.0E-10,
                $equation,
            );
        }

        self::assertSame([], Math::solve(
            'cosh(x) = sech(x + 1)',
            'x',
            -3.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        ));

        $oneIdenticallyZeroArgument = Math::solve(
            'cosh(x - x) = sech(x)',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertEqualsWithDelta(
            [0.0],
            \array_map(static fn ($solution): float => $solution->value, $oneIdenticallyZeroArgument),
            1.0E-10,
        );

        $this->expectException(InfiniteSolutionSetException::class);
        Math::solve(
            'cosh(x - x) = sech(x - x)',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
    }

    public function testEqualEvenHyperbolicFunctionsReduceToSignedArgumentRelations(): void
    {
