        self::assertEqualsWithDelta(
            [-1.0, 1.0],
            \array_map(static fn ($solution): float => $solution->value, $sechRoots),
            1.0E-10,
        );

        $this->expectException(InfiniteSolutionSetException::class);
        Math::solve('cosh(x) = cosh(-x)', 'x', -2.0, 2.0, solverOptions: $options);
    }

    public function testAbsoluteSpecialFunctionEqualitiesReduceOnMonotoneRanges(): void
    {
        foreach (['gamma', 'lgamma'] as $function) {
            $solutions = Math::solve(
                $function . '(x + 2) = ' . $function . '(2*x + 1)',
                'x',
                1.0,
                4.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [1.0],
                \array_map(static fn ($solution): float => $solution->value, $solutions),
                1.0E-10,
                $function,
            );
        }

        foreach (['gamma', 'lgamma'] as $function) {
            $boundaryRoot = Math::solve(
                $function . '(x + 2) = ' . $function . '(0.5*x + 2.5)',
                'x',
                0.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [1.0],
                \array_map(static fn ($solution): float => $solution->value, $boundaryRoot),
                1.0E-10,
                $function . ' at argument 2',
            );
        }

        foreach (['gamma', 'lgamma'] as $function) {
            $boundaryRoot = Math::solve(
                $function . '(x + 1.5) = ' . $function . '(0.5*x + 2)',
                'x',
                0.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [1.0],
                \array_map(static fn ($solution): float => $solution->value, $boundaryRoot),
                1.0E-10,
                $function . ' at argument 3/2',
            );
        }

        $nonMonotoneRange = Math::solve(
            'gamma(x) = gamma(3 - x)',
            'x',
            1.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertEqualsWithDelta(
            [1.0, 1.5, 2.0],
            \array_map(static fn ($solution): float => $solution->value, $nonMonotoneRange),
            1.0E-8,
        );

        foreach (
            [
                ['abs(gamma(x + 1.5)) = abs(gamma(0.5*x + 2))', 'gamma'],
                ['abs(lgamma(x + 2)) = abs(lgamma(0.5*x + 2.5))', 'lgamma'],
                ['abs(digamma(x + 1.5)) = abs(digamma(0.5*x + 2))', 'digamma'],
                ['abs(trigamma(x + 1)) = abs(trigamma(0.5*x + 1.5))', 'trigamma'],
                ['abs(tetragamma(x + 1)) = abs(tetragamma(0.5*x + 1.5))', 'tetragamma'],
                [
                    'abs(polygamma(0, x + 1.5)) = abs(digamma(0.5*x + 2))',
                    'polygamma(0)/digamma',
                ],
                [
                    'abs(polygamma(1, x + 1)) = abs(trigamma(0.5*x + 1.5))',
                    'polygamma(1)/trigamma',
                ],
                [
                    'abs(polygamma(3, x + 1)) = abs(polygamma(3, 0.5*x + 1.5))',
                    'polygamma(3)',
                ],
            ] as [$equation, $function]
        ) {
            $absoluteSolutions = Math::solve(
                $equation,
                'x',
                0.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [1.0],
                \array_map(static fn ($solution): float => $solution->value, $absoluteSolutions),
                1.0E-10,
                'abs(' . $function . ')',
            );
        }
    }

    public function testAbsoluteEqualitiesOfOddInjectiveFunctionsUseBothArgumentSigns(): void
    {
        foreach (
            [
                ['abs(sinh(x)) = abs(sinh(2*x + 1))', [-1.0, -1.0 / 3.0]],
                ['abs(tanh(x)) = abs(tanh(2*x + 1))', [-1.0, -1.0 / 3.0]],
                ['abs(asinh(x)) = abs(arcsinh(2*x + 1))', [-1.0, -1.0 / 3.0]],
                ['abs(atan(x)) = abs(arctan(2*x + 1))', [-1.0, -1.0 / 3.0]],
                ['abs(asin(0.5*x)) = abs(arcsin(0.25*x + 0.25))', [-1.0 / 3.0, 1.0]],
                ['abs(atanh(0.5*x)) = abs(arctanh(0.25*x + 0.25))', [-1.0 / 3.0, 1.0]],
                ['abs(erfinv(0.5*x)) = abs(erfinv(0.25*x + 0.25))', [-1.0 / 3.0, 1.0]],
                ['abs(erfcinv(x)) = abs(erfcinv(2*x))', [2.0 / 3.0]],
                ['abs(acot(x)) = abs(acot(2*x + 1))', [-1.0]],
                ['abs(acos(x)) = abs(arccos(2*x + 1))', [-1.0]],
                ['abs(acosh(x + 2)) = abs(acosh(2*x + 1))', [1.0]],
                ['abs(asec(x + 3)) = abs(asec(2*x + 2))', [1.0]],
                ['abs(asech(0.25*x + 0.5)) = abs(asech(0.125*x + 0.625))', [1.0]],
                ['abs(sqrt(x + 2)) = abs(sqrt(2*x + 1))', [1.0]],
                ['abs(sqrt(x^2)) = abs(sqrt(2*x + 1))', [1.0 - \sqrt(2.0)]],
                ['abs(acsc(x)) = abs(acsc(2*x + 1))', [-1.0]],
                ['abs(erf(x)) = abs(erf(2*x + 1))', [-1.0, -1.0 / 3.0]],
                ['abs(erfi(x)) = abs(erfi(2*x + 1))', [-1.0, -1.0 / 3.0]],
                ['abs(cbrt(x)) = abs(cbrt(2*x + 1))', [-1.0, -1.0 / 3.0]],
                ['abs(csch(x)) = abs(csch(2*x + 1))', [-1.0, -1.0 / 3.0]],
                ['abs(coth(x)) = abs(coth(2*x + 1))', [-1.0, -1.0 / 3.0]],
                ['abs(acsch(x)) = abs(acsch(2*x + 1))', [-1.0, -1.0 / 3.0]],
                ['abs(acoth(x + 3)) = abs(acoth(2*x + 2))', [-5.0 / 3.0, 1.0]],
            ] as [$equation, $expected]
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                $expected,
                \array_map(static fn ($solution): float => $solution->value, $solutions),
                1.0E-9,
                $equation,
            );
        }

        $this->expectException(InfiniteSolutionSetException::class);
        Math::solve(
            'abs(sinh(x - x)) = abs(sinh(0))',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
    }

