    public function testTrigonometricIdentitiesPreserveRemovableRationalHoles(): void
    {
        $argument = '(x^2 - 1)/(x - 1) - (x + 1)';
        $finiteIdentity = 'tan(' . $argument . ' + 1) = tan(' . $argument . ' + 1)';
        try {
            Math::solve(
                $finiteIdentity,
                'x',
                0.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::fail('An identity on a nonempty domain must report infinitely many roots.');
        } catch (InfiniteSolutionSetException) {
            self::assertTrue(true);
        }

        foreach (
            [
                'tan' => 'pi/2',
                'sec' => 'pi/2',
                'csc' => '0',
                'cot' => '0',
            ] as $function => $polePhase
        ) {
            $poleArgument = $argument . ' + ' . $polePhase;
            $poleIdentity = $function . '(' . $poleArgument . ') = '
                . $function . '(' . $poleArgument . ')';
            self::assertSame(
                [],
                Math::solve(
                    $poleIdentity,
                    'x',
                    0.0,
                    2.0,
                    solverOptions: new SolverOptions(scanSteps: 1),
                ),
                $poleIdentity,
            );
        }
    }

