    public function testEqualGammaQuantileCallsReduceToTheirProbabilityArguments(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $lower = Math::solve(
            'gammaincinv(2, x^2) = gammaincinv(1 + 1, x)',
            'x',
            0.0,
            1.0,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [0.0],
            \array_map(static fn ($solution): float => $solution->value, $lower),
            1.0E-12,
        );

        $upper = Math::solve(
            'gammainccinv(2, x^2) = gammainccinv(2, x)',
            'x',
            0.0,
            1.0,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [1.0],
            \array_map(static fn ($solution): float => $solution->value, $upper),
            1.0E-12,
        );

        $complementary = Math::solve(
            'gammaincinv(2, x) = gammainccinv(1 + 1, 0.75)',
            'x',
            0.0,
            1.0,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [0.25],
            \array_map(static fn ($solution): float => $solution->value, $complementary),
            1.0E-12,
        );

        $betaComplementary = Math::solve(
            'betaincinv(2, 3, x) = betainccinv(1 + 1, 3, 0.75)',
            'x',
            0.0,
            1.0,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [0.25],
            \array_map(static fn ($solution): float => $solution->value, $betaComplementary),
            1.0E-12,
        );

        foreach (['betaincinv', 'betainccinv'] as $function) {
            $equalCalls = Math::solve(
                $function . '(2, 3, x^2) = ' . $function . '(2, 3, x)',
                'x',
                0.0,
                1.0,
                solverOptions: $options,
            );
            self::assertEqualsWithDelta(
                [0.0, 1.0],
                \array_map(static fn ($solution): float => $solution->value, $equalCalls),
                1.0E-12,
                $function,
            );
        }
    }

