    public function testLambertWBranchPointCompositionsReportNearestDefinedResidual(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        foreach (
            [
                ['lambertw(sin(x)) = -1', 'lambertw(sin(', '))'],
                ['lambertw(sin(x), -1) = -1', 'lambertw(sin(', '), -1)'],
            ] as [$equation, $prefix, $suffix]
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                -\M_PI,
                \M_PI,
                solverOptions: $options,
            );
            self::assertEqualsWithDelta(
                [-2.7648651455312185, -0.376727508058575],
                \array_map(static fn ($solution): float => $solution->value, $solutions),
                1.0E-9,
                $equation,
            );
            foreach ($solutions as $solution) {
                $argument = \sprintf('%.17g', $solution->value);
                $evaluated = Math::evaluate($prefix . $argument . $suffix);
                self::assertSame(\abs($evaluated + 1.0), $solution->residual, $equation);
                self::assertLessThan(1.0E-7, $solution->residual, $equation);
            }
        }
    }

