        $minimumSolutions = Math::solve(
            'lgamma(2 + sin(x)) = ' . \sprintf('%.17g', $minimumTarget),
            'x',
            -\M_PI,
            \M_PI,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertEqualsWithDelta(
            [-2.5730935265205392, -0.5684991270692539],
            \array_map(static fn ($solution): float => $solution->value, $minimumSolutions),
            1.0E-8,
        );
    }

