    public function testSolvesEquationsContainingInverseErrorFunctions(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $errorInverse = Math::solve('erfinv(x) = 0.5', 'x', 0.0, 1.0, solverOptions: $options);
        $complementaryInverse = Math::solve(
            'erfcinv(x) = 0.5',
            'x',
            0.0,
            2.0,
            solverOptions: $options,
        );
        $polynomialArgument = Math::solve(
            'erfinv(x^2) = 0.5',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );

        self::assertCount(1, $errorInverse);
        self::assertEqualsWithDelta(Math::evaluate('erf(0.5)'), $errorInverse[0]->value, 1.0E-8);
        self::assertCount(1, $complementaryInverse);
        self::assertEqualsWithDelta(Math::evaluate('erfc(0.5)'), $complementaryInverse[0]->value, 1.0E-8);
        self::assertCount(2, $polynomialArgument);
        self::assertEqualsWithDelta(-\sqrt(Math::evaluate('erf(0.5)')), $polynomialArgument[0]->value, 1.0E-8);
        self::assertEqualsWithDelta(\sqrt(Math::evaluate('erf(0.5)')), $polynomialArgument[1]->value, 1.0E-8);
    }

    public function testComplementaryInverseErrorFunctionsReduceTheirArgumentsToOne(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        foreach (
            [
                ['erfinv(x) = erfcinv(0.5)', 0.5],
                ['erfcinv(0.5) = erfinv(x)', 0.5],
            ] as [$equation, $expected]
        ) {
            $roots = Math::solve($equation, 'x', -1.0, 1.0, solverOptions: $options);
            self::assertEqualsWithDelta(
                [$expected],
                \array_map(static fn ($solution): float => $solution->value, $roots),
                1.0E-10,
                $equation,
            );
        }

        $symmetricRoots = Math::solve(
            'erfinv(x^2) = erfcinv(0.5)',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [-\sqrt(0.5), \sqrt(0.5)],
            \array_map(static fn ($solution): float => $solution->value, $symmetricRoots),
            1.0E-10,
        );

        $domainFilteredRoots = Math::solve(
            'erfinv(x) = erfcinv(x^2)',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        self::assertEqualsWithDelta(
            [(-1.0 + \sqrt(5.0)) / 2.0],
            \array_map(static fn ($solution): float => $solution->value, $domainFilteredRoots),
            1.0E-10,
        );
    }

