    public function testForwardInverseIdentitiesReportInfiniteSolutionsOnPartialDomains(): void
    {
        foreach (
            [
                ['erfc(erfcinv(x)) = x', 0.0, 2.0],
                ['erfc(erfcinv(x)) = x', 0.0, 100.0],
                ['erf(erfinv(x / 2)) = x / 2', -2.0, 2.0],
                ['sin(asin(x)) = x', -2.0, 2.0],
                ['sin(asin(x)) = x', 0.0, 100.0],
                ['sin(arcsin(x)) = x', 0.0, 100.0],
                ['cos(arccos(x)) = x', 0.0, 100.0],
                ['tanh(arctanh(x)) = x', 0.0, 100.0],
                ['exp(ln(x)) = x', -2.0, 2.0],
            ] as [$equation, $lowerBound, $upperBound]
        ) {
            try {
                Math::solve(
                    $equation,
                    'x',
                    $lowerBound,
                    $upperBound,
                    solverOptions: new SolverOptions(scanSteps: 1),
                );
                self::fail('Expected an infinite solution set for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                // The identity holds on a nonempty open subset of the requested interval.
            }
        }

        self::assertSame([], Math::solve('erfc(erfcinv(x)) = x', 'x', 2.0, 3.0));
        self::assertSame([], Math::solve('erfc(erfcinv(x)) = x', 'x', 10.0, 100.0));
        self::assertSame(
            [],
            Math::solve(
                'erfc(erfcinv(x^2)) = x^2',
                'x',
                2.0,
                3.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
        self::assertSame([], Math::solve('sin(asin(x)) = x', 'x', 10.0, 100.0));
        self::assertSame([], Math::solve('sin(arcsin(x)) = x', 'x', 10.0, 100.0));
        self::assertSame([], Math::solve('tanh(arctanh(x)) = x', 'x', 10.0, 100.0));
        self::assertSame([], Math::solve('exp(ln(x)) = x', 'x', -2.0, 0.0));
    }

