    public function testUnboundedInverseRegularizedBetaPolynomialLevelsUseFiniteDomains(): void
    {
        $cases = [
            'betaincinv(2, 3, x) = x' => [0.0, 0.23240812075600273, 1.0],
            'betaincinv(2, 3, x) = 1 - x' => [0.5722055935286056],
            '1 - x = betaincinv(2, 3, x)' => [0.5722055935286056],
            'betainccinv(2, 3, x) = 2 * x' => [0.2660259172420461],
            'betaincinv(2, 3, x) = x^2' => [0.0, 0.7250754474671546, 1.0],
        ];
        foreach ($cases as $equation => $expectedRoots) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF);
            self::assertCount(\count($expectedRoots), $solutions, $equation);
            foreach ($expectedRoots as $index => $expectedRoot) {
                self::assertEqualsWithDelta($expectedRoot, $solutions[$index]->value, 1.0E-8, $equation);
            }
        }

        self::assertSame([], Math::solve('betaincinv(2, 3, x) = x', 'x', 2.0, 3.0));
        self::assertSame([], Math::solve('betainccinv(2, 3, x) = x', 'x', -3.0, -2.0));
    }

    public function testUnboundedInverseRegularizedFunctionsAcceptAffineProbabilities(): void
    {
        $cases = [
            'betaincinv(2, 3, 0.2 + 0.6*x) = 0.5' => 0.8125,
            'betainccinv(2, 3, 0.8 - 0.4*x) = 0.5' => 1.21875,
            'gammaincinv(2, 0.2 + 0.6*x) = 1' => 0.10706852942852506,
            'gammainccinv(2, 0.8 - 0.4*x) = 1' => 0.1606027941427876,
            '1 = gammaincinv(2, x)' => 1.0 - (2.0 / \M_E),
        ];
        foreach ($cases as $equation => $expectedRoot) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF);
            self::assertCount(1, $solutions, $equation);
            self::assertEqualsWithDelta($expectedRoot, $solutions[0]->value, 1.0E-8, $equation);
            self::assertLessThanOrEqual(1.0E-9, $solutions[0]->residual, $equation);
        }

