    public function testInverseRegularizedGammaEquationsInvertPolynomialArguments(): void
    {
        $probability = SpecialFunctions::regularizedGammaP(2.0, 1.0);
        $solutions = Math::solve(
            'gammaincinv(2, x^2) = 1',
            'x',
            -1.0,
            1.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(2, $solutions);
        self::assertEqualsWithDelta(-\sqrt($probability), $solutions[0]->value, 1.0E-8);
        self::assertEqualsWithDelta(\sqrt($probability), $solutions[1]->value, 1.0E-8);

        $complementary = Math::solve(
            'gammainccinv(2, x) = 1',
            'x',
            0.0,
            1.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $complementary);
        self::assertEqualsWithDelta(\exp(-1.0) * 2.0, $complementary[0]->value, 1.0E-8);
    }

