    public function testTinyInverseFunctionLevelsPreserveShiftedQuadraticRoots(): void
    {
        $target = 1.0E-18;
        foreach (
            [
                'erf((100*(x-0.12345))^2)' => ($target * \sqrt(\M_PI)) / 2.0,
                'atan((100*(x-0.12345))^2)' => \tan($target),
                'log1p((100*(x-0.12345))^2)' => \expm1($target),
                'tanh((100*(x-0.12345))^2)' => \atanh($target),
                'asinh((100*(x-0.12345))^2)' => \sinh($target),
            ] as $expression => $innerLevel
        ) {
            $solutions = Math::solve(
                $expression . '=' . \sprintf('%.17g', $target),
                'x',
                -1.0,
                1.0,
            );
            $offset = \sqrt($innerLevel) / 100.0;

            self::assertCount(2, $solutions, $expression);
            self::assertEqualsWithDelta(0.12345 - $offset, $solutions[0]->value, 1.0E-14);
            self::assertEqualsWithDelta(0.12345 + $offset, $solutions[1]->value, 1.0E-14);
            foreach ($solutions as $solution) {
                self::assertLessThan($target * 1.0E-4, $solution->residual, $expression);
            }
        }
    }

    public function testInverseErrorFunctionsResolveTinyNonzeroLevels(): void
    {
        foreach ([1.0E-200, 1.0E-300, 1.0E-320] as $target) {
            $tolerance = \max(1.0E-323, $target * 1.0E-14);
            foreach ([1.0, -1.0] as $sign) {
                $signedTarget = $sign * $target;
                $expectedRoot = ($signedTarget * \sqrt(\M_PI)) / 2.0;
                $intervals = [[-1.0, 1.0], [-10.0 * $target, 10.0 * $target]];
                foreach ($intervals as [$lowerBound, $upperBound]) {
                    $solutions = Math::solve(
                        'erf(x) = ' . \sprintf('%.17g', $signedTarget),
                        'x',
                        $lowerBound,
                        $upperBound,
                    );

                    self::assertCount(1, $solutions);
                    self::assertEqualsWithDelta(
                        $expectedRoot,
                        $solutions[0]->value,
                        $tolerance,
                    );
                    self::assertLessThanOrEqual($tolerance, $solutions[0]->residual);
                }
            }
        }

        $complementarySolutions = Math::solve('erfc(x) = 1.0e-200', 'x', 0.0, 32.0);

        self::assertCount(1, $complementarySolutions);
        self::assertGreaterThan(20.0, $complementarySolutions[0]->value);
        self::assertEqualsWithDelta(
            1.0E-200,
            Math::evaluate('erfc(x)', ['x' => $complementarySolutions[0]->value]),
            1.0E-210,
        );
    }

    public function testLogarithmicRootsUseBestRepresentablePositiveInput(): void
    {
        $solutions = Math::solve('ln(x)=-740', 'x', 0.0, 1.0);

        self::assertCount(1, $solutions);
        self::assertGreaterThan(0.0, $solutions[0]->value);
        self::assertGreaterThan(0.0, $solutions[0]->residual);
        self::assertLessThan(0.01, $solutions[0]->residual);
        self::assertSame(
            \abs(Math::evaluate('ln(x)', ['x' => $solutions[0]->value]) + 740.0),
            $solutions[0]->residual,
        );

        self::assertSame([], Math::solve('ln(x)=-800', 'x', 0.0, 1.0));
        self::assertSame([], Math::solve('ln(x)=-746', 'x', 0.0, 1.0));

        $naturalMinimum = Math::solve('ln(x)=-745', 'x', 0.0, 1.0);
        $decimalMinimum = Math::solve('log10(x)=-323', 'x', 0.0, 1.0);
        $binaryMinimum = Math::solve('log2(x)=-1074', 'x', 0.0, 1.0);
        $shiftedMinimum = Math::solve('log1p(x)=-37', 'x', -1.0, 0.0);

        self::assertCount(1, $naturalMinimum);
        self::assertSame(5.0E-324, $naturalMinimum[0]->value);
        self::assertCount(1, $decimalMinimum);
        self::assertSame(1.0E-323, $decimalMinimum[0]->value);
        self::assertCount(1, $binaryMinimum);
        self::assertSame(5.0E-324, $binaryMinimum[0]->value);
        self::assertCount(1, $shiftedMinimum);
        self::assertSame(-0.9999999999999999, $shiftedMinimum[0]->value);
        self::assertSame([], Math::solve('log1p(x)=-40', 'x', -1.0, 0.0));
    }

    public function testDistinctTinyRootsOnOppositeSidesOfZeroArePreserved(): void
    {
        $polynomialRoots = Math::solve('x^2 = 1.0e-200', 'x', -1.0E-100, 1.0E-100);
        $errorFunctionRoots = Math::solve(
            'erf(x^2) = 1.0e-200',
            'x',
            -1.0E-100,
            1.0E-100,
        );

        self::assertCount(2, $polynomialRoots);
        self::assertEqualsWithDelta(-1.0E-100, $polynomialRoots[0]->value, 1.0E-110);
        self::assertEqualsWithDelta(1.0E-100, $polynomialRoots[1]->value, 1.0E-110);

        $errorRootMagnitude = \sqrt((1.0E-200 * \sqrt(\M_PI)) / 2.0);
        self::assertCount(2, $errorFunctionRoots);
        self::assertEqualsWithDelta(-$errorRootMagnitude, $errorFunctionRoots[0]->value, 1.0E-110);
        self::assertEqualsWithDelta($errorRootMagnitude, $errorFunctionRoots[1]->value, 1.0E-110);
    }

    public function testCloselySpacedTrigonometricEqualityRootsRemainDistinct(): void
    {
        $solutions = Math::solve(
            'sin(1.0e12*x) = cos(1.0e12*x)',
            'x',
            0.0,
            2.0E-11,
        );

        self::assertCount(7, $solutions);
        foreach ($solutions as $index => $solution) {
            self::assertEqualsWithDelta(
                ((\M_PI / 4.0) + ($index * \M_PI)) / 1.0E12,
                $solution->value,
                1.0E-25,
            );
        }
    }

    public function testCloselySpacedSumToProductRootsRemainDistinct(): void
    {
        $solutions = Math::solve(
            'sin(1.0e12*x) + sin(2.0e12*x) = 0',
            'x',
            0.0,
            2.0E-11,
        );

        $expectedPhases = [0.0];
        for ($period = 0; $period <= 2; ++$period) {
            $expectedPhases[] = (2.0 * \M_PI / 3.0) + ($period * 2.0 * \M_PI);
            $expectedPhases[] = (4.0 * \M_PI / 3.0) + ($period * 2.0 * \M_PI);
        }
        for ($multiple = 1; $multiple <= 6; ++$multiple) {
            $expectedPhases[] = $multiple * \M_PI;
        }
        \sort($expectedPhases);

        self::assertCount(13, $solutions);
        foreach ($solutions as $index => $solution) {
            self::assertEqualsWithDelta(
                $expectedPhases[$index] / 1.0E12,
                $solution->value,
                1.0E-24,
            );
        }
    }

    public function testAffineSineCosineCombinationsPreserveCloselySpacedRoots(): void
    {
