            ['sin(1.0e12*x)*cos(1.0e12*x) = 0', 13, 0.0, \M_PI / 2.0],
            ['sin(1.0e12*x)^2 = 0.5', 13, \M_PI / 4.0, \M_PI / 2.0],
        ];

        foreach ($cases as [$equation, $count, $firstPhase, $phaseStep]) {
