    public function testPeriodicPolynomialZeroPhaseKeepsTheExactRepeatedRoot(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        foreach (
            [
                ['tan((x - 0.123)^4) = 0', -1.0, 1.0],
                ['sec((x - 0.123)^4) = 1', -1.0, 1.0],
            ] as [$equation, $lower, $upper]
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                $lower,
                $upper,
                solverOptions: $options,
            );

            self::assertCount(1, $solutions, $equation);
            self::assertEqualsWithDelta(0.123, $solutions[0]->value, 1.0E-12, $equation);
            self::assertLessThanOrEqual(1.0E-10, $solutions[0]->residual, $equation);
        }

        $nonzeroPhaseSolutions = Math::solve(
            'tan((x - 0.123)^4) = 1',
            'x',
            -0.9,
            1.1,
            solverOptions: $options,
        );
        $phaseRootOffset = (\M_PI / 4.0) ** 0.25;

        self::assertCount(2, $nonzeroPhaseSolutions);
        self::assertEqualsWithDelta(0.123 - $phaseRootOffset, $nonzeroPhaseSolutions[0]->value, 1.0E-9);
        self::assertEqualsWithDelta(0.123 + $phaseRootOffset, $nonzeroPhaseSolutions[1]->value, 1.0E-9);
    }

