    public function testPeriodicSineExtremaDoNotDuplicateEquivalentPhases(): void
    {
        foreach ([1, 256] as $scanSteps) {
            $sine = Math::solve(
                'sin(x) = -1',
                'x',
                -100.0,
                100.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            $squaredSine = Math::solve(
                'sin(x)^2 = 1',
                'x',
                -100.0,
                100.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            $squaredCosine = Math::solve(
                'cos(x)^2 = 1',
                'x',
                -100.0,
                100.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );

            self::assertCount(32, $sine, 'sin(x)=-1, scanSteps=' . $scanSteps);
            self::assertCount(64, $squaredSine, 'sin(x)^2=1, scanSteps=' . $scanSteps);
            self::assertCount(63, $squaredCosine, 'cos(x)^2=1, scanSteps=' . $scanSteps);
            foreach ([...$sine, ...$squaredSine, ...$squaredCosine] as $solution) {
                self::assertLessThanOrEqual(1.0E-10, $solution->residual);
            }
        }
    }

