    public function testNestedPeriodicPhaseZeroLevelsReportAccumulation(): void
    {
        $detectedAccumulations = 0;
        foreach (
            [
                'sin(x*sin(1/x)) = 0',
                'sin(sin(1/x)) = 0',
                'cos(x*sin(1/x)) = 1',
                'tan(x*sin(1/x)) = 0',
                'sin(sin(1/x)+pi/2) = 1',
                'cos(pi/2+x*sin(1/x)) = 0',
                'sin(pi+x*sin(1/x)) = 0',
                'sin(sin(1/x)+100*pi) = 0',
                'cos(100*pi+x*sin(1/x)) = 1',
                'tan(100*pi+x*sin(1/x)) = 0',
                'sin(sin(1/x)+100*pi+0.3) = 0',
                'cos(100*pi+0.3+x*sin(1/x)) = cos(0.3)',
                'sin(sin(1/x)+cos(1/x)+100*pi) = 0',
            ] as $equation
        ) {
            try {
                Math::solve(
                    $equation,
                    'x',
                    0.0,
                    1.0,
                    solverOptions: new SolverOptions(scanSteps: 1),
                );
                self::fail('Expected infinitely many nested periodic zero-level roots for ' . $equation);
            } catch (InfiniteRootAccumulationException) {
                ++$detectedAccumulations;
            }
        }
        self::assertSame(13, $detectedAccumulations);

        Math::solve(
            'sin(x*sin(1/x)) = 0.1',
            'x',
            0.0,
            1.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertSame(
            [],
            Math::solve(
                'sin(sin(1/x)+100*pi+1.5) = 0',
                'x',
                0.0,
                1.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
    }

