            try {
                Math::solve($equation, 'x', 0.0, 1.0, solverOptions: $options);
                self::fail('Expected infinite root accumulation for ' . $equation);
            } catch (InfiniteRootAccumulationException) {
                ++$detectedAccumulations;
            }
