        self::assertSame(3, $detectedAccumulations);
        self::assertSame(
            [],
            Math::solve('sin(1 / x) = 1 + x^2', 'x', 0.0, 1.0, solverOptions: $options),
        );
        self::assertSame(
            [],
            Math::solve('sec(1 / x) = 1 - x', 'x', 0.0, 1.0, solverOptions: $options),
        );
    }

