    public function testUnboundedComposedPeriodicPhasesReportAccumulation(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $equations = [
            'sin(exp(1 / x)) = 0',
            'sin(exp(1 / x)) = 0.5',
            'cos(exp(1 / x)) = 0',
            'sin(ln(x)) = 0',
            'sin(1 / sqrt(x)) = 0',
            'sin(exp(1 / (x - 0.2))) = 0',
            'sin(exp(-1 / (x - 0.2))) = 0.5',
            'sin(1 / ln(x)) = 0',
            'sin(1 / log(x, 2)) = 0',
            'sin(1 / log1p(x - 1)) = 0',
        ];
        $detected = 0;
        foreach ($equations as $equation) {
            try {
                Math::solve($equation, 'x', 0.0, 1.0, solverOptions: $options);
                self::fail('Expected infinite root accumulation for ' . $equation);
            } catch (InfiniteRootAccumulationException) {
                ++$detected;
            }
        }
        self::assertSame(\count($equations), $detected);
        self::assertSame(
            [],
            Math::solve(
                'sin(exp(-1 / x)) = 0.5',
                'x',
                0.0,
                1.0,
                solverOptions: $options,
            ),
        );
        self::assertSame(
            [],
            Math::solve(
                'sin(exp(-1 / (x - 0.2)^2)) = 0',
                'x',
                0.0,
                1.0,
                solverOptions: $options,
            ),
        );
        self::assertSame(
            [],
            Math::solve(
                'sin(1 / ln(x + 2)) = 0',
                'x',
                0.0,
                1.0,
                solverOptions: $options,
            ),
        );
    }

