    public function testPeriodicRationalArgumentCancelsRemovableFactorsForRangeAnalysis(): void
    {
        $solutions = Math::solve(
            'sin((x^2 - 1) / (x - 1)) = 0',
            'x',
            0.0,
            10_000.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(3183, $solutions);
        foreach ($solutions as $index => $solution) {
            $phaseIndex = $index + 1;
            self::assertEqualsWithDelta(
                ($phaseIndex * \M_PI) - 1.0,
                $solution->value,
                1.0E-8,
            );
            self::assertNotEqualsWithDelta(1.0, $solution->value, 1.0E-8);
            self::assertLessThanOrEqual(1.0E-8, $solution->residual);
        }
    }

