    public function testCanceledRationalPhasePreservesRepeatedRootsOnce(): void
    {
        $solutions = Math::solve(
            'sin(((x^2 - 1)^2) / (x - 1)^2) = 0',
            'x',
            -2.0,
            100.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(3248, $solutions);
        self::assertEqualsWithDelta(-1.0, $solutions[0]->value, 1.0E-10);
        self::assertLessThanOrEqual(1.0E-10, $solutions[0]->residual);
        self::assertGreaterThan(0.0, $solutions[1]->value);
        foreach (\array_slice($solutions, 1) as $index => $solution) {
            $phaseIndex = $index + 1;
