    public function testEqualInjectiveFunctionsReduceToTheirArgumentEquation(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        foreach (
            [
                'exp(1000 * x) = exp(1000 * x + 1)',
                'csch(1000 * x) = csch(1000 * x + 1)',
                'coth(1000 * x) = coth(1000 * x + 1)',
                'erf(1000 * x) = erf(1000 * x + 1)',
            ] as $equation
        ) {
            self::assertSame(
                [],
                Math::solve(
                    $equation,
                    'x',
                    -10.0,
                    10.0,
                    solverOptions: $options,
                ),
                $equation,
            );
        }
        $finiteSolutions = Math::solve(
            'sinh(x^2) = sinh(1)',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $undefinedArgumentEquality = Math::solve(
            'ln(x - 1) = ln(1 - x)',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $validDomainBoundary = Math::solve(
            'sqrt(x - 1) = sqrt(1 - x)',
            'x',
            0.0,
            2.0,
            solverOptions: $options,
        );

        self::assertCount(2, $finiteSolutions);
        self::assertEqualsWithDelta(-1.0, $finiteSolutions[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(1.0, $finiteSolutions[1]->value, 1.0E-10);
        self::assertSame([], $undefinedArgumentEquality);
        self::assertCount(1, $validDomainBoundary);
        self::assertSame(1.0, $validDomainBoundary[0]->value);
        foreach ($finiteSolutions as $solution) {
            self::assertLessThanOrEqual(1.0E-10, $solution->residual);
        }
    }

    public function testEqualInjectiveFunctionsReduceToPolynomialArgumentsOnUnboundedIntervals(): void
    {
        foreach (
            [
                'exp(x^2) = exp(x + 1)',
                'expm1(x^2) = expm1(x + 1)',
                'ln(x^2 + 2) = ln(x + 3)',
            ] as $equation
        ) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF);
            self::assertEqualsWithDelta(
                [-0.6180339887498949, 1.618033988749895],
                \array_map(static fn (EquationSolution $solution): float => $solution->value, $solutions),
                1.0E-10,
                $equation,
            );
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-10, $solution->residual, $equation);
            }
        }
    }

    public function testOddInjectiveFunctionSumsReduceToArgumentSums(): void
    {
        $solutions = Math::solve(
            'atan(x^2) = -arctan(x^2 - 1)',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertEqualsWithDelta(
            [-\sqrt(0.5), \sqrt(0.5)],
            \array_map(static fn ($solution): float => $solution->value, $solutions),
            1.0E-10,
        );
        foreach ($solutions as $solution) {
            self::assertLessThanOrEqual(1.0E-10, $solution->residual);
        }

        $domainRestricted = Math::solve(
            'asin(x) + arcsin(1 - 2*x) = 0',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(1, $domainRestricted);
        self::assertEqualsWithDelta(1.0, $domainRestricted[0]->value, 1.0E-10);

        $inverseHyperbolic = Math::solve(
            'atanh(x^2/4) = -arctanh(x^2 - 3/4)',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertEqualsWithDelta(
            [-\sqrt(0.6), \sqrt(0.6)],
            \array_map(static fn ($solution): float => $solution->value, $inverseHyperbolic),
            1.0E-10,
        );

        $reciprocalHyperbolic = Math::solve(
            'csch(x - 1) + csch((x - 1)^2) = 0',
            'x',
            -1.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $reciprocalHyperbolic);
        self::assertSame(0.0, $reciprocalHyperbolic[0]->value);

        $fixedArgument = Math::solve(
            'csch(x) = -csch(1)',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $fixedArgument);
        self::assertSame(-1.0, $fixedArgument[0]->value);

        foreach (
            [
                'erfc(x^2) + erfc(1 - 2*x^2) = 2',
                '2 = erfc(x^2) + erfc(1 - 2*x^2)',
                'erfc(x^2) = 2 - erfc(1 - 2*x^2)',
            ] as $equation
        ) {
            $complementaryErrors = Math::solve(
                $equation,
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [-1.0, 1.0],
                \array_map(static fn ($solution): float => $solution->value, $complementaryErrors),
                1.0E-10,
                $equation,
            );
        }

        foreach (
            [
                'acot(1000*(x - 0.123)^2) + acot(2000*x - 1000) = pi',
                'pi = acot(1000*(x - 0.123)^2) + acot(2000*x - 1000)',
                'acot(1000*(x - 0.123)^2) = pi - acot(2000*x - 1000)',
            ] as $equation
        ) {
            $inverseCotangents = Math::solve(
                $equation,
                'x',
                -3.0,
                3.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [
                    (-1.754 - \sqrt((1.754 ** 2) + (4.0 * 0.984871))) / 2.0,
                    (-1.754 + \sqrt((1.754 ** 2) + (4.0 * 0.984871))) / 2.0,
                ],
                \array_map(static fn ($solution): float => $solution->value, $inverseCotangents),
                1.0E-10,
                $equation,
            );
        }

        self::assertSame(
            [],
            Math::solve(
                'acot(x) + acot(-x) = 2',
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );

        $nonComplementaryAcot = Math::solve(
            'acot(1000*(x - 0.123)^2) + acot(2000*x - 1000) = 2',
            'x',
            -2.0,
            3.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertNotEqualsWithDelta(0.123, $nonComplementaryAcot[0]->value, 1.0E-6);
    }

    public function testComplementaryFunctionSumsReduceToArgumentEquality(): void
    {
        foreach (
            [
                'arcsin(0.2*(x^2 - 1)) + acos(0.2*(1 - 2*x^2)) = pi/2',
                'pi/2 = asin(0.2*(x^2 - 1)) + arccos(0.2*(1 - 2*x^2))',
                'asin(0.2*(x^2 - 1)) = pi/2 - acos(0.2*(1 - 2*x^2))',
            ] as $equation
        ) {
            $inverseSineCosine = Math::solve(
                $equation,
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [-\sqrt(2.0 / 3.0), \sqrt(2.0 / 3.0)],
                \array_map(static fn ($solution): float => $solution->value, $inverseSineCosine),
                1.0E-10,
                $equation,
            );
        }

        $inverseSecantCosecant = Math::solve(
            'asec(1.4 + 0.1*x^2) + acsc(1.5 - 0.05*x^2) = pi/2',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertEqualsWithDelta(
            [-\sqrt(2.0 / 3.0), \sqrt(2.0 / 3.0)],
            \array_map(static fn ($solution): float => $solution->value, $inverseSecantCosecant),
            1.0E-10,
        );

        foreach (
            [
                'acos(0.2*(x^2 - 1)) + arccos(0.2*(1 - 2*x^2)) = pi',
                'pi = acos(0.2*(x^2 - 1)) + acos(0.2*(1 - 2*x^2))',
                'acos(0.2*(x^2 - 1)) = pi - acos(0.2*(1 - 2*x^2))',
            ] as $equation
        ) {
            $inverseCosines = Math::solve(
                $equation,
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [0.0],
                \array_map(static fn ($solution): float => $solution->value, $inverseCosines),
                1.0E-10,
                $equation,
            );
        }

        $inverseSecants = Math::solve(
            'asec(1.4 + 0.1*x^2) + asec(-1.6 + 0.2*x^2) = pi',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertEqualsWithDelta(
            [-\sqrt(2.0 / 3.0), \sqrt(2.0 / 3.0)],
            \array_map(static fn ($solution): float => $solution->value, $inverseSecants),
            1.0E-10,
        );

        $saturatedErrorFunctions = Math::solve(
            'erf(1000*(x - 0.123)^2) + erfc(2000*x) = 1',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        $expectedSmallRoot = (2.246 - \sqrt((2.246 ** 2) - (4.0 * 0.015129))) / 2.0;
        self::assertCount(1, $saturatedErrorFunctions);
        self::assertEqualsWithDelta($expectedSmallRoot, $saturatedErrorFunctions[0]->value, 1.0E-10);

        $inverseTrigonometric = Math::solve(
            'atan(1000*(x^2 - 1)) + acot(2000*x - 1000) = pi/2',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertEqualsWithDelta(
            [0.0, 2.0],
            \array_map(static fn ($solution): float => $solution->value, $inverseTrigonometric),
            1.0E-10,
        );
    }

    public function testEqualInverseFunctionsReduceToEqualityOfTheirArguments(): void
    {
        foreach (
            [
                ['asin(x^2 - 1) = arcsin(0.5)', [-\sqrt(1.5), \sqrt(1.5)]],
                ['acos(x^2 - 1) = arccos(0.5)', [-\sqrt(1.5), \sqrt(1.5)]],
                ['atan(x^2) = arctan(1)', [-1.0, 1.0]],
                ['asec(1 + x^2) = asec(2)', [-1.0, 1.0]],
                ['acsc(1 + x^2) = acsc(2)', [-1.0, 1.0]],
                ['acot(x^2) = acot(1)', [-1.0, 1.0]],
                ['asinh(x^2) = arcsinh(1)', [-1.0, 1.0]],
                ['acosh(1 + x^2) = arccosh(2)', [-1.0, 1.0]],
                ['atanh(x^2) = arctanh(0.25)', [-0.5, 0.5]],
                ['asech(1 / (1 + x^2)) = asech(0.5)', [-1.0, 1.0]],
                ['acsch(1 / (1 + x^2)) = acsch(0.5)', [-1.0, 1.0]],
                ['acoth(1 + x^2) = acoth(2)', [-1.0, 1.0]],
            ] as [$equation, $expected]
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                $expected,
                \array_map(static fn ($solution): float => $solution->value, $solutions),
                1.0E-10,
                $equation,
            );
        }
    }

    public function testInverseSineEqualsInverseCosineUsesPythagoreanReduction(): void
    {
        foreach (
            [
                'asin(x) = acos(2*x - 1)',
                'arcsin(x) = arccos(2*x - 1)',
                'acos(2*x - 1) = arcsin(x)',
            ] as $equation
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta([0.8], \array_map(
                static fn ($solution): float => $solution->value,
                $solutions,
            ), 1.0E-10, $equation);
        }

        $reciprocalInversePair = Math::solve(
            'asec(1 + x) = acsc(2)',
            'x',
            -3.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertEqualsWithDelta(
            [(2.0 / \sqrt(3.0)) - 1.0],
            \array_map(static fn ($solution): float => $solution->value, $reciprocalInversePair),
            1.0E-10,
        );

        foreach (
            [
                'asinh(x) = acosh(2*x)',
                'arcsinh(x) = arccosh(2*x)',
                'acosh(2*x) = arcsinh(x)',
            ] as $equation
        ) {
            $hyperbolicSolutions = Math::solve(
                $equation,
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [1.0 / \sqrt(3.0)],
                \array_map(static fn ($solution): float => $solution->value, $hyperbolicSolutions),
                1.0E-10,
                $equation,
            );
        }

        foreach (
            [
                'asinh(x) = acsch(2*x + 1)',
                'acsch(2*x + 1) = arcsinh(x)',
            ] as $equation
        ) {
            $reciprocalHyperbolicSolutions = Math::solve(
                $equation,
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [-1.0, 0.5],
                \array_map(static fn ($solution): float => $solution->value, $reciprocalHyperbolicSolutions),
                1.0E-10,
                $equation,
            );
        }

        foreach (
            [
                'acosh(1 + x) = acsch(1)',
                'acsch(1) = acosh(1 + x)',
            ] as $equation
        ) {
            $coshCosecantSolutions = Math::solve(
                $equation,
                'x',
                -3.0,
                1.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [\sqrt(2.0) - 1.0],
                \array_map(static fn ($solution): float => $solution->value, $coshCosecantSolutions),
                1.0E-10,
                $equation,
            );
        }

        foreach (
            [
                'acoth(1 + x) = atanh(x/2)',
                'arctanh(x/2) = acoth(1 + x)',
            ] as $equation
        ) {
            $cotanhTangentSolutions = Math::solve(
                $equation,
                'x',
                -3.0,
                3.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [1.0],
                \array_map(static fn ($solution): float => $solution->value, $cotanhTangentSolutions),
                1.0E-10,
                $equation,
            );
        }

        foreach (
            [
                'acosh(1 + x) = atanh(0.5)',
                'arctanh(0.5) = arccosh(1 + x)',
            ] as $equation
        ) {
            $coshTangentSolutions = Math::solve(
                $equation,
                'x',
                -3.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [(2.0 / \sqrt(3.0)) - 1.0],
                \array_map(static fn ($solution): float => $solution->value, $coshTangentSolutions),
                1.0E-10,
                $equation,
            );
        }

        foreach (
            [
                'acosh(1 + x) = acoth(2)',
                'acoth(2) = arccosh(1 + x)',
            ] as $equation
        ) {
            $coshCotanhSolutions = Math::solve(
                $equation,
                'x',
                -3.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [(2.0 / \sqrt(3.0)) - 1.0],
                \array_map(static fn ($solution): float => $solution->value, $coshCotanhSolutions),
                1.0E-10,
                $equation,
            );
        }

        foreach (
            [
                'asinh(x) = acoth(2)',
                'acoth(2) = arcsinh(x)',
            ] as $equation
        ) {
            $sinhCotanhSolutions = Math::solve(
                $equation,
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [1.0 / \sqrt(3.0)],
                \array_map(static fn ($solution): float => $solution->value, $sinhCotanhSolutions),
                1.0E-10,
                $equation,
            );
        }

        foreach (
            [
                'acosh(1 + x) = asech(0.5)',
                'asech(0.5) = arccosh(1 + x)',
            ] as $equation
        ) {
            $coshSechSolutions = Math::solve(
                $equation,
                'x',
                -3.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [1.0],
                \array_map(static fn ($solution): float => $solution->value, $coshSechSolutions),
                1.0E-10,
                $equation,
            );
        }

        foreach (
            [
                'asinh(x) = asech(0.5)',
                'asech(0.5) = arcsinh(x)',
            ] as $equation
        ) {
            $sinhSechSolutions = Math::solve(
                $equation,
                'x',
                -3.0,
                3.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [\sqrt(3.0)],
                \array_map(static fn ($solution): float => $solution->value, $sinhSechSolutions),
                1.0E-10,
                $equation,
            );
        }

        foreach (
            [
                ['asin(x) = atan(1)', \sqrt(0.5)],
                ['arctan(1) = arcsin(x)', \sqrt(0.5)],
                ['asin(x) = atan(-1)', -\sqrt(0.5)],
                ['acos(x) = atan(1)', \sqrt(0.5)],
                ['atan(1) = arccos(x)', \sqrt(0.5)],
                ['asec(1 + x) = atan(1)', \sqrt(2.0) - 1.0],
                ['atan(1) = asec(1 + x)', \sqrt(2.0) - 1.0],
                ['acsc(1 + x) = atan(1)', \sqrt(2.0) - 1.0],
                ['atan(1) = acsc(1 + x)', \sqrt(2.0) - 1.0],
                ['acot(1 + x) = atan(1)', 0.0],
                ['atan(1) = acot(1 + x)', 0.0],
            ] as [$equation, $expected]
        ) {
            $inverseTangentSolutions = Math::solve(
                $equation,
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [$expected],
                \array_map(static fn ($solution): float => $solution->value, $inverseTangentSolutions),
                1.0E-10,
                $equation,
            );
        }

        foreach (
            [
                'asin(x) = asec(2)',
                'asec(2) = arcsin(x)',
            ] as $equation
        ) {
            $sineSecantSolutions = Math::solve(
                $equation,
                'x',
                -1.0,
                1.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [\sqrt(3.0) / 2.0],
                \array_map(static fn ($solution): float => $solution->value, $sineSecantSolutions),
                1.0E-10,
                $equation,
            );
        }

        foreach (
            [
                'asin(x) = acsc(2)',
                'acsc(2) = arcsin(x)',
                'acos(x) = asec(2)',
                'asec(2) = arccos(x)',
                'acos(x) = acsc(2)',
                'acsc(2) = arccos(x)',
            ] as $equation
        ) {
            $reciprocalAngleSolutions = Math::solve(
                $equation,
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                (\str_contains($equation, 'acos') || \str_contains($equation, 'arccos'))
                    && \str_contains($equation, 'acsc')
                    ? [\sqrt(3.0) / 2.0]
                    : [0.5],
                \array_map(static fn ($solution): float => $solution->value, $reciprocalAngleSolutions),
                1.0E-10,
                $equation,
            );
        }

        foreach (
            [
                'asinh(x) = atanh(0.5)',
                'arctanh(0.5) = arcsinh(x)',
            ] as $equation
        ) {
            $sinhTangentSolutions = Math::solve(
                $equation,
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [1.0 / \sqrt(3.0)],
                \array_map(static fn ($solution): float => $solution->value, $sinhTangentSolutions),
                1.0E-10,
                $equation,
            );
        }

        foreach (
            [
                'asin(x) = acot(1)',
                'acot(1) = arcsin(x)',
                'acos(x) = acot(1)',
                'acot(1) = arccos(x)',
            ] as $equation
        ) {
            $arcCotangentSolutions = Math::solve(
                $equation,
                'x',
                -1.0,
                1.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [\sqrt(2.0) / 2.0],
                \array_map(static fn ($solution): float => $solution->value, $arcCotangentSolutions),
                1.0E-10,
                $equation,
            );
        }

        foreach (
            [
                ['asec(2) = acot(x)', 1.0 / \sqrt(3.0)],
                ['acot(x) = asec(2)', 1.0 / \sqrt(3.0)],
                ['acsc(2) = acot(x)', \sqrt(3.0)],
                ['acot(x) = acsc(2)', \sqrt(3.0)],
            ] as [$equation, $expected]
        ) {
            $reciprocalCotangentSolutions = Math::solve(
                $equation,
                'x',
                -3.0,
                3.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [$expected],
                \array_map(static fn ($solution): float => $solution->value, $reciprocalCotangentSolutions),
                1.0E-10,
                $equation,
            );
        }

        foreach (
            [
                'acoth(x) = acsch(2)',
                'acsch(2) = acoth(x)',
            ] as $equation
        ) {
            $cotanhCosecantSolutions = Math::solve(
                $equation,
                'x',
                -3.0,
                3.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [\sqrt(5.0)],
                \array_map(static fn ($solution): float => $solution->value, $cotanhCosecantSolutions),
                1.0E-10,
                $equation,
            );
        }

        $cotanhSechSolutions = Math::solve(
            'acoth(1 + x) = asech(0.5)',
            'x',
            -3.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertEqualsWithDelta(
            [(2.0 / \sqrt(3.0)) - 1.0],
            \array_map(static fn ($solution): float => $solution->value, $cotanhSechSolutions),
            1.0E-10,
        );

        foreach (
            [
                'acsch(1 + x) = asech(0.5)',
                'asech(0.5) = acsch(1 + x)',
            ] as $equation
        ) {
            $cosecantSechSolutions = Math::solve(
                $equation,
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [1.0 / \sqrt(3.0) - 1.0],
                \array_map(static fn ($solution): float => $solution->value, $cosecantSechSolutions),
                1.0E-10,
                $equation,
            );
        }

        foreach (
            [
                'asech(1 + x) = atanh(0.5)',
                'arctanh(0.5) = asech(1 + x)',
            ] as $equation
        ) {
            $sechTangentSolutions = Math::solve(
                $equation,
                'x',
                -3.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [\sqrt(3.0) / 2.0 - 1.0],
                \array_map(static fn ($solution): float => $solution->value, $sechTangentSolutions),
                1.0E-10,
                $equation,
            );
        }

        foreach (
            [
                'acsch(1 + x) = atanh(0.5)',
                'arctanh(0.5) = acsch(1 + x)',
            ] as $equation
        ) {
            $cosecantTangentSolutions = Math::solve(
                $equation,
                'x',
                -3.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta(
                [\sqrt(3.0) - 1.0],
                \array_map(static fn ($solution): float => $solution->value, $cosecantTangentSolutions),
                1.0E-10,
                $equation,
            );
        }
    }

    public function testEqualRootFunctionsWithMatchingDegreesReduceTheirRadicands(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $oddRoots = Math::solve(
            'root(exp(x), 3) = root(exp(x^2), 3)',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $evenRoots = Math::solve(
            'root(x - 1, 2) = root(x^2 - 1, 2)',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $negativeDegreeRoots = Math::solve(
            'root(x - 1, -3) = root(x^2 - 1, -3)',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $equivalentConstantDegrees = Math::solve(
            'root(exp(x), 2 + 2) = root(exp(x^2), 4)',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $equivalentPolynomialDegrees = Math::solve(
            'root(exp(x), 2*x + 3) = root(exp(x^2), x + x + 3)',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );

        self::assertSame([0.0, 1.0], \array_map(
            static fn ($solution): float => $solution->value,
            $oddRoots,
        ));
        self::assertSame([1.0], \array_map(
            static fn ($solution): float => $solution->value,
            $evenRoots,
        ));
        self::assertSame([0.0], \array_map(
            static fn ($solution): float => $solution->value,
            $negativeDegreeRoots,
        ));
        self::assertSame([0.0, 1.0], \array_map(
            static fn ($solution): float => $solution->value,
            $equivalentConstantDegrees,
        ));
        self::assertSame([0.0, 1.0], \array_map(
            static fn ($solution): float => $solution->value,
            $equivalentPolynomialDegrees,
        ));
    }

    public function testEqualLogarithmBasesPermitSafeArgumentReduction(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $validRoot = Math::solve(
            'log(x + 2, x + 2) = log(2, x + 2)',
            'x',
            -1.0,
            2.0,
            solverOptions: $options,
        );
        $invalidBaseAtArgumentRoot = Math::solve(
            'log(x + 1, x) = log(2, x)',
            'x',
            0.0,
            2.0,
            solverOptions: $options,
        );
        $equivalentConstantBases = Math::solve(
            'log(x + 2, 2 + 2) = log(2, 4)',
            'x',
            -1.0,
            2.0,
            solverOptions: $options,
        );
        $equivalentPolynomialBases = Math::solve(
            'log(x + 2, 2*x + 3) = log(2, x + x + 3)',
            'x',
            -1.0,
            2.0,
            solverOptions: $options,
        );

        self::assertCount(1, $validRoot);
        self::assertSame(0.0, $validRoot[0]->value);
        self::assertSame([], $invalidBaseAtArgumentRoot);
        self::assertCount(1, $equivalentConstantBases);
        self::assertSame(0.0, $equivalentConstantBases[0]->value);
        self::assertCount(1, $equivalentPolynomialBases);
        self::assertSame(0.0, $equivalentPolynomialBases[0]->value);
    }

    public function testVariableBaseLogarithmLevelsAreReducedAndDomainChecked(): void
    {
        foreach ([1, 256] as $scanSteps) {
            $solutions = Math::solve(
                'log(x^2 + 1, x + 2) = 2',
                'x',
                -3.0,
                4.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );

            self::assertCount(1, $solutions, 'scanSteps=' . $scanSteps);
            self::assertSame(-0.75, $solutions[0]->value);
