    public function testSolvesEquationsUsingInverseReciprocalHyperbolicFunctions(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $asech = Math::solve(
            'asech(x^2) = 1',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $acsch = Math::solve(
            'acsch(x^2) = 1',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $acoth = Math::solve(
            'acoth(x^2) = 1',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $invalidAsechTarget = Math::solve(
            'asech(x^2) = -1',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $invalidAcschTarget = Math::solve(
            'acsch(x^2) = 0',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $invalidAcothTarget = Math::solve(
            'acoth(x^2) = 0',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );

        foreach (
            [
                [$asech, \sqrt(1.0 / \cosh(1.0))],
                [$acsch, \sqrt(1.0 / \sinh(1.0))],
                [$acoth, \sqrt(\cosh(1.0) / \sinh(1.0))],
            ] as [$solutions, $root]
        ) {
            self::assertCount(2, $solutions);
            self::assertEqualsWithDelta(-$root, $solutions[0]->value, 1.0E-10);
            self::assertEqualsWithDelta($root, $solutions[1]->value, 1.0E-10);
        }
        self::assertSame([], $invalidAsechTarget);
        self::assertSame([], $invalidAcschTarget);
        self::assertSame([], $invalidAcothTarget);
    }

