    public function testSolvesPolynomialRadicandsWithConstantIntegerRootDegrees(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $evenRoot = Math::solve(
            'root((x - 2)^2, 2) = 1',
            'x',
            -2.0,
            6.0,
            solverOptions: $options,
        );
        $negativeEvenRoot = Math::solve(
            'root(x^2, -2) = 0.5',
            'x',
            -4.0,
            4.0,
            solverOptions: $options,
        );
        $negativeOddRoot = Math::solve(
            'root(x^3, -3) = -0.5',
            'x',
            -4.0,
            4.0,
            solverOptions: $options,
        );
        $reversedEquation = Math::solve(
            '1 = root((x - 2)^2, 2)',
            'x',
            -2.0,
            6.0,
            solverOptions: $options,
        );
        $negativeEvenTarget = Math::solve(
            'root(x^2, 2) = -1',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $underflowedLevel = Math::solve(
            'root(x, 3) = 1e-200',
            'x',
            -1.0E-300,
            1.0E-300,
            solverOptions: $options,
        );
        $scaledUnderflowedLevel = Math::solve(
            'root(1e-300*x, 3) = 1e-100',
            'x',
            0.0,
            2.0,
            solverOptions: $options,
        );

        foreach ([$evenRoot, $reversedEquation] as $solutions) {
            self::assertCount(2, $solutions);
            self::assertEqualsWithDelta(1.0, $solutions[0]->value, 1.0E-10);
            self::assertEqualsWithDelta(3.0, $solutions[1]->value, 1.0E-10);
        }
        self::assertCount(2, $negativeEvenRoot);
        self::assertEqualsWithDelta(-2.0, $negativeEvenRoot[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(2.0, $negativeEvenRoot[1]->value, 1.0E-10);
        self::assertCount(1, $negativeOddRoot);
        self::assertEqualsWithDelta(-2.0, $negativeOddRoot[0]->value, 1.0E-10);
        self::assertSame([], $negativeEvenTarget);
        self::assertSame([], $underflowedLevel);
        self::assertCount(1, $scaledUnderflowedLevel);
        self::assertEqualsWithDelta(1.0, $scaledUnderflowedLevel[0]->value, 1.0E-10);
    }

    public function testUnboundedHypotenuseEquationsReduceToRationalEquations(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $cases = [
            'hypot(x, 1) = 2' => [-\sqrt(3.0), \sqrt(3.0)],
            '3 = hypot(x^2, 1)' => [-\sqrt(2.0 * \sqrt(2.0)), \sqrt(2.0 * \sqrt(2.0))],
            'hypot(x, x) = 2' => [-\sqrt(2.0), \sqrt(2.0)],
            'hypot(x^2, 1) = 1' => [0.0],
            'hypot(x, 1) = 1' => [0.0],
            'hypot(x, 1) = x - 1' => [],
            'hypot(x, 1) = x + 1' => [0.0],
            'hypot(1 / x, 1) = 2' => [-1.0 / \sqrt(3.0), 1.0 / \sqrt(3.0)],
            'hypot(x, 1) = -2' => [],
            'hypot(sin(x), 1) = x' => [1.404491648197793],
            'hypot(sin(x), 1) = x + 0.5' => [0.6821539076078613],
            'hypot(sin(x), 1) = 2' => [],
            'hypot(x, 1) = sin(x)' => [],
            'hypot(x, 1) = sin(x) + 2' => [-0.8015281833019283, 2.4450075080858777],
            'hypot(x^2 + 1, 0) = -(x^2 + 1)' => [],
        ];
        foreach ($cases as $equation => $expected) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF, solverOptions: $options);
            self::assertCount(\count($expected), $solutions, $equation);
            foreach ($expected as $index => $value) {
                self::assertEqualsWithDelta($value, $solutions[$index]->value, 1.0E-9, $equation);
            }
        }
    }

    public function testSolvesHypotenuseOfPolynomialArgumentsAnalytically(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $polynomialAndConstant = Math::solve(
            'hypot(x^2, 3) = 5',
            'x',
            -3.0,
            3.0,
            solverOptions: $options,
        );
        $twoPolynomialArguments = Math::solve(
            'hypot(x - 2, x + 2) = sqrt(10)',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $reversedEquation = Math::solve(
            '5 = hypot(x^2, 3)',
            'x',
            -3.0,
            3.0,
            solverOptions: $options,
        );
        $negativeTarget = Math::solve(
            'hypot(x, 1) = -1',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $tinyTargetOptions = new SolverOptions(
            scanSteps: 1,
            absoluteTolerance: 1.0E-220,
        );
        $tinyTarget = Math::solve(
            'hypot(x, 0) = 1e-200',
            'x',
            -2.0E-200,
            2.0E-200,
            solverOptions: $tinyTargetOptions,
        );
        $tinyTargetReversed = Math::solve(
            'hypot(0, 2*x) = 1e-200',
            'x',
            -1.0E-200,
            1.0E-200,
            solverOptions: $tinyTargetOptions,
        );
        $rationalCoordinate = Math::solve(
            'hypot(1 / (x^2 + 1), 1) = 1.25',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $twoRationalCoordinates = Math::solve(
            'hypot(1 / x, 1 / (x - 1)) = sqrt(5)',
            'x',
            -3.0,
            3.0,
            solverOptions: $options,
        );
        $removableHole = Math::solve(
            'hypot((x^2 - 1) / (x - 1), 0) = 2',
            'x',
            -4.0,
            4.0,
            solverOptions: $options,
        );

        foreach ([$polynomialAndConstant, $reversedEquation] as $solutions) {
            self::assertCount(2, $solutions);
            self::assertEqualsWithDelta(-2.0, $solutions[0]->value, 1.0E-10);
            self::assertEqualsWithDelta(2.0, $solutions[1]->value, 1.0E-10);
        }
        self::assertCount(2, $twoPolynomialArguments);
        self::assertEqualsWithDelta(-1.0, $twoPolynomialArguments[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(1.0, $twoPolynomialArguments[1]->value, 1.0E-10);
        self::assertSame([], $negativeTarget);
        self::assertCount(2, $tinyTarget);
        self::assertSame(-1.0E-200, $tinyTarget[0]->value);
        self::assertSame(1.0E-200, $tinyTarget[1]->value);
        self::assertCount(2, $tinyTargetReversed);
        self::assertSame(-5.0E-201, $tinyTargetReversed[0]->value);
        self::assertSame(5.0E-201, $tinyTargetReversed[1]->value);
        self::assertCount(2, $rationalCoordinate);
        self::assertEqualsWithDelta(-1.0 / \sqrt(3.0), $rationalCoordinate[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(1.0 / \sqrt(3.0), $rationalCoordinate[1]->value, 1.0E-10);
        self::assertCount(2, $twoRationalCoordinates);
        self::assertEqualsWithDelta(-0.4694833410413175, $twoRationalCoordinates[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(1.4694833410413175, $twoRationalCoordinates[1]->value, 1.0E-10);
        self::assertCount(1, $removableHole);
        self::assertSame(-3.0, $removableHole[0]->value);
    }

    public function testZeroHypotenuseSolvesSharedPolynomialCoordinateZeros(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        foreach (
            [
                'hypot(x - 0.123, (x - 0.123)^2) = 0',
                'hypot((x - 0.123)^2, x - 0.123) = 0',
                'hypot((x - 0.123)^4, (x - 0.123)^6) = 0',
                '0 = hypot(x - 0.123, (x - 0.123)^2)',
                'hypot(0, (x - 0.123)^2) = 0',
                'hypot((x - 0.123)^4 / (x + 2), (x - 0.123)^6 / (x + 3)) = 0',
            ] as $equation
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                -1.0,
                1.0,
                solverOptions: $options,
            );

            self::assertCount(1, $solutions, $equation);
            self::assertEqualsWithDelta(0.123, $solutions[0]->value, 1.0E-10, $equation);
            self::assertLessThanOrEqual(1.0E-10, $solutions[0]->residual, $equation);
        }

        self::assertSame(
            [],
            Math::solve(
                'hypot(x - 1, x - 2) = 0',
                'x',
                -1.0,
                3.0,
                solverOptions: $options,
            ),
        );
        self::assertSame(
            [],
            Math::solve(
                'hypot((x - 0.123) / (x - 0.123), (x - 0.123)^2 / (x + 3)) = 0',
                'x',
                -1.0,
                1.0,
                solverOptions: $options,
            ),
        );
    }

