    public function testSolvesAtan2EquationsWithPolynomialCoordinatesAndFiltersQuadrants(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $direct = Math::solve(
            'atan2(x, 1) = pi / 4',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $reversed = Math::solve(
            'pi / 4 = atan2(1, x)',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $polynomialBranches = Math::solve(
            'atan2(x^2 - 1, x) = pi / 4',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $axis = Math::solve(
            'atan2(1, x) = pi / 2',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $wrongQuadrant = Math::solve(
            'atan2(x, 1) = 3 * pi / 4',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $rationalCoordinate = Math::solve(
            'atan2(1 / (x - 1), 1) = pi / 4',
            'x',
            -2.0,
            3.0,
            solverOptions: $options,
        );
        $removableHole = Math::solve(
            'atan2((x^2 - 1) / (x - 1), 2) = pi / 4',
            'x',
            -2.0,
            3.0,
            solverOptions: $options,
        );

        self::assertCount(1, $direct);
        self::assertEqualsWithDelta(1.0, $direct[0]->value, 1.0E-10);
        self::assertCount(1, $reversed);
        self::assertEqualsWithDelta(1.0, $reversed[0]->value, 1.0E-10);
        self::assertCount(1, $polynomialBranches);
        self::assertEqualsWithDelta((1.0 + \sqrt(5.0)) / 2.0, $polynomialBranches[0]->value, 1.0E-10);
        self::assertCount(1, $axis);
        self::assertSame(0.0, $axis[0]->value);
        self::assertSame([], $wrongQuadrant);
        self::assertCount(1, $rationalCoordinate);
        self::assertSame(2.0, $rationalCoordinate[0]->value);
        self::assertSame([], $removableHole);
    }

