    public function testAcothReturnsNearestRepresentableRootNearOpenDomainBoundary(): void
    {
        foreach ([-12.0, -10.0, 10.0, 12.0] as $target) {
            $solutions = Math::solve(
                'acoth(x) = ' . \sprintf('%.17g', $target),
                'x',
                $target < 0.0 ? -2.0 : 1.0,
                $target < 0.0 ? -1.0 : 2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );

            self::assertCount(1, $solutions, 'target=' . $target);
            self::assertSame(
                $target < 0.0
                    ? -$this->positiveCothLevel(-$target)
                    : $this->positiveCothLevel($target),
                $solutions[0]->value,
                'target=' . $target,
            );
            self::assertGreaterThan(1.0E-10, $solutions[0]->residual, 'target=' . $target);
        }
    }

