    public function testInverseHyperbolicLevelsRoundedToExcludedBoundariesProjectToDefinedFloats(): void
    {
        $cases = [
            ['atanh(x) = 20', 0.0, 1.0, 0.9999999999999999],
            ['atanh(x) = -20', -1.0, 0.0, -0.9999999999999999],
            ['acoth(x) = 20', 1.0, 2.0, 1.0000000000000002],
            ['acoth(x) = -20', -2.0, -1.0, -1.0000000000000002],
            ['asech(x) = 750', 0.0, 1.0, 5.0E-324],
            ['acsch(x) = 750', 0.0, 1.0, 5.0E-324],
            ['acsch(x) = -750', -1.0, 0.0, -5.0E-324],
        ];

        foreach ($cases as [$equation, $lowerBound, $upperBound, $expectedValue]) {
            $solutions = Math::solve(
                $equation,
                'x',
                $lowerBound,
                $upperBound,
                solverOptions: new SolverOptions(scanSteps: 1),
            );

            self::assertCount(1, $solutions, $equation);
            self::assertSame($expectedValue, $solutions[0]->value, $equation);
            self::assertGreaterThan(1.0E-10, $solutions[0]->residual, $equation);
        }
    }

    private function positiveCothLevel(float $value): float
    {
        return 1.0 + (2.0 / \expm1(2.0 * $value));
    }

    public function testSolvesMinAndMaxEquationsByFilteringPolynomialBranches(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $minimum = Math::solve(
            'min(x^2, 1) = 0.5',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $maximum = Math::solve(
            '2 = max(x^2, 1)',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $multipleActiveBranches = Math::solve(
            'min(x^2, 1 - x^2) = 0.25',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $impossible = Math::solve(
            'max(x^2, 1) = -1',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );

        foreach ([$minimum, $maximum] as $solutions) {
            self::assertCount(2, $solutions);
        }
        self::assertEqualsWithDelta(-\sqrt(0.5), $minimum[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(\sqrt(0.5), $minimum[1]->value, 1.0E-10);
        self::assertEqualsWithDelta(-\sqrt(2.0), $maximum[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(\sqrt(2.0), $maximum[1]->value, 1.0E-10);
        self::assertCount(4, $multipleActiveBranches);
        foreach (
            [-\sqrt(0.75), -0.5, 0.5, \sqrt(0.75)] as $index => $root
        ) {
            self::assertEqualsWithDelta($root, $multipleActiveBranches[$index]->value, 1.0E-10);
        }
        self::assertSame([], $impossible);
    }

    public function testMinMaxEquationsWithVariableTargetsUseExactBranchConstraints(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $maximum = Math::solve(
            'max(sin(x), 0) = x',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $piecewiseRoots = Math::solve(
            'max(2*x, 1) = x + 1',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $noMinimumRoots = Math::solve(
            'min(2*x, 1) = x + 1',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $constantMaximum = Math::solve(
            'max(1, 2) = x',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $constantMinimum = Math::solve(
            'min(1, 2) = x',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );

        self::assertSame([0.0], \array_map(
            static fn (EquationSolution $solution): float => $solution->value,
            $maximum,
        ));
        self::assertSame([0.0, 1.0], \array_map(
            static fn (EquationSolution $solution): float => $solution->value,
            $piecewiseRoots,
        ));
        self::assertSame([], $noMinimumRoots);
        self::assertSame([2.0], \array_map(
            static fn (EquationSolution $solution): float => $solution->value,
            $constantMaximum,
        ));
        self::assertSame([1.0], \array_map(
            static fn (EquationSolution $solution): float => $solution->value,
            $constantMinimum,
        ));
    }

