    public function testMinMaxAgainstPolynomialTargetsPartitionEveryBranch(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $minimum = Math::solve(
            'min(x, x^2) = (x - 0.3)^2',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $maximum = Math::solve(
            'max(x, x^2) = (x - 0.3)^2',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $multipleRoots = Math::solve(
            'min(x, x^2) = x^3',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $reversed = Math::solve(
            'x^3 = min(x, x^2)',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );

        self::assertCount(2, $minimum);
        self::assertEqualsWithDelta(0.15, $minimum[0]->value, 1.0E-10);
        self::assertEqualsWithDelta((1.6 + \sqrt(2.2)) / 2.0, $minimum[1]->value, 1.0E-10);
        self::assertCount(1, $maximum);
        self::assertEqualsWithDelta((1.6 - \sqrt(2.2)) / 2.0, $maximum[0]->value, 1.0E-10);
        self::assertSame([-1.0, 0.0, 1.0], \array_map(
            static fn ($solution): float => $solution->value,
            $multipleRoots,
        ));
        self::assertSame([-1.0, 0.0, 1.0], \array_map(
            static fn ($solution): float => $solution->value,
            $reversed,
        ));

        $this->expectException(InfiniteSolutionSetException::class);
        Math::solve(
            'min(x, x^2) = x^2',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
    }

    public function testMinMaxRationalBranchesPartitionAtPolesAndIntersections(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $minimum = Math::solve(
            'min(1 / x, 1 / x^2) = 0.5',
            'x',
            -3.0,
            3.0,
            solverOptions: $options,
        );
        $maximum = Math::solve(
            'max(1 / x, 1 / x^2) = 0.5',
            'x',
            -3.0,
            3.0,
            solverOptions: $options,
        );

        self::assertCount(1, $minimum);
        self::assertEqualsWithDelta(\sqrt(2.0), $minimum[0]->value, 1.0E-10);
        self::assertCount(2, $maximum);
        self::assertEqualsWithDelta(-\sqrt(2.0), $maximum[0]->value, 1.0E-10);
        self::assertSame(2.0, $maximum[1]->value);

        $this->expectException(InfiniteSolutionSetException::class);
        Math::solve(
            'min(1 / x, 2) = 1 / x',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
    }

    #[DataProvider('minMaxInfinitePlateauProvider')]
    public function testMinMaxPlateausAreReportedAsInfiniteSolutionSets(
        string $equation,
        float $lowerBound,
        float $upperBound,
    ): void {
        $this->expectException(InfiniteSolutionSetException::class);

