    /** @return iterable<string, array{string, float, float}> */
    public static function minMaxInfinitePlateauProvider(): iterable
    {
        yield 'minimum capped by a constant branch' => ['min(x^2, 1) = 1', -2.0, 2.0];
        yield 'maximum floored by a constant branch' => ['max(x^2, 1) = 1', -2.0, 2.0];
        yield 'minimum constant branch over a half interval' => ['min(x, 1) = 1', -1.0, 2.0];
        yield 'maximum constant branch over a half interval' => ['max(x, 1) = 1', -2.0, 1.0];
    }

    public function testNestedPiecewisePlateausAreNotReturnedAsFiniteRoots(): void
    {
        $infiniteSetsDetected = 0;
        foreach (
            [
                ['max(min(x, 1), 0) = 1', 0.0, 2.0],
                ['min(max(x, 0), 1) = 0', -1.0, 2.0],
                ['min(abs(x), 1) = 1', -2.0, 2.0],
            ] as [$equation, $lowerBound, $upperBound]
        ) {
            try {
                Math::solve(
                    $equation,
                    'x',
                    $lowerBound,
                    $upperBound,
                    solverOptions: new SolverOptions(scanSteps: 1),
                );
                self::fail($equation . ' should have infinitely many solutions.');
            } catch (\DomainException) {
                ++$infiniteSetsDetected;
            }
        }

        self::assertSame(3, $infiniteSetsDetected);
    }

    public function testPiecewiseCuspRootsAreFoundWithCoarseScans(): void
    {
