    public function testSolvesIsolatedPolynomialRoundingBoundaryRoots(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $floor = Math::solve(
            'floor(-x^2) = 0',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        $ceil = Math::solve(
            'ceil(x^2) = 0',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        $positiveRoundTie = Math::solve(
            'round(0.5 - x^2) = 1',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        $negativeRoundTie = Math::solve(
            'round(x^2 - 0.5) = -1',
