    public function testFloorAndCeilEquationsIsolateTranscendentalRootsAcrossSteps(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $floor = Math::solve('floor(x) = sin(x)', 'x', -10.0, 10.0, solverOptions: $options);
        $ceil = Math::solve('ceil(x) = sin(x)', 'x', -10.0, 10.0, solverOptions: $options);

        self::assertCount(2, $floor);
        self::assertEqualsWithDelta(0.0, $floor[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(\M_PI / 2.0, $floor[1]->value, 1.0E-10);
        self::assertCount(2, $ceil);
        self::assertEqualsWithDelta(-\M_PI / 2.0, $ceil[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(0.0, $ceil[1]->value, 1.0E-10);
        foreach ([...$floor, ...$ceil] as $solution) {
            self::assertLessThanOrEqual(1.0E-10, $solution->residual);
        }
    }

    public function testRoundingFunctionsInvertRationalArgumentsAtTheirBoundaryLevels(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $isolatedRoot = Math::solve(
            'floor(1 / (x^2 + 1)) = 1',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        self::assertCount(1, $isolatedRoot);
        self::assertEqualsWithDelta(0.0, $isolatedRoot[0]->value, 1.0E-10);

        $infiniteSets = 0;
        foreach (
            [
                ['floor(1 / x) = 2', 0.2, 0.6],
                ['ceil(1 / (x^2 + 1)) = 1', -2.0, 2.0],
                ['round(1 / (x^2 + 1)) = 1', -2.0, 2.0],
            ] as [$equation, $lowerBound, $upperBound]
        ) {
            try {
                Math::solve(
                    $equation,
                    'x',
                    $lowerBound,
                    $upperBound,
                    solverOptions: $options,
                );
                self::fail('Expected an infinite solution set for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                ++$infiniteSets;
            }
        }
        self::assertSame(3, $infiniteSets);

        self::assertSame(
            [],
            Math::solve('floor(x / x) = 0', 'x', -2.0, 2.0, solverOptions: $options),
        );
    }

    public function testRoundingFunctionsAgainstPolynomialsEnumerateIntegerRoots(): void
