    public function testUnboundedPolynomialQuantizersAgainstConstantTargets(): void
    {
        foreach (['floor(x) = 3', 'ceil(x) = 3', 'round(x) = 3', 'trunc(x) = 3'] as $equation) {
            try {
                Math::solve($equation, 'x', -\INF, \INF);
                self::fail("Expected an infinite solution set for {$equation}.");
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        $isolatedBoundary = Math::solve('floor(-x^2) = 0', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [0.0],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $isolatedBoundary),
            1.0E-12,
        );
        self::assertSame([], Math::solve('floor(x^2) = -1', 'x', -\INF, \INF));

        foreach (['floor(x - x) = 0', 'ceil(x - x) = 0', 'round(x - x) = 0', 'trunc(x - x) = 0'] as $equation) {
            try {
                Math::solve($equation, 'x', -\INF, \INF);
                self::fail("Expected an infinite solution set for {$equation}.");
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }
        self::assertSame([], Math::solve('floor(x - x) = 3', 'x', -\INF, \INF));
    }

