    public function testUnboundedReflectedQuantizerPairsUseTheirSignSymmetries(): void
    {
        foreach (
            [
                'floor(x) + ceil(-x) = 0',
                'round(x) + round(-x) = 0',
                'trunc(x) + trunc(-x) = 0',
                'floor(x) + floor(-x) = 0',
                'floor(x) + floor(-x) = -1',
                'ceil(x) + ceil(-x) = 1',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', -\INF, \INF);
                self::fail("Expected an infinite solution set for {$equation}.");
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        $fixedPoint = Math::solve('floor(x) - floor(-x) = 0', 'x', -\INF, \INF);
        self::assertSame(
            [0.0],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $fixedPoint),
        );
        self::assertSame([], Math::solve('floor(x) + floor(-x) = 2', 'x', -\INF, \INF));
    }

