        );
    }

    public function testUnboundedPolynomialFloorAndCeilAgainstBoundedFunctions(): void
    {
        $floorRoots = Math::solve('floor(x^2) = sin(x)', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [0.0],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $floorRoots),
            1.0E-10,
        );

        $ceilRoots = Math::solve('ceil(x^2) = sin(x)', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [0.0],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $ceilRoots),
            1.0E-10,
        );

        self::assertSame([], Math::solve('floor(x^2) = cos(x)', 'x', -\INF, \INF));

        $polynomialPhaseRoots = Math::solve('floor(x^2) = sin(x^2)', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [-\sqrt(\M_PI / 2.0), 0.0, \sqrt(\M_PI / 2.0)],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                $polynomialPhaseRoots,
            ),
            1.0E-9,
        );

        $reversedSides = Math::solve('sin(x) = floor(x^2)', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [0.0],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $reversedSides),
            1.0E-10,
        );

        $roundRoots = Math::solve('round(x^2) = sin(2*x^2)', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [-\sqrt(\M_PI / 4.0), 0.0, \sqrt(\M_PI / 4.0)],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $roundRoots),
            1.0E-9,
        );

        $truncRoots = Math::solve('trunc(x^2) = sin(x^2)', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [-\sqrt(\M_PI / 2.0), 0.0, \sqrt(\M_PI / 2.0)],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $truncRoots),
            1.0E-9,
        );
    }

    public function testUnboundedMinMaxPolynomialBranchesAgainstBoundedFunctions(): void
    {
        $minimumRoots = Math::solve('min(x^2, 2) = sin(x)', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [0.0, 0.87672621539833],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $minimumRoots),
            1.0E-9,
        );

        $maximumRoots = Math::solve('max(x^2, -2) = sin(x)', 'x', -\INF, \INF);
        self::assertEqualsWithDelta(
            [0.0, 0.87672621539833],
            \array_map(static fn (EquationSolution $solution): float => $solution->value, $maximumRoots),
            1.0E-9,
        );

        try {
            Math::solve('min(x^2, 0) = sin(x)', 'x', -\INF, \INF);
            self::fail('The equation reduces to sin(x) = 0 on an unbounded interval.');
        } catch (InfiniteSolutionSetException) {
            self::assertTrue(true);
        }

        $minimumOfTwoPolynomials = Math::solve(
            'min(x^2, (x - 1)^2) = sin(x)',
            'x',
            -\INF,
            \INF,
        );
        self::assertEqualsWithDelta(
            [0.0, 1.9615690349892247],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                $minimumOfTwoPolynomials,
            ),
            1.0E-9,
        );

        $maximumOfTwoPolynomials = Math::solve(
            'sin(x) = max(x^2, (x - 1)^2)',
            'x',
            -\INF,
            \INF,
        );
        self::assertEqualsWithDelta(
            [0.38623687064953277, 0.87672621539833],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                $maximumOfTwoPolynomials,
            ),
            1.0E-9,
        );

        self::assertEqualsWithDelta(
            [0.0, 1.0],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve('min(x^2, (x - 1)^2) = 0', 'x', -\INF, \INF),
            ),
            1.0E-10,
        );

        self::assertEqualsWithDelta(
            [0.0],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve('abs(min(x^2, 2)) = 0', 'x', -\INF, \INF),
            ),
            1.0E-10,
        );

        self::assertEqualsWithDelta(
            [-1.0, 1.0],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve('abs(max(x^2, -2)) = 1', 'x', -\INF, \INF),
            ),
            1.0E-10,
        );

        self::assertEqualsWithDelta(
            [-1.0, 1.0],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve('max(x^2, sin(x)) = 1', 'x', -\INF, \INF),
            ),
            1.0E-10,
        );

        self::assertEqualsWithDelta(
            [0.0],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve('max(x^2, tanh(x)) = 0', 'x', -\INF, \INF),
            ),
            1.0E-10,
        );

        self::assertEqualsWithDelta(
            [-1.0, 1.0],
            \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                Math::solve('max(x^2, abs(sin(x))) = 1', 'x', -\INF, \INF),
            ),
            1.0E-10,
        );

        foreach (
            [
                'min(x^2, sin(x)) = 0',
                'min(x^2, cos(x)) = 0',
                'min(x^2, abs(sin(x))) = 0.5',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', -\INF, \INF);
                self::fail('Expected an infinite solution set for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }
    }

    public function testUnboundedNestedMinMaxAndAbsoluteValueBranches(): void
    {
