    public function testRoundingTermsCombinedWithPolynomialsUseExactLevels(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $cases = [
            ['floor(2*x) + x^2 = 3', [-\sqrt(10.0), -3.0, 1.0]],
            ['2*floor(2*x) + x^2 = 5', [-5.0, 1.0]],
            ['ceil(2*x) + x^2 = 3', [-3.0, -\sqrt(8.0), 1.0]],
            ['round(2*x) + x^2 = 3', [-3.0, 1.0]],
        ];
        foreach ($cases as [$equation, $expectedRoots]) {
            $solutions = Math::solve(
                $equation,
                'x',
                -5.0,
                5.0,
                solverOptions: $options,
            );
            self::assertCount(\count($expectedRoots), $solutions, $equation);
            foreach ($expectedRoots as $index => $expectedRoot) {
                self::assertEqualsWithDelta(
                    $expectedRoot,
                    $solutions[$index]->value,
                    1.0E-9,
                    $equation,
                );
                self::assertLessThanOrEqual(1.0E-10, $solutions[$index]->residual);
            }
        }

        foreach ([1, 512] as $scanSteps) {
            self::assertSame(
                [],
                Math::solve(
                    'floor(x^2) - x^2 = -1',
                    'x',
                    -5.0,
                    5.0,
                    solverOptions: new SolverOptions(scanSteps: $scanSteps),
                ),
            );
        }
    }

