    public function testSameArgumentFloorCeilSumFindsIntervalsAcrossRationalPoles(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $caught = false;
        try {
            Math::solve(
                'floor(1/x) + ceil(1/x) = 3',
                'x',
                -5.0,
                5.0,
                solverOptions: $options,
            );
        } catch (InfiniteSolutionSetException) {
            $caught = true;
        }
        self::assertTrue($caught);

        foreach (
            [
                ['floor(1/x) + ceil(1/x) = 3', 0.5, 1.0, false, false],
                ['3 = floor(1/x) + ceil(1/x)', 0.5, 1.0, false, false],
                ['floor(1/x) + ceil(1/x) = -1', -5.0, -1.0, true, false],
            ] as [$equation, $lower, $upper, $includesLower, $includesUpper]
        ) {
            $intervals = Math::solveEquationSet(
                $equation,
                'x',
                -5.0,
                5.0,
                solverOptions: $options,
            );
            self::assertCount(1, $intervals, $equation);
            self::assertEqualsWithDelta($lower, $intervals[0]->lowerBound, 1.0E-12, $equation);
            self::assertEqualsWithDelta($upper, $intervals[0]->upperBound, 1.0E-12, $equation);
            self::assertSame($includesLower, $intervals[0]->includesLowerBound, $equation);
            self::assertSame($includesUpper, $intervals[0]->includesUpperBound, $equation);
        }

        $removableHoleIntervals = Math::solveEquationSet(
            'floor((3*x-3)/(2*x-2)) + ceil((3*x-3)/(2*x-2)) = 3',
            'x',
            -5.0,
            5.0,
            solverOptions: $options,
        );
        self::assertCount(2, $removableHoleIntervals);
        self::assertSame(-5.0, $removableHoleIntervals[0]->lowerBound);
        self::assertSame(1.0, $removableHoleIntervals[0]->upperBound);
        self::assertTrue($removableHoleIntervals[0]->includesLowerBound);
        self::assertFalse($removableHoleIntervals[0]->includesUpperBound);
        self::assertSame(1.0, $removableHoleIntervals[1]->lowerBound);
        self::assertSame(5.0, $removableHoleIntervals[1]->upperBound);
        self::assertFalse($removableHoleIntervals[1]->includesLowerBound);
        self::assertTrue($removableHoleIntervals[1]->includesUpperBound);

        $differentEquivalentArgumentIntervals = Math::solveEquationSet(
            'floor((3*x-3)/(2*x-2)) + ceil(1.5) = 3',
            'x',
            -5.0,
            5.0,
            solverOptions: $options,
        );
        self::assertCount(2, $differentEquivalentArgumentIntervals);
        self::assertSame(1.0, $differentEquivalentArgumentIntervals[0]->upperBound);
        self::assertFalse($differentEquivalentArgumentIntervals[0]->includesUpperBound);
        self::assertSame(1.0, $differentEquivalentArgumentIntervals[1]->lowerBound);
        self::assertFalse($differentEquivalentArgumentIntervals[1]->includesLowerBound);
        $caughtEquivalentArgumentSet = false;
        try {
            Math::solve(
                'floor((3*x-3)/(2*x-2)) + ceil(1.5) = 3',
                'x',
                -5.0,
                5.0,
                solverOptions: $options,
            );
        } catch (InfiniteSolutionSetException) {
            $caughtEquivalentArgumentSet = true;
        }
        self::assertTrue($caughtEquivalentArgumentSet);

        $evenTargetRoots = Math::solve(
            'floor(1/x) + ceil(1/x) = 4',
            'x',
            -5.0,
            5.0,
            solverOptions: $options,
        );
        self::assertCount(1, $evenTargetRoots);
        self::assertSame(0.5, $evenTargetRoots[0]->value);
    }

    public function testUnboundedSameArgumentFloorCeilSumsClassifyIntervalsAndPoints(): void
    {
        foreach (
            [
                'floor(x) + ceil(x) = 3',
                '3 = floor(x / 2) + ceil(x / 2)',
                'floor(x) + floor(x) = 4',
                'floor(x^2) + floor(x^2) = 2',
                '2 * floor(x) = 4',
                'round(x) + round(x) = 4',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', -\INF, \INF);
                self::fail("Expected an infinite solution set for {$equation}.");
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        foreach (
            [
                'floor(x) + ceil(x) = 2' => [1.0],
                'floor(x / 2) + ceil(x / 2) = 2' => [2.0],
                'floor(-x^2) + floor(-x^2) = 0' => [0.0],
            ] as $equation => $expected
        ) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF);
            self::assertSame(
                $expected,
                \array_map(static fn (EquationSolution $solution): float => $solution->value, $solutions),
                $equation,
            );
        }
    }

