        foreach (
            [
                ['binomial(x, 2) = 6', -10.0, 10.0, [4.0]],
                ['permutation(x, 2) = 12', -10.0, 10.0, [4.0]],
                ['binomial(x^2, 2) = 6', -10.0, 10.0, [-2.0, 2.0]],
                ['permutation(x^2, 2) = 12', -10.0, 10.0, [-2.0, 2.0]],
                ['binomial(5, x) = 10', -2.0, 8.0, [2.0, 3.0]],
                ['permutation(5, x) = 20', -2.0, 8.0, [2.0]],
                ['binomial(10, x^2) = 210', -5.0, 5.0, [-\sqrt(6.0), -2.0, 2.0, \sqrt(6.0)]],
                ['permutation(5, x^2) = 120', -5.0, 5.0, [-\sqrt(5.0), -2.0, 2.0, \sqrt(5.0)]],
                ['binomial(x, x - 2) = 6', -10.0, 10.0, [4.0]],
                ['permutation(x, x - 2) = 12', -10.0, 10.0, [4.0]],
                ['binomial(x^2, x^2 - 2) = 6', -5.0, 5.0, [-2.0, 2.0]],
