    public function testCombinatorialEquationsPreserveQuantizedSolutionIntervals(): void
    {
        $options = new SolverOptions(scanSteps: 8);
        $cases = [
            ['permutation(5, floor(x)) = 20', 0.0, 5.0, [[2.0, 3.0]]],
            ['binomial(floor(x), floor(x) - 2) = 6', 0.0, 6.0, [[4.0, 5.0]]],
            [
                'binomial(10, round(x)) = 45',
                0.0,
                10.0,
                [[1.5, 2.5], [7.5, 8.5]],
            ],
        ];

        foreach ($cases as [$equation, $lowerBound, $upperBound, $expectedIntervals]) {
            $intervals = Math::solveEquationSet(
                $equation,
                'x',
                $lowerBound,
                $upperBound,
                solverOptions: $options,
            );

            self::assertCount(\count($expectedIntervals), $intervals, $equation);
            foreach ($expectedIntervals as $index => [$expectedLower, $expectedUpper]) {
                self::assertSame($expectedLower, $intervals[$index]->lowerBound, $equation);
                self::assertSame($expectedUpper, $intervals[$index]->upperBound, $equation);
                self::assertTrue($intervals[$index]->includesLowerBound, $equation);
                self::assertFalse($intervals[$index]->includesUpperBound, $equation);
            }

            try {
                Math::solve(
                    $equation,
                    'x',
                    $lowerBound,
                    $upperBound,
                    solverOptions: $options,
                );
                self::fail('An infinite combinatorial solution set must not be returned as point roots.');
            } catch (InfiniteSolutionSetException) {
                continue;
            }
        }
    }

    public function testCombinatorialQuantizedPeriodicArgumentFindsEveryInterval(): void
    {
        $a = \asin(0.4);
        $b = \asin(0.6);
        $period = 2.0 * \M_PI;
        $expected = [[\max(-10.0, \M_PI - $b - (2.0 * $period)), \M_PI - $a - (2.0 * $period), true, true]];
        for ($periodIndex = -1; $periodIndex <= 1; ++$periodIndex) {
            $shift = $periodIndex * $period;
            $expected[] = [$a + $shift, $b + $shift, true, false];
            $expected[] = [\M_PI - $b + $shift, \M_PI - $a + $shift, false, true];
        }

        $intervals = Math::solveEquationSet(
            'binomial(10, floor(5 * sin(x))) = 45',
            'x',
            -10.0,
            10.0,
            solverOptions: new SolverOptions(scanSteps: 8),
        );

        self::assertCount(7, $intervals);
        foreach ($expected as $index => [$expectedLower, $expectedUpper, $includesLower, $includesUpper]) {
            self::assertEqualsWithDelta($expectedLower, $intervals[$index]->lowerBound, 1.0E-8);
            self::assertEqualsWithDelta($expectedUpper, $intervals[$index]->upperBound, 1.0E-8);
            self::assertSame($includesLower, $intervals[$index]->includesLowerBound);
            self::assertSame($includesUpper, $intervals[$index]->includesUpperBound);
        }
    }

