    public function testDirectMinimumAndMaximumEquationsPreserveTheirSolutionSets(): void
    {
        foreach (
            [
                'min(sin(x), 0) = 0',
                'max(abs(x), 1) = 1',
                'max(-x^2, -1) = -1',
            ] as $equation
        ) {
            $threw = false;
            try {
                Math::solve(
                    $equation,
                    'x',
                    -5.0,
                    5.0,
                    solverOptions: new SolverOptions(scanSteps: 8),
                );
            } catch (InfiniteSolutionSetException) {
                $threw = true;
            }
            self::assertTrue($threw, $equation);
        }

        $isolated = Math::solve(
            'min(abs(x), 1) = 0.5',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 8),
        );
        self::assertCount(2, $isolated);
        self::assertEqualsWithDelta(-0.5, $isolated[0]->value, 1.0E-9);
        self::assertEqualsWithDelta(0.5, $isolated[1]->value, 1.0E-9);

        $tangent = Math::solve(
            'min(x^2, 1) = 0',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 8),
        );
        self::assertCount(1, $tangent);
        self::assertSame(0.0, $tangent[0]->value);
    }

    public function testSolvesGcdAndLcmEquationsByEnumeratingIntegerLevels(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $gcd = Math::solve(
            'gcd(x, 6) = 3',
            'x',
            -10.0,
            10.0,
            solverOptions: $options,
        );
        $lcm = Math::solve(
            '12 = lcm(x, 6)',
            'x',
            -15.0,
            15.0,
            solverOptions: $options,
        );
        $polynomialArgument = Math::solve(
            'gcd(x^2, 6) = 3',
            'x',
            -5.0,
            5.0,
            solverOptions: $options,
        );
        $nonIntegerTarget = Math::solve(
            'gcd(x, 6) = 2.5',
            'x',
            -10.0,
            10.0,
            solverOptions: $options,
        );
        $rationalGcd = Math::solve(
            'gcd(1 / (x + 1), 1) = 1',
            'x',
            -0.4,
            0.4,
            solverOptions: $options,
        );
        $rationalLcm = Math::solve(
            'lcm(1 / (x + 1), 1) = 1',
            'x',
            -0.4,
            0.4,
            solverOptions: $options,
        );
        $rationalIntegerLevels = Math::solve(
            'gcd(1 / x, 6) = 3',
            'x',
            0.05,
            0.5,
            solverOptions: $options,
        );

        self::assertCount(4, $gcd);
        foreach ([-9.0, -3.0, 3.0, 9.0] as $index => $root) {
            self::assertSame($root, $gcd[$index]->value);
        }
        self::assertCount(4, $lcm);
        foreach ([-12.0, -4.0, 4.0, 12.0] as $index => $root) {
            self::assertSame($root, $lcm[$index]->value);
        }
        self::assertCount(8, $polynomialArgument);
        $expectedPolynomialRoots = [
            -\sqrt(21.0), -\sqrt(15.0), -3.0, -\sqrt(3.0),
            \sqrt(3.0), 3.0, \sqrt(15.0), \sqrt(21.0),
        ];
        foreach ($expectedPolynomialRoots as $index => $root) {
            self::assertEqualsWithDelta($root, $polynomialArgument[$index]->value, 1.0E-10);
        }
        self::assertSame([], $nonIntegerTarget);
        self::assertCount(1, $rationalGcd);
        self::assertSame(0.0, $rationalGcd[0]->value);
        self::assertCount(1, $rationalLcm);
        self::assertSame(0.0, $rationalLcm[0]->value);
        self::assertCount(3, $rationalIntegerLevels);
        foreach ([1.0 / 15.0, 1.0 / 9.0, 1.0 / 3.0] as $index => $root) {
            self::assertEqualsWithDelta($root, $rationalIntegerLevels[$index]->value, 1.0E-12);
        }
    }

    public function testUnboundedPolynomialGcdAndLcmEquationsAreClassified(): void
    {
        foreach (['gcd(x, 6) = 3', 'gcd(x^2, 6) = 3', 'lcm(x, 0) = 0'] as $equation) {
            try {
                Math::solve($equation, 'x', -\INF, \INF);
                self::fail('Expected infinitely many roots for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        $lcmRoots = Math::solve('lcm(x, 6) = 12', 'x', -\INF, \INF);
        self::assertSame(
            [-12.0, -4.0, 4.0, 12.0],
            \array_map(static fn ($solution): float => $solution->value, $lcmRoots),
        );

        $polynomialRoots = Math::solve('lcm(x^2, 6) = 12', 'x', 0.0, \INF);
        self::assertEqualsWithDelta(
            [2.0, \sqrt(12.0)],
            \array_map(static fn ($solution): float => $solution->value, $polynomialRoots),
            1.0E-10,
        );

        self::assertSame([], Math::solve('gcd(x, 6) = 5', 'x', -\INF, \INF));
        self::assertSame(
            [-3.0, 3.0],
            \array_map(
                static fn ($solution): float => $solution->value,
                Math::solve('gcd(x, 0) = 3', 'x', -\INF, \INF),
            ),
        );
    }

    public function testUnboundedPolynomialCombinatorialEquationsUseIntegerLevels(): void
    {
        foreach (
            [
                'binomial(x, 2) = 1' => [2.0],
                'permutation(x, 2) = 2' => [2.0],
                'binomial(x, 2) = 0' => [0.0, 1.0],
                'binomial(4, x) = 4' => [1.0, 3.0],
                'permutation(4, x) = 12' => [2.0],
                'doublefactorial(x) = 3' => [3.0],
                'doublefactorial(x^2) = 1' => [-1.0, 0.0, 1.0],
            ] as $equation => $expected
        ) {
            $solutions = Math::solve($equation, 'x', -\INF, \INF);
            self::assertEqualsWithDelta(
                $expected,
                \array_map(static fn ($solution): float => $solution->value, $solutions),
                1.0E-10,
                $equation,
            );
        }

        foreach (['binomial(x, 0) = 1', 'binomial(4, x) = 0'] as $equation) {
            try {
                Math::solve($equation, 'x', -\INF, \INF);
                self::fail('Expected infinitely many roots for ' . $equation);
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        self::assertSame(
            [0.0],
            \array_map(
                static fn ($solution): float => $solution->value,
                Math::solve('binomial(x, 0) = 1', 'x', -\INF, 0.0),
            ),
        );
        self::assertSame([], Math::solve('binomial(4, x) = 0', 'x', -\INF, 0.0));
        self::assertSame(
            [0.0],
            \array_map(
                static fn ($solution): float => $solution->value,
                Math::solve('binomial(4, -x^2) = 1', 'x', -\INF, \INF),
            ),
        );
    }

