    public function testRationalGcdAndLcmHandleIntegerLevelsNearPoles(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $lcmRoots = Math::solve(
            'lcm(1 / x, 6) = 12',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        self::assertCount(4, $lcmRoots);
        foreach ([-0.25, -1.0 / 12.0, 1.0 / 12.0, 0.25] as $index => $root) {
            self::assertEqualsWithDelta($root, $lcmRoots[$index]->value, 1.0E-12);
        }

        $reversedNegativeConstantRoots = Math::solve(
            'lcm(-6, 1 / (x - 0.123)) = 12',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        self::assertCount(4, $reversedNegativeConstantRoots);
        foreach ([-0.127, 0.123 - (1.0 / 12.0), 0.123 + (1.0 / 12.0), 0.373] as $index => $root) {
            self::assertEqualsWithDelta($root, $reversedNegativeConstantRoots[$index]->value, 1.0E-12);
        }

        self::assertSame(
            [],
            Math::solve('gcd(1 / x, 6) = 5', 'x', -1.0, 1.0, solverOptions: $options),
        );
        self::assertSame(
            [-0.5, 0.5],
            \array_map(
                static fn ($solution): float => $solution->value,
                Math::solve('gcd(1 / x, 0) = 2', 'x', -1.0, 1.0, solverOptions: $options),
            ),
        );

        $this->expectException(InfiniteRootAccumulationException::class);
        Math::solve('gcd(1 / x, 6) = 3', 'x', -1.0, 1.0, solverOptions: $options);
    }

