    public function testPolygammaOfPositivePolynomialFindsEveryLevelPreimage(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $expectedRoots = [-1.3065629648764, -0.5411961001462, 0.5411961001462, 1.3065629648764];
        foreach ([0, 1, 2, 3, 8, SpecialFunctions::MAX_POLYGAMMA_ORDER] as $order) {
            $target = \sprintf('%.17g', SpecialFunctions::polygamma($order, 1.0));
            $equation = 'polygamma(' . $order . ', 0.5 + (x^2 - 1)^2) = ' . $target;
            $solutions = Math::solve($equation, 'x', -2.0, 2.0, solverOptions: $options);

            self::assertCount(4, $solutions, $equation);
            foreach ($expectedRoots as $index => $root) {
                self::assertEqualsWithDelta($root, $solutions[$index]->value, 1.0E-8, $equation);
                self::assertLessThanOrEqual(
                    1.0E-10,
                    $solutions[$index]->residual / \abs((float) $target),
                    $equation,
                );
            }
        }

        self::assertSame(
            [],
            Math::solve('polygamma(129, x^2 + 1) = 0', 'x', -2.0, 2.0, solverOptions: $options),
        );
    }

    public function testModifiedBesselLevelsInvertAcrossRealArgumentBranches(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $expectedRoots = [-1.3065629648764, -0.5411961001462, 0.5411961001462, 1.3065629648764];

        foreach ([0, 1, 2, -3, 16] as $order) {
            $target = \sprintf('%.17g', SpecialFunctions::besselI($order, 1.0));
            $functionCall = 'besseli(' . $order . ', 0.5 + (x^2 - 1)^2)';
            $equation = $order === -3 ? $target . ' = ' . $functionCall : $functionCall . ' = ' . $target;
            $solutions = Math::solve($equation, 'x', -2.0, 2.0, solverOptions: $options);

            self::assertCount(4, $solutions, $equation);
            foreach ($expectedRoots as $index => $root) {
                self::assertEqualsWithDelta($root, $solutions[$index]->value, 1.0E-8, $equation);
                self::assertLessThanOrEqual(
                    1.0E-10,
                    $solutions[$index]->residual / \max(\abs((float) $target), \PHP_FLOAT_MIN),
                    $equation,
                );
            }
        }

        $target = \sprintf('%.17g', SpecialFunctions::besselI(0, 2.0));
        $solutions = Math::solve(
            'besseli(0, 2 + 0.5*cos(2*x)) = ' . $target,
            'x',
            -2.0 * \M_PI,
            2.0 * \M_PI,
            solverOptions: $options,
        );
        $expectedPeriodicRoots = [
            -(7.0 * \M_PI / 4.0),
            -(5.0 * \M_PI / 4.0),
            -(3.0 * \M_PI / 4.0),
            -(M_PI / 4.0),
            \M_PI / 4.0,
            3.0 * \M_PI / 4.0,
            5.0 * \M_PI / 4.0,
            7.0 * \M_PI / 4.0,
        ];
        self::assertCount(8, $solutions);
        foreach ($expectedPeriodicRoots as $index => $root) {
            self::assertEqualsWithDelta($root, $solutions[$index]->value, 1.0E-8);
            self::assertLessThanOrEqual(
                1.0E-10,
                $solutions[$index]->residual / (float) $target,
            );
        }

        foreach (
            [
                ['besseli(1, (x^2 - 1)^2 - 1) = 0', [-\sqrt(2.0), 0.0, \sqrt(2.0)]],
                ['besseli(0, (x^2 - 1)^2 - 1) = 1', [-\sqrt(2.0), 0.0, \sqrt(2.0)]],
                [
                    'besseli(1, cos(x)) = 0',
                    [-3.0 * \M_PI / 2.0, -\M_PI / 2.0, \M_PI / 2.0, 3.0 * \M_PI / 2.0],
                ],
                [
                    'besseli(0, cos(x)) = 1',
                    [-3.0 * \M_PI / 2.0, -\M_PI / 2.0, \M_PI / 2.0, 3.0 * \M_PI / 2.0],
                ],
            ] as [$equation, $expectedRoots]
        ) {
            $solutions = Math::solve($equation, 'x', -2.0 * \M_PI, 2.0 * \M_PI, solverOptions: $options);

            self::assertCount(\count($expectedRoots), $solutions, $equation);
            foreach ($expectedRoots as $index => $root) {
                self::assertEqualsWithDelta($root, $solutions[$index]->value, 1.0E-8, $equation);
                self::assertLessThanOrEqual(1.0E-10, $solutions[$index]->residual, $equation);
            }
        }
        self::assertSame([], Math::solve('besseli(0, cos(x)) = 0', 'x', -2.0 * \M_PI, 2.0 * \M_PI));

        foreach (
            [
                [
                    'besseli(1, x^2 - 1) = ' . \sprintf('%.17g', SpecialFunctions::besselI(1, -0.5)),
                    [-\sqrt(0.5), \sqrt(0.5)],
                ],
                [
                    'besseli(2, x) = ' . \sprintf('%.17g', SpecialFunctions::besselI(2, 1.0)),
                    [-1.0, 1.0],
                ],
                [
                    'besseli(0, x) = ' . \sprintf('%.17g', SpecialFunctions::besselI(0, 1.0)),
                    [-1.0, 1.0],
                ],
            ] as [$equation, $expectedRoots]
        ) {
            $solutions = Math::solve($equation, 'x', -2.0, 2.0, solverOptions: $options);

            self::assertCount(\count($expectedRoots), $solutions, $equation);
            foreach ($expectedRoots as $index => $root) {
                self::assertEqualsWithDelta($root, $solutions[$index]->value, 1.0E-8, $equation);
                self::assertLessThanOrEqual(
                    1.0E-10,
                    $solutions[$index]->residual
                        / \max(1.0, \abs((float) \explode(' = ', $equation)[1])),
                    $equation,
                );
            }
        }

        foreach ([-4, -3, -2, -1, 0, 1, 2, 3, 4] as $order) {
            $target = \sprintf('%.17g', SpecialFunctions::besselI($order, 0.75));
            $equation = 'besseli(' . $order . ', 2*x + 0.25) = ' . $target;
            $solutions = Math::solve($equation, 'x', -2.0, 2.0, solverOptions: $options);
            $expectedRoots = ($order & 1) === 0 ? [-0.5, 0.25] : [0.25];

            self::assertCount(\count($expectedRoots), $solutions, $equation);
            foreach ($expectedRoots as $index => $root) {
                self::assertEqualsWithDelta($root, $solutions[$index]->value, 1.0E-9, $equation);
                self::assertLessThanOrEqual(1.0E-10, $solutions[$index]->residual, $equation);
            }
        }
    }

    public function testEqualModifiedBesselCallsReduceByOrderParity(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $cases = [
            ['besseli(1, x^2) = besseli(-1, 1)', [-1.0, 1.0]],
            ['besseli(2, x) = besseli(2, x^2)', [-1.0, 0.0, 1.0]],
            ['besseli(0, x) = besseli(0, x^2)', [-1.0, 0.0, 1.0]],
        ];

        foreach ($cases as [$equation, $expectedRoots]) {
            $solutions = Math::solve($equation, 'x', -2.0, 2.0, solverOptions: $options);

            self::assertCount(\count($expectedRoots), $solutions, $equation);
            foreach ($expectedRoots as $index => $root) {
                self::assertEqualsWithDelta($root, $solutions[$index]->value, 1.0E-9, $equation);
                self::assertLessThanOrEqual(1.0E-10, $solutions[$index]->residual, $equation);
            }
        }

        $this->expectException(\MathPHP\Solver\InfiniteSolutionSetException::class);
        Math::solve('besseli(2, x) = besseli(2, -x)', 'x', -2.0, 2.0, solverOptions: $options);
    }

    public function testEqualPolygammaCallsCancelOnStrictlyPositiveArgumentRanges(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        foreach (['digamma', 'trigamma', 'tetragamma'] as $function) {
            $equation = $function . '(x^2 + 1) = ' . $function . '(2)';
            $solutions = Math::solve($equation, 'x', -3.0, 3.0, solverOptions: $options);

            self::assertCount(2, $solutions, $equation);
            self::assertEqualsWithDelta(-1.0, $solutions[0]->value, 1.0E-9, $equation);
            self::assertEqualsWithDelta(1.0, $solutions[1]->value, 1.0E-9, $equation);
        }

        foreach ([0, 1, 2, 8, SpecialFunctions::MAX_POLYGAMMA_ORDER] as $order) {
            $equation = 'polygamma(' . $order . ', x^2 + 1) = polygamma(' . $order . ', 2)';
            $solutions = Math::solve($equation, 'x', -3.0, 3.0, solverOptions: $options);

            self::assertCount(2, $solutions, $equation);
            self::assertEqualsWithDelta(-1.0, $solutions[0]->value, 1.0E-9, $equation);
            self::assertEqualsWithDelta(1.0, $solutions[1]->value, 1.0E-9, $equation);
        }

        $periodicSolutions = Math::solve(
            'polygamma(3, 2 + sin(2*x)) = polygamma(3, 2)',
            'x',
            -2.0 * \M_PI,
            2.0 * \M_PI,
            solverOptions: $options,
        );
        self::assertCount(9, $periodicSolutions);
        foreach (range(-4, 4) as $index => $multiple) {
            self::assertEqualsWithDelta(
                $multiple * \M_PI / 2.0,
                $periodicSolutions[$index]->value,
                1.0E-8,
            );
        }
    }

