    }

    public function testRegularizedGammaAndBetaPolynomialArgumentsFindEveryLevelPreimage(): void
    {
        $gammaTarget = \sprintf('%.17g', SpecialFunctions::regularizedGammaP(2.0, 1.0));
        $betaTarget = \sprintf('%.17g', SpecialFunctions::regularizedBeta(2.0, 3.0, 0.25));
        $gammaComplementTarget = \sprintf('%.17g', 1.0 - (float) $gammaTarget);
        $betaComplementTarget = \sprintf('%.17g', 1.0 - (float) $betaTarget);
        $expectedGammaRoots = [-1.3065629648764, -0.5411961001462, 0.5411961001462, 1.3065629648764];
        $expectedBetaRoots = [-1.3381215994976, -0.45763586502579, 0.45763586502579, 1.3381215994976];
        $cases = [
            ['gammainc(2, 0.5 + (x^2 - 1)^2) = ' . $gammaTarget, $expectedGammaRoots],
            [
                'gammaincc(2, 0.5 + (x^2 - 1)^2) = '
                    . $gammaComplementTarget,
                $expectedGammaRoots,
            ],
            ['betainc(2, 3, 0.2 + 0.08*(x^2 - 1)^2) = ' . $betaTarget, $expectedBetaRoots],
            [
                'betaincc(2, 3, 0.2 + 0.08*(x^2 - 1)^2) = ' . $betaComplementTarget,
                $expectedBetaRoots,
            ],
        ];

        foreach ($cases as [$equation, $expectedRoots]) {
            $solutions = Math::solve(
                $equation,
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );

            self::assertCount(4, $solutions, $equation);
            foreach ($expectedRoots as $index => $expectedRoot) {
                self::assertEqualsWithDelta($expectedRoot, $solutions[$index]->value, 1.0E-9, $equation);
                self::assertLessThanOrEqual(1.0E-9, $solutions[$index]->residual, $equation);
            }
        }
    }

