    public function testBetaRecurrenceIsRecognizedAcrossPositiveAndNegativeNonPoleRanges(): void
    {
        foreach (
            [
                'beta(x + 1, 2) = x / (x + 2) * beta(x, 2)',
                'beta(x + 1, 2) = beta(x, 2) * x / (x + 2)',
                'x / (x + 2) * beta(x, 2) = beta(x + 1, 2)',
                'beta(x + 2, 2) = x * (x + 1) / ((x + 2) * (x + 3)) * beta(x, 2)',
                'beta(x + 2, 2) = beta(x, 2) * x * (x + 1) / ((x + 2) * (x + 3))',
                'beta(x, 2) = beta(x + 2, 2) * (x + 2) * (x + 3) / (x * (x + 1))',
                'beta(2, x + 1) = x / (x + 2) * beta(2, x)',
                'beta(2, x + 2) = x * (x + 1) / ((x + 2) * (x + 3)) * beta(2, x)',
                'beta(2, x) = beta(2, x + 2) * (x + 2) * (x + 3) / (x * (x + 1))',
                'beta(x + 1, -0.5) = x / (x - 0.5) * beta(x, -0.5)',
                'beta(-0.5, x + 1) = x / (x - 0.5) * beta(-0.5, x)',
            ] as $equation
        ) {
            foreach ([[0.1, 5.0], [-5.0, -0.1]] as [$lowerBound, $upperBound]) {
                try {
                    Math::solve($equation, 'x', $lowerBound, $upperBound);
                    self::fail('Expected infinitely many Beta recurrence solutions for ' . $equation);
                } catch (InfiniteSolutionSetException) {
                    self::assertTrue(true);
                }
            }
        }

        self::assertCount(
            1,
            Math::solve('beta(x + 1, 2) = x / (x + 2) * beta(x, 2)', 'x', 1.0, 1.0),
        );

        try {
            Math::solve('beta(x + 1, 2) = x / (x + 3) * beta(x, 2)', 'x', 0.1, 5.0);
        } catch (InfiniteSolutionSetException) {
            self::fail('A changed Beta recurrence denominator is not an identity.');
        } catch (RootSearchLimitException) {
            self::assertTrue(true);
        }

        try {
            Math::solve('beta(x + 1, -2) = x / (x - 2) * beta(x, -2)', 'x', 3.0, 5.0);
        } catch (InfiniteSolutionSetException) {
            self::fail('A pole-valued fixed Beta parameter has no defined recurrence domain.');
        } catch (RootSearchLimitException) {
            self::assertTrue(true);
        }
    }

    public function testIntegerShapeBetaReductionPreservesSymmetryAndNegativeRoots(): void
    {
        foreach (['beta(x, 2) = 1', 'beta(2, x) = 1'] as $equation) {
            $solutions = Math::solve($equation, 'x', -2.0, 1.0);
            self::assertCount(2, $solutions, $equation);
            self::assertEqualsWithDelta((-1.0 - \sqrt(5.0)) / 2.0, $solutions[0]->value, 1.0E-10);
            self::assertEqualsWithDelta((-1.0 + \sqrt(5.0)) / 2.0, $solutions[1]->value, 1.0E-10);
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-10, $solution->residual);
            }
        }

        self::assertCount(1, Math::solve('beta(x, 2) = 1', 'x', 0.0, 1.0));
    }

    public function testIntegerShapeBetaReductionRecoversNegativeNonPoleInputs(): void
    {
        foreach ([1, 2, 3, 5, 8] as $shape) {
            foreach ([-5.5, -4.5, -3.5, -2.5, -1.5, -0.5, 0.25, 0.8, 1.5, 3.25] as $expectedRoot) {
                $target = (float) Math::evaluate(
                    'beta(' . \sprintf('%.17g', $expectedRoot) . ', ' . $shape . ')',
                );
                $solutions = Math::solve(
                    'beta(x, ' . $shape . ') = ' . \sprintf('%.17g', $target),
                    'x',
                    -6.0,
                    5.0,
                );
                $matched = false;
                foreach ($solutions as $solution) {
                    if (\abs($solution->value - $expectedRoot) <= 1.0E-6) {
                        $matched = true;
                        self::assertLessThanOrEqual(1.0E-8, $solution->residual);
                        break;
                    }
                }
                self::assertTrue(
                    $matched,
                    'Missing beta root for shape ' . $shape . ' at ' . $expectedRoot,
                );
            }
        }
    }

