    public function testBetaZeroEquationCombinesTwoDifferentAffineTrigPhases(): void
    {
        foreach (
            [
                'beta(sin(x), sin(2*x)) = 0' => [9, 'sin(x)', 'sin(2*x)'],
                'beta(cos(x), cos(2*x)) = 0' => [12, 'cos(x)', 'cos(2*x)'],
                'beta(sin(x), cos(2*x)) = 0' => [13, 'sin(x)', 'cos(2*x)'],
                'beta(sin(x) + sin(2*x), cos(3*x)) = 0' => [26, 'sin(x) + sin(2*x)', 'cos(3*x)'],
            ] as $equation => [$expectedCount, $firstArgument, $secondArgument]
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                -10.0,
                10.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );

            self::assertCount($expectedCount, $solutions, $equation);
            foreach ($solutions as $solution) {
                self::assertSame(0.0, $solution->residual, $equation);
                foreach ([$firstArgument, $secondArgument] as $argument) {
                    $value = Math::evaluate($argument, ['x' => $solution->value]);
                    $nearestInteger = \round($value);
                    self::assertFalse(
                        $nearestInteger <= 0.0 && \abs($value - $nearestInteger) < 1.0E-8,
                        $equation . ' retained a beta pole.',
                    );
                }
            }
        }
    }

    public function testMatchingPolynomialSineCosineBetaPhasesUseExactLevels(): void
    {
        $expected = [];
        for ($level = 1; $level <= 5; ++$level) {
            $root = \sqrt((-\M_PI / 4.0) + ($level * \M_PI));
            $expected[] = -$root;
            $expected[] = $root;
        }
        \sort($expected, SORT_NUMERIC);

        foreach (
            ['beta(sin(x^2), cos(x^2)) = 0', 'beta(cos(x^2), sin(x^2)) = 0'] as $equation
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                -4.0,
                4.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );

            self::assertEqualsWithDelta(
                $expected,
                \array_map(static fn ($solution): float => $solution->value, $solutions),
                1.0E-9,
                $equation,
            );
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-12, $solution->residual, $equation);
            }
        }

        foreach (
            [
                'beta(sin(x^2), sin(x^2)) = 0' => [7.0 * \M_PI / 6.0, 11.0 * \M_PI / 6.0],
                'beta(cos(x^2), cos(x^2)) = 0' => [2.0 * \M_PI / 3.0, 4.0 * \M_PI / 3.0],
            ] as $equation => $phaseOffsets
        ) {
            $expected = [];
            foreach ($phaseOffsets as $offset) {
                for ($period = 0; $period <= 2; ++$period) {
                    $phase = $offset + (2.0 * \M_PI * $period);
                    if ($phase > 16.0) {
                        continue;
                    }
                    $root = \sqrt($phase);
                    $expected[] = -$root;
                    $expected[] = $root;
                }
            }
            \sort($expected, SORT_NUMERIC);
            $solutions = Math::solve(
                $equation,
                'x',
                -4.0,
                4.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );

            self::assertEqualsWithDelta(
                $expected,
                \array_map(static fn ($solution): float => $solution->value, $solutions),
                1.0E-9,
                $equation,
            );
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-12, $solution->residual, $equation);
            }
        }
    }

    public function testShiftedPolynomialSineCosineBetaPhasesUseCombinedAmplitude(): void
    {
        $phaseShift = \M_PI / 3.0;
        $sineCoefficient = 1.0 - \sin($phaseShift);
        $cosineCoefficient = \cos($phaseShift);
        $combinedPhase = \atan2($cosineCoefficient, $sineCoefficient);
        $expected = [];
        for ($period = 0; $period <= 3; ++$period) {
            foreach (
                [-$combinedPhase, \M_PI - $combinedPhase] as $offset
            ) {
                $phase = $offset + (2.0 * \M_PI * $period);
                if ($phase < 0.0 || $phase > 16.0) {
                    continue;
                }
                $root = \sqrt($phase);
                $expected[] = -$root;
                $expected[] = $root;
            }
        }
        \sort($expected, SORT_NUMERIC);

        $solutions = Math::solve(
            'beta(sin(x^2), cos(x^2 + pi / 3)) = 0',
            'x',
            -4.0,
            4.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertEqualsWithDelta(
            $expected,
            \array_map(static fn ($solution): float => $solution->value, $solutions),
            1.0E-9,
        );
        foreach ($solutions as $solution) {
            self::assertLessThanOrEqual(1.0E-12, $solution->residual);
        }
    }

