    public function testFactorialEquationsSearchTheirDiscreteIntegerDomain(): void
    {
        $factorialRoot = Math::solve(
            'x! = 6',
            'x',
            0.1,
            5.9,
            solverOptions: new SolverOptions(scanSteps: 17),
        );
        $affineOperandRoot = Math::solve('(2 * x + 1)! = 6', 'x', 0.1, 5.9);
        $scaledOperandRoot = Math::solve('(x / 2)! = 6', 'x', 0.1, 10.9);
        $polynomialOperandRoots = Math::solve('(x^2)! = 2', 'x', -2.0, 2.0);
        $higherPolynomialOperandRoots = Math::solve('(x^4)! = 2', 'x', -2.0, 2.0);
        $repeatedLevelRoots = Math::solve('((x^2 - 2)^2)! = 1', 'x', -2.0, 2.0);
        $highMultiplicityLevelRoots = Math::solve('((x^2 - 2)^8)! = 1', 'x', -2.0, 2.0);
        $fixedPoints = Math::solve('x! = x', 'x', 0.1, 5.9);
        $noInteger = Math::solve('x! = 6', 'x', 2.1, 2.9);

        self::assertCount(1, $factorialRoot);
        self::assertSame(3.0, $factorialRoot[0]->value);
        self::assertSame(0.0, $factorialRoot[0]->residual);
        self::assertCount(1, $affineOperandRoot);
        self::assertSame(1.0, $affineOperandRoot[0]->value);
        self::assertCount(1, $scaledOperandRoot);
        self::assertSame(6.0, $scaledOperandRoot[0]->value);
        self::assertCount(2, $polynomialOperandRoots);
        self::assertEqualsWithDelta(-\sqrt(2.0), $polynomialOperandRoots[0]->value, 1.0E-12);
        self::assertEqualsWithDelta(\sqrt(2.0), $polynomialOperandRoots[1]->value, 1.0E-12);
        self::assertSame(0.0, $polynomialOperandRoots[0]->residual);
        self::assertSame(0.0, $polynomialOperandRoots[1]->residual);
        self::assertCount(2, $higherPolynomialOperandRoots);
        self::assertEqualsWithDelta(-\pow(2.0, 0.25), $higherPolynomialOperandRoots[0]->value, 1.0E-12);
        self::assertEqualsWithDelta(\pow(2.0, 0.25), $higherPolynomialOperandRoots[1]->value, 1.0E-12);
        self::assertCount(6, $repeatedLevelRoots);
        foreach ([-\sqrt(3.0), -\sqrt(2.0), -1.0, 1.0, \sqrt(2.0), \sqrt(3.0)] as $index => $root) {
            self::assertEqualsWithDelta($root, $repeatedLevelRoots[$index]->value, 1.0E-12);
        }
        self::assertCount(6, $highMultiplicityLevelRoots);
        foreach ([-\sqrt(3.0), -\sqrt(2.0), -1.0, 1.0, \sqrt(2.0), \sqrt(3.0)] as $index => $root) {
            self::assertEqualsWithDelta($root, $highMultiplicityLevelRoots[$index]->value, 1.0E-12);
        }
        self::assertCount(2, $fixedPoints);
        self::assertSame(1.0, $fixedPoints[0]->value);
        self::assertSame(2.0, $fixedPoints[1]->value);
        self::assertSame([], $noInteger);
    }

    public function testUnboundedPolynomialFactorialEquationsEnumerateTheirIntegerDomain(): void
    {
        foreach (
            [
                ['x! = 6', -\INF, \INF, [3.0]],
                ['x! = 1', -\INF, \INF, [0.0, 1.0]],
                ['x! = x', -\INF, \INF, [1.0, 2.0]],
                ['(x^2)! = 2', -\INF, \INF, [-\sqrt(2.0), \sqrt(2.0)]],
                ['(-x)! = 1', -\INF, 0.0, [-1.0, 0.0]],
                ['x! = 6', 4.0, \INF, []],
            ] as [$equation, $lowerBound, $upperBound, $expectedRoots]
        ) {
            $solutions = Math::solve($equation, 'x', $lowerBound, $upperBound);
            self::assertEqualsWithDelta(
                $expectedRoots,
                \array_map(static fn ($solution): float => $solution->value, $solutions),
                1.0E-10,
                $equation,
            );
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-10, $solution->residual, $equation);
            }
        }
    }

    public function testVariableIntegerRootDegreesSearchTheirDiscreteDomain(): void
    {
        $directDegree = Math::solve(
            'root(16, x) = 2',
            'x',
            1.0,
            6.0,
            solverOptions: new SolverOptions(scanSteps: 17),
        );
        $affineDegree = Math::solve(
            'root(16, 2 * x + 1) = 2',
            'x',
            0.0,
            3.0,
            solverOptions: new SolverOptions(scanSteps: 17),
        );
        $negativeRadicand = Math::solve(
            'root(-32, x) = -2',
            'x',
            1.0,
            7.0,
            solverOptions: new SolverOptions(scanSteps: 17),
        );
        $polynomialDegree = Math::solve(
            'root(16, x^2) = 4',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 17),
        );
        $interiorDegreeLevel = Math::solve(
            'root(16, -x^2 + 2 * x) = 16',
            'x',
            0.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 17),
        );

        self::assertCount(1, $directDegree);
        self::assertSame(4.0, $directDegree[0]->value);
        self::assertSame(0.0, $directDegree[0]->residual);
        self::assertCount(1, $affineDegree);
        self::assertSame(1.5, $affineDegree[0]->value);
        self::assertSame(0.0, $affineDegree[0]->residual);
        self::assertCount(1, $negativeRadicand);
        self::assertSame(5.0, $negativeRadicand[0]->value);
        self::assertSame(0.0, $negativeRadicand[0]->residual);
        self::assertCount(2, $polynomialDegree);
        self::assertEqualsWithDelta(-\sqrt(2.0), $polynomialDegree[0]->value, 1.0E-12);
        self::assertEqualsWithDelta(\sqrt(2.0), $polynomialDegree[1]->value, 1.0E-12);
        self::assertSame(0.0, $polynomialDegree[0]->residual);
        self::assertSame(0.0, $polynomialDegree[1]->residual);
        self::assertCount(1, $interiorDegreeLevel);
        self::assertSame(1.0, $interiorDegreeLevel[0]->value);
    }

    public function testTranscendentalIntegerRootDegreesAreIsolatedByTheirLevelEquations(): void
    {
        $trigonometricDegree = Math::solve(
            'root(16, sin(x)) = 16',
            'x',
            -10.0,
            10.0,
            solverOptions: new SolverOptions(scanSteps: 17),
        );
        $exponentialDegree = Math::solve(
            'root(16, exp(x)) = 2',
            'x',
            -2.0,
            4.0,
            solverOptions: new SolverOptions(scanSteps: 17),
        );
        $narrowDegreePeak = Math::solve(
            'root(16, 10 * exp(-7000 * (x - 0.141)^2)) = 2',
            'x',
            0.0,
            1.0,
            solverOptions: new SolverOptions(scanSteps: 17),
        );

        self::assertCount(3, $trigonometricDegree);
        foreach ([-3.0 * \M_PI / 2.0, \M_PI / 2.0, 5.0 * \M_PI / 2.0] as $index => $root) {
            self::assertEqualsWithDelta($root, $trigonometricDegree[$index]->value, 1.0E-8);
            self::assertSame(0.0, $trigonometricDegree[$index]->residual);
        }
        self::assertCount(1, $exponentialDegree);
        self::assertEqualsWithDelta(\log(4.0), $exponentialDegree[0]->value, 1.0E-12);
        self::assertSame(0.0, $exponentialDegree[0]->residual);
        self::assertCount(2, $narrowDegreePeak);
        $offset = \sqrt(\log(2.5) / 7000.0);
        self::assertEqualsWithDelta(0.141 - $offset, $narrowDegreePeak[0]->value, 1.0E-12);
        self::assertEqualsWithDelta(0.141 + $offset, $narrowDegreePeak[1]->value, 1.0E-12);
        self::assertSame(0.0, $narrowDegreePeak[0]->residual);
        self::assertSame(0.0, $narrowDegreePeak[1]->residual);
    }

    public function testIntegerRootEquationsInvertConstantDegreesExactly(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $positiveOddRoot = Math::solve('root(x^2, 3) = 2', 'x', -4.0, 4.0, solverOptions: $options);
        $negativeOddRoot = Math::solve('root(x, 3) = -2', 'x', -10.0, 0.0, solverOptions: $options);
        $negativeDegree = Math::solve('root(x, -3) = -0.5', 'x', -16.0, 0.0, solverOptions: $options);
        $rationalArgument = Math::solve(
            'root((x - 1) / (x + 1), 3) = 2',
            'x',
            -4.0,
            4.0,
            solverOptions: $options,
        );
        $removableHole = Math::solve(
            'root((x^2 - 1) / (x - 1), 3) = root(2, 3)',
            'x',
            0.5,
            1.5,
            solverOptions: $options,
        );
        $invalidEvenTarget = Math::solve('root(x, 2) = -2', 'x', -10.0, 10.0, solverOptions: $options);
        $zeroNegativeDegree = Math::solve('root(x, -2) = 0', 'x', -10.0, 10.0, solverOptions: $options);
        $rootEqualsVariable = Math::solve('root(x, 3) = x', 'x', -2.0, 2.0, solverOptions: $options);
        $evenRootVariableTarget = Math::solve(
            'root(x^2, 2) = x + 1',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $evenRootWrongBranch = Math::solve(
            'root(x^2, 2) = x - 1',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $rootOnRight = Math::solve(
            'x + 1 = root(x^2, 2)',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $negativeDegreeVariableTarget = Math::solve(
            'root(x, -3) = x',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );

        self::assertCount(2, $positiveOddRoot);
        self::assertEqualsWithDelta(-\sqrt(8.0), $positiveOddRoot[0]->value, 1.0E-8);
        self::assertEqualsWithDelta(\sqrt(8.0), $positiveOddRoot[1]->value, 1.0E-8);
        self::assertCount(1, $negativeOddRoot);
        self::assertSame(-8.0, $negativeOddRoot[0]->value);
        self::assertCount(1, $negativeDegree);
        self::assertSame(-8.0, $negativeDegree[0]->value);
        self::assertCount(1, $rationalArgument);
        self::assertEqualsWithDelta(-9.0 / 7.0, $rationalArgument[0]->value, 1.0E-8);
        self::assertSame([], $removableHole);
        self::assertSame([], $invalidEvenTarget);
        self::assertSame([], $zeroNegativeDegree);
        self::assertCount(3, $rootEqualsVariable);
        self::assertSame([-1.0, 0.0, 1.0], \array_map(
            static fn ($solution): float => $solution->value,
            $rootEqualsVariable,
        ));
        self::assertCount(1, $evenRootVariableTarget);
        self::assertSame(-0.5, $evenRootVariableTarget[0]->value);
        self::assertSame([], $evenRootWrongBranch);
        self::assertCount(1, $rootOnRight);
        self::assertSame(-0.5, $rootOnRight[0]->value);
        self::assertSame([-1.0, 1.0], \array_map(
            static fn ($solution): float => $solution->value,
            $negativeDegreeVariableTarget,
        ));
    }

