    public function testPeriodicTrigonometricEquationsEnumerateExponentialArgumentLevels(): void
    {
        foreach (
            [
                ['sin(exp(x)) = 0', 0.0, 8.0, 1.0, 0.0],
                ['sin(exp(2*x + 1)) = 0', -0.5, 3.5, 2.0, 1.0],
                ['sin(exp(-x)) = 0', -8.0, 0.0, -1.0, 0.0],
            ] as [$equation, $lower, $upper, $slope, $intercept]
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                $lower,
                $upper,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            $lastLevel = (int) \floor(\exp(8.0) / \M_PI);

            self::assertCount($lastLevel, $solutions, $equation);
            foreach ($solutions as $index => $solution) {
                $level = $slope < 0.0 ? $lastLevel - $index : $index + 1;
                $expected = (\log($level * \M_PI) - $intercept) / $slope;
                self::assertEqualsWithDelta($expected, $solution->value, 1.0E-10);
                self::assertLessThanOrEqual(1.0E-10, $solution->residual);
            }
        }

        $wideRoots = Math::solve(
            'sin(exp(x)) = 0',
            'x',
            -1.0,
            10.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        $wideLastLevel = (int) \floor(\exp(10.0) / \M_PI);

        self::assertCount($wideLastLevel, $wideRoots);
        foreach ($wideRoots as $index => $solution) {
            self::assertEqualsWithDelta(\log(($index + 1) * \M_PI), $solution->value, 1.0E-10);
            self::assertLessThanOrEqual(1.0E-10, $solution->residual);
        }

        $cosineSolutions = Math::solve(
            'cos(exp(x)) = 0',
            'x',
            0.0,
            8.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        $cosineRootCount = (int) \floor((\exp(8.0) - (\M_PI / 2.0)) / \M_PI) + 1;

        self::assertCount($cosineRootCount, $cosineSolutions);
        foreach ($cosineSolutions as $index => $solution) {
            self::assertEqualsWithDelta(
                \log((\M_PI / 2.0) + ($index * \M_PI)),
                $solution->value,
                1.0E-10,
            );
            self::assertLessThanOrEqual(1.0E-10, $solution->residual);
        }
    }

    public function testSharedExponentialSineCosinePhaseEnumeratesEverySumRoot(): void
    {
        $solutions = Math::solve(
            'sin(exp(x)) + cos(exp(x)) = 0',
            'x',
            0.0,
            10.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(7_011, $solutions);
        foreach ($solutions as $index => $solution) {
            $expectedPhase = (3.0 * \M_PI / 4.0) + ($index * \M_PI);
            self::assertEqualsWithDelta(\log($expectedPhase), $solution->value, 1.0E-10);
            self::assertLessThanOrEqual(1.0E-10, $solution->residual);
        }

        $scaled = Math::solve(
            '2*sin(exp(x)) + 3*cos(exp(x)) = 1',
            'x',
            0.0,
            10.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        $phaseShift = \atan2(3.0, 2.0);
        $principal = \asin(1.0 / \hypot(2.0, 3.0));
        $expectedRoots = [];
        foreach ([$principal - $phaseShift, \M_PI - $principal - $phaseShift] as $basePhase) {
            $firstPeriod = (int) \ceil((1.0 - $basePhase) / (2.0 * \M_PI));
            $lastPeriod = (int) \floor((\exp(10.0) - $basePhase) / (2.0 * \M_PI));
            for ($period = $firstPeriod; $period <= $lastPeriod; ++$period) {
                $expectedRoots[] = \log($basePhase + ($period * 2.0 * \M_PI));
            }
        }
        \sort($expectedRoots, SORT_NUMERIC);

        self::assertCount(\count($expectedRoots), $scaled);
        foreach ($expectedRoots as $index => $expectedRoot) {
            self::assertEqualsWithDelta($expectedRoot, $scaled[$index]->value, 1.0E-10);
            self::assertLessThanOrEqual(1.0E-10, $scaled[$index]->residual);
        }
    }

    public function testExponentialPeriodicEquationFindsEveryRootAtLowScanDensity(): void
    {
        $solutions = Math::solve(
            'sin(exp(-x)) = 0.5',
            'x',
            -8.0,
            0.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        $maximumPhase = \exp(8.0);
        $principal = \asin(0.5);
        $expectedRoots = [];
        $period = 0;
        while (true) {
            $foundPhase = false;
            foreach ([$principal, \M_PI - $principal] as $phase) {
                $level = $phase + (2.0 * \M_PI * $period);
                if ($level >= 1.0 && $level <= $maximumPhase) {
                    $expectedRoots[] = -\log($level);
                    $foundPhase = true;
                }
            }
            if (!$foundPhase && $period * 2.0 * \M_PI > $maximumPhase) {
                break;
            }
            ++$period;
        }
        \sort($expectedRoots, SORT_NUMERIC);

        self::assertCount(\count($expectedRoots), $solutions);
        foreach ($expectedRoots as $index => $root) {
            self::assertEqualsWithDelta($root, $solutions[$index]->value, 1.0E-10);
            self::assertLessThanOrEqual(1.0E-10, $solutions[$index]->residual);
        }
    }

