            -2.0,
            2.0,
            solverOptions: $options,
        );
        $expectedAbsoluteValue = [
            -3.0 * \M_PI,
            -2.0 * \M_PI,
            -\M_PI,
            0.0,
            \M_PI,
            2.0 * \M_PI,
            3.0 * \M_PI,
        ];
        $expectedShifted = [];
        for ($level = 1; $level <= 3; ++$level) {
            $root = \sqrt((($level * \M_PI) ** 2) - 1.0);
            $expectedShifted[] = -$root;
            $expectedShifted[] = $root;
        }
        \sort($expectedShifted, SORT_NUMERIC);

        $cosineLevel = \sqrt(((\M_PI / 2.0) ** 2) - 1.0);
        $tangentLevel = \sqrt((\M_PI ** 2) - 1.0);

        self::assertCount(7, $absoluteValueRoots);
        self::assertCount(6, $shiftedRoots);
        self::assertCount(2, $cosineRoots);
        self::assertCount(2, $tangentRoots);
        self::assertSame([], $negativeRadicandRoots);
        foreach ($expectedAbsoluteValue as $index => $root) {
            self::assertEqualsWithDelta($root, $absoluteValueRoots[$index]->value, 1.0E-9);
        }
        foreach ($expectedShifted as $index => $root) {
            self::assertEqualsWithDelta($root, $shiftedRoots[$index]->value, 1.0E-9);
        }
        self::assertEqualsWithDelta(-$cosineLevel, $cosineRoots[0]->value, 1.0E-9);
        self::assertEqualsWithDelta($cosineLevel, $cosineRoots[1]->value, 1.0E-9);
        self::assertEqualsWithDelta(-$tangentLevel, $tangentRoots[0]->value, 1.0E-9);
        self::assertEqualsWithDelta($tangentLevel, $tangentRoots[1]->value, 1.0E-9);
    }

    public function testLogarithmicPeriodicArgumentsKeepCloselySpacedRootsDistinct(): void
    {
        $cases = [
            ['sin(ln(x)) = 0', \exp(-700.0), 1.0, \M_E, 700.0],
            ['sin(log10(x)) = 0', 1.0E-300, 1.0, 10.0, 300.0],
            ['sin(log2(x)) = 0', 2.0 ** -700.0, 1.0, 2.0, 700.0],
            ['sin(log(x, 2)) = 0', 2.0 ** -700.0, 1.0, 2.0, 700.0],
            ['sin(log(x, 0.5)) = 0', 1.0, 2.0 ** 700.0, 0.5, 700.0],
        ];

        foreach ($cases as [$equation, $lower, $upper, $base, $logarithmSpan]) {
            $solutions = Math::solve(
                $equation,
                'x',
                $lower,
                $upper,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            $lastLevel = (int) \floor($logarithmSpan / \M_PI);

            self::assertCount($lastLevel + 1, $solutions, $equation);
            foreach ($solutions as $index => $solution) {
                $level = $base < 1.0 ? $index : $lastLevel - $index;
                $expected = $base ** (-$level * \M_PI);
                self::assertEqualsWithDelta(
                    $expected,
                    $solution->value,
                    1.0E-12 * \abs($expected),
                    $equation,
                );
                self::assertLessThanOrEqual(1.0E-10, $solution->residual, $equation);
            }
        }
    }

    public function testPeriodicLogarithmsOfMatchingExponentialBasesReduceAnalytically(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $expectedSineRoots = [
            -3.0 * \M_PI,
            -2.0 * \M_PI,
            -\M_PI,
            0.0,
            \M_PI,
            2.0 * \M_PI,
            3.0 * \M_PI,
        ];
        $expectedDoubleFrequencyRoots = [];
        for ($level = -6; $level <= 6; ++$level) {
            $expectedDoubleFrequencyRoots[] = ($level * \M_PI) / 2.0;
        }
        $cases = [
            ['sin(log2(2^x)) = 0', $expectedSineRoots],
            ['sin(ln(exp(x))) = 0', $expectedSineRoots],
            ['sin(log(10^x, 10)) = 0', $expectedSineRoots],
            ['sin(log2(2^x * 2^x)) = 0', $expectedDoubleFrequencyRoots],
        ];

        foreach ($cases as [$equation, $expected]) {
            $solutions = Math::solve(
                $equation,
                'x',
                -10.0,
                10.0,
                solverOptions: $options,
            );

            self::assertCount(\count($expected), $solutions, $equation);
            foreach ($expected as $index => $root) {
                self::assertEqualsWithDelta($root, $solutions[$index]->value, 1.0E-9);
                self::assertLessThanOrEqual(1.0E-10, $solutions[$index]->residual);
            }
        }

        $polynomialExponentRoots = Math::solve(
            'sin(log2(2^(x^2))) = 0',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );

        self::assertCount(3, $polynomialExponentRoots);
        self::assertEqualsWithDelta(-\sqrt(\M_PI), $polynomialExponentRoots[0]->value, 1.0E-9);
        self::assertSame(0.0, $polynomialExponentRoots[1]->value);
        self::assertEqualsWithDelta(\sqrt(\M_PI), $polynomialExponentRoots[2]->value, 1.0E-9);

        $nestedPowerRoots = Math::solve(
            'sin(log2((2^x)^x)) = 0',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        self::assertCount(3, $nestedPowerRoots);
        self::assertEqualsWithDelta(-\sqrt(\M_PI), $nestedPowerRoots[0]->value, 1.0E-9);
        self::assertSame(0.0, $nestedPowerRoots[1]->value);
        self::assertEqualsWithDelta(\sqrt(\M_PI), $nestedPowerRoots[2]->value, 1.0E-9);

        $constantPowerRoots = Math::solve(
            'sin(log2((2^x)^2)) = 0',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        self::assertCount(3, $constantPowerRoots);
        self::assertEqualsWithDelta(-\M_PI / 2.0, $constantPowerRoots[0]->value, 1.0E-9);
        self::assertSame(0.0, $constantPowerRoots[1]->value);
        self::assertEqualsWithDelta(\M_PI / 2.0, $constantPowerRoots[2]->value, 1.0E-9);

        $otherPositiveBaseRoots = Math::solve(
            'sin(log2(4^x)) = 0',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        self::assertCount(3, $otherPositiveBaseRoots);
        self::assertEqualsWithDelta(-\M_PI / 2.0, $otherPositiveBaseRoots[0]->value, 1.0E-9);
        self::assertSame(0.0, $otherPositiveBaseRoots[1]->value);
        self::assertEqualsWithDelta(\M_PI / 2.0, $otherPositiveBaseRoots[2]->value, 1.0E-9);

        $reciprocalRoots = Math::solve(
            'sin(log2(1 / (2^x))) = 0',
            'x',
            -4.0,
            4.0,
            solverOptions: $options,
        );
        self::assertCount(3, $reciprocalRoots);
        self::assertEqualsWithDelta(-\M_PI, $reciprocalRoots[0]->value, 1.0E-9);
        self::assertSame(0.0, $reciprocalRoots[1]->value);
        self::assertEqualsWithDelta(\M_PI, $reciprocalRoots[2]->value, 1.0E-9);
    }

