    public function testPeriodicLogarithmsReduceProductsOfPositiveExponentialFactors(): void
    {
        $cases = [
            ['sin(log2(2^x * 4^x)) = 0', 3.0],
            ['sin(log2(2^x / 4^x)) = 0', -1.0],
            ['sin(ln(exp(x) * exp(2*x))) = 0', 3.0],
            ['sin(ln(exp(x) / exp(2*x))) = 0', -1.0],
        ];
        $options = new SolverOptions(scanSteps: 1);

        foreach ($cases as [$equation, $phaseSlope]) {
            $maximumLevel = (int) \floor(10.0 * \abs($phaseSlope) / \M_PI);
            $expected = [];
            for ($level = -$maximumLevel; $level <= $maximumLevel; ++$level) {
                $expected[] = ($level * \M_PI) / $phaseSlope;
            }
            \sort($expected, SORT_NUMERIC);
            $solutions = Math::solve($equation, 'x', -10.0, 10.0, solverOptions: $options);

            self::assertCount(\count($expected), $solutions, $equation);
            foreach ($expected as $index => $root) {
                self::assertEqualsWithDelta($root, $solutions[$index]->value, 1.0E-9, $equation);
                self::assertLessThanOrEqual(1.0E-10, $solutions[$index]->residual, $equation);
            }
        }
    }

    public function testLogarithmicPeriodicArgumentsEnumeratePositivePolynomialLevels(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $naturalLog = Math::solve(
            'sin(ln(x^2 + 1)) = 0',
            'x',
            -10.0,
            10.0,
            solverOptions: $options,
        );
        $baseTwoLog = Math::solve(
            'sin(log(x^2 + 1, 2)) = 0',
            'x',
            -10.0,
            10.0,
            solverOptions: $options,
        );
        $expectedNatural = [-\sqrt(\exp(\M_PI) - 1.0), 0.0, \sqrt(\exp(\M_PI) - 1.0)];
        $expectedBaseTwo = [
            -\sqrt((2.0 ** (2.0 * \M_PI)) - 1.0),
            -\sqrt((2.0 ** \M_PI) - 1.0),
            0.0,
            \sqrt((2.0 ** \M_PI) - 1.0),
            \sqrt((2.0 ** (2.0 * \M_PI)) - 1.0),
        ];

        self::assertCount(3, $naturalLog);
        self::assertCount(5, $baseTwoLog);
        foreach ($expectedNatural as $index => $root) {
            self::assertEqualsWithDelta($root, $naturalLog[$index]->value, 1.0E-9);
            self::assertLessThanOrEqual(1.0E-10, $naturalLog[$index]->residual);
        }
        foreach ($expectedBaseTwo as $index => $root) {
            self::assertEqualsWithDelta($root, $baseTwoLog[$index]->value, 1.0E-9);
            self::assertLessThanOrEqual(1.0E-10, $baseTwoLog[$index]->residual);
        }
    }

    public function testPeriodicLogarithmWithPositiveValuesApproachingZeroHasInfiniteRoots(): void
    {
        foreach (
            [
                ['sin(ln(x^2)) = 0', -1.0, 1.0],
                ['sin(log(x, 2)) = 0', -1.0, 1.0],
                ['sin(log(x^2, 0.5)) = 0', -1.0, 1.0],
            ] as [$equation, $lower, $upper]
        ) {
            $thrown = false;
            try {
                Math::solve($equation, 'x', $lower, $upper);
            } catch (\MathPHP\Solver\InfiniteSolutionSetException) {
                $thrown = true;
            }
