    public function testNestedBoundedTrigonometricFunctionsInvertTheirInnerLevels(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $zeroSine = Math::solve('sin(sin(exp(x))) = 0', 'x', 0.0, 8.0, solverOptions: $options);
        $reversed = Math::solve('0 = sin(sin(exp(x)))', 'x', 0.0, 8.0, solverOptions: $options);
        $unitCosine = Math::solve('cos(sin(exp(x))) = 1', 'x', 0.0, 8.0, solverOptions: $options);
        $zeroFromCosine = Math::solve('sin(cos(exp(x))) = 0', 'x', 0.0, 8.0, solverOptions: $options);
        $nonzeroLevel = Math::solve(
            'sin(sin(exp(x))) = 0.5',
            'x',
            0.0,
            4.0,
            solverOptions: $options,
        );

        self::assertCount(948, $zeroSine);
        self::assertCount(948, $reversed);
        self::assertCount(948, $unitCosine);
        self::assertCount(949, $zeroFromCosine);
        foreach ($zeroSine as $index => $solution) {
            $expected = \log(($index + 1) * \M_PI);
            self::assertEqualsWithDelta($expected, $solution->value, 1.0E-10);
            self::assertEqualsWithDelta($expected, $reversed[$index]->value, 1.0E-10);
            self::assertEqualsWithDelta($expected, $unitCosine[$index]->value, 1.0E-10);
        }

        $wideZeroSine = Math::solve(
            'sin(sin(exp(x))) = 0',
            'x',
            0.0,
            10.0,
            solverOptions: $options,
        );
        $wideLastLevel = (int) \floor(\exp(10.0) / \M_PI);

        self::assertCount($wideLastLevel, $wideZeroSine);
        foreach ($wideZeroSine as $index => $solution) {
            self::assertEqualsWithDelta(\log(($index + 1) * \M_PI), $solution->value, 1.0E-10);
            self::assertLessThanOrEqual(1.0E-10, $solution->residual);
        }

        foreach ($zeroFromCosine as $index => $solution) {
            self::assertEqualsWithDelta(
                \log((\M_PI / 2.0) + ($index * \M_PI)),
                $solution->value,
                1.0E-10,
            );
        }

        $innerLevel = \asin(\asin(0.5));
        $expected = [];
        foreach ([$innerLevel, \M_PI - $innerLevel] as $phase) {
            for ($period = -1; $period <= 10; ++$period) {
                $argument = $phase + ($period * 2.0 * \M_PI);
                if ($argument >= 1.0 && $argument <= \exp(4.0)) {
                    $expected[] = \log($argument);
                }
            }
        }
        \sort($expected, SORT_NUMERIC);

        self::assertCount(\count($expected), $nonzeroLevel);
        foreach ($expected as $index => $root) {
            self::assertEqualsWithDelta($root, $nonzeroLevel[$index]->value, 1.0E-10);
        }
    }

    public function testTrigonometricFunctionsInvertBoundedHyperbolicInnerFunctions(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $sineTanh = Math::solve(
            'sin(tanh(x)) = 0.5',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $cosineTanh = Math::solve(
            '0.9 = cos(tanh(x))',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $sineErf = Math::solve(
            'sin(erf(x)) = 0.5',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $cosineErf = Math::solve(
            'cos(erf(x)) = 0.9',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );

        self::assertCount(1, $sineTanh);
        self::assertEqualsWithDelta(\atanh(\asin(0.5)), $sineTanh[0]->value, 1.0E-10);
        self::assertLessThanOrEqual(1.0E-10, $sineTanh[0]->residual);
        self::assertCount(2, $cosineTanh);
        self::assertEqualsWithDelta(-\atanh(\acos(0.9)), $cosineTanh[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(\atanh(\acos(0.9)), $cosineTanh[1]->value, 1.0E-10);
        self::assertCount(1, $sineErf);
        self::assertEqualsWithDelta(0.503532600176424, $sineErf[0]->value, 1.0E-12);
        self::assertLessThanOrEqual(1.0E-10, $sineErf[0]->residual);
        self::assertCount(2, $cosineErf);
        self::assertEqualsWithDelta(-0.423768733039381, $cosineErf[0]->value, 1.0E-12);
        self::assertEqualsWithDelta(0.423768733039381, $cosineErf[1]->value, 1.0E-12);
        self::assertSame(
            [],
            Math::solve(
                'sin(erf(x)) = sin(1)',
                'x',
                -10.0,
                10.0,
                solverOptions: $options,
            ),
        );
        self::assertSame(
            [],
            Math::solve(
                'cos(tanh(x)) = cos(1)',
                'x',
                -10.0,
                10.0,
                solverOptions: $options,
            ),
        );
    }

    public function testNestedPeriodicFunctionEnumeratesReachableInnerLevels(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $solutions = Math::solve(
            'sin(cosh(x)) = 0',
            'x',
            -3.0,
            3.0,
            solverOptions: $options,
        );
        $sinhSolutions = Math::solve(
            'sin(sinh(x)) = 0',
            'x',
            -3.0,
            3.0,
            solverOptions: $options,
        );
        $sineAtan = Math::solve(
            'sin(atan(x)) = 0.5',
            'x',
            -10.0,
            10.0,
            solverOptions: $options,
        );
        $cosineAtan = Math::solve(
            'cos(atan(x)) = 0.5',
            'x',
            -10.0,
            10.0,
            solverOptions: $options,
        );
        $sineAsinh = Math::solve(
            'sin(asinh(x)) = 0.5',
            'x',
            -10.0,
            10.0,
            solverOptions: $options,
        );
        $cosineAsinh = Math::solve(
            'cos(asinh(x)) = 0.5',
            'x',
            -10.0,
            10.0,
            solverOptions: $options,
        );
        $absoluteSine = Math::solve(
            'sin(abs(x)) = 0',
            'x',
            -7.0,
            7.0,
            solverOptions: $options,
        );
        $acoshBoundaryRoots = Math::solve(
            'sin(acosh(x^2)) = 0',
            'x',
            -3.0,
            3.0,
            solverOptions: $options,
        );
        $outsideAcoshDomain = Math::solve(
            'sin(acosh(x^2)) = 0',
            'x',
            -0.5,
            0.5,
            solverOptions: $options,
        );
        $asinDomainRoots = Math::solve(
            'sin(asin(x^2)) = 0',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $acosDomainRoots = Math::solve(
            'cos(acos(x^2)) = 0.5',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        $unreachable = Math::solve(
            'sin(cosh(x)) = 0',
            'x',
            0.0,
            1.0,
            solverOptions: $options,
        );
        $sineAtMinimum = Math::solve(
            'sin(cosh(x)) = sin(1)',
            'x',
            0.0,
            1.0,
            solverOptions: $options,
        );
        $cosineAtMinimum = Math::solve(
            'cos(cosh(x)) = cos(1)',
            'x',
            0.0,
            1.0,
            solverOptions: $options,
        );

        self::assertCount(6, $solutions);
        $expected = [];
        for ($multiple = 1; $multiple <= 3; ++$multiple) {
            $root = \acosh($multiple * \M_PI);
            $expected[] = -$root;
            $expected[] = $root;
        }
        \sort($expected, SORT_NUMERIC);
        foreach ($expected as $index => $root) {
            self::assertEqualsWithDelta($root, $solutions[$index]->value, 1.0E-10);
            self::assertLessThanOrEqual(1.0E-10, $solutions[$index]->residual);
        }
        self::assertSame([], $unreachable);
        self::assertCount(7, $sinhSolutions);
        foreach (\range(-3, 3) as $index => $multiple) {
            self::assertEqualsWithDelta(
                \asinh($multiple * \M_PI),
                $sinhSolutions[$index]->value,
                1.0E-10,
            );
        }
        self::assertCount(1, $sineAtan);
        self::assertEqualsWithDelta(1.0 / \sqrt(3.0), $sineAtan[0]->value, 1.0E-10);
        self::assertCount(2, $cosineAtan);
        self::assertEqualsWithDelta(-\sqrt(3.0), $cosineAtan[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(\sqrt(3.0), $cosineAtan[1]->value, 1.0E-10);
        self::assertCount(2, $sineAsinh);
        self::assertEqualsWithDelta(\sinh(\M_PI / 6.0), $sineAsinh[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(\sinh(5.0 * \M_PI / 6.0), $sineAsinh[1]->value, 1.0E-10);
        self::assertCount(2, $cosineAsinh);
        self::assertEqualsWithDelta(-\sinh(\M_PI / 3.0), $cosineAsinh[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(\sinh(\M_PI / 3.0), $cosineAsinh[1]->value, 1.0E-10);
        self::assertCount(5, $absoluteSine);
        foreach ([-2.0 * \M_PI, -\M_PI, 0.0, \M_PI, 2.0 * \M_PI] as $index => $root) {
            self::assertEqualsWithDelta($root, $absoluteSine[$index]->value, 1.0E-10);
        }
        self::assertCount(2, $acoshBoundaryRoots);
        self::assertEqualsWithDelta(-1.0, $acoshBoundaryRoots[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(1.0, $acoshBoundaryRoots[1]->value, 1.0E-10);
        self::assertSame([], $outsideAcoshDomain);
        self::assertCount(1, $asinDomainRoots);
        self::assertSame(0.0, $asinDomainRoots[0]->value);
        self::assertCount(2, $acosDomainRoots);
        self::assertEqualsWithDelta(-\sqrt(0.5), $acosDomainRoots[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(\sqrt(0.5), $acosDomainRoots[1]->value, 1.0E-10);
        self::assertCount(1, $sineAtMinimum);
        self::assertSame(0.0, $sineAtMinimum[0]->value);
        self::assertCount(1, $cosineAtMinimum);
        self::assertSame(0.0, $cosineAtMinimum[0]->value);
    }

    public function testAffineSineCosineCombinationsEnumerateRootsAtCoarseScanResolution(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $solutions = Math::solve('sin(x) + cos(x) = 1.4', 'x', -10.0, 10.0, solverOptions: $options);
        $reversed = Math::solve('1.4 = cos(x) + sin(x)', 'x', -10.0, 10.0, solverOptions: $options);
        $difference = Math::solve('cos(x) - sin(x) = -1.4', 'x', -10.0, 10.0, solverOptions: $options);
        $unreachable = Math::solve('sin(x) + cos(x) = 2', 'x', -10.0, 10.0, solverOptions: $options);

        self::assertCount(6, $solutions);
        self::assertCount(6, $reversed);
        self::assertCount(6, $difference);
        self::assertSame([], $unreachable);
        $principal = \asin(1.4 / \hypot(1.0, 1.0));
        $phases = [
            $principal - (\M_PI / 4.0),
            \M_PI - $principal - (\M_PI / 4.0),
        ];
        $expected = [];
        foreach ($phases as $phase) {
            for ($period = -1; $period <= 1; ++$period) {
                $value = $phase + ($period * 2.0 * \M_PI);
                if ($value >= -10.0 && $value <= 10.0) {
                    $expected[] = $value;
                }
            }
        }
        \sort($expected, SORT_NUMERIC);

        foreach ($expected as $index => $root) {
            self::assertEqualsWithDelta($root, $solutions[$index]->value, 1.0E-10);
            self::assertEqualsWithDelta($root, $reversed[$index]->value, 1.0E-10);
            self::assertLessThanOrEqual(1.0E-10, $solutions[$index]->residual);
        }
        foreach ($difference as $solution) {
            self::assertLessThanOrEqual(1.0E-10, $solution->residual);
        }
    }

    public function testAffineSineCosineCombinationPreservesNearTangentRootPair(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $tangent = Math::solve(
            'sin(x) + cos(x) = sqrt(2)',
            'x',
            0.0,
            2.0,
            solverOptions: $options,
        );
        $nearTangentTarget = 1.4142135623730950;
        $nearTangent = Math::solve(
            'sin(x) + cos(x) = ' . \sprintf('%.16f', $nearTangentTarget),
            'x',
            0.0,
            2.0,
            solverOptions: $options,
        );

        self::assertCount(1, $tangent);
        self::assertEqualsWithDelta(\M_PI / 4.0, $tangent[0]->value, 1.0E-12);
        self::assertCount(2, $nearTangent);

        $offset = \acos($nearTangentTarget / \hypot(1.0, 1.0));
        self::assertEqualsWithDelta(\M_PI / 4.0 - $offset, $nearTangent[0]->value, 1.0E-9);
        self::assertEqualsWithDelta(\M_PI / 4.0 + $offset, $nearTangent[1]->value, 1.0E-9);
        self::assertLessThan(1.0E-7, $nearTangent[1]->value - $nearTangent[0]->value);
        foreach ([...$tangent, ...$nearTangent] as $solution) {
            self::assertLessThanOrEqual(1.0E-10, $solution->residual);
        }
    }

    public function testAffineTrigonometricProductsUseDoubleAngleLevels(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $sineSquare = Math::solve('sin(x)^2 = 0.25', 'x', -10.0, 10.0, solverOptions: $options);
        $cosineSquare = Math::solve('cos(x)^2 = 0.25', 'x', -10.0, 10.0, solverOptions: $options);
        $product = Math::solve('sin(x) * cos(x) = 0.25', 'x', -10.0, 10.0, solverOptions: $options);
        $oppositeSineProduct = Math::solve(
            'sin(x) * sin(-x) = 0.25',
            'x',
            -10.0,
            10.0,
            solverOptions: $options,
        );
        $oppositeCosineProduct = Math::solve(
            'cos(x) * cos(-x) = 0.25',
            'x',
            -10.0,
            10.0,
            solverOptions: $options,
        );
        $oppositeMixedProduct = Math::solve(
            'cos(x) * sin(-x) = 0.25',
            'x',
            -10.0,
            10.0,
            solverOptions: $options,
        );
        $repeatedTerm = Math::solve(
            'sin(x) + sin(x) = 0.5',
            'x',
            -10.0,
            10.0,
            solverOptions: $options,
        );
        $shifted = Math::solve(
            'sin(2*x + 1)^2 = 0.25',
            'x',
            -10.0,
            10.0,
            solverOptions: $options,
        );

        self::assertCount(14, $sineSquare);
        self::assertCount(12, $cosineSquare);
        self::assertCount(13, $product);
        self::assertSame([], $oppositeSineProduct);
        self::assertCount(12, $oppositeCosineProduct);
        self::assertCount(13, $oppositeMixedProduct);
        self::assertCount(7, $repeatedTerm);
        self::assertCount(25, $shifted);
        foreach (
            [
                $sineSquare,
                $cosineSquare,
                $product,
                $oppositeCosineProduct,
                $oppositeMixedProduct,
                $repeatedTerm,
                $shifted,
            ] as $solutions
        ) {
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-10, $solution->residual);
            }
        }
    }

