    public function testEqualTrigonometricFunctionsReduceToPolynomialPhaseLevels(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $sineSolutions = Math::solve(
            'sin(x^2) = sin(x)',
            'x',
            -5.0,
            5.0,
            solverOptions: $options,
        );
        $cosineSolutions = Math::solve(
            'cos(x^2) = cos(x)',
            'x',
            -5.0,
            5.0,
            solverOptions: $options,
        );
        $mixedSolutions = Math::solve(
            'sin(x^2) = cos(x)',
            'x',
            -5.0,
            5.0,
            solverOptions: $options,
        );
        $reversedMixedSolutions = Math::solve(
            'cos(x^2) = sin(x)',
            'x',
            -5.0,
            5.0,
            solverOptions: $options,
        );

        $expectedSine = [];
        for ($period = 0; $period <= 4; ++$period) {
            $discriminant = 1.0 + (8.0 * \M_PI * $period);
            foreach ([1.0, -1.0] as $sign) {
                $root = (1.0 + ($sign * \sqrt($discriminant))) / 2.0;
                if ($root >= -5.0 && $root <= 5.0) {
                    $expectedSine[] = $root;
                }
            }
        }
        for ($period = 0; $period <= 4; ++$period) {
            $level = \M_PI + (2.0 * \M_PI * $period);
            $discriminant = 1.0 + (4.0 * $level);
            foreach ([1.0, -1.0] as $sign) {
                $root = (-1.0 + ($sign * \sqrt($discriminant))) / 2.0;
                if ($root >= -5.0 && $root <= 5.0) {
                    $expectedSine[] = $root;
                }
            }
        }

        $expectedCosine = [];
        for ($period = 0; $period <= 4; ++$period) {
            $discriminant = 1.0 + (8.0 * \M_PI * $period);
            foreach ([1.0, -1.0] as $sign) {
                $root = (1.0 + ($sign * \sqrt($discriminant))) / 2.0;
                if ($root >= -5.0 && $root <= 5.0) {
                    $expectedCosine[] = $root;
                }
            }
        }
        for ($period = 0; $period <= 4; ++$period) {
            $level = 2.0 * \M_PI * $period;
            $discriminant = 1.0 + (4.0 * $level);
            foreach ([1.0, -1.0] as $sign) {
                $root = (-1.0 + ($sign * \sqrt($discriminant))) / 2.0;
                if ($root >= -5.0 && $root <= 5.0) {
                    $expectedCosine[] = $root;
                }
            }
        }
        $expectedMixed = [];
        for ($period = 0; $period <= 4; ++$period) {
            $level = (\M_PI / 2.0) + (2.0 * \M_PI * $period);
            $discriminant = 1.0 + (4.0 * $level);
            foreach ([-1.0, 1.0] as $linearCoefficient) {
                foreach ([-1.0, 1.0] as $sign) {
                    $root = (-$linearCoefficient + ($sign * \sqrt($discriminant))) / 2.0;
                    if ($root >= -5.0 && $root <= 5.0) {
                        $expectedMixed[] = $root;
                    }
                }
            }
        }
        $expectedReversedMixed = [];
        foreach ([[-1.0, -\M_PI / 2.0], [1.0, \M_PI / 2.0]] as [$linearCoefficient, $phase]) {
            $firstPeriod = (int) \ceil((-0.25 - $phase) / (2.0 * \M_PI));
            $lastPeriod = (int) \floor((30.0 - $phase) / (2.0 * \M_PI));
            for ($period = $firstPeriod; $period <= $lastPeriod; ++$period) {
                $level = $phase + (2.0 * \M_PI * $period);
                $discriminant = ($linearCoefficient ** 2) + (4.0 * $level);
                if ($discriminant < 0.0) {
                    continue;
                }
                foreach ([-1.0, 1.0] as $sign) {
                    $root = (-$linearCoefficient + ($sign * \sqrt($discriminant))) / 2.0;
                    if ($root >= -5.0 && $root <= 5.0) {
                        $expectedReversedMixed[] = $root;
                    }
                }
            }
        }
        \sort($expectedSine, SORT_NUMERIC);
        \sort($expectedCosine, SORT_NUMERIC);
        \sort($expectedMixed, SORT_NUMERIC);
        \sort($expectedReversedMixed, SORT_NUMERIC);
        $expectedSine = \array_values(\array_unique($expectedSine, SORT_REGULAR));
        $expectedCosine = \array_values(\array_unique($expectedCosine, SORT_REGULAR));
        $expectedMixed = \array_values(\array_unique($expectedMixed, SORT_REGULAR));
        $expectedReversedMixed = \array_values(\array_unique($expectedReversedMixed, SORT_REGULAR));

        self::assertCount(\count($expectedSine), $sineSolutions);
        self::assertCount(\count($expectedCosine), $cosineSolutions);
        self::assertCount(\count($expectedMixed), $mixedSolutions);
        self::assertCount(\count($expectedReversedMixed), $reversedMixedSolutions);
        foreach ($expectedSine as $index => $root) {
            self::assertEqualsWithDelta($root, $sineSolutions[$index]->value, 1.0E-9);
            self::assertLessThanOrEqual(1.0E-9, $sineSolutions[$index]->residual);
        }
        foreach ($expectedCosine as $index => $root) {
            self::assertEqualsWithDelta($root, $cosineSolutions[$index]->value, 1.0E-9);
            self::assertLessThanOrEqual(1.0E-9, $cosineSolutions[$index]->residual);
        }
        foreach ($expectedMixed as $index => $root) {
            self::assertEqualsWithDelta($root, $mixedSolutions[$index]->value, 1.0E-9);
            self::assertLessThanOrEqual(1.0E-9, $mixedSolutions[$index]->residual);
        }
        foreach ($expectedReversedMixed as $index => $root) {
            self::assertEqualsWithDelta($root, $reversedMixedSolutions[$index]->value, 1.0E-9);
            self::assertLessThanOrEqual(1.0E-9, $reversedMixedSolutions[$index]->residual);
        }
    }

    public function testEqualTrigonometricFunctionsReduceRationalPhaseLevels(): void
    {
        $expected = [
            'sin(1/x) = sin(1/(x + 1))' => [
                0.11723723996646064,
                0.1396522047893647,
                0.41103341671243243,
            ],
            'cos(1/x) = cos(1/(x + 1))' => [
                0.1396522047893647,
                0.18387419746568373,
            ],
            'tan(1/x) = tan(1/(x + 1))' => [
                0.1396522047893647,
                0.25386330736002183,
            ],
        ];

        foreach ($expected as $equation => $expectedRoots) {
            $scanResults = [];
            foreach ([1, 256] as $scanSteps) {
                $solutions = Math::solve(
                    $equation,
                    'x',
                    0.1,
                    2.0,
                    solverOptions: new SolverOptions(scanSteps: $scanSteps),
                );
                self::assertCount(\count($expectedRoots), $solutions, $equation);
                foreach ($solutions as $index => $solution) {
                    self::assertEqualsWithDelta($expectedRoots[$index], $solution->value, 1.0E-9);
                    self::assertLessThanOrEqual(1.0E-8, $solution->residual);
                }
                $scanResults[] = \array_map(
                    static fn ($solution): float => $solution->value,
                    $solutions,
                );
            }

            foreach ($scanResults[0] as $index => $root) {
                self::assertEqualsWithDelta($root, $scanResults[1][$index], 1.0E-9);
            }
        }
    }

