    public function testEqualTangentsReduceToPeriodicPolynomialLevelsAndExcludePoles(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $quadraticSolutions = Math::solve(
            'tan(x^2) = tan(x)',
            'x',
            -5.0,
            5.0,
            solverOptions: $options,
        );
        $reflectedSolutions = Math::solve(
            'tan(x) = tan(-x)',
            'x',
            -4.0,
            4.0,
            solverOptions: $options,
        );
        $mixedSolutions = Math::solve(
            'tan(x^2) = cot(x)',
            'x',
            -5.0,
            5.0,
            solverOptions: $options,
        );
        $reversedMixedSolutions = Math::solve(
            'cot(x^2) = tan(x)',
            'x',
            -5.0,
            5.0,
            solverOptions: $options,
        );

        $expectedQuadratic = [];
        for ($period = 0; $period <= 9; ++$period) {
            $discriminant = 1.0 + (4.0 * \M_PI * $period);
            foreach ([-1.0, 1.0] as $sign) {
                $root = (1.0 + ($sign * \sqrt($discriminant))) / 2.0;
                if ($root >= -5.0 && $root <= 5.0) {
                    $expectedQuadratic[] = $root;
                }
            }
        }
        \sort($expectedQuadratic, SORT_NUMERIC);
        $expectedMixed = [];
        for ($period = 0; $period <= 9; ++$period) {
            $level = (\M_PI / 2.0) + (\M_PI * $period);
            $discriminant = 1.0 + (4.0 * $level);
            foreach ([-1.0, 1.0] as $sign) {
                $root = (-1.0 + ($sign * \sqrt($discriminant))) / 2.0;
                if ($root >= -5.0 && $root <= 5.0) {
                    $expectedMixed[] = $root;
                }
            }
        }
        \sort($expectedMixed, SORT_NUMERIC);
        self::assertCount(\count($expectedQuadratic), $quadraticSolutions);
        foreach ($expectedQuadratic as $index => $root) {
            self::assertEqualsWithDelta($root, $quadraticSolutions[$index]->value, 1.0E-9);
            self::assertLessThanOrEqual(1.0E-9, $quadraticSolutions[$index]->residual);
        }
        self::assertCount(3, $reflectedSolutions);
        self::assertEqualsWithDelta(-\M_PI, $reflectedSolutions[0]->value, 1.0E-10);
        self::assertSame(0.0, $reflectedSolutions[1]->value);
        self::assertEqualsWithDelta(\M_PI, $reflectedSolutions[2]->value, 1.0E-10);
        self::assertCount(\count($expectedMixed), $mixedSolutions);
        self::assertCount(\count($expectedMixed), $reversedMixedSolutions);
        foreach ($expectedMixed as $index => $root) {
            self::assertEqualsWithDelta($root, $mixedSolutions[$index]->value, 1.0E-9);
            self::assertEqualsWithDelta($root, $reversedMixedSolutions[$index]->value, 1.0E-9);
            self::assertLessThanOrEqual(1.0E-9, $mixedSolutions[$index]->residual);
            self::assertLessThanOrEqual(1.0E-9, $reversedMixedSolutions[$index]->residual);
        }
    }

