    public function testSignedTrigonometricEqualitiesReduceToPhaseShiftedPolynomialLevels(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $equivalentEquations = [
            ['sin(x^2) = -sin(x)', 'sin(x^2) = sin(-x)'],
            ['cos(x^2) = -cos(x)', 'cos(x^2) = cos(x + pi)'],
            ['tan(x^2) = -tan(x)', 'tan(x^2) = tan(-x)'],
            ['sec(x^2) = -sec(x)', 'sec(x^2) = sec(x + pi)'],
            ['sin(x^2) = -cos(x)', 'sin(x^2) = sin(x - pi / 2)'],
            ['cos(x^2) = -sin(x)', 'cos(x^2) = cos(x + pi / 2)'],
            ['sec(x^2) = -csc(x)', 'sec(x^2) = sec(x + pi / 2)'],
            ['-sin(x^2) = cos(x)', 'sin(x^2) = -cos(x)'],
            ['tan(x^2) = -cot(x)', 'tan(x^2) = tan(x - pi / 2)'],
            ['cot(x^2) = -tan(x)', 'cot(x^2) = cot(x + pi / 2)'],
        ];

        foreach ($equivalentEquations as [$signedEquation, $phaseShiftedEquation]) {
            $signedSolutions = Math::solve(
                $signedEquation,
                'x',
                -5.0,
                5.0,
                solverOptions: $options,
            );
            $phaseShiftedSolutions = Math::solve(
                $phaseShiftedEquation,
                'x',
                -5.0,
                5.0,
                solverOptions: $options,
            );

            self::assertCount(\count($phaseShiftedSolutions), $signedSolutions, $signedEquation);
            foreach ($phaseShiftedSolutions as $index => $solution) {
                self::assertEqualsWithDelta(
                    $solution->value,
                    $signedSolutions[$index]->value,
                    1.0E-9,
                    $signedEquation,
                );
                self::assertLessThanOrEqual(1.0E-9, $signedSolutions[$index]->residual);
            }
        }
    }

    public function testReciprocalTrigonometricPairsReduceToDenominatorEqualities(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $secantSolutions = Math::solve(
            'sec(x^2) = sec(x)',
            'x',
            -5.0,
