        );
        $cosineSolutions = Math::solve(
            'cos(x^2) = cos(x)',
            'x',
            -5.0,
            5.0,
            solverOptions: $options,
        );
        $cosecantSolutions = Math::solve(
            'csc(x^2) = csc(x)',
            'x',
            -5.0,
            5.0,
            solverOptions: $options,
        );
        $cotangentSolutions = Math::solve(
            'cot(x^2) = cot(x)',
            'x',
            -5.0,
            5.0,
            solverOptions: $options,
        );

        self::assertCount(\count($cosineSolutions), $secantSolutions);
        foreach ($cosineSolutions as $index => $solution) {
            self::assertEqualsWithDelta($solution->value, $secantSolutions[$index]->value, 1.0E-10);
        }
        self::assertCount(16, $cosecantSolutions);
        self::assertCount(16, $cotangentSolutions);
        foreach ([...$cosecantSolutions, ...$cotangentSolutions] as $solution) {
            self::assertNotEqualsWithDelta(0.0, $solution->value, 1.0E-10);
            self::assertLessThanOrEqual(1.0E-9, $solution->residual);
        }
    }

    public function testAffineTrigonometricPolynomialsAreIsolatedAtCoarseScanResolution(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $equations = [
            'sin(x) + sin(2*x) + sin(3*x) = 0.5' => 13,
            'cos(x) + cos(2*x) + cos(3*x) = 0.5' => 6,
            'sin(2*x) + cos(3*x) + sin(4*x) = 0.5' => 19,
            'sin(x + 0.2) + sin(2*x + 0.7) - cos(3*x) = 0.5' => 14,
            'sin(x) + sin(2*x) + sin(3*x) = 0' => 19,
            '2*sin(x) + 3*sin(2*x) - 0.5*cos(3*x) = 0.5' => 13,
            'sin(x)/2 + cos(2*x)/3 + sin(3*x) = 0.25' => 13,
            '2*sin(x) + 3*sin(2*x) + 4*cos(3*x) = 5' => 6,
            'sin(x) + sin(2*x) + sin(3*x) + 0.25 = 0.5' => 13,
            '(sin(x) + 0.25)*2 + sin(2*x) + sin(3*x) = 1' => 7,
