    public function testNonPolynomialPeriodicArgumentAdaptsCoarseFallbackSampling(): void
    {
        $lowerBound = -5.0;
        $upperBound = 5.0;
        $solutions = Math::solve(
            'sin(exp(x) + x) = 0',
            'x',
            $lowerBound,
            $upperBound,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        $argumentAtLower = \exp($lowerBound) + $lowerBound;
        $argumentAtUpper = \exp($upperBound) + $upperBound;
        $firstPhase = (int) \ceil($argumentAtLower / \M_PI);
        $lastPhase = (int) \floor($argumentAtUpper / \M_PI);

        self::assertCount($lastPhase - $firstPhase + 1, $solutions);
        foreach ($solutions as $solution) {
            self::assertGreaterThanOrEqual($lowerBound, $solution->value);
            self::assertLessThanOrEqual($upperBound, $solution->value);
            self::assertLessThanOrEqual(1.0E-8, $solution->residual);
        }

        $nestedSolutions = Math::solve(
            'sin(exp(x) * sin(100 * x)) = 0',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(193, $nestedSolutions);
        foreach ($nestedSolutions as $solution) {
            self::assertLessThanOrEqual(1.0E-8, $solution->residual);
        }
    }

    public function testRationalPeriodicArgumentsEnumerateEveryPhaseLevel(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $lowerBound = 0.0001;
        $upperBound = 1.0;
        $zeroLevelRoots = Math::solve(
            'sin(1/x) = 0',
            'x',
            $lowerBound,
            $upperBound,
            solverOptions: $options,
        );

        self::assertCount(3183, $zeroLevelRoots);
        foreach ($zeroLevelRoots as $index => $solution) {
            $phaseIndex = 3183 - $index;
            self::assertEqualsWithDelta(
                1.0 / ($phaseIndex * \M_PI),
                $solution->value,
                1.0E-10,
            );
            self::assertLessThanOrEqual(1.0E-9, $solution->residual);
        }

        $halfLevelRoots = Math::solve(
            'sin(1/x) = 0.5',
            'x',
            $lowerBound,
            $upperBound,
            solverOptions: $options,
        );
        $expectedRoots = [];
        foreach ([\M_PI / 6.0, (5.0 * \M_PI) / 6.0] as $phase) {
            for ($periodIndex = 0; $periodIndex <= 1591; ++$periodIndex) {
                $angle = $phase + ($periodIndex * 2.0 * \M_PI);
                if ($angle >= 1.0 && $angle <= 10_000.0) {
                    $expectedRoots[] = 1.0 / $angle;
                }
            }
        }
        \sort($expectedRoots, SORT_NUMERIC);

        self::assertCount(\count($expectedRoots), $halfLevelRoots);
        foreach ($halfLevelRoots as $index => $solution) {
            self::assertEqualsWithDelta($expectedRoots[$index], $solution->value, 1.0E-10);
            self::assertLessThanOrEqual(1.0E-9, $solution->residual);
        }

        $boundedRationalRoots = Math::solve(
            'sin(1/(x^2 + 1)) = 0.8',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );
        self::assertCount(2, $boundedRationalRoots);
        self::assertEqualsWithDelta(
            -\sqrt((1.0 / \asin(0.8)) - 1.0),
            $boundedRationalRoots[0]->value,
            1.0E-10,
        );
        self::assertEqualsWithDelta(
            \sqrt((1.0 / \asin(0.8)) - 1.0),
            $boundedRationalRoots[1]->value,
            1.0E-10,
        );
    }

