    public function testPeriodicRootsAccumulateWhenTheTargetIsAFlatExponentialAtPhasePole(): void
    {
        foreach (
            [
                'sin(1/x) = exp(-1/x^2)',
                'sin(1/x) = -exp(-1/x^2)',
                'cos(1/x) = exp(-1/x^2)',
                'sin(1/x) = exp(-1/sqrt(x))',
            ] as $equation
        ) {
            $this->expectInfiniteRootAccumulation($equation, 0.0, 1.0);
        }

        try {
            Math::solve(
                'sin(1/x) = exp(1/sqrt(x))',
                'x',
                0.0,
                1.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
        } catch (InfiniteRootAccumulationException $exception) {
            self::fail(
                'An unbounded target must not be classified as an interior periodic target: '
                    . $exception->getMessage(),
            );
        }

        $finiteIntervalRoots = Math::solve(
            'sin(1/x) = exp(-1/x^2)',
            'x',
            0.01,
            1.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertNotEmpty($finiteIntervalRoots);
        self::assertLessThan(100, \count($finiteIntervalRoots));
    }

