    public function testLogarithmicTargetsApproachingPeriodicRangeBoundaryAreClassifiedBySide(): void
    {
        foreach (
            [
                'sin(1/x) = 1-1/ln(1/x)',
                'sin(1/x) = -1+1/ln(1/x)',
                'cos(1/x) = 1-1/ln(1/x)',
                'sin(1/(x-0.5)) = 1-1/ln(1/abs(x-0.5))',
            ] as $equation
        ) {
            $upper = str_contains($equation, 'x-0.5') ? 1.0 : 0.5;
            $this->expectInfiniteRootAccumulation($equation, 0.0, $upper);
        }

        foreach (
            [
                'sin(1/x) = 1+1/ln(1/x)',
                'sin(1/x) = -1-1/ln(1/x)',
                'cos(1/x) = 1+1/ln(1/x)',
                'sin(1/(x-0.5)) = 1+1/ln(1/abs(x-0.5))',
            ] as $equation
        ) {
            $upper = str_contains($equation, 'x-0.5') ? 1.0 : 0.5;
            self::assertSame(
                [],
                Math::solve(
                    $equation,
                    'x',
                    0.0,
                    $upper,
                    solverOptions: new SolverOptions(scanSteps: 1),
                ),
                $equation,
            );
        }
    }

