    public function testPositiveGammaPeriodicPhasesEnumerateEveryRootAtCoarseScanResolution(): void
    {
        $rootValues = [];
        foreach ([1, 256] as $scanSteps) {
            $solutions = Math::solve(
                'sin(gamma(1/x)) = 0',
                'x',
                0.125,
                1.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );

            self::assertCount(1604, $solutions, 'scanSteps=' . $scanSteps);
            self::assertEqualsWithDelta(0.12500136192072, $solutions[0]->value, 1.0E-12);
            self::assertEqualsWithDelta(0.28997121971712, $solutions[1603]->value, 1.0E-10);
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-8, $solution->residual);
            }
            $rootValues[] = array_map(
                static fn ($solution): float => $solution->value,
                $solutions,
            );
        }

        self::assertSame($rootValues[0], $rootValues[1]);

        $cosineSolutions = Math::solve(
            'cos(gamma(1/x)) = 0',
            'x',
            0.125,
            1.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1604, $cosineSolutions);
        foreach ($cosineSolutions as $solution) {
            self::assertLessThanOrEqual(1.0E-8, $solution->residual);
        }

        $narrowIntervalSolutions = Math::solve(
            'sin(gamma(1/x)) = 0',
            'x',
            1.0 / 10.001,
            0.1,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(260, $narrowIntervalSolutions);
        foreach ($narrowIntervalSolutions as $solution) {
            self::assertLessThanOrEqual(1.0E-8, $solution->residual);
        }

        $quadraticArgumentSolutions = Math::solve(
            'sin(gamma(x^2)) = 0',
            'x',
            2.0,
            \sqrt(8.0),
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1603, $quadraticArgumentSolutions);
        foreach ($quadraticArgumentSolutions as $solution) {
            self::assertLessThanOrEqual(1.0E-8, $solution->residual);
        }

        $this->expectException(\DomainException::class);
        Math::solve(
            'sin(gamma(1/x)) = 0',
            'x',
            0.1,
            1.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
    }

