    public function testPeriodicGammaFamilyOfBoundedTransformsReportsPoleAccumulation(): void
    {
        foreach (
            [
                'sin(digamma(exp(-1/x))) = 0',
                'sin(polygamma(4, exp(-1/x))) = 0',
                'sin(digamma(sqrt(x))) = 0',
                'sin(digamma(sqrt(exp(-1/x)))) = 0',
                'sin(digamma(exp(-1/sqrt(x)))) = 0',
                'sin(digamma(1-sqrt(x))) = 0',
            ] as $equation
        ) {
            try {
                Math::solve(
                    $equation,
                    'x',
                    0.0,
                    1.0,
                    solverOptions: new SolverOptions(scanSteps: 1),
                );
                self::fail(
                    'Expected infinitely many roots to accumulate at a bounded-transform preimage of a pole: '
                    . $equation,
                );
            } catch (InfiniteRootAccumulationException $exception) {
                self::assertStringContainsString('infinitely many roots', $exception->getMessage());
            }
        }

        Math::solve(
            'sin(digamma(1-exp(-1/x))) = 0',
            'x',
            0.0,
            1.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
    }

    public function testPeriodicUnboundedCompositionsReportAccumulationAtBoundaries(): void
    {
        foreach (
            [
                'sin(gamma(exp(-1/x))) = 0',
                'sin(lgamma(exp(-1/x))) = 0',
                'sin(digamma(exp(-1/x))) = 0',
                'sin(digamma(exp(-1/x)) + 1) = 0',
                'sin((1+x)*digamma(exp(-1/x))) = 0',
                'sin(digamma(exp(-1/x))/x) = 0',
                'sin(asinh(exp(-1/x))) = 0',
                'sin(acosh(exp(-1/x))) = 0',
                'sin(ln(exp(-1/x))) = 0',
                'sin(log(exp(-1/x), 2)) = 0',
                'sin(lambertw(exp(-1/x))) = 0',
                'sin(polygamma(0, exp(-1/x))) = 0',
            ] as $equation
        ) {
            $this->expectInfiniteRootAccumulation($equation, -1.0, 0.0);
        }

        self::assertSame(
            [],
            Math::solve(
                'sin(trigamma(exp(-1/x))) = 0',
                'x',
                -1.0,
                0.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
        $this->expectInfiniteRootAccumulation(
            'sin(lambertw(-exp(-1/x), -1)) = 0',
            0.0,
            1.0,
        );
        Math::solve(
            'sin(x*digamma(exp(-1/x))) = 0',
            'x',
            -1.0,
            0.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertSame(
            [],
            Math::solve(
                'sin(sqrt(-1/x)) = 0',
                'x',
                0.0,
                1.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
    }

    public function testPeriodicEquationWithContinuousNondifferentiableTargetReportsAccumulation(): void
    {
        foreach ([[-1.0, 1.0], [0.0, 1.0], [-1.0, 0.0]] as [$lower, $upper]) {
            try {
                Math::solve(
                    'sin(1/x) = sqrt(abs(x))',
                    'x',
                    $lower,
                    $upper,
                    solverOptions: new SolverOptions(scanSteps: 1),
                );
                self::fail('Expected infinitely many roots to accumulate at zero.');
            } catch (InfiniteRootAccumulationException $exception) {
                self::assertStringContainsString('infinitely many roots', $exception->getMessage());
            }
        }

        self::assertSame(
            [],
            Math::solve(
                'sin(1/x) = sqrt(abs(x)) + 2',
                'x',
                0.0,
                1.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
    }

    public function testPeriodicTargetsApproachingRangeBoundaryFromInsideReportAccumulation(): void
    {
        foreach (
            [
                'sin(1/x) = 1 - sqrt(abs(x))',
                'sin(1/x) = -1 + sqrt(abs(x))',
                'cos(1/x) = 1 - sqrt(abs(x))',
                'sin(1/x) = 1 - x^2',
                'cos(1/x) = -1 + sqrt(x^2)',
                'sin(1/x) = 1 - sqrt(abs(x)^2)',
                'sin(1/x) = 1 - sqrt(abs(x)^3)',
                'sin(1/x) = 1 - abs(x)^(3/2)',
            ] as $equation
        ) {
            try {
                Math::solve(
                    $equation,
                    'x',
                    0.0,
                    1.0,
                    solverOptions: new SolverOptions(scanSteps: 1),
                );
                self::fail('Expected infinitely many roots to accumulate at zero: ' . $equation);
            } catch (InfiniteRootAccumulationException $exception) {
                self::assertStringContainsString('infinitely many roots', $exception->getMessage());
            }
        }

        foreach (
            [
                'sin(1/x) = 1 + sqrt(abs(x))',
                'sin(1/x) = -1 - sqrt(abs(x))',
                'cos(1/x) = 1 + sqrt(abs(x))',
                'sin(1/x) = 1 + x^2',
                'cos(1/x) = -1 - sqrt(x^2)',
                'sin(1/x) = 1 + sqrt(abs(x)^2)',
                'sin(1/x) = 1 + sqrt(abs(x)^3)',
                'sin(1/x) = 1 + abs(x)^(3/2)',
            ] as $equation
        ) {
            self::assertSame(
                [],
                Math::solve(
                    $equation,
                    'x',
                    0.0,
                    1.0,
                    solverOptions: new SolverOptions(scanSteps: 1),
                ),
                $equation,
            );
        }
    }

    public function testPeriodicTargetsWithFlatExponentialBoundaryPerturbations(): void
    {
        foreach (
            [
                'sin(1/x) = 1 - exp(-1/x)',
                'sin(1/x) = -1 + exp(-1/x)',
                'sin(1/x) = 1 - x*exp(-1/x)',
                'sin(1/x) = 1 - x^2*exp(-1/x)',
            ] as $equation
        ) {
            $this->expectInfiniteRootAccumulation($equation, 0.0, 1.0);
        }

        foreach (
            [
                'sin(1/x) = 1 + exp(-1/x)',
                'sin(1/x) = -1 - exp(-1/x)',
                'sin(1/x) = 1 + x*exp(-1/x)',
            ] as $equation
        ) {
            try {
                Math::solve(
                    $equation,
                    'x',
                    0.0,
                    1.0,
                    solverOptions: new SolverOptions(scanSteps: 1),
                );
            } catch (InfiniteRootAccumulationException $exception) {
                self::fail('Expected the exponential perturbation to remain outside the periodic range: ' . $equation);
            }
        }
    }

    private function expectInfiniteRootAccumulation(string $equation, float $lower, float $upper): void
    {
        try {
            Math::solve(
                $equation,
                'x',
                $lower,
                $upper,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::fail('Expected an unbounded gamma-family phase to produce infinitely many roots: ' . $equation);
        } catch (InfiniteRootAccumulationException $exception) {
            self::assertStringContainsString('infinitely many roots', $exception->getMessage());
        }
    }

