    public function testPeriodicReciprocalAlgebraicLogPhasesReportBoundaryAccumulation(): void
    {
        foreach (
            [
                ['sin(1 / (x * ln(x))) = 0', 0.0, 0.5],
                ['sin(1 / (x * ln(1 / x))) = 0', 0.0, 0.5],
                ['sin(1 / (x * ln(x)^2)) = 0', 0.0, 0.5],
                ['sin(1 / (x * ln(1 / x)^2)) = 0', 0.0, 0.5],
                ['sin(1 / (x * ln(1 + x))) = 0', 0.0, 0.5],
                ['sin(1 / (x * (ln(1 + x) + 1))) = 0', 0.0, 0.5],
                ['sin(1 / (x * (ln(1 + x)^2 + 1))) = 0', 0.0, 0.5],
                ['sin(1 / (x * ln(1 - x))) = 0', 0.0, 0.5],
                ['sin(1 / ((x - 1) * ln(x - 1))) = 0', 1.0, 1.5],
            ] as [$equation, $lowerBound, $upperBound]
        ) {
            try {
                Math::solve(
                    $equation,
                    'x',
                    $lowerBound,
                    $upperBound,
                    solverOptions: new SolverOptions(scanSteps: 1),
                );
                self::fail('Expected accumulating periodic roots for ' . $equation);
            } catch (InfiniteRootAccumulationException) {
            }
        }

        $nestedExponentialPhase = Math::solve(
            'sin(1 / (x * ln(exp(1 / x^2)))) = 0',
            'x',
            0.0,
            0.5,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertSame([], $nestedExponentialPhase);

        $dominantPolePhase = Math::solve(
            'sin(1 / (x * (ln(exp(1 / x^2)) + 1))) = 0',
            'x',
            0.0,
            0.5,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertSame([], $dominantPolePhase);
    }

