    public function testRationalSincZeroEquationsEnumerateEveryPhaseLevel(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $lowerBound = 0.0001;
        $upperBound = 1.0;
        $sincRoots = Math::solve(
            'sinc(1/x) = 0',
            'x',
            $lowerBound,
            $upperBound,
            solverOptions: $options,
        );

        self::assertCount(3183, $sincRoots);
        foreach ($sincRoots as $index => $solution) {
            $phaseIndex = 3183 - $index;
            self::assertEqualsWithDelta(
                1.0 / ($phaseIndex * \M_PI),
                $solution->value,
                1.0E-10,
            );
            self::assertLessThanOrEqual(1.0E-9, $solution->residual);
        }

        $sincPiRoots = Math::solve(
            'sincpi(1/x) = 0',
            'x',
            $lowerBound,
            $upperBound,
            solverOptions: $options,
        );
        self::assertCount(10_000, $sincPiRoots);
        foreach ($sincPiRoots as $index => $solution) {
            $phaseIndex = 10_000 - $index;
            self::assertEqualsWithDelta(
                1.0 / $phaseIndex,
                $solution->value,
                1.0E-10,
            );
            self::assertLessThanOrEqual(1.0E-9, $solution->residual);
        }
    }

    public function testRationalSincpiExcludesARepeatedRemovableHole(): void
    {
        $solutions = Math::solve(
            'sincpi(((x^2 - 1)^2) / (x - 1)^2) = 0',
            'x',
            -2.0,
            10.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        $expectedRoots = [-2.0];
        for ($phase = 1; $phase <= 121; ++$phase) {
            if ($phase !== 4) {
                $expectedRoots[] = \sqrt($phase) - 1.0;
            }
        }

        self::assertCount(\count($expectedRoots), $solutions);
        foreach ($solutions as $index => $solution) {
            self::assertEqualsWithDelta($expectedRoots[$index], $solution->value, 1.0E-9);
            self::assertNotEqualsWithDelta(1.0, $solution->value, 1.0E-9);
            self::assertLessThanOrEqual(1.0E-9, $solution->residual);
        }
    }

