    public function testPolynomialPeriodicArgumentEnumeratesRepeatedAndSimpleRoots(): void
    {
        $solutions = Math::solve(
            'sin(x^2) = 0',
            'x',
            -10.0,
            10.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(63, $solutions);
        foreach ($solutions as $index => $solution) {
            if ($index === 31) {
                self::assertEqualsWithDelta(0.0, $solution->value, 1.0E-12);
            } elseif ($index < 31) {
                self::assertEqualsWithDelta(
                    -\sqrt((31 - $index) * \M_PI),
                    $solution->value,
                    1.0E-9,
                );
            } else {
                self::assertEqualsWithDelta(
                    \sqrt(($index - 31) * \M_PI),
                    $solution->value,
                    1.0E-9,
                );
            }
            self::assertLessThanOrEqual(1.0E-10, $solution->residual);
        }
    }

