    public function testExponentialZeroTargetDoesNotTreatUnderflowAsARoot(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $exponentialRoots = Math::solve(
            'exp(-1/x^2) = 0',
            'x',
            0.01,
            1.0,
            solverOptions: $options,
        );
        $productRoots = Math::solve(
            'exp(-1/x^2)*sin(1/x) = 0',
            'x',
            0.01,
            1.0,
            solverOptions: $options,
        );

        self::assertSame([], $exponentialRoots);
        self::assertCount(31, $productRoots);
        foreach ($productRoots as $index => $solution) {
            $level = 31 - $index;
            self::assertEqualsWithDelta(
                1.0 / ($level * \M_PI),
                $solution->value,
                1.0E-9,
            );
        }

        self::assertSame(
            [],
            Math::solve(
                'sin(exp(-1 / x)) = 0',
                'x',
                0.0,
                1.0,
                solverOptions: $options,
            ),
        );
        foreach (
            [
            'tan(exp(-1 / x)) = 0',
            'cos(exp(-1 / x)) = 1',
            'sin(exp(-1 / x)) = 1',
            'cos(exp(-1 / x)) = 0',
            'sin(-4 * exp(-1 / x)) = 0',
            ] as $equation
        ) {
            self::assertSame(
                [],
                Math::solve($equation, 'x', 0.0, 1.0, solverOptions: $options),
                $equation,
            );
        }
        foreach (
            [
                'sin(10 * exp(-1 / x)) = 0',
                'tan(-10 * exp(-1 / x)) = 0',
            ] as $equation
        ) {
            $roots = Math::solve($equation, 'x', 0.0, 1.0, solverOptions: $options);
            self::assertCount(1, $roots, $equation);
            self::assertEqualsWithDelta(
                -1.0 / \log(\M_PI / 10.0),
                $roots[0]->value,
                1.0E-8,
                $equation,
            );
        }
        $reachableSineRoot = Math::solve(
            'sin(exp(-1 / x)) = 0.2',
            'x',
            0.0,
            1.0,
            solverOptions: $options,
        );
        self::assertCount(1, $reachableSineRoot);
        self::assertEqualsWithDelta(
            -1.0 / \log(\asin(0.2)),
            $reachableSineRoot[0]->value,
            1.0E-8,
        );
    }

