    public function testPolynomialSincArgumentsEnumerateEveryZeroPhaseLevel(): void
    {
        $sincPiSolutions = Math::solve(
            'sincpi(x^4) = 0',
            'x',
            -3.0,
            3.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(162, $sincPiSolutions);
        foreach ($sincPiSolutions as $index => $solution) {
            $level = $index < 81 ? 81 - $index : $index - 80;
            $expected = $index < 81
                ? -\sqrt(\sqrt((float) $level))
                : \sqrt(\sqrt((float) $level));
            self::assertEqualsWithDelta($expected, $solution->value, 1.0E-9);
            self::assertLessThanOrEqual(1.0E-10, $solution->residual);
        }

        $sincSolutions = Math::solve(
            'sinc(x^2) = 0',
            'x',
            -3.0,
            3.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(4, $sincSolutions);
        foreach ($sincSolutions as $index => $solution) {
            $level = $index < 2 ? 2 - $index : $index - 1;
            $expected = $index < 2
                ? -\sqrt($level * \M_PI)
                : \sqrt($level * \M_PI);
            self::assertEqualsWithDelta($expected, $solution->value, 1.0E-9);
            self::assertLessThanOrEqual(1.0E-10, $solution->residual);
        }

        $phaseRoots = Math::solve(
            'sincpi(x) = 0.01',
            'x',
            0.0,
            81.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        $polynomialTargetRoots = Math::solve(
            'sincpi(x^4) = 0.01',
            'x',
            -3.0,
            3.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        $expectedPolynomialRoots = [];
        foreach ($phaseRoots as $phaseRoot) {
            $root = \sqrt(\sqrt($phaseRoot->value));
            $expectedPolynomialRoots[] = -$root;
            $expectedPolynomialRoots[] = $root;
        }
        \sort($expectedPolynomialRoots, SORT_NUMERIC);

        self::assertCount(62, $polynomialTargetRoots);
        foreach ($polynomialTargetRoots as $index => $solution) {
            self::assertEqualsWithDelta(
                $expectedPolynomialRoots[$index],
                $solution->value,
                1.0E-8,
            );
            self::assertLessThanOrEqual(1.0E-9, $solution->residual);
        }
    }

    public function testSineOverItsArgumentUsesSincPhaseInversion(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $quotientRoots = Math::solve(
            'sin(100000*x)/(100000*x) = 0.01',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        $sincRoots = Math::solve(
            'sinc(100000*x) = 0.01',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );

        self::assertCount(62, $quotientRoots);
        self::assertCount(\count($sincRoots), $quotientRoots);
        foreach ($quotientRoots as $index => $solution) {
            self::assertEqualsWithDelta($sincRoots[$index]->value, $solution->value, 1.0E-12);
            self::assertNotEqualsWithDelta(0.0, $solution->value, 1.0E-12);
            self::assertLessThanOrEqual(1.0E-9, $solution->residual);
        }

        $polynomialQuotientRoots = Math::solve(
            'sin(x^2)/(x^2) = 0.01',
            'x',
            -10.0,
            10.0,
            solverOptions: $options,
        );
        $polynomialSincRoots = Math::solve(
            'sinc(x^2) = 0.01',
            'x',
            -10.0,
            10.0,
            solverOptions: $options,
        );

        self::assertCount(62, $polynomialQuotientRoots);
        self::assertCount(\count($polynomialSincRoots), $polynomialQuotientRoots);
        foreach ($polynomialQuotientRoots as $index => $solution) {
            self::assertEqualsWithDelta(
                $polynomialSincRoots[$index]->value,
                $solution->value,
                1.0E-10,
            );
            self::assertNotEqualsWithDelta(0.0, $solution->value, 1.0E-10);
            self::assertLessThanOrEqual(1.0E-9, $solution->residual);
        }

        $rationalQuotientRoots = Math::solve(
            'sin(1/x)/(1/x) = 0.01',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );
        $rationalSincRoots = Math::solve(
            'sinc(1/x) = 0.01',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );

        self::assertCount(62, $rationalQuotientRoots);
        self::assertCount(\count($rationalSincRoots), $rationalQuotientRoots);
        foreach ($rationalQuotientRoots as $index => $solution) {
            self::assertEqualsWithDelta(
                $rationalSincRoots[$index]->value,
                $solution->value,
                1.0E-12,
            );
            self::assertNotEqualsWithDelta(0.0, $solution->value, 1.0E-12);
            self::assertLessThanOrEqual(1.0E-9, $solution->residual);
        }

        self::assertSame(
            [],
            Math::solve(
                'sin(x)/x = 1',
                'x',
                -1.0,
                1.0,
                solverOptions: $options,
            ),
        );
    }

    public function testInvertibleFunctionsOfRationalArgumentsEnumerateTangentLevels(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $tangentRoot = Math::solve(
            'exp(1/(x^2 + 1)) = exp(1)',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );

        self::assertCount(1, $tangentRoot);
        self::assertEqualsWithDelta(0.0, $tangentRoot[0]->value, 1.0E-10);
        self::assertLessThanOrEqual(1.0E-10, $tangentRoot[0]->residual);

        $reciprocalArgumentRoot = Math::solve(
            'exp(1/x) = exp(2)',
            'x',
            -1.0,
            1.0,
            solverOptions: $options,
        );

        self::assertCount(1, $reciprocalArgumentRoot);
        self::assertEqualsWithDelta(0.5, $reciprocalArgumentRoot[0]->value, 1.0E-10);
        self::assertLessThanOrEqual(1.0E-10, $reciprocalArgumentRoot[0]->residual);

        $twoBranchRoots = Math::solve(
            'sqrt(1/(x^2 + 1)) = 0.5',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );

        self::assertCount(2, $twoBranchRoots);
        self::assertEqualsWithDelta(-\sqrt(3.0), $twoBranchRoots[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(\sqrt(3.0), $twoBranchRoots[1]->value, 1.0E-10);
        foreach ($twoBranchRoots as $solution) {
            self::assertLessThanOrEqual(1.0E-10, $solution->residual);
        }

        $removableHoleOnly = Math::solve(
            'exp((x^2 - 1)/(x - 1)) = exp(2)',
            'x',
            -2.0,
            2.0,
            solverOptions: $options,
        );

        self::assertSame([], $removableHoleOnly);
    }

