    public function testZeroProductsCombineAnalyticallySolvedFactorRoots(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $lowerBound = -2.0;
        $upperBound = 2.0;
        $periodicRoots = Math::solve(
            'sin(exp(exp(x))) = 0',
            'x',
            $lowerBound,
            $upperBound,
            solverOptions: $options,
        );
        $productRoots = Math::solve(
            'sin(exp(exp(x))) * ln(x) = 0',
            'x',
            $lowerBound,
            $upperBound,
            solverOptions: $options,
        );
        $expectedRoots = \array_map(
            static fn ($root): float => $root->value,
            \array_values(\array_filter(
                $periodicRoots,
                static fn ($root): bool => $root->value > 0.0,
            )),
        );
        $expectedRoots[] = 1.0;
        \sort($expectedRoots, SORT_NUMERIC);

        self::assertCount(\count($periodicRoots) + 1, $productRoots);
        foreach ($productRoots as $index => $solution) {
            self::assertEqualsWithDelta($expectedRoots[$index], $solution->value, 1.0E-10);
            self::assertLessThanOrEqual(1.0E-9, $solution->residual);
        }
    }

    public function testRepeatedNonPolynomialZeroPowerReturnsOneRoot(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        foreach (
            [
                '(exp(x - 0.3) - 1)^2 = 0',
                '0 = (exp(x - 0.3) - 1)^2',
                '2 * (exp(x - 0.3) - 1)^2 = 0',
                '(exp(x - 0.3) - 1)^2 / 3 = 0',
            ] as $equation
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                -1.0,
                1.0,
                solverOptions: $options,
            );

            self::assertCount(1, $solutions, $equation);
            self::assertEqualsWithDelta(0.3, $solutions[0]->value, 1.0E-12, $equation);
            self::assertSame(0.0, $solutions[0]->residual, $equation);
        }

        self::assertSame(
            [],
            Math::solve(
                '(ln(x) - 0.3)^2 / (x - exp(0.3)) = 0',
                'x',
                0.1,
                2.0,
                solverOptions: $options,
            ),
        );
        $separateZero = Math::solve(
            '(ln(x) - 0.3)^2 / (x - 2) = 0',
            'x',
            0.1,
            3.0,
            solverOptions: $options,
        );
        self::assertCount(1, $separateZero);
        self::assertEqualsWithDelta(\exp(0.3), $separateZero[0]->value, 1.0E-10);

        $otherFactorRoot = Math::solve(
            '((ln(x) - 0.3) * (x - 1)) / ((x - exp(0.3)) * (x - 2)) = 0',
            'x',
            0.1,
            3.0,
            solverOptions: $options,
        );
        self::assertCount(1, $otherFactorRoot);
        self::assertSame(1.0, $otherFactorRoot[0]->value);

        $nearbyValidRoot = \exp(0.3) + 1.0E-8;
        $nearbyZero = Math::solve(
            \sprintf(
                '((ln(x) - 0.3) * (x - %.17g)) / (x - exp(0.3)) = 0',
                $nearbyValidRoot,
            ),
            'x',
            0.1,
            3.0,
            solverOptions: $options,
        );
        self::assertCount(1, $nearbyZero);
        self::assertEqualsWithDelta($nearbyValidRoot, $nearbyZero[0]->value, 1.0E-12);
    }

    public function testZeroProductFactorizationHandlesQuotientsAndNegativePowers(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $quotientRoots = Math::solve(
