            -10.0,
            10.0,
            solverOptions: $options,
        );
        self::assertCount(6, $reciprocalProductRoots);
        foreach ($reciprocalProductRoots as $index => $solution) {
            $rootNumber = $index < 3 ? $index - 3 : $index - 2;
            self::assertEqualsWithDelta($rootNumber * \M_PI, $solution->value, 1.0E-10);
            self::assertNotSame(0.0, $solution->value);
            self::assertLessThanOrEqual(1.0E-10, $solution->residual);
        }

        $domainRestrictedRoots = Math::solve(
            'sqrt(x) * ln(x) = 0',
            'x',
            -1.0,
            3.0,
            solverOptions: $options,
        );
        self::assertCount(1, $domainRestrictedRoots);
        self::assertSame(1.0, $domainRestrictedRoots[0]->value);

        self::assertSame([], Math::solve('x^-2 = 0', 'x', -2.0, 2.0));
        self::assertSame([], Math::solve('x^0 = 0', 'x', -2.0, 2.0));
    }

