    public function testUnboundedSincReciprocalIdentitiesReduceToSineLevels(): void
    {
        foreach (
            [
                'sinc(x) = 1/x',
                'sinc(x) = 1/(2*x)',
                'sincpi(x) = 1/(4*x)',
                'sinc(x) = x/x^2',
                'sinc(x) = (x + 1)/(x^2 + x)',
                'sincpi(x) = x/(4*x^2)',
                'sincpi(x) = 0.3183098861837905/x',
                'sinc(2*x + 1) = 1/(2*x + 1)',
                'sinc(1/x) = x',
                'sincpi(1/x) = x/pi',
                'sinc(x) = sin(x)/x',
                'sinc(x) = sin(x)/(-x)',
                'sinc(x) = sin(2*x)/(4*x)',
                'sinc(x) = sin(x)/(2*x)',
                'sinc(x) = sin(x)/(x/2)',
                'sincpi(x) = sin(pi*x)/(pi*x)',
                'sinc(x) = sin(2*x)/(2*x)',
                'sinc(x) = sin(x/2)/(x/2)',
                'sincpi(x) = sin(2*pi*x)/(2*pi*x)',
                'sincpi(x) = sin(pi*x/3)/(pi*x/3)',
                'sinc(x) = sin(1.5*x)/(1.5*x)',
                'sinc(x) = sin(-1.5*x)/(-1.5*x)',
                'sinc(x) = sin(1.50000000001*x)/(1.50000000001*x)',
                'sinc(x) = sin(1.5000000000001*x)/(1.5000000000001*x)',
                'sinc(x) = sin(1.4142135623730951*x)/(1.4142135623730951*x)',
                '-sinc(x) = -sin(x)/x',
                '-sinc(x) = 1/x',
                'sinc(x) = -1/x',
                '-sinc(x) = -1/x',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', -\INF, \INF);
                self::fail($equation . ' should have infinitely many roots.');
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }

        self::assertSame([], Math::solve('sinc(x) = 2/x', 'x', -\INF, \INF));
        self::assertSame([], Math::solve('sincpi(x) = 1/x', 'x', -\INF, \INF));
        self::assertSame([], Math::solve('sincpi(1/x) = x', 'x', -\INF, \INF));
        foreach (
            ['sinc(x) = -sin(x)/x', 'sincpi(x) = -sin(pi*x)/(pi*x)'] as $equation
        ) {
            try {
                Math::solve($equation, 'x', -\INF, \INF);
                self::fail($equation . ' should have infinitely many roots.');
            } catch (InfiniteSolutionSetException) {
                self::assertTrue(true);
            }
        }
        self::assertSame(
            [],
            Math::solve('sincpi(x) = 0.318309886183791/x', 'x', -\INF, \INF),
        );

        $boundedRationalPhase = Math::solve(
            'sinc(1/(x^2 + 1)) = (x^2 + 1)/2',
            'x',
            -\INF,
            \INF,
        );
        self::assertCount(2, $boundedRationalPhase);
        self::assertEqualsWithDelta(-\sqrt(6.0 / \M_PI - 1.0), $boundedRationalPhase[0]->value, 1.0E-8);
        self::assertEqualsWithDelta(\sqrt(6.0 / \M_PI - 1.0), $boundedRationalPhase[1]->value, 1.0E-8);
        foreach ($boundedRationalPhase as $solution) {
            self::assertLessThanOrEqual(1.0E-9, $solution->residual);
        }
    }

