    public function testInvertibleFunctionsOfPolynomialArgumentsAvoidScanMisses(): void
    {
        $tinyHyperbolicTarget = 1.0E-320;
        $tinyHyperbolicLevel = \log(2.0) - \log($tinyHyperbolicTarget);
        $cases = [
            ['exp((x - 2)^2) = 2', -4.0, 4.0, [2.0 - \sqrt(\log(2.0)), 2.0 + \sqrt(\log(2.0))]],
            ['ln((x - 1)^2) = 0', -2.0, 4.0, [0.0, 2.0]],
            ['log10(x^2) = 0', -2.0, 2.0, [-1.0, 1.0]],
            ['log2(x^2) = 1', -2.0, 2.0, [-\sqrt(2.0), \sqrt(2.0)]],
            ['log(x^2, 10) = 1', -4.0, 4.0, [-\sqrt(10.0), \sqrt(10.0)]],
            ['expm1(x) = 1', -2.0, 2.0, [\log(2.0)]],
            ['log1p(x) = 0', -2.0, 2.0, [0.0]],
            ['sqrt((x - 1)^2) = 2', -4.0, 4.0, [-1.0, 3.0]],
            ['cbrt(x^2) = 2', -4.0, 4.0, [-\sqrt(8.0), \sqrt(8.0)]],
            ['abs(x^2 - 1) = 0.5', -2.0, 2.0, [-\sqrt(1.5), -\sqrt(0.5), \sqrt(0.5), \sqrt(1.5)]],
            ['sinh(x^2) = 2', -2.0, 2.0, [-\sqrt(\asinh(2.0)), \sqrt(\asinh(2.0))]],
            ['cosh(x^2) = 2', -2.0, 2.0, [-\sqrt(\acosh(2.0)), \sqrt(\acosh(2.0))]],
            ['tanh(x) = 0.5', -2.0, 2.0, [\atanh(0.5)]],
            ['asinh(x) = 1', -2.0, 2.0, [\sinh(1.0)]],
            ['acosh(x) = 1', 0.0, 3.0, [\cosh(1.0)]],
            ['atanh(x) = 1', -1.0, 1.0, [\tanh(1.0)]],
            ['sech(x) = 0.5', -3.0, 3.0, [-\acosh(2.0), \acosh(2.0)]],
            ['csch(x) = 2', -2.0, 2.0, [\asinh(0.5)]],
            ['coth(x) = 2', -2.0, 2.0, [\atanh(0.5)]],
            ['sech(x) = 1e-320', -750.0, 750.0, [-$tinyHyperbolicLevel, $tinyHyperbolicLevel]],
            ['csch(x) = 1e-320', 700.0, 750.0, [$tinyHyperbolicLevel]],
            ['asin(x^2) = 0.5', -2.0, 2.0, [-\sqrt(\sin(0.5)), \sqrt(\sin(0.5))]],
            ['acos(x^2) = 1', -2.0, 2.0, [-\sqrt(\cos(1.0)), \sqrt(\cos(1.0))]],
            ['atan(x^2) = 0.5', -2.0, 2.0, [-\sqrt(\tan(0.5)), \sqrt(\tan(0.5))]],
            ['arcsin(x^2) = 0.5', -2.0, 2.0, [-\sqrt(\sin(0.5)), \sqrt(\sin(0.5))]],
            ['arccos(x^2) = 1', -2.0, 2.0, [-\sqrt(\cos(1.0)), \sqrt(\cos(1.0))]],
            ['arctan(x^2) = 0.5', -2.0, 2.0, [-\sqrt(\tan(0.5)), \sqrt(\tan(0.5))]],
            ['arcsinh(x^2) = 0.5', -2.0, 2.0, [-\sqrt(\sinh(0.5)), \sqrt(\sinh(0.5))]],
            ['arccosh(x^2 + 1) = 0.5', -2.0, 2.0, [-\sqrt(\cosh(0.5) - 1.0), \sqrt(\cosh(0.5) - 1.0)]],
            ['arctanh(x^2) = 0.5', -2.0, 2.0, [-\sqrt(\tanh(0.5)), \sqrt(\tanh(0.5))]],
            ['asec(exp(x)) = 1', -2.0, 2.0, [\log(1.0 / \cos(1.0))]],
            ['acsc(exp(x)) = pi/2', -2.0, 2.0, [0.0]],
            ['acot(exp(x)) = pi/4', -2.0, 2.0, [0.0]],
            ['asec(x^2) = 1', -2.0, 2.0, [-\sqrt(1.0 / \cos(1.0)), \sqrt(1.0 / \cos(1.0))]],
            ['acsc(x^2) = pi/6', -2.0, 2.0, [-\sqrt(2.0), \sqrt(2.0)]],
            ['acot(x^2) = pi/4', -2.0, 2.0, [-1.0, 1.0]],
        ];

        foreach ($cases as [$equation, $lower, $upper, $expected]) {
            $solutions = Math::solve(
                $equation,
                'x',
                $lower,
                $upper,
                solverOptions: new SolverOptions(scanSteps: 1),
            );

            self::assertCount(\count($expected), $solutions, $equation);
            foreach ($expected as $index => $root) {
                self::assertEqualsWithDelta($root, $solutions[$index]->value, 1.0E-8, $equation);
                self::assertLessThanOrEqual(1.0E-10, $solutions[$index]->residual, $equation);
            }
        }

        foreach (
            [
                'acsc(sin(x)) = pi/2' => [-3.0 * \M_PI / 2.0, \M_PI / 2.0],
                'acot(sin(x)) = pi/4' => [-3.0 * \M_PI / 2.0, \M_PI / 2.0],
            ] as $equation => $expected
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                -7.0,
                7.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );

            self::assertCount(2, $solutions, $equation);
            foreach ($expected as $index => $root) {
                self::assertEqualsWithDelta($root, $solutions[$index]->value, 1.0E-8, $equation);
                self::assertLessThanOrEqual(1.0E-10, $solutions[$index]->residual, $equation);
            }
        }

        foreach (
            [
                'asin(x) = pi/2' => 1.0,
                'acos(x) = pi' => -1.0,
                'asec(x) = pi' => -1.0,
                'acsc(x) = pi/2' => 1.0,
            ] as $equation => $expectedRoot
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );

            self::assertCount(1, $solutions, $equation);
            self::assertEqualsWithDelta($expectedRoot, $solutions[0]->value, 1.0E-10);
        }

        foreach (
            [
                'atan(x) = pi/2',
                'asec(x) = pi/2',
                'acsc(x) = 0',
                'acot(x) = 0',
                'acot(x) = pi',
            ] as $equation
        ) {
            self::assertSame(
                [],
                Math::solve(
                    $equation,
                    'x',
                    -2.0,
                    2.0,
                    solverOptions: new SolverOptions(scanSteps: 1),
                ),
                $equation,
            );
        }
    }

    public function testLambertWBranchesInvertPolynomialLevelEquations(): void
    {
        $principal = Math::solve(
            'lambertw(x^2) = 1',
            'x',
            -3.0,
            3.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(2, $principal);
        self::assertEqualsWithDelta(-\sqrt(\M_E), $principal[0]->value, 1.0E-9);
        self::assertEqualsWithDelta(\sqrt(\M_E), $principal[1]->value, 1.0E-9);

        $lowerBranch = Math::solve(
            'lambertw(x, -1) = -2',
            'x',
            -1.0,
            0.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $lowerBranch);
        self::assertEqualsWithDelta(-2.0 * \exp(-2.0), $lowerBranch[0]->value, 1.0E-10);
        self::assertLessThanOrEqual(1.0E-9, $lowerBranch[0]->residual);

        self::assertSame([], Math::solve(
            'lambertw(x) = -2',
            'x',
            -1.0,
            1.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        ));
    }

    public function testGammaOfLowerLambertWBranchFindsAllBoundedRootsIndependentOfScanDensity(): void
    {
        $rootValues = [];
        foreach ([1, 256] as $scanSteps) {
            $solutions = Math::solve(
                'gamma(lambertw(x, -1)) = 3',
                'x',
                -1.0 / \M_E,
                0.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );

            self::assertCount(8, $solutions, 'scanSteps=' . $scanSteps);
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-8, $solution->residual);
            }
            $rootValues[] = array_map(
                static fn ($solution): float => $solution->value,
                $solutions,
            );
        }

        self::assertEquals($rootValues[0], $rootValues[1]);
        self::assertSame([], Math::solve(
            'gamma(lambertw(x, -1)) = 0',
            'x',
            -1.0 / \M_E,
            0.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        ));
    }

