    public function testGammaCompositionsInvertTheirBoundedOuterLevels(): void
    {
        $periodicRootValues = [];
        foreach ([1, 256] as $scanSteps) {
            $gammaSolutions = Math::solve(
                'gamma(exp(x)) = 3',
                'x',
                -10.0,
                10.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(2, $gammaSolutions, 'gamma scanSteps=' . $scanSteps);
            foreach ($gammaSolutions as $solution) {
                self::assertLessThanOrEqual(1.0E-8, $solution->residual);
            }
            $periodicGammaSolutions = Math::solve(
                'gamma(sin(x)) = 3',
                'x',
                -10.0,
                10.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(7, $periodicGammaSolutions, 'gamma(sin(x)) scanSteps=' . $scanSteps);
            foreach ($periodicGammaSolutions as $solution) {
                self::assertLessThanOrEqual(1.0E-8, $solution->residual);
            }
            $periodicRootValues[] = array_map(
                static fn ($solution): float => $solution->value,
                $periodicGammaSolutions,
            );

            $periodicSolutions = Math::solve(
                'lgamma(sin(x)) = 0',
                'x',
                -10.0,
                10.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(3, $periodicSolutions, 'lgamma scanSteps=' . $scanSteps);
            foreach ($periodicSolutions as $solution) {
                self::assertLessThanOrEqual(1.0E-8, $solution->residual);
            }

        }

        foreach ($periodicRootValues[0] as $index => $root) {
            self::assertEqualsWithDelta($root, $periodicRootValues[1][$index], 1.0E-9);
        }
    }

    public function testGammaCompositionsReportAccumulationAtSingularities(): void
    {
        foreach (
            [
                'gamma(tan(x)) = 3',
                'lgamma(tan(x)) = 0',
                'gamma(log1p(sin(x))) = 3',
                'lgamma(log1p(sin(x))) = 0',
                'gamma(ln(sin(x))) = 3',
                'gamma(ln(sin(x^2))) = 3',
                'gamma(log1p(-cos(x))) = 3',
            ] as $equation
        ) {
            try {
                Math::solve($equation, 'x', -3.0, 3.0);
                self::fail('Expected infinitely many roots accumulating at a singularity: ' . $equation);
            } catch (InfiniteRootAccumulationException $exception) {
                self::assertStringContainsString('infinitely many roots', $exception->getMessage());
            }
        }

        $finiteSolutions = Math::solve('gamma(tan(x)) = 3', 'x', -1.0, 1.0);
        self::assertNotEmpty($finiteSolutions);
        foreach ($finiteSolutions as $solution) {
            self::assertLessThanOrEqual(1.0E-8, $solution->residual);
        }

        self::assertSame(
            [],
            Math::solve('gamma(ln(-sin(x^2))) = 3', 'x', -1.0, 1.0),
        );
        self::assertSame(
            [],
            Math::solve('lgamma(ln(-sin(x^2))) = 0', 'x', -1.0, 1.0),
        );
        self::assertSame(
            [],
            Math::solve('gamma(log1p(-1 - x^2)) = 3', 'x', -1.0, 1.0),
        );
    }

