    public function testLambertWProductEquationsUseBothRealBranches(): void
    {
        $target = -1.0 / \M_E + 1.0E-12;
        $targetSource = \sprintf('%.17g', $target);
        $offsetSource = \sprintf('%.17g', -$target);
        $shiftedTargetSource = \sprintf('%.17g', $target * \M_E);
        $lowerBranchRoot = (float) Math::evaluate('lambertw(' . $targetSource . ', -1)');
        $principalBranchRoot = (float) Math::evaluate('lambertw(' . $targetSource . ')');
        foreach ([1, 256] as $scanSteps) {
            foreach (
                [
                'x*exp(x)=' . $targetSource,
                $targetSource . '=exp(x)*x',
                'x*exp(x+1)=' . $shiftedTargetSource,
                'x*exp(x)+' . $offsetSource . '=0',
                '0=' . $offsetSource . '+exp(x)*x',
                ] as $equation
            ) {
                $solutions = Math::solve(
                    $equation,
                    'x',
                    -1.001,
                    -0.999,
                    solverOptions: new SolverOptions(scanSteps: $scanSteps),
                );

                self::assertCount(2, $solutions, $equation . ', scanSteps=' . $scanSteps);
                self::assertEqualsWithDelta($lowerBranchRoot, $solutions[0]->value, 1.0E-9);
                self::assertEqualsWithDelta($principalBranchRoot, $solutions[1]->value, 1.0E-9);
                foreach ($solutions as $solution) {
                    self::assertLessThanOrEqual(1.0E-10, $solution->residual);
                }
            }
        }
    }

