    public function testLambertWProductCombinesFactoredPolynomialPrefactors(): void
    {
        foreach (
            [
                [
                    'x*(x + 1)*exp(x^2 + x) = 1',
                    (float) Math::evaluate('lambertw(1)'),
                ],
                [
                    '2*x*(x + 1)*exp(3*(x^2 + x) + 2) = 1',
                    (float) Math::evaluate('lambertw(3/(2*exp(2)))') / 3.0,
                ],
                [
                    '-2*x*(x + 1)*exp(-3*(x^2 + x) + 2) = 0.1',
                    -(float) Math::evaluate('lambertw(0.15/exp(2))') / 3.0,
                ],
                [
                    'x*(x + 1)*exp(x^2 + x) = -0.1',
                    (float) Math::evaluate('lambertw(-0.1)'),
                ],
            ] as [$equation, $polynomialLevel]
        ) {
            foreach ([1, 256] as $scanSteps) {
                $solutions = Math::solve(
                    $equation,
                    'x',
                    -2.0,
                    1.0,
                    solverOptions: new SolverOptions(scanSteps: $scanSteps),
                );
                self::assertEqualsWithDelta(
                    [
                        (-1.0 - \sqrt(1.0 + (4.0 * $polynomialLevel))) / 2.0,
                        (-1.0 + \sqrt(1.0 + (4.0 * $polynomialLevel))) / 2.0,
                    ],
                    \array_map(static fn (EquationSolution $solution): float => $solution->value, $solutions),
                    1.0E-9,
                    $equation,
                );
                foreach ($solutions as $solution) {
                    self::assertLessThanOrEqual(1.0E-9, $solution->residual);
                }
            }
        }
    }

    public function testLambertWProductSupportsRationalPrefactors(): void
    {
        $principalLevel = (float) Math::evaluate('lambertw(-0.1)');
        $lowerLevel = (float) Math::evaluate('lambertw(-0.1, -1)');
        foreach ([1, 256] as $scanSteps) {
            $solutions = Math::solve(
                'x/(x + 1)*exp(x/(x + 1)) = -0.1',
                'x',
                -10.0,
                10.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertEqualsWithDelta(
                [
                    $lowerLevel / (1.0 - $lowerLevel),
                    $principalLevel / (1.0 - $principalLevel),
                ],
                \array_map(static fn (EquationSolution $solution): float => $solution->value, $solutions),
                1.0E-9,
            );
            foreach ($solutions as $solution) {
                self::assertNotEqualsWithDelta(-1.0, $solution->value, 1.0E-9);
                self::assertLessThanOrEqual(1.0E-9, $solution->residual);
            }

            $scaledLevel = (float) Math::evaluate('lambertw(0.2)') / 2.0;
            $scaledSolutions = Math::solve(
                '(x/(x + 1))*exp(2*x/(x + 1)) = 0.1',
                'x',
                -\INF,
                \INF,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertEqualsWithDelta(
                [$scaledLevel / (1.0 - $scaledLevel)],
                \array_map(static fn (EquationSolution $solution): float => $solution->value, $scaledSolutions),
                1.0E-9,
            );

            $cancelledPrefactor = Math::solve(
                '((x^2 - 1)/(x + 1))*exp((x^2 - 1)/(x + 1)) = 1',
                'x',
                -\INF,
                \INF,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertEqualsWithDelta(
                [(float) Math::evaluate('lambertw(1)') + 1.0],
                \array_map(static fn (EquationSolution $solution): float => $solution->value, $cancelledPrefactor),
                1.0E-9,
            );

            $productLevel = (float) Math::evaluate('lambertw(1)');
            $rationalProductSolutions = Math::solve(
                '(x/(x + 1))*(x + 2)*exp(x*(x + 2)/(x + 1)) = 1',
                'x',
                -\INF,
                \INF,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertEqualsWithDelta(
                [
                    ($productLevel - 2.0 - \sqrt(($productLevel * $productLevel) + 4.0)) / 2.0,
                    ($productLevel - 2.0 + \sqrt(($productLevel * $productLevel) + 4.0)) / 2.0,
                ],
                \array_map(
                    static fn (EquationSolution $solution): float => $solution->value,
                    $rationalProductSolutions,
                ),
                1.0E-9,
            );
        }
    }

    public function testLambertWProductSupportsMatchingRadicalPrefactors(): void
    {
        $squareRootLevel = (float) Math::evaluate('lambertw(1)');
        $scaledSquareRootLevel = 0.5 * (float) Math::evaluate('lambertw(2/e)');
        $cubeRootPrincipalLevel = (float) Math::evaluate('lambertw(-0.1)');
        $cubeRootLowerLevel = (float) Math::evaluate('lambertw(-0.1, -1)');
        $scaledCubeRootPrincipalLevel = 0.5 * (float) Math::evaluate('lambertw(-0.2/e)');
        $scaledCubeRootLowerLevel = 0.5 * (float) Math::evaluate('lambertw(-0.2/e, -1)');
        foreach ([1, 256] as $scanSteps) {
            $squareRootSolutions = Math::solve(
                'sqrt(x)*exp(sqrt(x)) = 1',
                'x',
                -\INF,
                \INF,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertEqualsWithDelta(
                [$squareRootLevel * $squareRootLevel],
                \array_map(static fn (EquationSolution $solution): float => $solution->value, $squareRootSolutions),
                1.0E-9,
            );
            $scaledSquareRootSolutions = Math::solve(
                'sqrt(x)*exp(2*sqrt(x) + 1) = 1',
                'x',
                -\INF,
                \INF,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertEqualsWithDelta(
                [$scaledSquareRootLevel * $scaledSquareRootLevel],
                \array_map(
                    static fn (EquationSolution $solution): float => $solution->value,
                    $scaledSquareRootSolutions,
                ),
                1.0E-9,
            );

            foreach (
                [
                    'cbrt(x)*exp(cbrt(x)) = -0.1',
                    'root(x, 3)*exp(root(x, 3)) = -0.1',
                ] as $equation
            ) {
                $cubeRootSolutions = Math::solve(
                    $equation,
                    'x',
                    -\INF,
                    \INF,
                    solverOptions: new SolverOptions(scanSteps: $scanSteps),
                );
                self::assertEqualsWithDelta(
                    [\pow($cubeRootLowerLevel, 3.0), \pow($cubeRootPrincipalLevel, 3.0)],
                    \array_map(static fn (EquationSolution $solution): float => $solution->value, $cubeRootSolutions),
                    1.0E-8,
                    $equation,
                );
                foreach ($cubeRootSolutions as $solution) {
                    self::assertLessThanOrEqual(1.0E-9, $solution->residual);
                }
            }

            $scaledCubeRootSolutions = Math::solve(
                'cbrt(x)*exp(2*cbrt(x) + 1) = -0.1',
                'x',
                -\INF,
                \INF,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertEqualsWithDelta(
                [
                    \pow($scaledCubeRootLowerLevel, 3.0),
                    \pow($scaledCubeRootPrincipalLevel, 3.0),
                ],
                \array_map(
                    static fn (EquationSolution $solution): float => $solution->value,
                    $scaledCubeRootSolutions,
                ),
                1.0E-8,
            );
        }
    }

    public function testLambertWHandlesIntegerPowersOfPolynomialExponentialArguments(): void
    {
        $squareRootTarget = \sqrt(0.1) / 2.0;
        $squareRoots = [
            2.0 * (float) Math::evaluate(
                'lambertw(' . \sprintf('%.17g', -$squareRootTarget) . ', -1)',
            ),
            2.0 * (float) Math::evaluate(
                'lambertw(' . \sprintf('%.17g', -$squareRootTarget) . ')',
            ),
            2.0 * (float) Math::evaluate(
                'lambertw(' . \sprintf('%.17g', $squareRootTarget) . ')',
            ),
        ];
        \sort($squareRoots, SORT_NUMERIC);

        $cubeRootTarget = -\pow(0.1 / 27.0, 1.0 / 3.0);
        $cubeRoots = [
            3.0 * (float) Math::evaluate(
                'lambertw(' . \sprintf('%.17g', $cubeRootTarget) . ', -1)',
            ),
            3.0 * (float) Math::evaluate(
                'lambertw(' . \sprintf('%.17g', $cubeRootTarget) . ')',
            ),
        ];
        \sort($cubeRoots, SORT_NUMERIC);
        $shiftedTargetRoot = \sqrt(0.1 / (4.0 * \M_E));
        $shiftedRoots = [
            2.0 * (float) Math::evaluate(
                'lambertw(' . \sprintf('%.17g', -$shiftedTargetRoot) . ', -1)',
            ),
            2.0 * (float) Math::evaluate(
                'lambertw(' . \sprintf('%.17g', -$shiftedTargetRoot) . ')',
            ),
            2.0 * (float) Math::evaluate(
                'lambertw(' . \sprintf('%.17g', $shiftedTargetRoot) . ')',
            ),
        ];
        \sort($shiftedRoots, SORT_NUMERIC);
        $constantRoot = \sqrt(0.1 / \exp(3.0));

        foreach ([1, 256] as $scanSteps) {
            $squared = Math::solve(
                'x^2*exp(x)=0.1',
                'x',
                -\INF,
                \INF,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(3, $squared);
            foreach ($squareRoots as $index => $expected) {
                self::assertEqualsWithDelta($expected, $squared[$index]->value, 1.0E-8);
            }

            self::assertSame(
                [],
                Math::solve(
                    'x^2*exp(x)=-0.1',
                    'x',
                    -10.0,
                    10.0,
                    solverOptions: new SolverOptions(scanSteps: $scanSteps),
                ),
            );

            $cubed = Math::solve(
                'x^3*exp(x)=-0.1',
                'x',
                -10.0,
                10.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(2, $cubed);
            foreach ($cubeRoots as $index => $expected) {
                self::assertEqualsWithDelta($expected, $cubed[$index]->value, 1.0E-8);
            }

            $shifted = Math::solve(
                'x^2*exp(x+1)=0.1',
                'x',
                -10.0,
                10.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(3, $shifted);
            foreach ($shiftedRoots as $index => $expected) {
                self::assertEqualsWithDelta($expected, $shifted[$index]->value, 1.0E-8);
            }

            $constantExponent = Math::solve(
                'x^2*exp(3)=0.1',
                'x',
                -1.0,
                1.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(2, $constantExponent);
            self::assertEqualsWithDelta(-$constantRoot, $constantExponent[0]->value, 1.0E-9);
            self::assertEqualsWithDelta($constantRoot, $constantExponent[1]->value, 1.0E-9);

            $tangent = Math::solve(
                'x^2*exp(x)=4/e^2',
                'x',
                -10.0,
                10.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(2, $tangent);
            self::assertEqualsWithDelta(-2.0, $tangent[0]->value, 1.0E-9);

            $highPower = Math::solve(
                'x^65*exp(x)=e',
                'x',
                0.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(1, $highPower);
            self::assertEqualsWithDelta(1.0, $highPower[0]->value, 1.0E-9);
        }
    }

    public function testCommensurateExponentialPolynomialsResolveNearTangentRoots(): void
    {
        $nearTangentTarget = 2.000000000001;
        $expectedMagnitude = \acosh($nearTangentTarget / 2.0);
        $positiveExponentialRoot = \log((\sqrt(13.0) - 1.0) / 2.0);

        foreach ([1, 256] as $scanSteps) {
            $nearTangent = Math::solve(
                'exp(x)+exp(-x)=2.000000000001',
                'x',
                -1.0,
                1.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(2, $nearTangent);
            self::assertEqualsWithDelta(-$expectedMagnitude, $nearTangent[0]->value, 1.0E-10);
            self::assertEqualsWithDelta($expectedMagnitude, $nearTangent[1]->value, 1.0E-10);

            $tangent = Math::solve(
                'exp(x)+exp(-x)=2',
                'x',
                -1.0,
                1.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(1, $tangent);
            self::assertEqualsWithDelta(0.0, $tangent[0]->value, 1.0E-12);

            self::assertSame(
                [],
                Math::solve(
                    'exp(x)+exp(-x)=1.5',
                    'x',
                    -1.0,
                    1.0,
                    solverOptions: new SolverOptions(scanSteps: $scanSteps),
                ),
            );

            self::assertSame(
                [],
                Math::solve(
                    'exp(x)-1.999999999999999*exp(0.5*x)+1=0',
                    'x',
                    -1.0,
                    1.0,
                    solverOptions: new SolverOptions(scanSteps: $scanSteps),
                ),
            );

            $nearTangentPair = Math::solve(
                'exp(x)-2.000000000000001*exp(0.5*x)+1=0',
                'x',
                -1.0,
                1.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(2, $nearTangentPair);
            self::assertEqualsWithDelta(-5.960464477539062E-8, $nearTangentPair[0]->value, 1.0E-12);
            self::assertEqualsWithDelta(5.960464477539062E-8, $nearTangentPair[1]->value, 1.0E-12);

            $quarticContact = Math::solve(
                'exp(4*x)-4*exp(3*x)+6*exp(2*x)-4*exp(x)+1=0',
                'x',
                -0.01,
                0.01,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(1, $quarticContact);
            self::assertEqualsWithDelta(0.0, $quarticContact[0]->value, 1.0E-10);

            self::assertSame(
                [],
                Math::solve(
                    'exp(4*x)-4*exp(3*x)+6*exp(2*x)-4*exp(x)+1.000000000000001=0',
                    'x',
                    -0.01,
                    0.01,
                    solverOptions: new SolverOptions(scanSteps: $scanSteps),
                ),
            );

            $sexticContact = Math::solve(
                'exp(6*x)-6*exp(5*x)+15*exp(4*x)-20*exp(3*x)+15*exp(2*x)-6*exp(x)+1=0',
                'x',
                -0.01,
                0.01,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(1, $sexticContact);
            self::assertEqualsWithDelta(0.0, $sexticContact[0]->value, 1.0E-10);

            self::assertSame(
                [],
                Math::solve(
                    'exp(6*x)-6*exp(5*x)+15*exp(4*x)-20*exp(3*x)+15*exp(2*x)-6*exp(x)+1.000000000000001=0',
                    'x',
                    -0.01,
                    0.01,
                    solverOptions: new SolverOptions(scanSteps: $scanSteps),
                ),
            );

            $octicContact = Math::solve(
                'exp(8*x)-8*exp(7*x)+28*exp(6*x)-56*exp(5*x)+70*exp(4*x)-56*exp(3*x)+28*exp(2*x)-8*exp(x)+1=0',
                'x',
                -0.01,
                0.01,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(1, $octicContact);
            self::assertEqualsWithDelta(0.0, $octicContact[0]->value, 1.0E-10);

            self::assertSame(
                [],
                Math::solve(
                    'exp(8*x)-8*exp(7*x)+28*exp(6*x)-56*exp(5*x)+70*exp(4*x)-56*exp(3*x)+28*exp(2*x)-8*exp(x)+1.000000000000001=0',
                    'x',
                    -0.01,
                    0.01,
                    solverOptions: new SolverOptions(scanSteps: $scanSteps),
                ),
            );

            $decicPolynomial = 'exp(10*x)-10*exp(9*x)+45*exp(8*x)-120*exp(7*x)'
                . '+210*exp(6*x)-252*exp(5*x)+210*exp(4*x)-120*exp(3*x)'
                . '+45*exp(2*x)-10*exp(x)+1';
            $decicContact = Math::solve(
                $decicPolynomial . '=0',
                'x',
                -0.01,
                0.01,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(1, $decicContact);
            self::assertEqualsWithDelta(0.0, $decicContact[0]->value, 1.0E-10);

            self::assertSame(
                [],
                Math::solve(
                    $decicPolynomial . '+0.000000000000001=0',
                    'x',
                    -0.01,
                    0.01,
                    solverOptions: new SolverOptions(scanSteps: $scanSteps),
                ),
            );

            $degreeSeventeenPolynomial = 'exp(17*x)-17*exp(16*x)+136*exp(15*x)-680*exp(14*x)'
                . '+2380*exp(13*x)-6188*exp(12*x)+12376*exp(11*x)-19448*exp(10*x)'
                . '+24310*exp(9*x)-24310*exp(8*x)+19448*exp(7*x)-12376*exp(6*x)'
                . '+6188*exp(5*x)-2380*exp(4*x)+680*exp(3*x)-136*exp(2*x)+17*exp(x)-1';
            $degreeSeventeenContact = Math::solve(
                $degreeSeventeenPolynomial . '=0',
                'x',
                -0.01,
                0.01,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(1, $degreeSeventeenContact);
            self::assertEqualsWithDelta(0.0, $degreeSeventeenContact[0]->value, 1.0E-10);

            self::assertSame(
                [],
                Math::solve(
                    $degreeSeventeenPolynomial . '+0.000000000000001=0',
                    'x',
                    -0.01,
                    0.01,
                    solverOptions: new SolverOptions(scanSteps: $scanSteps),
                ),
            );

            $commensurate = Math::solve(
                'exp(x)+exp(2*x)=3',
                'x',
                -10.0,
                10.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(1, $commensurate);
            self::assertEqualsWithDelta($positiveExponentialRoot, $commensurate[0]->value, 1.0E-10);

            $shifted = Math::solve(
                'exp(2*x+1)+exp(-2*x)=4',
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(2, $shifted);
        }
    }

    public function testTinyOffsetsPreserveQuarticExponentialRootTopology(): void
    {
        self::assertSame(
            [],
            Math::solve(
                'exp(4*x)-4*exp(3*x)+6*exp(2*x)-4*exp(x)+1+1e-20=0',
