        self::assertSame(
            [],
            Math::solve(
                'exp(4*x+0.4)-4*exp(3*x+0.3)+6*exp(2*x+0.2)-4*exp(x+0.1)+1+1e-15=0',
                'x',
                -0.11,
                -0.09,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );

        $perturbedPhase = Math::solve(
            'exp(4*x+0.4)-4*exp(3*x+0.300000000000001)+6*exp(2*x+0.2)-4*exp(x+0.1)+1=0',
            'x',
            -0.11,
            -0.09,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(2, $perturbedPhase);
        self::assertNotEqualsWithDelta(-0.1, $perturbedPhase[0]->value, 1.0E-5);

        $contact = Math::solve(
            'exp(4*x+1)-4*exp(3*x+0.75)+6*exp(2*x+0.5)-4*exp(x+0.25)+1=0',
            'x',
            -0.26,
            -0.24,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $contact);
        self::assertEqualsWithDelta(-0.25, $contact[0]->value, 1.0E-12);

        $nearbyRoots = Math::solve(
            'exp(4*x+1)-4*exp(3*x+0.75)+6*exp(2*x+0.5)-4*exp(x+0.25)+1-1e-12=0',
            'x',
            -0.26,
            -0.24,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(2, $nearbyRoots);
        self::assertEqualsWithDelta(log(1.0 - 1.0E-3) - 0.25, $nearbyRoots[0]->value, 1.0E-10);
        self::assertEqualsWithDelta(log(1.0 + 1.0E-3) - 0.25, $nearbyRoots[1]->value, 1.0E-10);

        self::assertSame(
            [],
            Math::solve(
                'exp(4*x+1)-4*exp(3*x+0.75)+6*exp(2*x+0.5)-4*exp(x+0.25)+1+1e-20=0',
                'x',
                -0.26,
                -0.24,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
    }

    public function testExpandedDegreeThirtyTwoExponentialBinomialKeepsExactRootTopology(): void
    {
        $terms = [];
        $coefficient = 1;
        for ($power = 0; $power <= 32; ++$power) {
            $signedCoefficient = ($power % 2) === 0 ? $coefficient : -$coefficient;
            $terms[] = $signedCoefficient . '*exp(' . $power . '*x)';
            $coefficient = (int) ($coefficient * (32 - $power) / ($power + 1));
        }
        $contactEquation = \implode(' + ', $terms) . ' = 0';
        $offsetEquation = \implode(' + ', $terms) . ' + 0.000000000000001 = 0';

        $contactRoots = Math::solve($contactEquation, 'x', -1.0, 1.0);
        $offsetRoots = Math::solve($offsetEquation, 'x', -1.0, 1.0);

        self::assertCount(1, $contactRoots);
        self::assertEqualsWithDelta(0.0, $contactRoots[0]->value, 1.0E-12);
        self::assertSame([], $offsetRoots);
    }

    public function testIncommensurateExponentialPolynomialsIsolateCloseRoots(): void
    {
        $solutions = Math::solve(
            'exp(x) + exp(-x) + exp(sqrt(2) * x) = 2.7300658587281',
            'x',
            -10.0,
            10.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(2, $solutions);
        self::assertEqualsWithDelta(-0.39524149954, $solutions[0]->value, 1.0E-9);
        self::assertEqualsWithDelta(-0.39368509122, $solutions[1]->value, 1.0E-9);
        self::assertLessThanOrEqual(1.0E-10, $solutions[0]->residual);
        self::assertLessThanOrEqual(1.0E-10, $solutions[1]->residual);

        $tangent = Math::solve(
            'exp(x) + exp(-x) + exp(sqrt(2) * x) = 2.7300648587281442',
            'x',
            -10.0,
            10.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $tangent);
        self::assertEqualsWithDelta(-0.39446327064, $tangent[0]->value, 1.0E-8);

        $nearTangentAbove = Math::solve(
            'exp(x) + exp(-x) + exp(sqrt(2) * x) = 2.7300648587281544',
            'x',
            -10.0,
            10.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(2, $nearTangentAbove);
        self::assertLessThanOrEqual(1.0E-10, $nearTangentAbove[0]->residual);
        self::assertLessThanOrEqual(1.0E-10, $nearTangentAbove[1]->residual);

        $nearTangentBelow = Math::solve(
            'exp(x) + exp(-x) + exp(sqrt(2) * x) = 2.730064858728134',
            'x',
            -10.0,
            10.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertSame([], $nearTangentBelow);

        self::assertSame(
            [],
            Math::solve(
                'exp(x) + exp(-x) + exp(sqrt(2) * x) = 2.7300638587281',
                'x',
                -10.0,
                10.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
    }

