    public function testExponentialCancellationDistinguishesIdentityFromNoRoots(): void
    {
        try {
            Math::solve(
                'exp(x) - 2 * exp(x) + exp(x) = 0',
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::fail('Expected the cancelled exponential identity to report infinitely many solutions.');
        } catch (\DomainException) {
        }

        self::assertSame(
            [],
            Math::solve(
                'exp(x) - 2 * exp(x) + exp(x) = 1',
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
    }

    public function testPolynomialPhaseExponentialSumsResolveRepeatedAndCloseRoots(): void
    {
        $nearTangentTarget = 2.000000000001;
        $nearTangentMagnitude = \sqrt(\acosh($nearTangentTarget / 2.0));
        $positiveExponentialLevel = \log((\sqrt(13.0) - 1.0) / 2.0);
        $polynomialPhaseMagnitude = \sqrt($positiveExponentialLevel);
        $poweredSumMagnitude = \sqrt(\log(\sqrt(8.0) - 1.0));

        foreach ([1, 256] as $scanSteps) {
            $nearTangent = Math::solve(
                'exp(x^2)+exp(-x^2)=2.000000000001',
                'x',
                -1.0,
                1.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(2, $nearTangent);
            self::assertEqualsWithDelta(-$nearTangentMagnitude, $nearTangent[0]->value, 1.0E-9);
            self::assertEqualsWithDelta($nearTangentMagnitude, $nearTangent[1]->value, 1.0E-9);

            $tangent = Math::solve(
                'exp(x^2)+exp(-x^2)=2',
                'x',
                -1.0,
                1.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(1, $tangent);
            self::assertEqualsWithDelta(0.0, $tangent[0]->value, 1.0E-12);

            $quadraticPhase = Math::solve(
                'exp(x^2)+exp(2*x^2)=3',
                'x',
                -1.0,
                1.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(2, $quadraticPhase);
            self::assertEqualsWithDelta(
                -$polynomialPhaseMagnitude,
                $quadraticPhase[0]->value,
                1.0E-9,
            );
            self::assertEqualsWithDelta(
                $polynomialPhaseMagnitude,
                $quadraticPhase[1]->value,
                1.0E-9,
            );

            $shiftedPhase = Math::solve(
                'exp((x-1)^2)+exp(2*(x-1)^2)=3',
                'x',
                -1.0,
                3.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(2, $shiftedPhase);
            self::assertEqualsWithDelta(
                1.0 - $polynomialPhaseMagnitude,
                $shiftedPhase[0]->value,
                1.0E-9,
            );
            self::assertEqualsWithDelta(
                1.0 + $polynomialPhaseMagnitude,
                $shiftedPhase[1]->value,
                1.0E-9,
            );

            $multipleCriticalPoints = Math::solve(
                'exp(x^3-3*x)+exp(2*(x^3-3*x))=3',
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(3, $multipleCriticalPoints);
            foreach ($multipleCriticalPoints as $solution) {
                self::assertLessThanOrEqual(1.0E-9, $solution->residual);
            }

            $poweredExponential = Math::solve(
                'exp(x^2)^2+2*exp(x^2)=8',
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(2, $poweredExponential);
            self::assertEqualsWithDelta(
                -\sqrt(\log(2.0)),
                $poweredExponential[0]->value,
                1.0E-9,
            );
            self::assertEqualsWithDelta(
                \sqrt(\log(2.0)),
                $poweredExponential[1]->value,
                1.0E-9,
            );

            $poweredSum = Math::solve(
                '(exp(x^2)+1)^2=8',
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(2, $poweredSum);
            self::assertEqualsWithDelta(-$poweredSumMagnitude, $poweredSum[0]->value, 1.0E-9);
            self::assertEqualsWithDelta($poweredSumMagnitude, $poweredSum[1]->value, 1.0E-9);

            self::assertSame(
                [],
                Math::solve(
                    'exp(x^2)^-1+exp(-x^2)=3',
                    'x',
                    -2.0,
                    2.0,
                    solverOptions: new SolverOptions(scanSteps: $scanSteps),
                ),
            );
        }
    }

    public function testPositiveConstantBasePowersSharePolynomialExponentialPhases(): void
    {
        $linearRoot = \log(3.0) / \log(2.0);
        $quadraticRoot = \sqrt($linearRoot);

        foreach ([1, 256] as $scanSteps) {
            $linear = Math::solve(
                '2^x+4^x=12',
                'x',
                -4.0,
                4.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(1, $linear);
            self::assertEqualsWithDelta($linearRoot, $linear[0]->value, 1.0E-9);

            $quadratic = Math::solve(
                '2^(x^2)+4^(x^2)=12',
                'x',
                -4.0,
                4.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(2, $quadratic);
            self::assertEqualsWithDelta(-$quadraticRoot, $quadratic[0]->value, 1.0E-9);
            self::assertEqualsWithDelta($quadraticRoot, $quadratic[1]->value, 1.0E-9);

            $reciprocalBases = Math::solve(
                '0.5^x+2^x=4.25',
                'x',
                -4.0,
                4.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(2, $reciprocalBases);
            self::assertEqualsWithDelta(-2.0, $reciprocalBases[0]->value, 1.0E-9);
            self::assertEqualsWithDelta(2.0, $reciprocalBases[1]->value, 1.0E-9);
        }
    }

    public function testRationalExponentialPhaseEquationsCrossMultiplySafely(): void
    {
        $expected = \log(3.0) / \log(2.0);
        $nestedFractionRoot = \log((\sqrt(5.0) - 1.0) / 2.0);
        $negativePowerSumRoot = \log((1.0 + \sqrt(5.0)) / 2.0);

        foreach ([1, 256] as $scanSteps) {
            foreach (
                [
                    '2^x/(1+2^x)=0.75' => $expected,
                    '0.75=2^x/(1+2^x)' => $expected,
                    'exp(x)/(1+exp(x))=0.5' => 0.0,
                    'exp(x)/(exp(x)-1)=2' => \log(2.0),
                    '1/(1+exp(x))+1/(2+exp(x))=1' => $nestedFractionRoot,
                    '(1+exp(x))^-1+exp(-x)=1' => $negativePowerSumRoot,
                ] as $equation => $root
            ) {
                $solutions = Math::solve(
                    $equation,
                    'x',
                    -4.0,
                    4.0,
                    solverOptions: new SolverOptions(scanSteps: $scanSteps),
                );
                self::assertCount(1, $solutions, $equation);
                self::assertEqualsWithDelta($root, $solutions[0]->value, 1.0E-9, $equation);
            }

            self::assertSame(
                [],
                Math::solve(
                    '2^x/(1+2^x)=1.5',
                    'x',
                    -4.0,
                    4.0,
                    solverOptions: new SolverOptions(scanSteps: $scanSteps),
                ),
            );
            self::assertSame(
                [],
                Math::solve(
                    '(exp(x)-1)/(exp(x)-1)=2',
                    'x',
                    -4.0,
                    4.0,
                    solverOptions: new SolverOptions(scanSteps: $scanSteps),
                ),
            );
            $cancelledPoleAndRepeatedRoot = Math::solve(
                '((exp(x)-1)*(exp(x)-2)^2)/(exp(x)-1)=0',
                'x',
                -4.0,
                4.0,
                solverOptions: new SolverOptions(scanSteps: $scanSteps),
            );
            self::assertCount(1, $cancelledPoleAndRepeatedRoot);
            self::assertEqualsWithDelta(
                \log(2.0),
                $cancelledPoleAndRepeatedRoot[0]->value,
                1.0E-9,
            );
        }
    }

    public function testPolynomialPhaseHyperbolicEquationsUseExponentialReduction(): void
    {
        $cases = [
            'sinh(x^2) = exp(-x^2)' => [\sqrt(0.5 * \log(3.0)), 2],
            'cosh(x^2) = 1.5*exp(-x^2)' => [\sqrt(0.5 * \log(2.0)), 2],
            'tanh(x^2) = exp(-2*x^2)' => [\sqrt(0.5 * \log(1.0 + \sqrt(2.0))), 2],
            'sech(x^2) = 1.5*exp(-x^2)' => [\sqrt(0.5 * \log(3.0)), 2],
            'csch(x^2) = 3*exp(-x^2)' => [\sqrt(0.5 * \log(3.0)), 2],
            'coth(x^2) = 1+4*exp(-2*x^2)' => [\sqrt(0.5 * \log(2.0)), 2],
        ];

        foreach ($cases as $equation => [$expectedRoot, $expectedCount]) {
            $solutions = Math::solve(
                $equation,
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );

            self::assertCount($expectedCount, $solutions, $equation);
            self::assertEqualsWithDelta(-$expectedRoot, $solutions[0]->value, 1.0E-9, $equation);
            self::assertEqualsWithDelta($expectedRoot, $solutions[1]->value, 1.0E-9, $equation);
        }
    }

    public function testNumericalSolveUsesCertifiedIsolationForErrorFunctionFixedPoints(): void
