    public function testCoshAgainstMatchedMonomialFindsEveryRootAtCoarseResolution(): void
    {
        $roots = [-2.5939160904942637, -1.6213479461032523, 1.6213479461032523, 2.5939160904942637];
        foreach (['cosh(x)=x^2', 'x^2=cosh(x)'] as $equation) {
            $solutions = Math::solve(
                $equation,
                'x',
                -5.0,
                5.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );
            self::assertEqualsWithDelta($roots, \array_map(
                static fn (EquationSolution $solution): float => $solution->value,
                $solutions,
            ), 1.0E-10, $equation);
        }

        $scaledArgumentRoots = \array_map(static fn (float $root): float => $root / 2.0, $roots);
        $scaledSolutions = Math::solve(
            'cosh(2*x)=4*x^2',
            'x',
            -5.0,
            5.0,
            solverOptions: new SolverOptions(scanSteps: 1),
