    public function testIncommensuratePolynomialPhaseExponentialSumsAreIsolated(): void
    {
        $expectedOffset = \sqrt(\log(2.0));
        foreach (
            [
                'exp(x^2) + exp(sqrt(2)*x^2) = 2 + 2^sqrt(2)' => [0.0, $expectedOffset],
                'exp((x-1)^2) + exp(sqrt(2)*(x-1)^2) = 2 + 2^sqrt(2)' => [1.0, $expectedOffset],
            ] as $equation => [$center, $offset]
        ) {
            $solutions = Math::solve(
                $equation,
                'x',
                $center - 2.0,
                $center + 2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );

            self::assertCount(2, $solutions, $equation);
            self::assertEqualsWithDelta($center - $offset, $solutions[0]->value, 1.0E-9, $equation);
            self::assertEqualsWithDelta($center + $offset, $solutions[1]->value, 1.0E-9, $equation);
        }

        $rationalSolutions = Math::solve(
            'exp(x^2)/(1+exp(sqrt(2)*x^2)) = 2/(1+2^sqrt(2))',
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(4, $rationalSolutions);
        self::assertEqualsWithDelta(-\sqrt(\log(2.0)), $rationalSolutions[0]->value, 1.0E-9);
        self::assertEqualsWithDelta(-0.7444762997047966, $rationalSolutions[1]->value, 1.0E-8);
        self::assertEqualsWithDelta(0.7444762997047966, $rationalSolutions[2]->value, 1.0E-8);
        self::assertEqualsWithDelta(\sqrt(\log(2.0)), $rationalSolutions[3]->value, 1.0E-9);
        foreach ($rationalSolutions as $solution) {
            self::assertLessThanOrEqual(1.0E-10, $solution->residual);
        }

        $endpointRoot = Math::solve(
            'exp(x^2)+exp(sqrt(2)*x^2)=2',
            'x',
            0.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $endpointRoot);
        self::assertSame(0.0, $endpointRoot[0]->value);

        self::assertSame(
            [],
            Math::solve(
                'exp(x^2)+exp(sqrt(2)*x^2)=1',
                'x',
                0.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );

        $frequency = \sqrt(2.0);
        $tangentPhase = \log($frequency) / (1.0 + $frequency);
        $tangentTarget = \exp($tangentPhase) + \exp(-$frequency * $tangentPhase);
        $tangentEquation = 'exp(x^2)+exp(-sqrt(2)*x^2)=' . \sprintf('%.17g', $tangentTarget);
        $tangentRoots = Math::solve(
            $tangentEquation,
            'x',
            -2.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        $expectedTangentRoot = \sqrt($tangentPhase);
        self::assertCount(2, $tangentRoots, $tangentEquation);
        self::assertEqualsWithDelta(-$expectedTangentRoot, $tangentRoots[0]->value, 1.0E-8);
        self::assertEqualsWithDelta($expectedTangentRoot, $tangentRoots[1]->value, 1.0E-8);

        $belowTangentEquation = 'exp(x^2)+exp(-sqrt(2)*x^2)='
            . \sprintf('%.17g', $tangentTarget - 1.0E-10);
        self::assertSame(
            [],
            Math::solve(
                $belowTangentEquation,
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
    }

    public function testEquationSearchIncludesDefinedLambertWBranchPoint(): void
    {
        $solutions = Math::solve(
            'lambertw(x) + x = -1 - 1/e',
            'x',
            -1.0,
            0.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(1, $solutions);
        self::assertEqualsWithDelta(-1.0 / \M_E, $solutions[0]->value, 1.0E-8);
        self::assertLessThanOrEqual(1.0E-9, $solutions[0]->residual);
    }

    public function testErfcPolynomialEquationPreservesTinyComplementaryTargets(): void
    {
        $target = Math::evaluate('erfc(10)');
        $solutions = Math::solve(
            \sprintf('erfc(x^2) = %.17g', $target),
            'x',
            -4.0,
            4.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(2, $solutions);
        self::assertEqualsWithDelta(-\sqrt(10.0), $solutions[0]->value, 1.0E-9);
        self::assertEqualsWithDelta(\sqrt(10.0), $solutions[1]->value, 1.0E-9);
        foreach ($solutions as $solution) {
            self::assertLessThanOrEqual(1.0E-55, $solution->residual);
        }
    }

    public function testSquareRootInversionDoesNotReportAnUnrepresentableRoot(): void
    {
        $unrepresentable = Math::solve(
            'sqrt(x) = 1e-200',
            'x',
            0.0,
            1.0E-300,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        $unrepresentableCube = Math::solve(
            'cbrt(x) = 1e-200',
            'x',
            -1.0E-300,
            1.0E-300,
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        $scaledAffine = Math::solve(
            'sqrt(1e-200*x) = 1e-100',
            'x',
            0.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertSame([], $unrepresentable);
        self::assertSame([], $unrepresentableCube);
        self::assertCount(1, $scaledAffine);
        self::assertEqualsWithDelta(1.0, $scaledAffine[0]->value, 1.0E-10);
        self::assertLessThanOrEqual(1.0E-110, $scaledAffine[0]->residual);
    }

    public function testNonPolynomialRootDetectionIsInvariantToSmallScaling(): void
    {
        $solutions = Math::solve('1e-20 * sin(x) = 0', 'x', 2.0, 4.0);

        self::assertCount(1, $solutions);
        self::assertEqualsWithDelta(\M_PI, $solutions[0]->value, 1.0E-8);
    }

    public function testLargeIntegerAffineCoefficientsRemainDistinctInScalarSolving(): void
    {
        $options = new SolverOptions(scanSteps: 1);
        $equations = [
            '9007199254740993 * x = 9007199254740992 * x' => 0.0,
            '9007199254740993 * x = 9007199254740992 * x + 1' => 1.0,
            '9007199254740992 * x = 9007199254740993 * x + 1' => -1.0,
        ];

        foreach ($equations as $equation => $expectedRoot) {
            $solutions = Math::solve(
                $equation,
                'x',
                -2.0,
                2.0,
                solverOptions: $options,
            );

            self::assertCount(1, $solutions, $equation);
            self::assertSame($expectedRoot, $solutions[0]->value, $equation);
            self::assertSame(0, $solutions[0]->iterations, $equation);
        }
    }

    public function testLargeIntegerPolynomialDifferencesPreserveAllRoots(): void
    {
        $solutions = Math::solve(
            '9007199254740993 * x^2 = 9007199254740992 * x^2 + x',
            'x',
            -2.0,
            2.0,
        );

        self::assertCount(2, $solutions);
        self::assertSame(0.0, $solutions[0]->value);
        self::assertSame(1.0, $solutions[1]->value);
        self::assertSame(0.0, $solutions[0]->residual);
        self::assertSame(0.0, $solutions[1]->residual);

        $parameterizedSolutions = Math::solve(
            'scale * x^2 = (scale - 1) * x^2 + x',
            'x',
            -2.0,
            2.0,
            ['scale' => 9007199254740993],
        );

        self::assertCount(2, $parameterizedSolutions);
        self::assertSame(0.0, $parameterizedSolutions[0]->value);
        self::assertSame(1.0, $parameterizedSolutions[1]->value);
    }

    public function testFlatRootAtScanPointIsNotDuplicatedByDerivativeNoise(): void
    {
        $solutions = Math::solve('tan(x) = x', 'x', -5.0, 5.0);

        self::assertCount(3, $solutions);
        self::assertEqualsWithDelta(-4.4934094579, $solutions[0]->value, 1.0E-7);
        self::assertEqualsWithDelta(0.0, $solutions[1]->value, 1.0E-10);
        self::assertEqualsWithDelta(4.4934094579, $solutions[2]->value, 1.0E-7);
    }

    public function testAffineTangentLevelsUsePoleAndCriticalPointPartitions(): void
    {
        $cases = [
            'tan(x)=x' => [-4.4934094579, 0.0, 4.4934094579],
            'x=tan(x)' => [-4.4934094579, 0.0, 4.4934094579],
            'tan(x)=2*x' => [
                -4.604216777,
                -1.165561185,
                0.0,
                1.165561185,
                4.604216777,
            ],
            'tan(2*x+0.3)=x' => [
                -3.953106892,
                -2.301228425,
                -0.2920939021,
                1.971486468,
                3.643042085,
            ],
        ];

        foreach ($cases as $equation => $expectedRoots) {
            $solutions = Math::solve(
                $equation,
                'x',
                -5.0,
                5.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            );

            self::assertEqualsWithDelta(
                $expectedRoots,
                \array_map(static fn (EquationSolution $solution): float => $solution->value, $solutions),
                1.0E-8,
                $equation,
            );
            foreach ($solutions as $solution) {
                self::assertLessThanOrEqual(1.0E-8, $solution->residual, $equation);
            }
        }
    }

    public function testNonPolynomialRepeatedRootCanBeFoundByNumericalFallback(): void
    {
        $solutions = Math::solve(
            'sin(x)^2 = 0',
            'x',
            2.0,
            4.0,
            solverOptions: new SolverOptions(scanSteps: 256),
        );

        self::assertCount(1, $solutions);
        self::assertEqualsWithDelta(\M_PI, $solutions[0]->value, 1.0E-8);
    }

    public function testRoundoffFlatTangentIsNotSplitIntoTwoNearbyRoots(): void
    {
        $tangent = '1.234567';
        $delta = '(x - ' . $tangent . ')';
        $equation = 'tan(x) = tan(' . $tangent . ')'
            . ' + ' . $delta . ' / cos(' . $tangent . ')^2'
            . ' + tan(' . $tangent . ') * ' . $delta . '^2 / cos(' . $tangent . ')^2'
            . ' + (1 + 3 * tan(' . $tangent . ')^2) * ' . $delta . '^3'
            . ' / (3 * cos(' . $tangent . ')^2)';
        $solutions = Math::solve(
            $equation,
            'x',
            1.1,
            1.4,
            solverOptions: new SolverOptions(scanSteps: 16),
        );

        self::assertCount(1, $solutions);
        self::assertEqualsWithDelta((float) $tangent, $solutions[0]->value, 1.0E-6);
    }

    public function testZeroIntegerPowersReduceToTheirNonPolynomialBaseRoots(): void
    {
        foreach ([2, 4] as $power) {
            foreach (
                [
                    'erf(x)^' . $power . ' = 0',
                    '0 = (erf(x))^' . $power,
                ] as $equation
            ) {
                $solutions = Math::solve(
                    $equation,
                    'x',
                    -2.0,
                    2.0,
                    solverOptions: new SolverOptions(scanSteps: 1),
                );

                self::assertCount(1, $solutions, $equation);
                self::assertEqualsWithDelta(0.0, $solutions[0]->value, 1.0E-10, $equation);
                self::assertLessThanOrEqual(1.0E-12, $solutions[0]->residual, $equation);
            }
        }

        $parameterizedSolution = Math::solve(
            'erf(x - shift)^2 = 0',
            'x',
            -2.0,
            2.0,
            ['shift' => 0.3],
            solverOptions: new SolverOptions(scanSteps: 1),
        );
        self::assertCount(1, $parameterizedSolution);
        self::assertEqualsWithDelta(0.3, $parameterizedSolution[0]->value, 1.0E-10);

        self::assertSame(
            [],
            Math::solve(
                'erf(x)^x = 0',
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
        self::assertSame(
            [],
            Math::solve(
                'erf(x)^-2 = 0',
                'x',
                -2.0,
                2.0,
                solverOptions: new SolverOptions(scanSteps: 1),
            ),
        );
    }


    public function testRemovableRationalSingularityIsNotReportedAsRoot(): void
    {
        $solutions = Math::solve(
            '(x^2 - 1) / (x - 1) = 2',
            'x',
            0.0,
            2.0,
            solverOptions: new SolverOptions(scanSteps: 17),
        );

        self::assertSame([], $solutions);
    }

    public function testRootNearNonRemovableRationalPoleIsRetained(): void
    {
        $solutions = Math::solve(
            '1 / (x - 1) = 1000',
            'x',
            0.9,
            1.1,
            solverOptions: new SolverOptions(scanSteps: 17),
        );

        self::assertCount(1, $solutions);
        self::assertEqualsWithDelta(1.001, $solutions[0]->value, 2.0E-10);
        self::assertLessThan(1.0E-6, $solutions[0]->residual);
    }

    public function testRationalRootNearPoleReportsBestRepresentableResidual(): void
    {
        $solutions = Math::solve(
            '1 / (x - 1) = 1e12',
            'x',
            0.9,
            1.1,
            solverOptions: new SolverOptions(scanSteps: 1),
        );

        self::assertCount(1, $solutions);
        $solution = $solutions[0];
        $residualAt = static fn (float $value): float => \abs((1.0 / ($value - 1.0)) - 1.0E12);

        self::assertSame($residualAt($solution->value), $solution->residual);
        $spacing = \PHP_FLOAT_EPSILON * \abs($solution->value);
        self::assertLessThanOrEqual(
            $residualAt($solution->value - $spacing),
            $solution->residual,
        );
        self::assertLessThanOrEqual(
            $residualAt($solution->value + $spacing),
            $solution->residual,
        );
    }

    public function testPolynomialRepeatedRootIsInvariantToEquationScaling(): void
    {
        foreach (
            [
            '0.00000000000000000001 * (x - 0.5)^2 = 0',
            '1.0e20 * (x - 0.5)^2 = 0',
            ] as $equation
        ) {
            $solutions = Math::solve($equation, 'x', -1.0, 1.0);

            self::assertCount(1, $solutions);
            self::assertEqualsWithDelta(0.5, $solutions[0]->value, 1.0E-10);
        }
    }

    public function testCloseDistinctPolynomialRootsAreNotReportedAsCriticalRoots(): void
    {
        foreach ([1.0000001, 1.00000001] as $secondRoot) {
            $solutions = Math::solve(
                '(x - 1) * (x - ' . $secondRoot . ') = 0',
                'x',
                0.0,
                2.0,
            );

            self::assertCount(2, $solutions);
            self::assertEqualsWithDelta(1.0, $solutions[0]->value, 2.0E-9);
            self::assertEqualsWithDelta($secondRoot, $solutions[1]->value, 2.0E-9);
        }
    }

    public function testHighMultiplicityPolynomialReturnsOneCandidatePerRoot(): void
    {
        foreach ([3, 8] as $multiplicity) {
            $solutions = Math::solve(
                '(x^2 - 2)^' . $multiplicity . ' = 0',
                'x',
                -2.0,
                2.0,
            );

            self::assertCount(2, $solutions);
            self::assertEqualsWithDelta(-\sqrt(2.0), $solutions[0]->value, 1.0E-12);
            self::assertEqualsWithDelta(\sqrt(2.0), $solutions[1]->value, 1.0E-12);
        }

        $singleRoot = Math::solve('(x - 0.123456789)^5 = 0', 'x', -2.0, 2.0);

        self::assertCount(1, $singleRoot);
        self::assertEqualsWithDelta(0.123456789, $singleRoot[0]->value, 1.0E-12);
    }

    public function testReciprocalTrigonometricPhaseOnPoleFreeIntervals(): void
    {
        foreach ([[-0.5, -0.25, -1.0], [0.25, 0.5, 1.0]] as [$lower, $upper, $sign]) {
            $solutions = Math::solve('sin(1/x)=0', 'x', $lower, $upper);
            self::assertCount(1, $solutions);
            self::assertEqualsWithDelta($sign / \M_PI, $solutions[0]->value, 1.0E-10);
        }
    }

    public function testReciprocalTrigonometricPhaseAtPole(): void
    {
        foreach (['sin(1/x)=0', 'cos(1/x)=0', 'tan(1/x)=0', 'sin(1/x)^2=0', 'sin(1/x)=1/2'] as $equation) {
            try {
                Math::solve($equation, 'x', 0.0, 1.0);
                self::fail('Expected infinitely many roots for ' . $equation);
            } catch (InfiniteRootAccumulationException) {
                self::assertTrue(true);
            }
        }
        self::assertSame([], Math::solve('sin(1/x)=2', 'x', 0.0, 1.0));
        self::assertSame([], Math::solve('sec(1/x)=0', 'x', 0.0, 1.0));
    }

    public function testMaximumPolynomialDegreeIsValidated(): void
    {
        $this->expectException(\InvalidArgumentException::class);
        $this->expectExceptionMessage('maxPolynomialDegree must be between 1 and 256');

        new SolverOptions(maxPolynomialDegree: 257);
    }
